/**
 * 《时代巨浪：大国履职记》微信小游戏 (Game Core Edition)
 * 
 * 核心系统架构：
 * 1. 🎵 前端原生五音 BGM 引擎：
 *    - 零外部音频资源依赖，基于 WebAudio/wx.createWebAudioContext 实时程序化合成
 *    - 中国风宫商角徵羽五声音阶变奏
 *    - 拟真环境音效 (印章音、环境风声、纸张翻动、算筹报信)
 * 2. 🎬 时代主题封面与历程回顾：
 *    - 1992-2035 时代年轮与六大生涯发展赛道
 * 3. 📜 历史节点与职业发展决策：
 *    - 36 个重大时代历史节点与赛道成长主线
 *    - 属性检定与因果回响
 * 4. 🏛️ 任用考核与履职评价体系：
 *    - 业务履职、群众信赖、合规守正、成果评议
 * 5. 🎨 界面与交互动效：
 *    - 时间轴导轨、案头公文、朋友圈动态与家族门风
 */

// ==========================================
// 🛠️ 运行时基础设施：可重现随机、字号优化、开发日志与数据埋点
// ==========================================
// 兼容微信小游戏 (wx) 与字节跳动/抖音小游戏 (tt)
var wx = (typeof GameGlobal !== 'undefined' && (GameGlobal.wx || GameGlobal.tt)) ||
         (typeof globalThis !== 'undefined' && (globalThis.wx || globalThis.tt)) ||
         (typeof global !== 'undefined' && (global.wx || global.tt)) ||
         (typeof window !== 'undefined' && (window.wx || window.tt)) ||
         (typeof tt !== 'undefined' ? tt : undefined);

if (typeof GameGlobal !== 'undefined' && !GameGlobal.wx && wx) {
  try { GameGlobal.wx = wx; } catch (_) {}
}
if (typeof globalThis !== 'undefined' && !globalThis.wx && wx) {
  try { globalThis.wx = wx; } catch (_) {}
}
if (typeof console !== 'undefined' && typeof console.log === 'function') {
  console.log("【时代巨浪】game.js 开始加载，平台环境:", typeof wx !== 'undefined' ? (typeof tt !== 'undefined' ? '抖音小游戏' : '微信小游戏') : '宿主/Node');
}
if (typeof wx !== 'undefined' && typeof wx.onError === 'function') {
  try {
    wx.onError(function(err) {
      console.error('【MiniGame Runtime Error】', err);
    });
  } catch (_) {}
}

const __DEV__ = (typeof global !== 'undefined' && !!global.__DEV__) || (typeof wx !== 'undefined' && typeof wx.getAccountInfoSync === 'function' ? ((wx.getAccountInfoSync().miniProgram || {}).envVersion === 'develop') : (typeof process !== 'undefined' && process.env && process.env.NODE_ENV !== 'production'));

const _runtimeErrorBuffer = [];
function logDebugError(context, err) {
  const msg = err && err.message ? err.message : String(err || '');
  if (_runtimeErrorBuffer.length >= 50) _runtimeErrorBuffer.shift();
  _runtimeErrorBuffer.push({ ts: Date.now(), context: String(context || 'unknown'), error: msg });
  if (__DEV__) {
    console.warn(`[LifeSim Dev Warn] ${context}:`, err);
  }
}

// 种子可控伪随机数发生器 (Mulberry32 PRNG)
let _initialGameSeed = (Date.now() ^ 0x9E3779B9) >>> 0;
let _gameSeed = _initialGameSeed;
let _fxSeed = (Date.now() ^ 0x85EBCA6B) >>> 0;
function setRandomSeed(seed) {
  _initialGameSeed = (seed >>> 0) || 1;
  _gameSeed = _initialGameSeed;
  _fxSeed = ((seed ^ 0x85EBCA6B) >>> 0) || 1;
  if (typeof state !== 'undefined' && state) {
    state.runSeed = _initialGameSeed;
    state._needsSeedInit = true;
    state.birthProfile = null;
    state.endgameSettled = false;
    state.earlyRetireReason = null;
    state.annualActionsTaken = 0;
    state.threeYearActionCount = 0;
    state.inactionStreak = 0;
    state.unresolvedDecisionEvent = null;
    state.unresolvedCrisis = null;
    state.auditCooldownUntil = 0;
    state.debtCooldownUntil = 0;
    state.healthCooldownUntil = 0;
    const elements = ['gold', 'wood', 'water', 'fire', 'earth'];
    state.elementDestiny = elements[Math.floor(seededRandom() * elements.length)];
    state.lifespanCeiling = 71 + Math.floor(seededRandom() * 11); // 71~81 岁先天寿数基准（后续随体魄与调摄动态演化至 60~95 岁）
    state.baseLifespanSeed = state.lifespanCeiling;
    state._lockedStrategy = null;
    if (state.creation) {
      state.creation.surname = '';
      state.creation.givenName = '';
      state.creation.gender = '';
      state.creation.elementDestiny = state.elementDestiny;
    }
  }
}
function setGameSeed(seed) {
  setRandomSeed(seed);
}
function seededRandom() {
  _gameSeed = (_gameSeed + 0x6D2B79F5) >>> 0;
  let t = Math.imul(_gameSeed ^ (_gameSeed >>> 15), 1 | _gameSeed);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}
function fxRandom() {
  _fxSeed = (_fxSeed + 0x6D2B79F5) >>> 0;
  let t = Math.imul(_fxSeed ^ (_fxSeed >>> 15), 1 | _fxSeed);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}

// 核心属性统一读写与实时钳制引擎（杜绝中途属性突破 100 或 0 被误判为默认 50）
const CORE_BOUNDED_STATS = {
  rep: { min: 0, max: 100, def: 50 },
  clean: { min: 0, max: 100, def: 80 },
  health: { min: 0, max: 100, def: 80 },
  sp: { min: 0, max: 100, def: 35 },
  iq: { min: 0, max: 100, def: 50 },
  eq: { min: 0, max: 100, def: 50 },
  courage: { min: 0, max: 100, def: 50 },
  resilience: { min: 0, max: 100, def: 50 }
};

function getBaseStat(key, fallback, st) {
  const target = st || (typeof state !== 'undefined' ? state : null);
  if (!target) return fallback !== undefined ? fallback : 0;
  const val = target[key];
  if (typeof val === 'number' && !Number.isNaN(val)) return val;
  const cfg = CORE_BOUNDED_STATS[key];
  return fallback !== undefined ? fallback : (cfg ? cfg.def : 0);
}

function getStat(key, fallback, st) {
  const target = st || (typeof state !== 'undefined' ? state : null);
  if (!target) return fallback !== undefined ? fallback : 0;
  let baseVal = getBaseStat(key, fallback, target);
  // 当日有效临时岁策吉运光环加成（不永久写入底层属性，次日或跨局自动失效）
  if (target.activeDailyBlessing && target.activeDailyBlessing.effects && typeof target.activeDailyBlessing.effects[key] === 'number') {
    const todayStr = typeof getTodayDateString === 'function' ? getTodayDateString() : '';
    if (!target.activeDailyBlessing.date || target.activeDailyBlessing.date === todayStr) {
      baseVal += target.activeDailyBlessing.effects[key];
    }
  }
  const cfg = CORE_BOUNDED_STATS[key];
  return cfg ? Math.max(cfg.min, Math.min(cfg.max, baseVal)) : baseVal;
}

function setStat(key, val, st) {
  const target = st || (typeof state !== 'undefined' ? state : null);
  if (!target) return 0;
  const cfg = CORE_BOUNDED_STATS[key];
  const raw = typeof val === 'number' && !Number.isNaN(val) ? val : (cfg ? cfg.def : 0);
  const clamped = cfg ? Math.max(cfg.min, Math.min(cfg.max, Math.round(raw))) : Math.round(raw);
  target[key] = clamped;
  return clamped;
}

function addStat(key, delta, fallbackOrSt, maybeSt) {
  const isObj = fallbackOrSt && typeof fallbackOrSt === 'object';
  const target = isObj ? fallbackOrSt : (maybeSt || (typeof state !== 'undefined' ? state : null));
  if (!target) return 0;
  const fallback = typeof fallbackOrSt === 'number' ? fallbackOrSt : undefined;
  // 必须基于底层真实基准值累加，防止当日临时吉运光环被误写入底表固化为永久属性
  const cur = getBaseStat(key, fallback, target);
  let d = Number(delta) || 0;
  if (d > 0 && (key === 'rep' || key === 'iq' || key === 'eq' || key === 'courage' || key === 'clean' || key === 'resilience')) {
    if (cur >= 88) {
      d = d >= 4 ? 1 : 0;
    } else if (cur >= 78) {
      d = d >= 3 ? Math.max(1, Math.round(d * 0.42)) : (d === 2 && ((target.age || 0) % 2 === 0) ? 1 : 0);
    } else if (cur >= 68) {
      d = d >= 2 ? Math.max(1, Math.round(d * 0.62)) : (((target.age || 0) % 2 === 0) ? 1 : 0);
    }
  }
  return setStat(key, cur + d, target);
}

function syncRankProgression(newLevel, st) {
  const target = st || (typeof state !== 'undefined' ? state : null);
  if (!target) return 1;
  const clampedLvl = Math.max(1, Math.min(5, Math.round(Number(newLevel) || 1)));
  target.govLevel = clampedLvl;
  target.rankIndex = clampedLvl;
  target.lifetimeMaxRank = Math.max(1, Math.min(5, Math.max(target.lifetimeMaxRank || 1, clampedLvl)));
  return clampedLvl;
}

function bindReactiveStatClamping(st) {
  const target = st || (typeof state !== 'undefined' ? state : null);
  if (!target || target.__reactiveStatsBound) return target;
  const backing = {};
  const keys = Object.keys(CORE_BOUNDED_STATS);
  for (let i = 0; i < keys.length; i++) {
    const k = keys[i];
    const cfg = CORE_BOUNDED_STATS[k];
    const initVal = typeof target[k] === 'number' && !Number.isNaN(target[k]) ? target[k] : cfg.def;
    backing[k] = Math.max(cfg.min, Math.min(cfg.max, Math.round(initVal)));
    Object.defineProperty(target, k, {
      configurable: true,
      enumerable: true,
      get() {
        return backing[k];
      },
      set(v) {
        const num = typeof v === 'number' && !Number.isNaN(v) ? v : backing[k];
        backing[k] = Math.max(cfg.min, Math.min(cfg.max, Math.round(num)));
      }
    });
  }
  let backingStrategy = (typeof target.strategy === 'string' && target.strategy) ? target.strategy : 'balanced';
  if (backingStrategy === 'overwork') backingStrategy = 'aggressive';
  Object.defineProperty(target, 'strategy', {
    configurable: true,
    enumerable: true,
    get() {
      return backingStrategy;
    },
    set(v) {
      const norm = v === 'overwork' ? 'aggressive' : (['balanced', 'aggressive', 'clean', 'network', 'wellness'].includes(v) ? v : 'balanced');
      backingStrategy = norm;
      if (!target._internalStrategySet) {
        target._lockedStrategy = norm;
      }
    }
  });
  Object.defineProperty(target, '__reactiveStatsBound', {
    value: true,
    configurable: true,
    enumerable: false
  });
  return target;
}

function clampCoreStats(st) {
  const target = st || (typeof state !== 'undefined' ? state : null);
  if (!target) return;
  const boundedKeys = Object.keys(CORE_BOUNDED_STATS);
  for (let i = 0; i < boundedKeys.length; i++) {
    const k = boundedKeys[i];
    if (typeof target[k] === 'number' && !Number.isNaN(target[k])) {
      const cfg = CORE_BOUNDED_STATS[k];
      target[k] = Math.max(cfg.min, Math.min(cfg.max, Math.round(target[k])));
    }
  }
  if ((target.age || 0) < 18) {
    target.govLevel = 0;
    target.rankIndex = 0;
    target.lifetimeMaxRank = 0;
  } else if (typeof target.govLevel === 'number' || typeof target.rankIndex === 'number') {
    const lvl = Math.max(1, Math.min(5, Math.round(target.govLevel || target.rankIndex || 1)));
    target.govLevel = lvl;
    target.rankIndex = lvl;
    target.lifetimeMaxRank = Math.max(target.lifetimeMaxRank || 1, lvl);
  }
}

// 关键节点埋点与数据上报
function reportGameMilestone(eventName, eventData = {}) {
  try {
    if (typeof wx !== 'undefined' && typeof wx.reportEvent === 'function') {
      wx.reportEvent(eventName, eventData);
    } else if (__DEV__) {
      console.log(`[LifeSim Milestone] ${eventName}:`, eventData);
    }
  } catch (err) {
    logDebugError('reportGameMilestone', err);
  }
}

// 全局大字关怀模式与字号自适应增强系统 (Elder Accessibility & Global Font Legibility)
let globalFontScale = 1.0;
let isElderAccessibilityMode = false;

function getSystemFontAccessibilityMinSize() {
  return isElderAccessibilityMode ? 17 : 15;
}

function elevateFontSize(fontStr, minSize = 15) {
  if (!fontStr || typeof fontStr !== 'string') return fontStr;
  const targetMin = Math.max(minSize, getSystemFontAccessibilityMinSize());
  return fontStr.replace(/(\d+(\.\d+)?)px/g, (match, p1) => {
    let num = parseFloat(p1);
    if (isElderAccessibilityMode) {
      num = Math.round(num * 1.15 * 10) / 10;
    }
    if (num < targetMin) {
      return targetMin + 'px';
    }
    return Math.round(num * 10) / 10 + 'px';
  });
}

function wrapCanvasContextFont(rawCtx) {
  if (!rawCtx) return rawCtx;

  // 确保 Canvas 原生 ellipse 在缺乏支持的小程序/小游戏环境中平稳降级
  try {
    if (typeof rawCtx.ellipse !== 'function') {
      rawCtx.ellipse = function(x, y, radiusX, radiusY, rotation, startAngle, endAngle, counterclockwise) {
        this.save();
        this.translate(x, y);
        if (rotation) this.rotate(rotation);
        this.scale(Math.max(0.001, Math.abs(radiusX)), Math.max(0.001, Math.abs(radiusY)));
        this.arc(0, 0, 1, startAngle || 0, endAngle !== undefined ? endAngle : Math.PI * 2, counterclockwise);
        this.restore();
      };
    }
  } catch (_) {}

  return rawCtx;
}

// ==========================================
// 一、 视口与全屏系统 (Gapless Edge-to-Edge & Fault-Tolerant JSBridge)
// ==========================================
let sysInfo = {};
try {
  if (typeof wx !== 'undefined') {
    if (typeof wx.getWindowInfo === 'function') {
      sysInfo = wx.getWindowInfo() || {};
    }
    if ((!sysInfo || !sysInfo.windowWidth) && typeof wx.getSystemInfoSync === 'function') {
      sysInfo = wx.getSystemInfoSync() || {};
    }
  }
} catch (_) {}
if ((!sysInfo || !sysInfo.windowWidth) && typeof window !== 'undefined') {
  sysInfo = {
    windowWidth: window.innerWidth,
    windowHeight: window.innerHeight,
    pixelRatio: window.devicePixelRatio || 2
  };
}

let screenWidth = (typeof sysInfo.windowWidth === 'number' && sysInfo.windowWidth >= 200) ? sysInfo.windowWidth : 375;
let screenHeight = (typeof sysInfo.windowHeight === 'number' && sysInfo.windowHeight >= 300) ? sysInfo.windowHeight : 812;
let dpr = Math.min(2.0, sysInfo.pixelRatio || 2);

// 优先获取微信小游戏已存在的全局上屏 Canvas（避免调用 wx.createCanvas() 创建隐式离屏 Canvas 导致黑屏）
let mainCanvas = (typeof GameGlobal !== 'undefined' && GameGlobal.canvas) ||
                 (typeof globalThis !== 'undefined' && globalThis.canvas) ||
                 (typeof window !== 'undefined' && window.canvas) ||
                 null;

if (!mainCanvas && typeof wx !== 'undefined' && typeof wx.createCanvas === 'function') {
  try {
    mainCanvas = wx.createCanvas();
  } catch (e) {
    logDebugError('createCanvas', e);
  }
} else if (!mainCanvas && typeof document !== 'undefined' && typeof document.createElement === 'function') {
  try {
    mainCanvas = document.createElement('canvas');
  } catch (_) {}
}

if (typeof GameGlobal !== 'undefined' && !GameGlobal.canvas && mainCanvas) {
  try { GameGlobal.canvas = mainCanvas; } catch (_) {}
}

let canvas = mainCanvas;
let ctx = null;
if (canvas) {
  canvas.width = screenWidth * dpr;
  canvas.height = screenHeight * dpr;
  ctx = canvas.getContext('2d');
  if (ctx) {
    wrapCanvasContextFont(ctx);
    if (typeof ctx.scale === 'function') {
      ctx.scale(dpr, dpr);
    }
  }
}

if (typeof console !== 'undefined' && typeof console.log === 'function') {
  console.log("【时代巨浪】Canvas 初始化就绪:", {
    hasCanvas: !!canvas,
    isGlobalCanvas: typeof GameGlobal !== 'undefined' && canvas === GameGlobal.canvas,
    width: canvas ? canvas.width : 0,
    height: canvas ? canvas.height : 0,
    screenWidth,
    screenHeight,
    dpr,
    hasCtx: !!ctx
  });
}

let capsule = { top: 48, bottom: 80, left: screenWidth - 87, right: screenWidth - 7, width: 80, height: 32 };
function updateCapsule() {
  capsule = { top: 48, bottom: 80, left: screenWidth - 87, right: screenWidth - 7, width: 80, height: 32 };
  if (typeof wx !== 'undefined' && typeof wx.getMenuButtonBoundingClientRect === 'function') {
    try {
      const c = wx.getMenuButtonBoundingClientRect();
      if (c && c.width > 0 && c.top > 0) capsule = c;
    } catch (_) {}
  }
}
updateCapsule();

if (typeof wx !== 'undefined' && typeof wx.onWindowResize === 'function') {
  try {
    wx.onWindowResize((res) => {
      if (!res || !res.windowWidth || !res.windowHeight) return;
      sysInfo = res;
      screenWidth = res.windowWidth;
      screenHeight = res.windowHeight;
      if (res.pixelRatio) dpr = Math.min(2.0, res.pixelRatio);
      if (canvas && ctx) {
        canvas.width = screenWidth * dpr;
        canvas.height = screenHeight * dpr;
        if (typeof ctx.scale === 'function') {
          ctx.scale(dpr, dpr);
        }
      }
      updateCapsule();
      if (typeof requestRender === 'function') requestRender();
    });
  } catch (_) {}
}

const dashboardH = 156; // 主角核心履职卡片高度
const dockNavH = 52;   // 底部导航栏高度
const actionBarH = 46; // 推进一年操作栏高度

function getTopBarH() {
  const safeTop = (sysInfo && sysInfo.safeArea ? sysInfo.safeArea.top : 44);
  return Math.max(capsule.bottom + 4, safeTop + 4);
}

function getSafeBottomGap() {
  if (sysInfo && sysInfo.safeArea && sysInfo.safeArea.bottom) {
    return Math.max(16, screenHeight - sysInfo.safeArea.bottom);
  }
  return 20;
}

function getBottomDockTotalH() {
  return dockNavH + getSafeBottomGap();
}

function getTopHeaderBottom() {
  return getTopBarH() + (state.pendingPhoneCrisis ? 32 : 0);
}

function getDashboardY() {
  return getTopHeaderBottom() + 6;
}

function getContentTop() {
  return getDashboardY() + dashboardH + 8;
}

function getContentBottom() {
  return screenHeight - getBottomDockTotalH() - actionBarH - 6;
}

function getContentH() {
  return Math.max(120, getContentBottom() - getContentTop());
}

// ==========================================
// 二、 空谷传响·同调同拍与时代场景声学引擎 (Harmonic Quantization, Sidechain Ducking & Era Ambience)
// ==========================================
let audioCtx = null;
let masterBusNode = null;
let bgmBusNode = null;
let activeTonalBus = null;
let bgmEnabled = true;
let sfxEnabled = true;
let bgmPlaying = false;
let bgmNextNoteTime = 0;
let bgmBeat = 0;
let bgmMelodyIdx = 2;
let bgmTimer = null;
let _lastTonalSfxTime = 0;
let _tonalSfxComboStep = 0;

function getAudioContext() {
  if (!audioCtx) {
    if (typeof wx !== 'undefined' && typeof wx.createWebAudioContext === 'function') {
      try { audioCtx = wx.createWebAudioContext(); } catch (e) { logDebugError("caughtException_" + 5, e); }
    }
    if (!audioCtx && typeof AudioContext !== 'undefined') {
      try { audioCtx = new AudioContext(); } catch (e) { logDebugError("caughtException_" + 6, e); }
    } else if (!audioCtx && typeof webkitAudioContext !== 'undefined') {
      try { audioCtx = new webkitAudioContext(); } catch (e) { logDebugError("caughtException_" + 7, e); }
    }
  }
  if (audioCtx && audioCtx.state === 'suspended') {
    try { audioCtx.resume(); } catch (e) { logDebugError("caughtException_" + 8, e); }
  }
  return audioCtx;
}

// 营造“空谷传响、丝竹入微”的立体声亭台卷积混响与柔和动态主母线
function getMasterAudioBus(ctxAudio) {
  if (!ctxAudio) return null;
  if (masterBusNode && masterBusNode._ctx === ctxAudio) {
    return masterBusNode;
  }
  try {
    const t = ctxAudio.currentTime || 0;
    const masterGain = ctxAudio.createGain();
    masterGain.gain.setValueAtTime(0.84, t);
    masterGain._ctx = ctxAudio;

    // 丝绸级温润高频柔化：滤除 6.5kHz 以上数码毛刺，令所有音色如丝绸般细腻顺滑
    const warmthFilter = ctxAudio.createBiquadFilter();
    warmthFilter.type = 'lowpass';
    warmthFilter.frequency.setValueAtTime(6400, t);
    warmthFilter.Q.setValueAtTime(0.5, t);
    masterGain.connect(warmthFilter);

    const dryGain = ctxAudio.createGain();
    dryGain.gain.setValueAtTime(0.74, t);
    warmthFilter.connect(dryGain);

    // 1. 0.95秒立体声水榭木构卷积混响 (ConvolverNode: 清润木质早期反射 + 自然极柔和衰减)
    let hasReverb = false;
    if (typeof ctxAudio.createConvolver === 'function') {
      try {
        const sr = ctxAudio.sampleRate || 44100;
        const irLen = Math.floor(sr * 0.95);
        const irBuf = ctxAudio.createBuffer(2, irLen, sr);
        const earlyTaps = [
          { time: 0.016, gain: 0.22, pan: -0.25 },
          { time: 0.032, gain: 0.18, pan: 0.28 },
          { time: 0.054, gain: 0.12, pan: -0.18 },
          { time: 0.082, gain: 0.08, pan: 0.15 }
        ];
        for (let ch = 0; ch < 2; ch++) {
          const data = irBuf.getChannelData(ch);
          let lp = 0;
          for (let i = 0; i < irLen; i++) {
            const sec = i / sr;
            const white = Math.random() * 2 - 1;
            // 陡峭的高频阻尼，彻底消除白噪声沙沙毛刺，仅留温润木质箱体余韵
            const damp = Math.max(0.12, 0.78 * Math.exp(-sec * 3.2));
            lp = lp * (1 - damp) + white * damp;
            const env = Math.pow(1 - i / irLen, 2.8) * Math.exp(-sec * 2.2);
            data[i] = lp * env * 0.24;
          }
          earlyTaps.forEach(tap => {
            const idx = Math.floor(tap.time * sr);
            if (idx < irLen) {
              const pMul = ch === 0 ? (1 - tap.pan * 0.4) : (1 + tap.pan * 0.4);
              data[idx] += tap.gain * pMul * 0.18;
            }
          });
        }
        const convolver = ctxAudio.createConvolver();
        convolver.buffer = irBuf;
        const wetGain = ctxAudio.createGain();
        wetGain.gain.setValueAtTime(0.11, t); // 11% 细腻空间混响深度，绝不浑浊
        warmthFilter.connect(convolver);
        convolver.connect(wetGain);
        wetGain.connect(dryGain); // 混响信号汇入主控母线一并做柔和压限
        hasReverb = true;
      } catch (e) { hasReverb = false; }
    }

    let lastNode = dryGain;
    if (ctxAudio.createDynamicsCompressor) {
      try {
        const comp = ctxAudio.createDynamicsCompressor();
        comp.threshold.setValueAtTime(-16, t);
        comp.knee.setValueAtTime(20, t);
        comp.ratio.setValueAtTime(2.6, t);
        comp.attack.setValueAtTime(0.012, t);
        comp.release.setValueAtTime(0.20, t);
        lastNode.connect(comp);
        lastNode = comp;
      } catch (e) { /* ignore */ }
    }

    lastNode.connect(ctxAudio.destination);
    masterBusNode = masterGain;
    return masterBusNode;
  } catch (e) {
    return ctxAudio.destination;
  }
}

// BGM 专属子母线（支持侧链闪避 Sidechain Ducking：当事件音效响起时，BGM 自动柔和退居幕后，绝不打架）
function getBgmSubBus(ctxAudio) {
  const master = getMasterAudioBus(ctxAudio);
  if (!ctxAudio || !master) return null;
  if (bgmBusNode && bgmBusNode._ctx === ctxAudio) return bgmBusNode;
  const bus = ctxAudio.createGain();
  bus.gain.setValueAtTime(0.85, ctxAudio.currentTime || 0);
  bus._ctx = ctxAudio;
  bus.connect(master);
  bgmBusNode = bus;
  return bus;
}

function duckBgmForSfx(ctxAudio, duckDuration = 0.55, dipLevel = 0.76) {
  if (!ctxAudio || !bgmPlaying) return;
  const bus = getBgmSubBus(ctxAudio);
  if (!bus || !bus.gain) return;
  try {
    const t = ctxAudio.currentTime;
    bus.gain.cancelScheduledValues(t);
    bus.gain.setValueAtTime(Math.max(0.001, bus.gain.value || 0.85), t);
    bus.gain.linearRampToValueAtTime(dipLevel, t + 0.06);
    bus.gain.exponentialRampToValueAtTime(0.85, t + Math.max(0.35, duckDuration));
  } catch (e) { /* ignore */ }
}

// 乐音音效柔和交叉淡化母线 + 双音效自动对位排期（彻底解决连续两个 playSoundEffect 同时撞车不和谐的问题）
function acquireTonalSfxBus(ctxAudio) {
  const master = getMasterAudioBus(ctxAudio);
  if (!ctxAudio || !master) return null;
  const t = ctxAudio.currentTime;
  const nowMs = Date.now();
  const gapMs = nowMs - _lastTonalSfxTime;

  // 若在 60ms~650ms 内再次触发不同乐音音效，平滑淡出前一个音效，防止不同旋律叠音混浊
  if (gapMs >= 55 && activeTonalBus && activeTonalBus._ctx === ctxAudio) {
    try {
      activeTonalBus.gain.cancelScheduledValues(t);
      activeTonalBus.gain.setValueAtTime(Math.max(0.0001, activeTonalBus.gain.value || 0.8), t);
      activeTonalBus.gain.exponentialRampToValueAtTime(0.001, t + 0.18);
    } catch (e) { /* ignore */ }
  }
  const bus = ctxAudio.createGain();
  bus.gain.setValueAtTime(0.88, t);
  bus._ctx = ctxAudio;
  bus.connect(master);
  activeTonalBus = bus;
  return bus;
}

// 计算双音效连发时的和谐错位延迟与声部对位偏移（如代码同一帧连续调用 seal_stamp + flute 或 bianzhong + guzheng）
function getHarmoniousSfxSchedule() {
  const nowMs = Date.now();
  const gapMs = nowMs - _lastTonalSfxTime;
  if (gapMs < 240) {
    _tonalSfxComboStep = (_tonalSfxComboStep + 1) % 3;
    _lastTonalSfxTime = nowMs;
    // 第二个同时触发的乐音自动延后 0.22s（恰合半拍雅乐律动），音高移至五度/八度协和位，化撞车为琴箫合奏！
    return {
      delayOffset: _tonalSfxComboStep * 0.22,
      degreeShift: _tonalSfxComboStep * 2,
      volScale: 0.78
    };
  }
  _tonalSfxComboStep = 0;
  _lastTonalSfxTime = nowMs;
  return { delayOffset: 0, degreeShift: 0, volScale: 1.0 };
}

function toggleBGM() {
  bgmEnabled = !bgmEnabled;
  if (!bgmEnabled) {
    stopBGM();
    showToast("🔇 音乐已静音", "info");
  } else {
    startBGM();
    showToast("🎵 岁月雅乐已开启", "gold");
  }
  requestRender();
}

// ==========================================
// 同宫同调·纯正五声协和音阶体系 (全时代共享无三全音冲突的纯五度相生五声音阶 C - D - E - G - A)
// 彻底根除不同时代/不同音效之间 F# 与 C/F 碰撞产生的不和谐音程
// ==========================================
const PENTATONIC_SCALES = {
  childhood: {
    base: 261.63, // C宫清澈童谣调 (C - D - E - G - A)
    chords: [
      [130.81, 196.00, 261.63, 329.63], // C宫温润和弦
      [110.00, 164.81, 220.00, 329.63], // A羽摇篮和弦
      [146.83, 220.00, 293.66, 392.00], // D商清泉和弦
      [98.00,  196.00, 293.66, 392.00]  // G徵晴空和弦
    ],
    melody: [196.00, 220.00, 261.63, 293.66, 329.63, 392.00, 440.00, 523.25, 587.33, 659.25, 783.99]
  },
  early: {
    base: 196.00, // G徵/C宫八九十年代春潮调 (与童谣调同宫系统，无缝和谐过渡)
    chords: [
      [98.00,  196.00, 293.66, 392.00], // G徵朝气和弦
      [110.00, 164.81, 220.00, 329.63], // A羽温情和弦
      [130.81, 196.00, 261.63, 392.00], // C宫宽广和弦
      [146.83, 220.00, 293.66, 440.00]  // D商奋进和弦
    ],
    melody: [164.81, 196.00, 220.00, 261.63, 293.66, 329.63, 392.00, 440.00, 523.25, 587.33, 659.25]
  },
  mid: {
    base: 146.83, // D商/G徵千禧腾飞钟磬调 (同属 C-D-E-G-A 纯五度相生系统)
    chords: [
      [73.42,  146.83, 220.00, 293.66], // D商钟鸣和弦
      [110.00, 164.81, 220.00, 329.63], // A羽丝竹和弦
      [98.00,  146.83, 196.00, 293.66], // G徵腾飞和弦
      [130.81, 196.00, 261.63, 392.00]  // C宫辉煌和弦
    ],
    melody: [146.83, 164.81, 196.00, 220.00, 261.63, 293.66, 329.63, 392.00, 440.00, 523.25, 587.33]
  },
  modern: {
    base: 110.00, // A羽/C宫深邃岁月沉思调
    chords: [
      [55.00,  110.00, 164.81, 220.00], // A羽沧桑弦底
      [65.41,  130.81, 196.00, 261.63], // C宫深沉底音
      [73.42,  146.83, 220.00, 293.66], // D商岁月转位
      [98.00,  146.83, 196.00, 329.63]  // G徵辽阔和弦
    ],
    melody: [130.81, 146.83, 164.81, 196.00, 220.00, 261.63, 293.66, 329.63, 392.00, 440.00, 523.25]
  }
};

function getCurrentScale() {
  const age = state.age !== undefined ? state.age : 18;
  const yr = state.year || 1992;
  if (age < 15) return PENTATONIC_SCALES.childhood;
  if (yr < 2000) return PENTATONIC_SCALES.early;
  if (yr < 2013) return PENTATONIC_SCALES.mid;
  return PENTATONIC_SCALES.modern;
}

// 动态获取与当前 BGM 小节和弦 100% 协和的五声音高（让所有音效自动融入当前背景音乐的和声织体）
function getHarmonizedFreq(degreeIdx = 4, octaveMul = 1.0) {
  const scale = getCurrentScale();
  const mel = scale.melody || PENTATONIC_SCALES.early.melody;
  const clampedIdx = Math.max(0, Math.min(mel.length - 1, Math.round(degreeIdx)));
  return mel[clampedIdx] * (octaveMul || 1.0);
}

function getCurrentActiveChord() {
  try {
    if (typeof getCurrentBgmSuite === 'function') {
      const suite = getCurrentBgmSuite();
      if (suite && suite.chords && suite.chords.length) {
        const barIdx = Math.floor((bgmBeatCount || bgmBeat || 0) / 4) % suite.chords.length;
        return suite.chords[barIdx] || suite.chords[0];
      }
    }
  } catch (e) {}
  const scale = getCurrentScale();
  const stepInPhrase = (bgmBeatCount || bgmBeat || 0) % 16;
  const chordIdx = Math.floor(stepInPhrase / 4) % 4;
  return scale.chords[chordIdx] || scale.chords[0];
}

// ==========================================
// 采样级细腻物理建模与自然环境声缓冲池
// ==========================================
const AUDIO_NOISE_BUFFERS = {};
function getNoiseBuffer(ctxAudio, key, dur, fillFn) {
  if (!ctxAudio) return null;
  const sampleRate = ctxAudio.sampleRate || 44100;
  const cacheKey = key + '_' + sampleRate;
  if (AUDIO_NOISE_BUFFERS[cacheKey]) {
    return AUDIO_NOISE_BUFFERS[cacheKey];
  }
  try {
    const bufferSize = Math.max(64, Math.floor(sampleRate * dur));
    const buf = ctxAudio.createBuffer(1, bufferSize, sampleRate);
    const output = buf.getChannelData(0);
    fillFn(output, bufferSize, sampleRate);
    AUDIO_NOISE_BUFFERS[cacheKey] = buf;
    return buf;
  } catch (e) {
    return null;
  }
}

// 产生温润粉红环境噪声（用于竹林听雨、校园梧桐微风、车间蒸汽远景、宣纸墨韵）
function getPinkNoiseBuffer(ctxAudio, dur = 3.0) {
  return getNoiseBuffer(ctxAudio, `pink_amb_${dur.toFixed(1)}`, dur, (out, len) => {
    let b0 = 0, b1 = 0, b2 = 0, b3 = 0, b4 = 0, b5 = 0, b6 = 0;
    for (let i = 0; i < len; i++) {
      const white = Math.random() * 2 - 1;
      b0 = 0.99886 * b0 + white * 0.0555179;
      b1 = 0.99332 * b1 + white * 0.0750759;
      b2 = 0.96900 * b2 + white * 0.1538520;
      b3 = 0.86650 * b3 + white * 0.3104856;
      b4 = 0.55000 * b4 + white * 0.5329522;
      b5 = -0.7616 * b5 - white * 0.0168980;
      out[i] = (b0 + b1 + b2 + b3 + b4 + b5 + b6 + white * 0.5362) * 0.042;
      b6 = white * 0.115926;
    }
  });
}

// 通用 PCM 缓冲播放辅助（带丝绒软起音包络，消除任何数码咔哒声）
function _triggerPcmBuffer(ctxAudio, dest, buf, vol, startTime, rateJitter) {
  if (!ctxAudio || !dest || !buf) return;
  const t = startTime !== undefined ? startTime : ctxAudio.currentTime;
  const src = ctxAudio.createBufferSource();
  src.buffer = buf;
  if (rateJitter && src.playbackRate) {
    src.playbackRate.setValueAtTime(1.0 + (Math.random() * 2 - 1) * rateJitter, t);
  }
  const gain = ctxAudio.createGain();
  const targetV = Math.max(0.001, Math.min(0.65, vol || 0.16));
  gain.gain.setValueAtTime(0.0001, t);
  gain.gain.linearRampToValueAtTime(targetV, t + 0.004);
  src.connect(gain);
  gain.connect(dest);
  src.start(t);
  return src;
}

// 1. 细腻丝桐 Karplus-Strong 数字波导拨弦算法 (增加指腹柔化与琴箱双共振峰，消除生硬金属感)
function getKarplusStrongBuffer(ctxAudio, freq, dur, character) {
  const f = Math.max(55, Math.min(1760, Math.round(freq * 10) / 10));
  const d = Math.min(dur || 1.5, 2.6);
  const charKey = character || 'guzheng';
  return getNoiseBuffer(ctxAudio, `ks_delicate_${charKey}_${f}_${d.toFixed(2)}`, d, (out, len, sr) => {
    const period = Math.max(8, Math.round(sr / f));
    const ring = new Float32Array(period);
    const pickPos = charKey === 'guqin' ? Math.floor(period * 0.30) : (charKey === 'pipa' ? Math.floor(period * 0.14) : Math.max(2, Math.floor(period * 0.18)));
    for (let i = 0; i < period; i++) {
      const phase = i / period;
      // 采用平滑正弦拱形初始弦位移代替生硬折线，声音更加温润细腻
      const arch = Math.sin(Math.PI * phase);
      const harmonic = 0.35 * Math.sin(2 * Math.PI * phase);
      const rand = (Math.sin(i * 12.9898 + f) * 43758.5453 % 1) * 2 - 1;
      ring[i] = (arch * 0.62 + harmonic) + rand * (charKey === 'guqin' ? 0.12 : 0.22);
    }
    for (let i = period - 1; i >= pickPos; i--) {
      ring[i] = ring[i] - 0.42 * ring[i - pickPos];
    }
    // 增加预平滑次数，赋予“轻拢慢捻”的丝绒触感
    const smoothPasses = charKey === 'guqin' ? 4 : (charKey === 'pipa' ? 1 : 2);
    for (let p = 0; p < smoothPasses; p++) {
      let prev = ring[period - 1];
      for (let i = 0; i < period; i++) {
        const cur = ring[i];
        ring[i] = 0.26 * prev + 0.48 * cur + 0.26 * ring[(i + 1) % period];
        prev = cur;
      }
    }

    const loss = charKey === 'guqin' ? 0.9952 : (charKey === 'pipa' ? 0.9942 : 0.9972);
    const blend = charKey === 'guqin' ? 0.48 : (charKey === 'pipa' ? 0.26 : 0.34);
    let bodyState1 = 0, bodyState2 = 0;
    let ptr = 0;
    for (let i = 0; i < len; i++) {
      const nextPtr = (ptr + 1) % period;
      const currentSample = ring[ptr];
      ring[ptr] = loss * ((1 - blend) * currentSample + blend * ring[nextPtr]);
      ptr = nextPtr;

      bodyState1 = 0.965 * bodyState1 + currentSample * 0.035;
      bodyState2 = 0.87 * bodyState2 + (currentSample - bodyState1) * 0.13;
      const env = i < 96 ? Math.sin((i / 96) * (Math.PI * 0.5)) : Math.exp(-i / (sr * (d * 0.65)));
      out[i] = (currentSample * 0.72 + bodyState2 * 0.38) * env;
    }
  });
}

// 2. 温润紫檀木/算盘珠/教室粉笔微模态轻触 PCM (物理接触噪声微脉冲 + 高阻尼微模态，彻底消除任何电子蜂鸣与调性感)
function getTactileClickBuffer(ctxAudio, style) {
  const st = style || 'wood_click';
  let dur = 0.032;
  if (st === 'wood_click') dur = 0.022;
  return getNoiseBuffer(ctxAudio, `tactile_v3_${st}`, dur, (out, len, sr) => {
    let f0 = 320, damp = 520, crisp = 0.28;
    if (st === 'wood_click') { f0 = 320; damp = 520; crisp = 0.28; }
    else if (st === 'abacus_hi') { f0 = 980; damp = 380; crisp = 0.22; }
    else if (st === 'abacus_lo') { f0 = 780; damp = 340; crisp = 0.20; }
    else if (st === 'watch_1') { f0 = 1560; damp = 560; crisp = 0.25; }
    else if (st === 'watch_2') { f0 = 1320; damp = 520; crisp = 0.22; }
    else if (st === 'dice') { f0 = 740; damp = 320; crisp = 0.24; }
    else if (st === 'chalk') { f0 = 640; damp = 420; crisp = 0.18; }
    else if (st === 'wood_block') { f0 = 420; damp = 260; crisp = 0.22; }

    for (let i = 0; i < len; i++) {
      const t = i / sr;
      const att = i < 18 ? (i / 18) : 1.0;
      // 微秒级非周期性物理敲击微脉冲（无音调纯接触噪声，0.8ms）
      const contactNoise = (Math.random() * 2 - 1) * (t < 0.0008 ? (1 - t / 0.0008) : 0) * 0.22;
      const contactPulse = t < 0.0010 ? Math.sin(Math.PI * (t / 0.0010)) * crisp : 0;
      const m1 = Math.exp(-t * damp) * Math.sin(2 * Math.PI * f0 * t);
      const m2 = Math.exp(-t * damp * 2.1) * Math.sin(2 * Math.PI * (f0 * 2.28) * t) * 0.24;
      const m3 = Math.exp(-t * damp * 3.6) * Math.sin(2 * Math.PI * (f0 * 3.85) * t) * 0.08;
      out[i] = (contactNoise + contactPulse + m1 * 0.65 + m2 + m3) * att * 0.76;
    }
  });
}

// 3. 细腻宣纸翻卷与课堂书页微响 PCM
function getPaperFlipBuffer(ctxAudio, isScroll) {
  const dur = isScroll ? 0.15 : 0.082;
  return getNoiseBuffer(ctxAudio, `paper_velvet_v2_${isScroll ? 'long' : 'short'}`, dur, (out, len, sr) => {
    let prev1 = 0, prev2 = 0, lp = 0;
    for (let i = 0; i < len; i++) {
      const t = i / sr;
      const normT = t / dur;
      const edgeSnap = t < 0.010 ? Math.sin(Math.PI * (t / 0.010)) * 0.24 : 0;
      const arcEnv = Math.pow(Math.sin(Math.PI * normT), 1.6) * Math.exp(-normT * 1.3);
      const density = 0.13 + 0.16 * Math.sin(Math.PI * normT);
      const r = Math.random();
      const impulse = r < density ? (r < density * 0.5 ? 1 : -1) : 0;
      const diff = impulse - 1.35 * prev1 + 0.45 * prev2;
      prev2 = prev1;
      prev1 = impulse;
      lp = 0.66 * lp + 0.34 * diff;
      out[i] = (edgeSnap * diff * 0.3 + lp * arcEnv * 0.58);
    }
  });
}

// 4. 寿山石印章温润落案 PCM
function getSealStampBuffer(ctxAudio) {
  return getNoiseBuffer(ctxAudio, 'seal_stamp_v2_pcm', 0.13, (out, len, sr) => {
    let prev = 0;
    for (let i = 0; i < len; i++) {
      const t = i / sr;
      const noise = (Math.random() * 2 - 1) - prev * 0.72;
      prev = noise;
      const slap = t < 0.005 ? noise * Math.exp(-t * 620) * 0.32 : 0;
      const desk1 = Math.exp(-t * 38) * Math.sin(2 * Math.PI * 104 * t) * 0.65;
      const desk2 = Math.exp(-t * 82) * Math.sin(2 * Math.PI * 228 * t) * 0.28;
      const desk3 = Math.exp(-t * 190) * Math.sin(2 * Math.PI * 490 * t) * 0.12;
      out[i] = Math.tanh((slap + desk1 + desk2 + desk3) * 1.15) * 0.72;
    }
  });
}

// 5. 曾侯乙青铜编钟/灵璧玉磬/银元/青瓷细腻模态 PCM
function getMetallicModalBuffer(ctxAudio, baseFreq, dur, material) {
  const f = Math.round(baseFreq * 10) / 10;
  const d = Math.min(dur || 1.2, 2.5);
  const mat = material || 'bronze';
  return getNoiseBuffer(ctxAudio, `metal_v2_${mat}_${f}_${d.toFixed(2)}`, d, (out, len, sr) => {
    const modes = mat === 'coin'
      ? [
          { r: 1.0, a: 0.52, k: 12.0 },
          { r: 1.618, a: 0.32, k: 19.0 },
          { r: 2.414, a: 0.16, k: 29.0 }
        ]
      : (mat === 'jade'
        ? [
            { r: 1.0, a: 0.66, k: 4.5 },
            { r: 2.0, a: 0.26, k: 9.5 },
            { r: 3.16, a: 0.10, k: 20.0 }
          ]
        : [
            { r: 0.5, a: 0.26, k: 1.9 },   // 浑厚钟体低八度共鸣
            { r: 1.0, a: 0.62, k: 2.3 },   // 隧部正鼓音
            { r: 1.0025, a: 0.24, k: 2.6 },// 扁钟柔和差拍余韵
            { r: 1.50, a: 0.26, k: 3.8 },  // 纯五度协和泛音（消除跨调小三度碰撞）
            { r: 2.00, a: 0.18, k: 5.8 },
            { r: 3.00, a: 0.08, k: 11.0 }
          ]);

    for (let i = 0; i < len; i++) {
      const t = i / sr;
      // 3.5ms 丝绸木槌软起音，彻底消除金属敲击的生硬刺耳感
      const att = t < 0.0035 ? Math.sin((t / 0.0035) * (Math.PI * 0.5)) : 1.0;
      let sum = 0;
      for (let m = 0; m < modes.length; m++) {
        const md = modes[m];
        sum += md.a * Math.exp(-t * md.k) * Math.sin(2 * Math.PI * (f * md.r) * t);
      }
      out[i] = sum * att * 0.68;
    }
  });
}

// 6. 紫砂茶汤注水与清泉水滴 Minnaert 气泡声学方程 PCM
function getWaterPourBuffer(ctxAudio) {
  return getNoiseBuffer(ctxAudio, 'water_minnaert_v2', 0.42, (out, len, sr) => {
    const drops = [
      { t0: 0.010, f0: 620, tau: 0.0070, amp: 0.34 },
      { t0: 0.068, f0: 840, tau: 0.0060, amp: 0.40 },
      { t0: 0.132, f0: 720, tau: 0.0065, amp: 0.34 },
      { t0: 0.198, f0: 960, tau: 0.0055, amp: 0.42 },
      { t0: 0.268, f0: 790, tau: 0.0062, amp: 0.36 },
      { t0: 0.338, f0: 1060, tau: 0.0052, amp: 0.30 }
    ];
    for (let i = 0; i < len; i++) {
      const t = i / sr;
      let s = 0;
      for (let d = 0; d < drops.length; d++) {
        const dr = drops[d];
        const dt = t - dr.t0;
        if (dt >= 0 && dt < 0.038) {
          const instPhase = 2 * Math.PI * dr.f0 * dt * (1 + 0.14 * (dt / 0.028));
          const env = (dt < 0.0018 ? dt / 0.0018 : 1.0) * Math.exp(-dt / dr.tau);
          s += Math.sin(instPhase) * env * dr.amp;
        }
      }
      out[i] = s * 0.72;
    }
  });
}

// 7. 高拟真竹管物理气鸣声学 PCM（竹笛 / 洞箫 / 古埙）：
// 吹孔气流粉红噪声（Breath chiff）+ 管腔非线性偶次/奇次谐波 + 细微呼吸微扰与柔和腹颤，彻底杜绝振荡器电子音
function getAcousticWindBuffer(ctxAudio, freq, dur, inst) {
  const f = Math.round(freq * 10) / 10;
  const d = Math.min(dur || 1.6, 4.0);
  const kind = inst || 'flute';
  return getNoiseBuffer(ctxAudio, `acoustic_wind_${kind}_${f}_${d.toFixed(2)}`, d, (out, len, sr) => {
    const isXiao = (kind === 'xiao');
    const isXun = (kind === 'xun');
    let phase = 0;
    let jitter = 0;
    let tremoloPhase = 0;
    let breathFlt = 0;

    for (let i = 0; i < len; i++) {
      const t = i / sr;
      // 微妙自然腹颤（长音 0.45s 之后起颤，频率 4.8Hz，振幅仅 3.5%）
      tremoloPhase += 2 * Math.PI * 4.8 / sr;
      const flutter = (t > 0.45 ? 1.0 + 0.035 * Math.sin(tremoloPhase) : 1.0);

      // 人类吹奏唇部微压波动与音高随机漂移（±3音分微扰，彻底消除机械感）
      jitter = 0.94 * jitter + 0.06 * ((Math.random() * 2 - 1) * 0.0035);
      const instFreq = f * (1 + jitter);
      phase += 2 * Math.PI * instFreq / sr;

      // 吹孔起吹空气摩擦 chiff 与全程管内细微气流声
      const rawNoise = Math.random() * 2 - 1;
      breathFlt = 0.78 * breathFlt + 0.22 * rawNoise;
      const breathAtt = t < 0.07 ? (0.24 * (1 - t / 0.07)) : 0.024;
      const breathChiff = breathFlt * breathAtt;

      // 天然竹管/陶埙谐波分布
      const s1 = Math.sin(phase);
      const s2 = (isXun ? 0.08 : (isXiao ? 0.18 : 0.26)) * Math.sin(phase * 2);
      const s3 = (isXun ? 0.02 : (isXiao ? 0.06 : 0.10)) * Math.sin(phase * 3);
      const s4 = (isXun ? 0.0 : (isXiao ? 0.015 : 0.03)) * Math.sin(phase * 4);

      // 柔和呼吸起音包络（45ms~75ms 柔升）与余音自然气断
      const attTime = isXun ? 0.075 : (isXiao ? 0.065 : 0.045);
      const att = t < attTime ? Math.pow(t / attTime, 1.6) : 1.0;
      const decTime = d - 0.22;
      const dec = t > decTime ? Math.exp(-(t - decTime) * 14) : 1.0;

      out[i] = (s1 + s2 + s3 + s4 + breathChiff) * att * dec * flutter * 0.70;
    }
  });
}

// 8. 高拟真二胡/马头琴弓弦摩擦与蟒皮琴筒共振 PCM：
// 真实马尾弓毛抓弦瞬态摩擦（Rosin bow friction）+ 桐木/蟒皮琴筒亥姆霍兹共鸣，柔韧深情
function getAcousticBowedBuffer(ctxAudio, freq, dur) {
  const f = Math.round(freq * 10) / 10;
  const d = Math.min(dur || 2.0, 4.0);
  return getNoiseBuffer(ctxAudio, `acoustic_erhu_${f}_${d.toFixed(2)}`, d, (out, len, sr) => {
    let phase = 0;
    let bowNoise = 0;
    let bodyRes1 = 0, bodyRes2 = 0;

    for (let i = 0; i < len; i++) {
      const t = i / sr;
      // 运弓吟揉（微揉音 5.2Hz，微幅深度）
      const vibPhase = 2 * Math.PI * 5.2 * t;
      const vib = (t > 0.35 ? 0.005 * Math.sin(vibPhase) : 0);
      phase += 2 * Math.PI * (f * (1 + vib)) / sr;

      // 弓毛松香颗粒抓弦杂音
      bowNoise = 0.85 * bowNoise + 0.15 * (Math.random() * 2 - 1);
      const friction = bowNoise * (t < 0.12 ? 0.18 * (1 - t / 0.12) : 0.025);

      // 丝弦振动非对称锯齿/三角波形
      const pMod = phase % (2 * Math.PI);
      const saw = 1 - (pMod / Math.PI);
      const tri = (pMod < Math.PI) ? (2 * pMod / Math.PI - 1) : (3 - 2 * pMod / Math.PI);
      const rawString = saw * 0.42 + tri * 0.58;

      // 琴筒与蛇皮低通共振
      bodyRes1 = 0.82 * bodyRes1 + (rawString + friction) * 0.18;
      bodyRes2 = 0.72 * bodyRes2 + bodyRes1 * 0.28;

      // 慢弓起伏包络（85ms 柔和慢起，平稳拉弓，自然推挽收弓）
      const att = t < 0.085 ? Math.pow(t / 0.085, 1.4) : 1.0;
      const dec = t > d - 0.25 ? Math.exp(-(t - (d - 0.25)) * 12) : 1.0;

      out[i] = (bodyRes2 * 0.88 + Math.sin(phase) * 0.12) * att * dec * 0.72;
    }
  });
}

// 9. 高拟真笙管簧片和鸣 PCM（纯正铜簧片与竹管自然耦合，温润如玉，彻底消灭锯齿电音）
function getAcousticShengBuffer(ctxAudio, freq, dur) {
  const f = Math.round(freq * 10) / 10;
  const d = Math.min(dur || 2.2, 4.2);
  return getNoiseBuffer(ctxAudio, `acoustic_sheng_${f}_${d.toFixed(2)}`, d, (out, len, sr) => {
    let phase = 0;
    for (let i = 0; i < len; i++) {
      const t = i / sr;
      phase += 2 * Math.PI * f / sr;
      // 簧片与竹管共鸣：基音温润，微弱二倍频与四倍频
      const reed = Math.sin(phase) * 0.84 + Math.sin(phase * 2) * 0.14 + Math.sin(phase * 3) * 0.04;
      const att = t < 0.12 ? (t / 0.12) : 1.0;
      const dec = t > d - 0.28 ? Math.exp(-(t - (d - 0.28)) * 10) : 1.0;
      out[i] = reed * att * dec * 0.65;
    }
  });
}

// ==========================================
// 东方传统乐器与时代音色“丝竹入微”细腻原声回放引擎
// 100% 采用基于真实物理声学（PCM波导/管腔空气动力学/金石模态）原生采样，零合成器振荡器电音
// ==========================================
function playInstrumentTone(instrument, freq, duration, volume, delaySec = 0, customBus = null, exactStartTime = null) {
  const ctxAudio = getAudioContext();
  if (!ctxAudio || !freq) return;
  try {
    const dest = customBus || getMasterAudioBus(ctxAudio);
    if (!dest) return;
    const baseT = (exactStartTime !== null && exactStartTime !== undefined) ? exactStartTime : ctxAudio.currentTime;
    const t = baseT + (delaySec || 0);
    const v = Math.max(0.005, Math.min(0.28, (volume || 0.08) * 0.95));
    const d = Math.max(0.25, Math.min(duration || 1.4, 4.2));

    if (instrument === 'guqin') {
      // 【古琴】：纯正丝弦物理波导散音 + 苍古桐木琴腔共鸣
      const ksBuf = getKarplusStrongBuffer(ctxAudio, freq, Math.min(d, 2.8), 'guqin');
      _triggerPcmBuffer(ctxAudio, dest, ksBuf, v * 0.95, t, 0.001);
    } else if (instrument === 'guzheng' || instrument === 'pipa') {
      // 【古筝 / 琵琶】：“大珠小珠落玉盘”清透晶莹真丝拨弦
      const isPipa = (instrument === 'pipa');
      const ksBuf = getKarplusStrongBuffer(ctxAudio, freq, Math.min(d, 2.2), isPipa ? 'pipa' : 'guzheng');
      _triggerPcmBuffer(ctxAudio, dest, ksBuf, v * (isPipa ? 0.88 : 0.95), t, 0.001);
    } else if (instrument === 'flute' || instrument === 'xiao' || instrument === 'xun') {
      // 【竹笛 / 洞箫 / 古埙】：高拟真竹管气鸣物理声学 PCM（带柔和起吹 air chiff，纯净透亮）
      const windBuf = getAcousticWindBuffer(ctxAudio, freq, d, instrument);
      _triggerPcmBuffer(ctxAudio, dest, windBuf, v * 0.88, t, 0.001);
    } else if (instrument === 'erhu') {
      // 【二胡】：真实马尾弓弦摩擦与蟒皮琴筒亥姆霍兹共振 PCM
      const erhuBuf = getAcousticBowedBuffer(ctxAudio, freq, d);
      _triggerPcmBuffer(ctxAudio, dest, erhuBuf, v * 0.86, t, 0.001);
    } else if (instrument === 'bianzhong' || instrument === 'bianqing') {
      // 【曾侯乙编钟 / 灵璧玉磬】：纯五度协和模态金石清越共鸣
      const mat = instrument === 'bianqing' ? 'jade' : 'bronze';
      const buf = getMetallicModalBuffer(ctxAudio, freq, Math.max(1.2, d), mat);
      _triggerPcmBuffer(ctxAudio, dest, buf, v * 0.85, t, 0.001);
    } else if (instrument === 'sheng' || instrument === 'cello_drone' || instrument === 'pad') {
      // 【笙簧和鸣】：温润簧管自然声韵 PCM，柔和铺底衬托丝竹（无任何锯齿电音）
      const shengBuf = getAcousticShengBuffer(ctxAudio, freq, d);
      _triggerPcmBuffer(ctxAudio, dest, shengBuf, v * 0.72, t, 0.001);
    } else if (instrument === 'musicbox') {
      // 【童年发条八音盒】：温润晶莹的灵璧玉质梳齿清音
      const buf = getMetallicModalBuffer(ctxAudio, freq, Math.min(1.4, d), 'jade');
      _triggerPcmBuffer(ctxAudio, dest, buf, v * 0.68, t, 0.001);
    } else if (instrument === 'drum') {
      // 【中国大堂鼓 / 檀木梆子】：深沉软槌鼓皮下潜与清脆檀木板
      if (freq < 200) {
        const osc = ctxAudio.createOscillator();
        const dG = ctxAudio.createGain();
        osc.type = 'sine';
        osc.frequency.setValueAtTime(92, t);
        osc.frequency.exponentialRampToValueAtTime(46, t + 0.18);
        dG.gain.setValueAtTime(0.0001, t);
        dG.gain.linearRampToValueAtTime(v * 0.55, t + 0.010);
        dG.gain.exponentialRampToValueAtTime(0.0001, t + 0.48);
        osc.connect(dG);
        dG.connect(dest);
        osc.start(t);
        osc.stop(t + 0.50);
      } else {
        const buf = getTactileClickBuffer(ctxAudio, 'wood_block');
        _triggerPcmBuffer(ctxAudio, dest, buf, v * 0.55, t, 0.010);
      }
    } else {
      const buf = getKarplusStrongBuffer(ctxAudio, freq, d, 'guzheng');
      _triggerPcmBuffer(ctxAudio, dest, buf, v * 0.85, t, 0.001);
    }
  } catch (e) { logDebugError("caughtException_" + 9, e); }
}

function playSynthesizedTone(freq, type, duration, volume, attackTime, decayTime) {
  playInstrumentTone('guqin', freq, Math.min(duration || 1.4, 2.2), (volume || 0.05) * 0.80);
}

// ==========================================
// 鲜活时代场景背景音合成引擎 (学堂校园、国营工厂车间、街巷市井、绿皮火车、静谧书斋)
// 所有音高严格对齐当前 BGM 的五声调式与和弦，细腻入微地还原时代空气感
// ==========================================
function detectCurrentEraScene(evtObj) {
  const age = state.age !== undefined ? state.age : 18;
  const yr = state.year || 1992;
  const tr = state.track || '';
  const job = String(state.jobTitle || '');
  const pClass = (state.birthProfile && state.birthProfile.parents && state.birthProfile.parents.classType) || '';
  const evtText = evtObj
    ? `${evtObj.title || ''} ${evtObj.desc || ''} ${evtObj.context || ''}`
    : (state.activeDecisionEvent ? `${state.activeDecisionEvent.title || ''} ${state.activeDecisionEvent.desc || ''}` : '');

  if (/火车|绿皮车|站台|春运|铁道|列车|南下|北上|返乡/.test(evtText)) return 'train';
  if (/学校|学堂|教室|课堂|高考|中考|读书|课本|同窗|少年宫|老师|试卷|大学|校友|温书|题海/.test(evtText)) return 'school';
  if (/工厂|车间|机床|纺织|钢铁|锅炉|工人|技工|厂长|流水线|矿山|工地|汽笛|国企|车床|铁人|技改|制造/.test(evtText)) return 'factory';
  if (/街头|集市|弄堂|胡同|个体户|摆摊|下海|供销社|粮票|百货|商铺|夜市/.test(evtText)) return 'street';

  // 若无特定事件文本，则根据人物当前年龄段、时代与职业赛道自动匹配场景背景音
  if (age >= 6 && age <= 18) return 'school';
  if (age < 6) return 'street';
  if (yr <= 2003 && (tr === 'tech' || tr === 'agri' || /厂|车间|工|矿|建|技|制造/.test(job) || pClass === '工薪模范' || pClass === '地质先锋')) {
    return 'factory';
  }
  if (yr <= 2002 && (tr === 'biz' || tr === 'trade')) return 'street';
  return 'study';
}

// 播放细腻的时代场景环境背景声 (volMul 控制前景事件触发 vs BGM 背景呼吸铺底)
function playEraSceneAmbience(sceneType, volMul = 1.0, customBus = null) {
  const ctxAudio = getAudioContext();
  if (!ctxAudio) return;
  try {
    const dest = customBus || getMasterAudioBus(ctxAudio);
    if (!dest) return;
    const t = ctxAudio.currentTime;
    const v = Math.max(0.01, Math.min(0.35, 0.08 * volMul));
    const pinkBuf = getPinkNoiseBuffer(ctxAudio, 3.0);

    if (sceneType === 'school') {
      // 【学堂与青春校园背景音】：
      // 1. 窗外夏日梧桐微风与远方细腻蝉鸣/晚自习秋虫低吟
      if (pinkBuf) {
        const breeze = ctxAudio.createBufferSource();
        breeze.buffer = pinkBuf;
        const bFlt = ctxAudio.createBiquadFilter();
        const bG = ctxAudio.createGain();
        bFlt.type = 'bandpass';
        bFlt.frequency.setValueAtTime(1650, t);
        bFlt.frequency.linearRampToValueAtTime(2200, t + 1.1);
        bFlt.frequency.exponentialRampToValueAtTime(1400, t + 2.4);
        bFlt.Q.setValueAtTime(3.2, t);
        bG.gain.setValueAtTime(0.0001, t);
        bG.gain.linearRampToValueAtTime(v * 0.42, t + 0.45);
        bG.gain.exponentialRampToValueAtTime(0.0001, t + 2.4);
        breeze.connect(bFlt);
        bFlt.connect(bG);
        bG.connect(dest);
        breeze.start(t);
        breeze.stop(t + 2.5);
      }
      // 2. 教室同窗轻轻翻动课本书页 + 讲台粉笔板书微叩
      _triggerPcmBuffer(ctxAudio, dest, getPaperFlipBuffer(ctxAudio, false), v * 0.75, t + 0.08, 0.04);
      _triggerPcmBuffer(ctxAudio, dest, getTactileClickBuffer(ctxAudio, 'chalk'), v * 0.55, t + 0.24, 0.05);
      _triggerPcmBuffer(ctxAudio, dest, getTactileClickBuffer(ctxAudio, 'chalk'), v * 0.42, t + 0.33, 0.06);
      // 3. 远方教学楼传来的悠扬上下课预备钟声（严格对齐当前 BGM 五声调式 5 -> 3 -> 1）
      const bell1 = getHarmonizedFreq(5, 2.0);
      const bell2 = getHarmonizedFreq(4, 2.0);
      const bell3 = getHarmonizedFreq(2, 2.0);
      _triggerPcmBuffer(ctxAudio, dest, getMetallicModalBuffer(ctxAudio, bell1, 1.1, 'jade'), v * 0.62, t + 0.15, 0.002);
      _triggerPcmBuffer(ctxAudio, dest, getMetallicModalBuffer(ctxAudio, bell2, 1.1, 'jade'), v * 0.52, t + 0.48, 0.002);
      _triggerPcmBuffer(ctxAudio, dest, getMetallicModalBuffer(ctxAudio, bell3, 1.4, 'bronze'), v * 0.56, t + 0.82, 0.002);
    } else if (sceneType === 'factory') {
      // 【八九十年代国营大厂与车间背景音】：远景低沉规律的车床机械律动与蒸汽微息，温和内敛绝不喧宾夺主
      [0, 0.48, 0.96].forEach((dl, idx) => {
        const loomBuf = getTactileClickBuffer(ctxAudio, idx === 0 ? 'wood_block' : 'abacus_lo');
        _triggerPcmBuffer(ctxAudio, dest, loomBuf, v * 0.28, t + dl, 0.015);
      });
      if (pinkBuf) {
        const steam = ctxAudio.createBufferSource();
        steam.buffer = pinkBuf;
        const sFlt = ctxAudio.createBiquadFilter();
        const sG = ctxAudio.createGain();
        sFlt.type = 'lowpass';
        sFlt.frequency.setValueAtTime(320, t);
        sG.gain.setValueAtTime(0.0001, t);
        sG.gain.linearRampToValueAtTime(v * 0.16, t + 0.25);
        sG.gain.exponentialRampToValueAtTime(0.0001, t + 1.6);
        steam.connect(sFlt);
        sFlt.connect(sG);
        sG.connect(dest);
        steam.start(t);
        steam.stop(t + 1.7);
      }
    } else if (sceneType === 'street') {
      // 【八九十年代街巷弄堂与市井烟火背景音】：
      // 远方胡同掠过的二八大杠清脆车铃 + 供销社算盘拨珠 + 弄堂穿堂微风
      const bellF1 = getHarmonizedFreq(6, 2.0);
      const bellF2 = getHarmonizedFreq(5, 2.0);
      _triggerPcmBuffer(ctxAudio, dest, getMetallicModalBuffer(ctxAudio, bellF1, 0.35, 'jade'), v * 0.55, t + 0.04, 0.01);
      _triggerPcmBuffer(ctxAudio, dest, getMetallicModalBuffer(ctxAudio, bellF2, 0.35, 'coin'), v * 0.45, t + 0.10, 0.01);
      _triggerPcmBuffer(ctxAudio, dest, getTactileClickBuffer(ctxAudio, 'abacus_lo'), v * 0.52, t + 0.28, 0.02);
      _triggerPcmBuffer(ctxAudio, dest, getTactileClickBuffer(ctxAudio, 'abacus_hi'), v * 0.44, t + 0.35, 0.02);
    } else if (sceneType === 'train') {
      // 【年代绿皮火车与远行站台背景音】：铁轨接缝“哐当—哐当”节拍 + 远方汽笛共鸣
      const railBuf = getTactileClickBuffer(ctxAudio, 'wood_block');
      [0.0, 0.13, 0.52, 0.65, 1.04, 1.17].forEach((dl, i) => {
        _triggerPcmBuffer(ctxAudio, dest, railBuf, v * (i % 2 === 0 ? 0.65 : 0.48), t + dl, 0.01);
      });
      const hornF = getHarmonizedFreq(3, 1.0);
      playInstrumentTone('xiao', hornF, 1.4, v * 0.65, 0.18, dest);
      playInstrumentTone('xiao', hornF * 1.5, 1.4, v * 0.45, 0.20, dest);
    } else {
      // 【静谧书斋、茶寮与案头背景音】：竹林微风 + 红泥小炉茶水微沸 + 檐角玉磬微吟
      _triggerPcmBuffer(ctxAudio, dest, getWaterPourBuffer(ctxAudio), v * 0.58, t + 0.05, 0.02);
      const chimeF = getHarmonizedFreq(6, 2.0);
      _triggerPcmBuffer(ctxAudio, dest, getMetallicModalBuffer(ctxAudio, chimeF, 1.2, 'jade'), v * 0.42, t + 0.22, 0.005);
    }
  } catch (e) { /* ignore */ }
}

