function getCurrentBgmSuite() {
  const age = (typeof state !== 'undefined' && state && state.age !== undefined) ? state.age : 18;
  const yr = (typeof state !== 'undefined' && state && state.year) ? state.year : 1992;
  if (age < 16) return ERA_BGM_SUITES.childhood;
  if (yr < 2000) return ERA_BGM_SUITES.early;
  if (yr < 2013) return ERA_BGM_SUITES.mid;
  return ERA_BGM_SUITES.modern;
}

// 乐器立体声声相定位与空间景深节点缓存
const _pannerNodes = new Map();
function getSpatialInstrumentBus(ctxAudio, inst, parentBus) {
  if (!ctxAudio || !parentBus) return parentBus;
  // 立体声声像声场分布：
  // 洞箫/竹笛 (主旋律)：中央略偏左 (-0.12)，清晰突出，前瞻景深
  // 古筝 (流水琶音)：偏右 (+0.36)，灵动流淌
  // 琵琶 (弹挑加花)：偏左 (+0.28)，颗粒饱满
  // 古琴 (低音地基)：中央微厚重 (-0.05)，宽广沉稳
  // 编钟/磬 (远景鸣响)：深远偏右 (+0.42)，空间长余韵
  // 八音盒 (清脆泛音)：微右 (+0.22)
  // 二胡 (副旋律对位)：偏左 (-0.30)
  // 笙/排箫 (和声铺底)：立体声拓宽 (0.0)
  const panMap = {
    xiao: -0.12,
    flute: -0.10,
    guzheng: 0.38,
    pipa: -0.32,
    guqin: -0.04,
    bianzhong: 0.44,
    bianqing: 0.35,
    musicbox: 0.22,
    erhu: -0.28,
    sheng: 0.05
  };
  const panVal = panMap[inst] !== undefined ? panMap[inst] : 0.0;
  if (typeof ctxAudio.createStereoPanner === 'function') {
    const key = inst + '_' + (parentBus === getMasterAudioBus(ctxAudio) ? 'master' : 'bgm');
    let pNode = _pannerNodes.get(key);
    if (!pNode || pNode._ctx !== ctxAudio) {
      try {
        pNode = ctxAudio.createStereoPanner();
        pNode.pan.setValueAtTime(panVal, ctxAudio.currentTime || 0);
        pNode._ctx = ctxAudio;
        pNode.connect(parentBus);
        _pannerNodes.set(key, pNode);
      } catch (e) {
        return parentBus;
      }
    }
    return pNode;
  }
  return parentBus;
}

// 调度单拍音乐事件（Web Audio 精确时钟前瞻调度）
// 构建真正的“低音地基 + 和声琶音织体 + 副旋律呼应 + 主旋律高歌”四层立体声乐层次
function scheduleBgmBeat(exactTime, beatIdx, suite) {
  const ctxAudio = getAudioContext();
  if (!ctxAudio) return;
  const bgmBus = getBgmSubBus(ctxAudio);
  if (!bgmBus) return;

  const stepInPhrase = beatIdx % suite.totalBeats;
  const barIdx = Math.floor(stepInPhrase / 4);
  const beatInBar = stepInPhrase % 4;
  const chord = suite.chords[barIdx % suite.chords.length] || suite.chords[0];

  // ----------------------------------------------------
  // 第一层【地基低音层 (Bass & Foundation)】：深沉古琴定音 + 笙簧温润微和声铺底
  // ----------------------------------------------------
  if (beatInBar === 0) {
    const rootF = chord[0] * (chord[0] < 80 ? 2.0 : (chord[0] > 180 ? 0.5 : 1.0));
    const bassBus = getSpatialInstrumentBus(ctxAudio, 'guqin', bgmBus);
    // 拍头：古琴浑厚散音根音，深沉筑底
    playInstrumentTone('guqin', rootF, suite.beatSec * 3.2, 0.042, 0, bassBus, exactTime);

    // 句首与段落转折小节（小节 0, 4, 8, 12）：远景金石编钟或玉磬鸣响，破空而来，荡气回肠
    if (barIdx % 4 === 0) {
      const isModernOrChild = (suite === ERA_BGM_SUITES.modern || suite === ERA_BGM_SUITES.childhood);
      const chimeInst = isModernOrChild ? 'bianqing' : 'bianzhong';
      const chimeBus = getSpatialInstrumentBus(ctxAudio, chimeInst, bgmBus);
      playInstrumentTone(chimeInst, chord[0] * (isModernOrChild ? 2.5 : 1.5), suite.beatSec * 3.5, 0.032, 0, chimeBus, exactTime);
    }
  }

  // ----------------------------------------------------
  // 第二层【中景和声织体与流水琶音层 (Harmonic Texture & Arpeggios)】
  // 古筝、琵琶与八音盒的细腻弹挑，在 1、2、3 拍流动，营造空山流水、移步换景的生动层次
  // ----------------------------------------------------
  const arpInst = (suite === ERA_BGM_SUITES.childhood)
    ? 'musicbox'
    : (suite === ERA_BGM_SUITES.modern ? 'pipa' : 'guzheng');
  const arpBus = getSpatialInstrumentBus(ctxAudio, arpInst, bgmBus);

  if (beatInBar === 1) {
    // 第 1 拍弱拍：和弦三音轻声拂拭
    const f1 = chord[1] || chord[0] * 1.25;
    playInstrumentTone(arpInst, f1, suite.beatSec * 1.4, 0.022, 0, arpBus, exactTime);
  } else if (beatInBar === 2) {
    // 第 2 拍次强拍（眼）：和弦五音或八度流水拨弦，清澈灵动
    const f2 = chord[2] || chord[0] * 1.5;
    playInstrumentTone(arpInst, f2, suite.beatSec * 1.8, 0.028, 0, arpBus, exactTime);
    // 半拍后轻挑装饰音（流水花指感）
    const fDecor = chord[3] || chord[2] * 1.25;
    playInstrumentTone(arpInst, fDecor, suite.beatSec * 0.9, 0.016, suite.beatSec * 0.5, arpBus, exactTime);
  } else if (beatInBar === 3) {
    // 第 3 拍弱拍：高音轻轻悬停，为下一小节主干音留白引路
    const f3 = chord[3] || chord[1] * 2.0;
    playInstrumentTone(arpInst, f3, suite.beatSec * 1.1, 0.020, 0, arpBus, exactTime);
  }

  // ----------------------------------------------------
  // 第三层【对位呼应层 (Counterpoint Echo)】
  // 当主旋律长音留白或间歇时，副旋律乐器（二胡/洞箫/古筝）轻声对话，形成中式音乐经典“你问我答、丝竹相和”
  // ----------------------------------------------------
  if (suite === ERA_BGM_SUITES.early || suite === ERA_BGM_SUITES.mid) {
    // 奋斗与千禧年代：竹笛为主，古筝在第 2.5 拍与小节尾轻声点缀呼应
    if (beatInBar === 3) {
      const echoF = chord[0] * 2.0;
      const echoBus = getSpatialInstrumentBus(ctxAudio, 'pipa', bgmBus);
      playInstrumentTone('pipa', echoF, suite.beatSec * 0.9, 0.024, suite.beatSec * 0.5, echoBus, exactTime);
    }
  } else if (suite === ERA_BGM_SUITES.modern) {
    // 当代与沧海沉思：古琴低语为主，二胡在偶数小节第 2 拍弱奏呼应
    if (barIdx % 2 === 1 && beatInBar === 2) {
      const erhuF = chord[1] * 1.5;
      const erhuBus = getSpatialInstrumentBus(ctxAudio, 'erhu', bgmBus);
      playInstrumentTone('erhu', erhuF, suite.beatSec * 2.2, 0.026, suite.beatSec * 0.25, erhuBus, exactTime);
    }
  }

  // ----------------------------------------------------
  // 第四层【前景主旋律高光层 (Foreground Lead Melody)】
  // 竹笛、洞箫、古琴、八音盒，独立空间定位与呼吸力度，歌唱性主线叙事
  // ----------------------------------------------------
  if (suite.notes && suite.notes.length) {
    for (let i = 0; i < suite.notes.length; i++) {
      const note = suite.notes[i];
      if (Math.abs(note.beat - stepInPhrase) < 0.01) {
        const leadBus = getSpatialInstrumentBus(ctxAudio, note.inst, bgmBus);
        playInstrumentTone(
          note.inst,
          note.freq,
          note.dur * suite.beatSec,
          note.vol * 1.08,
          0,
          leadBus,
          exactTime
        );
      }
    }
  }
}

// 高精度前瞻调度器循环（35ms 轮询，保持未来 250ms 音频缓冲区满载）
function bgmSchedulerLoop() {
  if (!bgmPlaying || !bgmEnabled) return;
  const ctxAudio = getAudioContext();
  if (!ctxAudio) return;

  const suite = getCurrentBgmSuite();
  const lookaheadSec = 0.25;

  while (bgmNextNoteTime < ctxAudio.currentTime + lookaheadSec) {
    scheduleBgmBeat(bgmNextNoteTime, bgmBeatCount, suite);
    bgmNextNoteTime += suite.beatSec;
    bgmBeatCount++;
    bgmBeat = bgmBeatCount;
  }
}

function startBGM() {
  if (bgmPlaying) return;
  const ctxAudio = getAudioContext();
  if (!ctxAudio) return;
  bgmPlaying = true;
  bgmBeatCount = 0;
  bgmBeat = 0;
  bgmNextNoteTime = ctxAudio.currentTime + 0.06;
  if (bgmLookaheadTimer) clearInterval(bgmLookaheadTimer);
  bgmLookaheadTimer = setInterval(bgmSchedulerLoop, 35);
}

function stopBGM() {
  bgmPlaying = false;
  if (bgmLookaheadTimer) {
    clearInterval(bgmLookaheadTimer);
    bgmLookaheadTimer = null;
  }
}

// 兼容单拍调试与历史调用接口
function bgmTick() {
  bgmSchedulerLoop();
}

const _sfxLastPlayTime = {};

function playSoundEffect(type) {
  if (!sfxEnabled) return;
  const now = Date.now();
  const minGap = (type === 'click' || type === 'abacus' || type === 'abacus_bead_click') ? 45 : 120;
  if (_sfxLastPlayTime[type] && (now - _sfxLastPlayTime[type] < minGap)) {
    return;
  }
  _sfxLastPlayTime[type] = now;

  const ctxAudio = getAudioContext();
  if (!ctxAudio) return;

  try {
    const t = ctxAudio.currentTime;
    const master = getMasterAudioBus(ctxAudio);
    if (!master) return;

    // ==========================================
    // 零、 鲜活时代场景背景音直通触发 (学堂校园、国营工厂车间、街巷市井、绿皮火车、书斋茶寮)
    // 自然柔和融入背景，绝不粗暴强行压低背景音乐
    // ==========================================
    if (type === 'school_ambience' || type === 'campus_breeze') {
      playEraSceneAmbience('school', 0.65, master);
      return;
    }
    if (type === 'factory_ambience' || type === 'factory_whistle' || type === 'workshop_loom') {
      playEraSceneAmbience('factory', 0.65, master);
      return;
    }
    if (type === 'street_ambience' || type === 'lane_breeze') {
      playEraSceneAmbience('street', 0.65, master);
      return;
    }
    if (type === 'train_ambience') {
      playEraSceneAmbience('train', 0.65, master);
      return;
    }
    if (type === 'study_ambience') {
      playEraSceneAmbience('study', 0.65, master);
      return;
    }

    // ==========================================
    // 一、 细腻器物触感与文房雅事纯粹拟音 (不夹杂额外乐音，确保与紧随其后的丝竹音效 100% 和谐共存)
    // ==========================================
    if (type === 'click') {
      // 温润紫檀木轻触（轻盈内敛，绝不抢戏）
      _triggerPcmBuffer(ctxAudio, master, getTactileClickBuffer(ctxAudio, 'wood_click'), 0.14, t, 0.025);
      return;
    }
    if (type === 'abacus' || type === 'abacus_bead_click') {
      // 老式红木算盘拨珠细腻三连拨
      _triggerPcmBuffer(ctxAudio, master, getTactileClickBuffer(ctxAudio, 'abacus_lo'), 0.17, t, 0.02);
      _triggerPcmBuffer(ctxAudio, master, getTactileClickBuffer(ctxAudio, 'abacus_hi'), 0.15, t + 0.044, 0.02);
      _triggerPcmBuffer(ctxAudio, master, getTactileClickBuffer(ctxAudio, 'abacus_lo'), 0.12, t + 0.092, 0.025);
      return;
    }
    if (type === 'pocket_watch_tick') {
      // 老上海机械怀表擒纵轮细腻滴答
      _triggerPcmBuffer(ctxAudio, master, getTactileClickBuffer(ctxAudio, 'watch_1'), 0.14, t, 0.01);
      _triggerPcmBuffer(ctxAudio, master, getTactileClickBuffer(ctxAudio, 'watch_2'), 0.11, t + 0.14, 0.01);
      _triggerPcmBuffer(ctxAudio, master, getTactileClickBuffer(ctxAudio, 'watch_1'), 0.10, t + 0.28, 0.01);
      return;
    }
    if (type === 'dice') {
      // 骨质色子落入青花瓷碗细腻连跳（瓷碗泛音严格对齐当前调式五音）
      const dBuf = getTactileClickBuffer(ctxAudio, 'dice');
      [0, 0.055, 0.105, 0.148, 0.182].forEach((dl, i) => {
        _triggerPcmBuffer(ctxAudio, master, dBuf, 0.19 * Math.pow(0.76, i), t + dl, 0.05);
      });
      const bowlFreq = getHarmonizedFreq(6, 2.0);
      _triggerPcmBuffer(ctxAudio, master, getMetallicModalBuffer(ctxAudio, bowlFreq, 0.38, 'jade'), 0.08, t + 0.06, 0.01);
      return;
    }
    if (type === 'wooden_shuttle_loom_clack' || type === 'bamboo_dipper_water_clack' || type === 'mortar_pestle_grind') {
      // 织布木梭 / 竹筒水车 / 药臼捣药
      _triggerPcmBuffer(ctxAudio, master, getTactileClickBuffer(ctxAudio, 'wood_block'), 0.19, t, 0.02);
      _triggerPcmBuffer(ctxAudio, master, getTactileClickBuffer(ctxAudio, 'abacus_lo'), 0.14, t + 0.11, 0.025);
      if (type === 'bamboo_dipper_water_clack') {
        _triggerPcmBuffer(ctxAudio, master, getWaterPourBuffer(ctxAudio), 0.18, t + 0.08, 0.025);
      }
      return;
    }
    if (type === 'stamp' || type === 'seal_stamp_heavy' || type === 'ink_seal_thud' || type === 'wax_seal_stamp' || type === 'rubbing_pad_tap') {
      // 寿山石印章温润落案（纯物理印石与红木书案低频共鸣，不叠加强制钟声以免与紧随其后的器乐音效撞车）
      _triggerPcmBuffer(ctxAudio, master, getSealStampBuffer(ctxAudio), type === 'rubbing_pad_tap' ? 0.18 : 0.28, t, 0.018);
      return;
    }
    if (
      type === 'paper' || type === 'paper_rustle' ||
      type === 'silk_scroll_unfurl' || type === 'blueprint_unroll_foley' ||
      type === 'brush_ink_whisper' || type === 'brush_stroke_foley' ||
      type === 'pencil_sketch_rustle' || type === 'ink_grinding_whisper' ||
      type === 'silk_thread_shimmer' || type === 'ink_splash'
    ) {
      // 宣纸轻拈翻页 / 丝帛展开 / 狼毫运笔微响（双阶段细腻纸张纤维声）
      const isScroll = (type === 'silk_scroll_unfurl' || type === 'blueprint_unroll_foley' || type === 'ink_splash');
      _triggerPcmBuffer(ctxAudio, master, getPaperFlipBuffer(ctxAudio, isScroll), 0.20, t, 0.03);
      if (isScroll) {
        _triggerPcmBuffer(ctxAudio, master, getPaperFlipBuffer(ctxAudio, false), 0.14, t + 0.11, 0.04);
      }
      return;
    }
    if (type === 'tea' || type === 'tea_pour' || type === 'tea_pour_trickle' || type === 'tea_water_pour' || type === 'inkstone_jade_water_drip') {
      // 紫砂烹茶 / 砚池滴水：清润水滴气泡 + 同调青花瓷盖轻碰
      _triggerPcmBuffer(ctxAudio, master, getWaterPourBuffer(ctxAudio), 0.24, t, 0.025);
      const cupFreq = getHarmonizedFreq(5, 2.0);
      _triggerPcmBuffer(ctxAudio, master, getMetallicModalBuffer(ctxAudio, cupFreq, 0.42, 'jade'), 0.08, t + 0.18, 0.008);
      return;
    }

    // ==========================================
    // 二、 80/90/00年代鲜活时代记忆拟音 (全部严格对齐当前 BGM 五声调式，清脆且和谐)
    // ==========================================
    if (type === 'bicycle_bell') {
      // 80/90年代永久/凤凰牌二八大杠清脆双车铃（铃碗音高锁定当前调式高音徵与羽，和谐悦耳）
      const bellHi = getMetallicModalBuffer(ctxAudio, getHarmonizedFreq(6, 2.0), 0.34, 'jade');
      const bellLo = getMetallicModalBuffer(ctxAudio, getHarmonizedFreq(5, 2.0), 0.30, 'coin');
      [0, 0.050, 0.100, 0.22, 0.270, 0.320].forEach((dl, idx) => {
        _triggerPcmBuffer(ctxAudio, master, idx % 2 === 0 ? bellHi : bellLo, 0.15, t + dl, 0.006);
      });
      return;
    }
    if (type === 'pager_beep') {
      // 90年代摩托罗拉寻呼机/BP机经典双连蜂鸣（锁定当前调式高八度宫音，温润不刺耳）
      const beepF = getHarmonizedFreq(7, 2.0);
      [0, 0.095, 0.28, 0.375].forEach(dl => {
        const osc = ctxAudio.createOscillator();
        const g = ctxAudio.createGain();
        osc.type = 'sine';
        osc.frequency.setValueAtTime(beepF, t + dl);
        g.gain.setValueAtTime(0.0001, t + dl);
        g.gain.linearRampToValueAtTime(0.075, t + dl + 0.006);
        g.gain.setValueAtTime(0.068, t + dl + 0.052);
        g.gain.exponentialRampToValueAtTime(0.0001, t + dl + 0.070);
        osc.connect(g);
        g.connect(master);
        osc.start(t + dl);
        osc.stop(t + dl + 0.075);
      });
      return;
    }
    if (type === 'phone') {
      // 老式机械双铜碗座机振铃（双铃碗严格构成当前调式纯五度协和音程）
      const b1 = getMetallicModalBuffer(ctxAudio, getHarmonizedFreq(4, 2.0), 0.18, 'coin');
      const b2 = getMetallicModalBuffer(ctxAudio, getHarmonizedFreq(6, 2.0), 0.18, 'jade');
      for (let i = 0; i < 6; i++) {
        _triggerPcmBuffer(ctxAudio, master, i % 2 === 0 ? b1 : b2, 0.13, t + i * 0.046, 0.006);
      }
      return;
    }
    if (type === 'dial_up') {
      // 90年代末拨号上网记忆（和谐五声按键音 + 经典握手弦音）
      [0, 0.09, 0.18].forEach((dl, idx) => {
        const f1 = getHarmonizedFreq(idx + 2, 1.0);
        const f2 = getHarmonizedFreq(idx + 5, 2.0);
        [f1, f2].forEach(f => {
          const osc = ctxAudio.createOscillator();
          const g = ctxAudio.createGain();
          osc.type = 'sine';
          osc.frequency.setValueAtTime(f, t + dl);
          g.gain.setValueAtTime(0.05, t + dl);
          g.gain.exponentialRampToValueAtTime(0.0001, t + dl + 0.07);
          osc.connect(g);
          g.connect(master);
          osc.start(t + dl);
          osc.stop(t + dl + 0.075);
        });
      });
      playInstrumentTone('musicbox', getHarmonizedFreq(5, 2.0), 0.65, 0.07, 0.28, master);
      playInstrumentTone('musicbox', getHarmonizedFreq(7, 2.0), 0.85, 0.06, 0.38, master);
      return;
    }
    if (type === 'school_bell') {
      // 学堂手摇铜铃与校园钟声（调用校园微环境声景 + 同调铜铃）
      duckBgmForSfx(ctxAudio, 1.5, 0.45);
      playEraSceneAmbience('school', 1.0, master);
      return;
    }
    if (type === 'typewriter') {
      // 年代机械打字机清脆连击 + 换行回车同调铜铃
      const kBuf = getTactileClickBuffer(ctxAudio, 'abacus_hi');
      _triggerPcmBuffer(ctxAudio, master, kBuf, 0.16, t, 0.03);
      _triggerPcmBuffer(ctxAudio, master, kBuf, 0.14, t + 0.068, 0.04);
      _triggerPcmBuffer(ctxAudio, master, kBuf, 0.15, t + 0.135, 0.03);
      _triggerPcmBuffer(ctxAudio, master, getMetallicModalBuffer(ctxAudio, getHarmonizedFreq(6, 2.0), 0.50, 'jade'), 0.12, t + 0.21, 0.004);
      return;
    }
    if (type === 'tin_tap') {
      // 老式红双喜搪瓷茶缸磕碰实木桌面
      _triggerPcmBuffer(ctxAudio, master, getTactileClickBuffer(ctxAudio, 'wood_block'), 0.17, t, 0.02);
      _triggerPcmBuffer(ctxAudio, master, getMetallicModalBuffer(ctxAudio, getHarmonizedFreq(3, 1.0), 0.26, 'coin'), 0.13, t + 0.008, 0.01);
      return;
    }
    if (type === 'coin' || type === 'coin_cascade' || type === 'toast' || type === 'porcelain_ping_resonance') {
      if (type === 'toast' || type === 'porcelain_ping_resonance') {
        // 欢聚碰杯 / 青瓷清鸣（纯五度协和双盏清音）
        _triggerPcmBuffer(ctxAudio, master, getMetallicModalBuffer(ctxAudio, getHarmonizedFreq(5, 2.0), 0.60, 'jade'), 0.16, t, 0.005);
        _triggerPcmBuffer(ctxAudio, master, getMetallicModalBuffer(ctxAudio, getHarmonizedFreq(7, 2.0), 0.55, 'jade'), 0.13, t + 0.07, 0.005);
      } else {
        // 金玉满堂：银元/铜钱按当前调式五声上行清脆落盘
        const degs = type === 'coin_cascade' ? [4, 5, 6, 7] : [5, 7];
        degs.forEach((dg, idx) => {
          const cf = getHarmonizedFreq(dg, 4.0);
          _triggerPcmBuffer(ctxAudio, master, getMetallicModalBuffer(ctxAudio, cf, 0.34, 'coin'), 0.15 - idx * 0.02, t + idx * 0.058, 0.008);
        });
      }
      return;
    }

    // ==========================================
    // 三、 东方传统礼乐、丝竹画卷与山水意境声景
    // 全部经由同调和声量化器 (getHarmonizedFreq) + 双音效自动对位排期 (getHarmoniousSfxSchedule) + BGM 侧链闪避
    // ==========================================
    const tonalBus = acquireTonalSfxBus(ctxAudio) || master;
    const sched = getHarmoniousSfxSchedule();
    const dOff = sched.delayOffset;
    const degOff = sched.degreeShift;
    const vMul = sched.volScale;
    const activeChord = getCurrentActiveChord();
    if (type === 'fanfare' || type === 'ceremony' || type === 'victory' || type === 'grand_achievement') {
      duckBgmForSfx(ctxAudio, 1.2 + dOff, 0.72);
    }

    if (type === 'alert' || type === 'war' || type === 'heartbeat_dilemma' || type === 'war_drum_resonance' || type === 'battle_drum_roll') {
      // 【风云低回·古琴沉雷警示】：锁定当前和弦低音根音与五度音，深沉内敛绝不刺耳
      const lowRoot = activeChord[0] || getHarmonizedFreq(0, 0.5);
      const lowFifth = activeChord[1] || getHarmonizedFreq(2, 0.5);
      playInstrumentTone('drum', 88, 0.55, 0.12 * vMul, dOff, tonalBus);
      playInstrumentTone('guqin', lowFifth, 1.45, 0.11 * vMul, dOff + 0.03, tonalBus);
      playInstrumentTone('guqin', lowRoot, 1.85, 0.12 * vMul, dOff + 0.18, tonalBus);
      return;
    }

    if (
      type === 'fanfare' || type === 'triumph_brass' || type === 'bugle_call_brass' ||
      type === 'horn_call_majestic' || type === 'state_orchestra_fanfare' ||
      type === 'court_hymn_peace' || type === 'spark' || type === 'crowd_cheer'
    ) {
      // 【金石丝竹同调华彩】：在当前 BGM 调式和弦上绽放五声琶音与竹笛长音
      const rootF = activeChord[1] || getHarmonizedFreq(2 + degOff, 1.0);
      playInstrumentTone('bianzhong', rootF, 2.2, 0.085 * vMul, dOff, tonalBus);
      playInstrumentTone('pad', rootF * 1.5, 2.0, 0.065 * vMul, dOff + 0.03, tonalBus);
      [2, 3, 4, 5, 7].forEach((dg, idx) => {
        const f = getHarmonizedFreq(dg + degOff, 1.0);
        playInstrumentTone('guzheng', f, 1.4, (0.085 - idx * 0.008) * vMul, dOff + idx * 0.068, tonalBus);
      });
      playInstrumentTone('flute', getHarmonizedFreq(7 + degOff, 1.0), 1.55, 0.082 * vMul, dOff + 0.28, tonalBus);
      return;
    }

    if (
      type === 'guqin_deep_reverie' || type === 'guqin_flowing_water' ||
      type === 'guqin_water_flow' || type === 'guqin_zen_pluck'
    ) {
      // 【高山流水·古琴吟猱泛音画卷】：当前和弦根音铺底 + 同调古琴流水三叠 + 清泉微滴
      playInstrumentTone('cello_drone', activeChord[0] || getHarmonizedFreq(0, 0.5), 2.4, 0.065 * vMul, dOff, tonalBus);
      playInstrumentTone('guqin', getHarmonizedFreq(2 + degOff, 1.0), 2.0, 0.105 * vMul, dOff + 0.02, tonalBus);
      playInstrumentTone('guqin', getHarmonizedFreq(4 + degOff, 1.0), 1.9, 0.095 * vMul, dOff + 0.22, tonalBus);
      playInstrumentTone('guqin', getHarmonizedFreq(5 + degOff, 1.0), 2.2, 0.105 * vMul, dOff + 0.44, tonalBus);
      if (type === 'guqin_flowing_water' || type === 'guqin_water_flow') {
        _triggerPcmBuffer(ctxAudio, tonalBus, getWaterPourBuffer(ctxAudio), 0.15 * vMul, t + dOff + 0.10, 0.02);
      }
      return;
    }

    if (
      type === 'dizi_soaring_melody' || type === 'dizi_xiao_ensemble' ||
      type === 'luan_flute_ethereal' || type === 'bamboo_flute'
    ) {
      // 【姑苏春晓·竹笛洞箫云端和鸣】：同调笙簧衬底 + 竹笛与洞箫柔美五度呼应
      playInstrumentTone('pad', activeChord[1] || getHarmonizedFreq(2, 1.0), 2.2, 0.06 * vMul, dOff, tonalBus);
      playInstrumentTone('guzheng', getHarmonizedFreq(3 + degOff, 1.0), 1.5, 0.07 * vMul, dOff + 0.02, tonalBus);
      playInstrumentTone('flute', getHarmonizedFreq(5 + degOff, 1.0), 1.2, 0.09 * vMul, dOff + 0.06, tonalBus);
      playInstrumentTone('xiao', getHarmonizedFreq(7 + degOff, 1.0), 1.6, 0.085 * vMul, dOff + 0.28, tonalBus);
      return;
    }

    if (type === 'xiao_reverie' || type === 'dongxiao_whisper') {
      // 【平沙落雁·洞箫幽谷独白】：同调古琴散音承托 + 洞箫温润气韵长音
      playInstrumentTone('guqin', activeChord[1] || getHarmonizedFreq(1 + degOff, 1.0), 2.2, 0.08 * vMul, dOff, tonalBus);
      playInstrumentTone('xiao', getHarmonizedFreq(4 + degOff, 1.0), 1.4, 0.095 * vMul, dOff + 0.06, tonalBus);
      playInstrumentTone('xiao', getHarmonizedFreq(5 + degOff, 1.0), 1.8, 0.09 * vMul, dOff + 0.34, tonalBus);
      return;
    }

    if (type === 'xun_ancient_clay') {
      // 【太古遗音·陶埙苍茫咏叹】
      playInstrumentTone('cello_drone', activeChord[0] || getHarmonizedFreq(0, 0.5), 2.4, 0.07 * vMul, dOff, tonalBus);
      playInstrumentTone('xun', getHarmonizedFreq(3 + degOff, 1.0), 1.5, 0.10 * vMul, dOff + 0.04, tonalBus);
      playInstrumentTone('xun', getHarmonizedFreq(2 + degOff, 1.0), 2.0, 0.095 * vMul, dOff + 0.38, tonalBus);
      return;
    }

    if (type === 'erhu_sorrow') {
      // 【江河岁月·二胡深情揉弦】
      playInstrumentTone('guqin', activeChord[1] || getHarmonizedFreq(1, 1.0), 2.2, 0.075 * vMul, dOff, tonalBus);
      playInstrumentTone('erhu', getHarmonizedFreq(4 + degOff, 1.0), 1.3, 0.095 * vMul, dOff + 0.04, tonalBus);
      playInstrumentTone('erhu', getHarmonizedFreq(5 + degOff, 1.0), 1.1, 0.09 * vMul, dOff + 0.30, tonalBus);
      playInstrumentTone('erhu', getHarmonizedFreq(3 + degOff, 1.0), 1.8, 0.10 * vMul, dOff + 0.56, tonalBus);
      return;
    }

    if (type === 'pipa_spring_blossoms' || type === 'pipa_tremolo' || type === 'guzheng_cascade' || type === 'guzheng_harmonic_pluck') {
      // 【春江花月夜·琵琶轮指与古筝流水刮奏】：严格按当前调式五声级进流淌
      const inst = (type === 'guzheng_cascade' || type === 'guzheng_harmonic_pluck') ? 'guzheng' : 'pipa';
      const degList = type === 'guzheng_harmonic_pluck' ? [3, 5, 7] : [2, 3, 4, 5, 6];
      degList.forEach((dg, idx) => {
        playInstrumentTone(inst, getHarmonizedFreq(dg + degOff, 1.0), 1.35, (0.09 - idx * 0.008) * vMul, dOff + idx * 0.062, tonalBus);
      });
      playInstrumentTone('xiao', getHarmonizedFreq(5 + degOff, 1.0), 1.6, 0.065 * vMul, dOff + 0.22, tonalBus);
      return;
    }

    if (type === 'sheng_harmonious_reed') {
      // 【凤鸣朝阳·笙簧传统五度和音】
      const fBase = getHarmonizedFreq(3 + degOff, 1.0);
      const fNext = getHarmonizedFreq(4 + degOff, 1.0);
      playInstrumentTone('sheng', fBase, 1.9, 0.08 * vMul, dOff, tonalBus);
      playInstrumentTone('sheng', fBase * 1.5, 1.9, 0.07 * vMul, dOff + 0.02, tonalBus);
      playInstrumentTone('sheng', fNext, 2.1, 0.08 * vMul, dOff + 0.30, tonalBus);
      playInstrumentTone('sheng', fNext * 1.5, 2.1, 0.07 * vMul, dOff + 0.32, tonalBus);
      return;
    }

    if (
      type === 'rain_on_bamboo_leaves' || type === 'rain_gentle' ||
      type === 'waves_crashing_shore' || type === 'storm_wind_thunder' ||
      type === 'storm_gale' || type === 'storm_surge_strings' ||
      type === 'hearth_fire_tea_ambience'
    ) {
      // 【潇湘夜雨·沧海松涛自然诗境】：温润粉红环境雨声/海浪呼吸 + 同调古琴/洞箫点染
      const pinkBuf = getPinkNoiseBuffer(ctxAudio, 2.4);
      if (pinkBuf) {
        const nSrc = ctxAudio.createBufferSource();
        nSrc.buffer = pinkBuf;
        const nFilter = ctxAudio.createBiquadFilter();
        const nGain = ctxAudio.createGain();
        const isWave = (type === 'waves_crashing_shore' || type === 'storm_wind_thunder' || type === 'storm_gale');
        nFilter.type = isWave ? 'lowpass' : 'bandpass';
        nFilter.frequency.setValueAtTime(isWave ? 280 : 1100, t + dOff);
        nFilter.frequency.linearRampToValueAtTime(isWave ? 560 : 1650, t + dOff + 0.8);
        nFilter.frequency.exponentialRampToValueAtTime(isWave ? 200 : 850, t + dOff + 2.1);
        nFilter.Q.setValueAtTime(isWave ? 1.1 : 1.6, t + dOff);

        nGain.gain.setValueAtTime(0.0001, t + dOff);
        nGain.gain.linearRampToValueAtTime(0.10 * vMul, t + dOff + 0.38);
        nGain.gain.exponentialRampToValueAtTime(0.0001, t + dOff + 2.1);
        nSrc.connect(nFilter);
        nFilter.connect(nGain);
        nGain.connect(tonalBus);
        nSrc.start(t + dOff);
        nSrc.stop(t + dOff + 2.2);
      }
      _triggerPcmBuffer(ctxAudio, tonalBus, getWaterPourBuffer(ctxAudio), 0.16 * vMul, t + dOff + 0.08, 0.03);
      playInstrumentTone('guqin', getHarmonizedFreq(3 + degOff, 1.0), 1.9, 0.085 * vMul, dOff + 0.12, tonalBus);
      playInstrumentTone('xiao', getHarmonizedFreq(5 + degOff, 1.0), 1.7, 0.075 * vMul, dOff + 0.34, tonalBus);
      return;
    }

    if (
      type === 'chime_stone_bianqing' || type === 'chime_stone_high' ||
      type === 'bianqing_chime' || type === 'wind_chime' || type === 'wind_chime_breeze'
    ) {
      // 【檐角铁马与灵璧玉磬】：严格锁定当前调式高音五声的清脆风铃
      [4, 5, 6, 7].forEach((dg, idx) => {
        playInstrumentTone('bianqing', getHarmonizedFreq(dg + degOff, 2.0), 1.35, (0.085 - idx * 0.012) * vMul, dOff + idx * 0.085, tonalBus);
      });
      return;
    }

    if (
      type === 'bell' || type === 'bell_grand_chime' || type === 'bianzhong' ||
      type === 'ceremony' || type === 'bianzhong_chime' || type === 'bianzhong_sacred_hymn' ||
      type === 'temple_bell_deep' || type === 'temple_bell_reverb' || type === 'chime_bell_pulse' ||
      type === 'gong' || type === 'gong_resonant' || type === 'gong_deep_reverence' ||
      type === 'gong_drum_resonation' || type === 'bronze_ding_chime' || type === 'destiny_chime'
    ) {
      // 【金声玉振·曾侯乙编钟与古刹晨钟】：严格对齐当前和弦根音与五度音
      const rootBell = activeChord[1] || getHarmonizedFreq(2 + degOff, 1.0);
      const fifthBell = rootBell * 1.5;
      const isTemple = (type === 'temple_bell_deep' || type === 'temple_bell_reverb' || type.indexOf('gong') === 0);
      if (isTemple) {
        playInstrumentTone('drum', 85, 0.70, 0.095 * vMul, dOff, tonalBus);
        playInstrumentTone('bianzhong', rootBell * 0.5, 2.5, 0.115 * vMul, dOff + 0.02, tonalBus);
        playInstrumentTone('bianzhong', fifthBell * 0.5, 2.3, 0.095 * vMul, dOff + 0.26, tonalBus);
      } else {
        playInstrumentTone('bianzhong', rootBell, 2.2, 0.105 * vMul, dOff, tonalBus);
        playInstrumentTone('bianzhong', fifthBell, 2.0, 0.095 * vMul, dOff + 0.14, tonalBus);
        playInstrumentTone('bianqing', rootBell * 2.0, 1.7, 0.075 * vMul, dOff + 0.28, tonalBus);
      }
      return;
    }

    // 其余雅集与人生节点提示：同调古琴、古筝与洞箫三声部诗意和鸣
    playInstrumentTone('guqin', getHarmonizedFreq(2 + degOff, 1.0), 1.7, 0.085 * vMul, dOff, tonalBus);
    playInstrumentTone('guzheng', getHarmonizedFreq(4 + degOff, 1.0), 1.5, 0.078 * vMul, dOff + 0.09, tonalBus);
    playInstrumentTone('xiao', getHarmonizedFreq(6 + degOff, 1.0), 1.6, 0.072 * vMul, dOff + 0.20, tonalBus);
    return;
  } catch (e) { logDebugError("caughtException_" + 11, e); }
}

function triggerHaptic(type) {
  if (typeof wx === 'undefined') return;
  if (state && state.hapticEnabled === false) return;
  if (type === 'long') {
    if (typeof wx.vibrateLong === 'function') {
      try { wx.vibrateLong(); return; } catch (e) { logDebugError("caughtException_" + 12, e); }
    }
  }
  if (typeof wx.vibrateShort === 'function') {
    try { wx.vibrateShort({ type: type || 'light' }); } catch (e) { logDebugError("caughtException_" + 13, e); }
  }
}

// ==========================================
// 三、 60FPS 常驻动态呼吸光效与粒子物理引擎
// ==========================================
let screenShakeX = 0;
let screenShakeY = 0;
let screenShakeTime = 0;
let screenShakeMag = 6;

function triggerScreenShake(magnitude, durationMs) {
  screenShakeTime = durationMs || 220;
  screenShakeMag = magnitude || 6;
}

// 常驻 40 颗丁达尔浮动金粉微粒 (更密集而空灵的历史微尘)
const ambientMotes = [];
for (let i = 0; i < 40; i++) {
  ambientMotes.push({
    x: fxRandom() * screenWidth,
    y: fxRandom() * screenHeight,
    radius: 0.8 + fxRandom() * 1.8,
    speedY: -0.15 - fxRandom() * 0.3,
    speedX: (fxRandom() - 0.5) * 0.18,
    baseAlpha: 0.15 + fxRandom() * 0.45,
    phase: fxRandom() * Math.PI * 2
  });
}

// 墨泥朱砂粒子池
let inkParticles = [];
function spawnDustParticles(x, y, color, count) {
  for (let i = 0; i < count; i++) {
    const angle = fxRandom() * Math.PI * 2;
    const spd = 1.5 + fxRandom() * 4.5;
    inkParticles.push(obtainPooledParticle((obj) => {
      obj.x = x;
      obj.y = y;
      obj.vx = Math.cos(angle) * spd;
      obj.vy = Math.sin(angle) * spd;
      obj.radius = 1.2 + fxRandom() * 2.5;
      obj.alpha = 0.95;
      obj.decay = 0.02 + fxRandom() * 0.03;
      obj.color = color || '#ef4444';
    }));
  }
}

// 浮空文字队列
let floatingTexts = [];
function addFloatingText(text, x, y, color) {
  floatingTexts.push(obtainPooledParticle((obj) => {
    obj.text = text;
    obj.x = x;
    obj.y = y;
    obj.vy = -1.2;
    obj.alpha = 1.0;
    obj.color = color || '#f59e0b';
  }));
}

// 🖋️ V25 动态水墨晕染涟漪引擎 (Ink Wash Ripple Fluid Engine)
let touchRipples = [];
function addTouchRipple(x, y, color = null) {
  const sIdx = Math.abs((state.year || 1980) % 4);
  const seasonInkColors = ['#fb7185', '#f59e0b', '#d97706', '#60a5fa'];
  const inkColor = color || seasonInkColors[sIdx];
  touchRipples.push({
    x: x,
    y: y,
    radius: 3,
    maxRadius: 42,
    alpha: 0.85,
    color: inkColor,
    droplets: [
      { dx: (seededRandom() - 0.5) * 12, dy: (seededRandom() - 0.5) * 12, r: 1.4 + seededRandom() * 1.6 },
      { dx: (seededRandom() - 0.5) * 18, dy: (seededRandom() - 0.5) * 18, r: 1.0 + seededRandom() * 1.3 },
      { dx: (seededRandom() - 0.5) * 24, dy: (seededRandom() - 0.5) * 24, r: 0.8 + seededRandom() * 1.0 }
    ]
  });
  if (touchRipples.length > 18) touchRipples.shift();
}

