// ==========================================
// 四、 字体排版与中式国风视觉装帧
// ==========================================
const FONT_CHRONICLE = '"STSong", "Songti SC", "SimSun", "Noto Serif CJK SC", "Georgia", serif';
const FONT_UI = '-apple-system, BlinkMacSystemFont, "PingFang SC", "Helvetica Neue", "Segoe UI", sans-serif';
const FONT_MONO = '"SF Mono", "Menlo", "Monaco", monospace';

function formatCurrency(amount) {
  const num = Number(amount) || 0;
  if (Math.abs(num) >= 100000000) {
    return '¥' + (num / 100000000).toFixed(2) + '亿';
  } else if (Math.abs(num) >= 10000) {
    return '¥' + (num / 10000).toFixed(1) + '万';
  } else {
    return '¥' + Math.round(num);
  }
}

function drawCornerOrnaments(context, x, y, w, h, len, color) {
  if (w <= 0 || h <= 0) return;
  context.strokeStyle = color || '#f59e0b';
  context.lineWidth = 1.5;
  context.beginPath();

  // 左上角
  context.moveTo(x + 2, y + len + 2);
  context.lineTo(x + 2, y + 2);
  context.lineTo(x + len + 2, y + 2);

  // 右上角
  context.moveTo(x + w - len - 2, y + 2);
  context.lineTo(x + w - 2, y + 2);
  context.lineTo(x + w - 2, y + len + 2);

  // 左下角
  context.moveTo(x + 2, y + h - len - 2);
  context.lineTo(x + 2, y + h - 2);
  context.lineTo(x + len + 2, y + h - 2);

  // 右下角
  context.moveTo(x + w - len - 2, y + h - 2);
  context.lineTo(x + w - 2, y + h - 2);
  context.lineTo(x + w - 2, y + h - len - 2);

  context.stroke();
}

const SEAL_OFFSCREEN_CACHE = new Map();

function drawSealDirect(context, cx, cy, text, sub, radius) {
  const r = radius || 38;
  context.save();
  context.translate(cx, cy);
  context.rotate(-0.12);

  // 外同心双圈
  context.strokeStyle = '#dc2626';
  context.lineWidth = 2.5;
  context.beginPath();
  context.arc(0, 0, r, 0, Math.PI * 2);
  context.stroke();

  context.lineWidth = 1.0;
  context.beginPath();
  context.arc(0, 0, r - 3.5, 0, Math.PI * 2);
  context.stroke();

  // 五角星徽
  context.fillStyle = '#dc2626';
  context.beginPath();
  for (let i = 0; i < 5; i++) {
    const a = (i * 4 * Math.PI) / 5 - Math.PI / 2;
    const rad = 7.5;
    const px = Math.cos(a) * rad;
    const py = Math.sin(a) * rad;
    if (i === 0) context.moveTo(px, py);
    else context.lineTo(px, py);
  }
  context.closePath();
  context.fill();

  // 印文章文
  context.textAlign = 'center';
  context.textBaseline = 'middle';
  context.font = 'bold 14px ' + FONT_CHRONICLE;
  context.fillText(text || '准予批复', 0, 13);

  if (sub) {
    context.font = 'bold 14px ' + FONT_UI;
    context.fillText(sub, 0, 23);
  }

  context.restore();
}

function drawSeal(context, cx, cy, text, sub, radius) {
  const r = radius || 38;
  const sealText = text || '准予批复';
  const sealSub = sub || '';
  const key = `${sealText}_${sealSub}_${r}`;

  let cached = SEAL_OFFSCREEN_CACHE.get(key);
  if (!cached) {
    try {
      const pad = 6;
      const dim = Math.ceil((r + pad) * 2);
      let offCanvas = null;
      if (typeof wx !== 'undefined' && typeof wx.createOffscreenCanvas === 'function') {
        offCanvas = wx.createOffscreenCanvas({ type: '2d', width: dim, height: dim });
      } else if (typeof document !== 'undefined') {
        offCanvas = document.createElement('canvas');
        offCanvas.width = dim;
        offCanvas.height = dim;
      }
      if (offCanvas) {
        const offCtx = offCanvas.getContext('2d');
        if (offCtx) {
          drawSealDirect(offCtx, dim / 2, dim / 2, sealText, sealSub, r);
          cached = { canvas: offCanvas, dim, halfDim: dim / 2 };
          if (SEAL_OFFSCREEN_CACHE.size > 20) {
            const firstKey = SEAL_OFFSCREEN_CACHE.keys().next().value;
            SEAL_OFFSCREEN_CACHE.delete(firstKey);
          }
          SEAL_OFFSCREEN_CACHE.set(key, cached);
        }
      }
    } catch (e) { logDebugError("caughtException_" + 14, e); }
  }

  if (cached && cached.canvas) {
    context.drawImage(cached.canvas, cx - cached.halfDim, cy - cached.halfDim);
  } else {
    drawSealDirect(context, cx, cy, sealText, sealSub, r);
  }
}

/**
 * 🎨 矢量自绘传统国风徽记系统 (Pure Vector Seal Badges)
 * 彻底告别对操作系统特定字体 Emoji (👶, 🕰️, 📽️, 📜, 🏆 等) 的依赖，保障跨机型国风质感与高精度渲染
 */
function drawTraditionalSealBadge(context, type, cx, cy, radius, color) {
  if (!context) return;
  const r = radius || 14;
  const clr = color || '#f59e0b';
  context.save();
  context.translate(cx, cy);

  switch (type) {
    case 'baby':
    case 'infant':
    case 'lock': {
      // 🌟 如意长命锁徽标 (取代 👶)
      context.strokeStyle = clr;
      context.fillStyle = clr;
      context.lineWidth = 1.6;

      // 锁梁 (上圆弧弯环)
      context.beginPath();
      context.arc(0, -r * 0.45, r * 0.48, Math.PI, 0, false);
      context.stroke();

      // 如意云头主体锁面 (扁鼓/弧角梯形)
      context.beginPath();
      context.moveTo(-r * 0.8, -r * 0.3);
      context.quadraticCurveTo(-r * 0.9, r * 0.5, 0, r * 0.65);
      context.quadraticCurveTo(r * 0.9, r * 0.5, r * 0.8, -r * 0.3);
      context.quadraticCurveTo(0, -r * 0.1, -r * 0.8, -r * 0.3);
      context.closePath();
      context.stroke();

      // 锁心如意圆孔
      context.beginPath();
      context.arc(0, r * 0.15, r * 0.18, 0, Math.PI * 2);
      context.fill();
      break;
    }

    case 'era':
    case 'clock':
    case 'sundial': {
      // 🕰️ 青铜日晷刻度盘徽标 (取代 🕰️)
      context.strokeStyle = clr;
      context.fillStyle = clr;
      context.lineWidth = 1.5;

      // 外晷盘
      context.beginPath();
      context.arc(0, 0, r * 0.85, 0, Math.PI * 2);
      context.stroke();

      // 内同心圆
      context.lineWidth = 0.9;
      context.beginPath();
      context.arc(0, 0, r * 0.55, 0, Math.PI * 2);
      context.stroke();

      // 四方时辰刻线
      for (let i = 0; i < 4; i++) {
        const ang = (i * Math.PI) / 2;
        context.beginPath();
        context.moveTo(Math.cos(ang) * (r * 0.55), Math.sin(ang) * (r * 0.55));
        context.lineTo(Math.cos(ang) * (r * 0.85), Math.sin(ang) * (r * 0.85));
        context.stroke();
      }

      // 晷针 (斜向金光指针)
      context.lineWidth = 1.8;
      context.beginPath();
      context.moveTo(0, 0);
      context.lineTo(r * 0.45, -r * 0.45);
      context.stroke();

      // 晷心基准点
      context.beginPath();
      context.arc(0, 0, r * 0.18, 0, Math.PI * 2);
      context.fill();
      break;
    }

    case 'film':
    case 'scroll':
    case 'chronicle': {
      // 📽️ 锦缎展卷 / 丹青画卷轴徽标 (取代 📽️ / 📜)
      context.strokeStyle = clr;
      context.fillStyle = clr;
      context.lineWidth = 1.5;

      // 展开的锦帛画幅
      context.beginPath();
      context.rect(-r * 0.7, -r * 0.5, r * 1.4, r * 1.0);
      context.stroke();

      // 卷轴两端轴头
      context.lineWidth = 2.0;
      context.beginPath();
      context.moveTo(-r * 0.7, -r * 0.75);
      context.lineTo(-r * 0.7, r * 0.75);
      context.moveTo(r * 0.7, -r * 0.75);
      context.lineTo(r * 0.7, r * 0.75);
      context.stroke();

      // 卷内书文字痕
      context.lineWidth = 1.0;
      context.beginPath();
      context.moveTo(-r * 0.4, -r * 0.18);
      context.lineTo(r * 0.4, -r * 0.18);
      context.moveTo(-r * 0.4, r * 0.18);
      context.lineTo(r * 0.2, r * 0.18);
      context.stroke();
      break;
    }

    case 'medal':
    case 'tripod':
    case 'trophy': {
      // 🏆 商周青铜宝鼎徽标 (取代 🏆)
      context.strokeStyle = clr;
      context.fillStyle = clr;
      context.lineWidth = 1.5;

      // 鼎腹 (大圆腹碗形)
      context.beginPath();
      context.arc(0, -r * 0.05, r * 0.65, 0, Math.PI, false);
      context.lineTo(-r * 0.65, -r * 0.05);
      context.closePath();
      context.stroke();

      // 鼎沿两侧立耳
      context.beginPath();
      context.rect(-r * 0.6, -r * 0.4, r * 0.22, r * 0.35);
      context.rect(r * 0.38, -r * 0.4, r * 0.22, r * 0.35);
      context.stroke();

      // 鼎足 (三足鼎立)
      context.lineWidth = 1.8;
      context.beginPath();
      context.moveTo(-r * 0.45, r * 0.5);
      context.lineTo(-r * 0.5, r * 0.85);
      context.moveTo(0, r * 0.6);
      context.lineTo(0, r * 0.85);
      context.moveTo(r * 0.45, r * 0.5);
      context.lineTo(r * 0.5, r * 0.85);
      context.stroke();
      break;
    }

    case 'repair':
    case 'taichi':
    default: {
      // ☯️ 太极玄印徽标 (用于异常修复 / 乾坤流转)
      context.strokeStyle = clr;
      context.fillStyle = clr;
      context.lineWidth = 1.5;

      // 外周道圈
      context.beginPath();
      context.arc(0, 0, r * 0.85, 0, Math.PI * 2);
      context.stroke();

      // S 弯太极曲线
      context.beginPath();
      context.arc(0, -r * 0.425, r * 0.425, -Math.PI / 2, Math.PI / 2, false);
      context.arc(0, r * 0.425, r * 0.425, -Math.PI / 2, Math.PI / 2, true);
      context.arc(0, 0, r * 0.85, Math.PI / 2, -Math.PI / 2, true);
      context.closePath();
      context.fill();

      // 阴阳双鱼眼
      context.fillStyle = '#0f172a';
      context.beginPath();
      context.arc(0, -r * 0.425, r * 0.16, 0, Math.PI * 2);
      context.fill();

      context.fillStyle = clr;
      context.beginPath();
      context.arc(0, r * 0.425, r * 0.16, 0, Math.PI * 2);
      context.fill();
      break;
    }
  }

  context.restore();
}

function roundRect(context, x, y, width, height, radius, fill, stroke, strokeColor, strokeWidth) {
  if (width <= 0 || height <= 0 || !context) return;
  const r = Math.min(radius || 6, width / 2, height / 2);
  context.beginPath();
  if (typeof context.arcTo === 'function') {
    context.moveTo(x + r, y);
    context.lineTo(x + width - r, y);
    context.arcTo(x + width, y, x + width, y + r, r);
    context.lineTo(x + width, y + height - r);
    context.arcTo(x + width, y + height, x + width - r, y + height, r);
    context.lineTo(x + r, y + height);
    context.arcTo(x, y + height, x, y + height - r, r);
    context.lineTo(x, y + r);
    context.arcTo(x, y, x + r, y, r);
    context.closePath();
  } else {
    context.rect(x, y, width, height);
    context.closePath();
  }

  if (fill) context.fill();
  if (stroke) {
    if (strokeColor) context.strokeStyle = strokeColor;
    if (strokeWidth !== undefined) context.lineWidth = strokeWidth;
    context.stroke();
  }
}

function drawWrappedText(ctx, text, x, y, maxWidth, lineHeight) {
  if (!text) return 0;
  ctx.font = elevateFontSize(ctx.font, 15);
  const effectiveLineHeight = Math.max(lineHeight || 20, isElderAccessibilityMode ? 24 : 21);
  const lines = wrapTextLines(text, maxWidth, ctx.font);
  const totalH = lines.length * effectiveLineHeight;
  // 视口快速剔除：若整个文本块在屏幕垂直可见域之外，直接返回计算高度供排版，跳过昂贵的底层 fillText
  if (y + totalH < -20 || y > screenHeight + 20) {
    return totalH;
  }
  for (let idx = 0; idx < lines.length; idx++) {
    const lineY = y + idx * effectiveLineHeight;
    if (lineY >= -20 && lineY <= screenHeight + 20) {
      ctx.fillText(lines[idx], x, lineY);
    }
  }
  return totalH;
}

const wrapText = drawWrappedText;

const WRAP_TEXT_CACHE = new Map();

function wrapTextLines(text, maxWidth, font) {
  if (!text) return [];
  const effectiveFont = elevateFontSize(font, 15);
  const cacheKey = effectiveFont + '||' + maxWidth + '||' + text;
  const cached = WRAP_TEXT_CACHE.get(cacheKey);
  if (cached) return cached;

  ctx.save();
  ctx.font = effectiveFont;
  const paragraphs = String(text).split('\n');
  const lines = [];

  for (let p = 0; p < paragraphs.length; p++) {
    const para = paragraphs[p];
    if (para.length === 0) {
      if (paragraphs.length > 1 && p < paragraphs.length - 1) {
        lines.push('');
      }
      continue;
    }

    // 整段快速命中检测：若直接能容纳，单次 measureText 即刻完成，省去逐字测量与数组分配
    if (ctx.measureText(para).width <= maxWidth) {
      lines.push(para);
      continue;
    }

    let cur = '';
    for (let i = 0; i < para.length; i++) {
      const ch = para[i];
      const test = cur + ch;
      if (measureTextMemo(ctx, test, effectiveFont) > maxWidth && cur.length > 0) {
        lines.push(cur);
        cur = ch;
      } else {
        cur = test;
      }
    }
    if (cur.length > 0) lines.push(cur);
  }
  ctx.restore();

  if (WRAP_TEXT_CACHE.size > 800) {
    const firstKey = WRAP_TEXT_CACHE.keys().next().value;
    WRAP_TEXT_CACHE.delete(firstKey);
  }
  WRAP_TEXT_CACHE.set(cacheKey, lines);
  return lines;
}

const FIT_TEXT_CACHE = new Map();

function fitText(text, maxWidth, font) {
  if (!text) return '';
  const effectiveFont = elevateFontSize(font, 15);
  const cacheKey = effectiveFont + '||' + maxWidth + '||' + text;
  const cached = FIT_TEXT_CACHE.get(cacheKey);
  if (cached !== undefined) return cached;

  ctx.save();
  ctx.font = effectiveFont;
  if (measureTextMemo(ctx, text, effectiveFont) <= maxWidth) {
    ctx.restore();
    if (FIT_TEXT_CACHE.size > 1200) {
      const firstKey = FIT_TEXT_CACHE.keys().next().value;
      FIT_TEXT_CACHE.delete(firstKey);
    }
    FIT_TEXT_CACHE.set(cacheKey, text);
    return text;
  }
  let low = 1, high = text.length, best = 1;
  while (low <= high) {
    const mid = (low + high) >> 1;
    const cand = text.slice(0, mid) + '…';
    if (measureTextMemo(ctx, cand, effectiveFont) <= maxWidth) {
      best = mid;
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }
  ctx.restore();
  const res = text.slice(0, best) + '…';
  if (FIT_TEXT_CACHE.size > 1200) {
    const firstKey = FIT_TEXT_CACHE.keys().next().value;
    FIT_TEXT_CACHE.delete(firstKey);
  }
  FIT_TEXT_CACHE.set(cacheKey, res);
  return res;
}

