function setAnnualStrategy(strategyKey) {
  const norm = strategyKey === 'overwork' ? 'aggressive' : (STRATEGIES[strategyKey] ? strategyKey : 'balanced');
  state.strategy = norm;
  state._lockedStrategy = norm;
  if (typeof reportGameMilestone === 'function') {
    reportGameMilestone('strategy_switched', { strategy: norm, age: state.age || 18, year: state.year || 1992 });
  }
  const info = STRATEGIES[norm];
  playSoundEffect('stamp');
  triggerHaptic('light');
  showToast(`🧭 年度方针已切换为【${info.name}】：${info.desc}`, 'gold');
  saveGameState();
  requestRender();
}

