function hasTalent(talentId) {
  return (state.unlockedTalents || []).includes(talentId);
}

function unlockTalent(talentId) {
  const talent = TALENTS_DATABASE.find(t => t.id === talentId) || TALENT_POOL.find(t => t.id === talentId);
  if (!talent) return;
  if (hasTalent(talentId)) {
    showToast(`处世之道【${talent.name}】已融会贯通！`, 'info');
    return;
  }
  if ((state.talentPoints || 0) < (talent.cost || 1)) {
    showToast(`人生阅历尚浅，需 ${talent.cost || 1} 点处世心得！`, 'alert');
    return;
  }
  state.talentPoints -= (talent.cost || 1);
  if (!state.unlockedTalents) state.unlockedTalents = [];
  state.unlockedTalents.push(talentId);

  if (talentId === 'decisive' && (state.age || 0) % 2 === 0) {
    state.maxAp = 4 + (state.bonusMaxAp || 0);
    state.ap = Math.min(state.maxAp, (state.ap || 0) + 1);
  }

  playSoundEffect('gong');
  triggerHaptic('heavy');
  addFloatingText(`✨ 领悟【${talent.name}】!`, screenWidth / 2, getDashboardY() + 40, "#f59e0b");
  showToast(`⚡ 成功领悟【${talent.name}】！`, 'gold');
  addChronicleItem(state.age, state.year, `【人生体悟】在岁月磨砺中融会贯通【${talent.name}】（${talent.branch}）：${talent.desc}`, "处世心得", "promo");
  requestRender();
}

