function plantKarmaSeed(key, choice, title) {
  if ((state.age || 0) < 22) return;
  if (!state.karmaPledges) state.karmaPledges = {};
  if (state.karmaPledges[key]) return;
  state.karmaPledges[key] = {
    choice: choice,
    title: title || key,
    age: state.age,
    year: state.year
  };
  addChronicleItem(state.age, state.year, `【因果伏笔】你的战略决断《${title || key}》已被写入历史因果簿，数载之后必有时代回响。`, "因果伏笔", "history");
}

function checkKarmaEchoes(age, year) {
  if (!state.karmaPledges || age < 32) return;
  if (!state.karmaHistory) state.karmaHistory = [];

  for (let i = 0; i < KARMA_ECHO_DEFINITIONS.length; i++) {
    const echo = KARMA_ECHO_DEFINITIONS[i];
    if (state.handledEvents['echo_' + echo.id]) continue;
    const pledge = state.karmaPledges[echo.seedKey];
    if (pledge && pledge.choice === echo.seedChoice && (year - pledge.year) >= echo.minYearsElapsed) {
      state.handledEvents['echo_' + echo.id] = true;
      echo.apply(state);
      clampCoreStats(state);
      state.karmaHistory.push({
        id: echo.id,
        title: echo.title,
        desc: echo.desc,
        impactDesc: echo.impactDesc,
        year: year,
        age: age
      });
      playSoundEffect('gong');
      triggerHaptic('heavy');
      showToast(`🔮 触发历史因果回响：${echo.title}！`, 'gold');
      addChronicleItem(age, year, `${echo.title} ${echo.desc} 时代收益：${echo.impactDesc}`, "因果回响", "promo");
      break;
    }
  }
}


