// 🚀 V17 性能加速引擎：高频文字宽度 LRU 缓存与粒子对象池
// ==========================================
const _measureTextCache = new Map();
const MEASURE_TEXT_CACHE = _measureTextCache;
function measureTextMemo(context, text, font) {
  const key = (font || '') + '::' + String(text || '');
  if (MEASURE_TEXT_CACHE.has(key)) return MEASURE_TEXT_CACHE.get(key);
  if (context && typeof context.measureText === 'function') {
    if (font) context.font = font;
    const res = context.measureText(text) || { width: 0 };
    if (MEASURE_TEXT_CACHE.size > 800) {
      const firstKey = MEASURE_TEXT_CACHE.keys().next().value;
      MEASURE_TEXT_CACHE.delete(firstKey);
    }
    MEASURE_TEXT_CACHE.set(key, res.width);
    return res.width;
  }
  return (String(text || '').length) * 12;
}

