// 敏感词文本安全过滤引擎 (Sanitizer + wx.security.msgSecCheck / wx.cloud.callFunction + 失败降级默认名)
const _SENSITIVE_REGEX = new RegExp('(\\u66b4\\u529b|\\u8d4c\\u535a|\\u8272\\u60c5|\\u53cd\\u52a8|\\u90aa\\u6559|\\u5206\\u88c2|\\u6bd2\\u54c1|\\u6d17\\u94b1|\\u884c\\u8d3f|\\u8d2a\\u6c61|\\u8d70\\u79c1|\\u4e70\\u5b98|\\u5356\\u5b98|\\u8bc8\\u9a97|\\u66b4\\u6050|\\u6d89\\u9ec4|\\u6d89\\u8d4c)', 'gi');
function sanitizeUserInput(inputStr) {
  if (typeof inputStr !== 'string') return '';
  return inputStr.trim().replace(_SENSITIVE_REGEX, '***');
}

let _wxCloudInitialized = false;
function ensureCloudSecurityInit() {
  if (_wxCloudInitialized) return true;
  if (typeof wx !== 'undefined' && wx.cloud && typeof wx.cloud.init === 'function') {
    try {
      wx.cloud.init({ traceUser: true });
      _wxCloudInitialized = true;
      return true;
    } catch (err) {
      logDebugError('wx.cloud.init', err);
    }
  }
  return false;
}

function checkTextContentSafety(inputStr, callback, fallbackText = '陈守正') {
  const safeFallback = (typeof fallbackText === 'string' && fallbackText.trim()) ? fallbackText.trim() : '陈守正';
  const cleaned = sanitizeUserInput(inputStr);
  if (!cleaned || cleaned.includes('***')) {
    if (typeof callback === 'function') callback(false, safeFallback);
    return Promise.resolve({ safe: false, text: safeFallback });
  }

  // 优先调用微信原生内容安全接口 wx.security.msgSecCheck，异常或拒绝时一律降级为默认安全文本 (Fail-Closed)
  if (typeof wx !== 'undefined' && wx.security && typeof wx.security.msgSecCheck === 'function') {
    return new Promise(resolve => {
      let settled = false;
      const finish = (isSafe) => {
        if (settled) return;
        settled = true;
        const outText = isSafe ? cleaned : safeFallback;
        if (typeof callback === 'function') callback(isSafe, outText);
        resolve({ safe: isSafe, text: outText });
      };
      try {
        const ret = wx.security.msgSecCheck({
          content: cleaned,
          success: (res) => {
            const errCode = res && (res.errCode !== undefined ? res.errCode : (res.result ? res.result.errCode : 0));
            finish(errCode === 0 || errCode === undefined);
          },
          fail: (err) => {
            logDebugError('wx.security.msgSecCheck', err);
            finish(false);
          }
        });
        if (ret && typeof ret.then === 'function') {
          ret.then(res => {
            const errCode = res && (res.errCode !== undefined ? res.errCode : (res.result ? res.result.errCode : 0));
            finish(errCode === 0 || errCode === undefined);
          }).catch(err => {
            logDebugError('wx.security.msgSecCheck', err);
            finish(false);
          });
        }
      } catch (err) {
        logDebugError('wx.security.msgSecCheck', err);
        finish(false);
      }
    });
  }

  // 次选云函数 msgSecCheck，初始化失败或调用报错时同样严格降级为默认安全文本 (Fail-Closed)
  if (typeof wx !== 'undefined' && wx.cloud && typeof wx.cloud.callFunction === 'function') {
    ensureCloudSecurityInit();
    try {
      return wx.cloud.callFunction({
        name: 'msgSecCheck',
        data: { content: cleaned }
      }).then(res => {
        const errCode = res && res.result ? res.result.errCode : 0;
        const isSafe = (errCode === 0 || errCode === undefined);
        const outText = isSafe ? cleaned : safeFallback;
        if (typeof callback === 'function') callback(isSafe, outText);
        return { safe: isSafe, text: outText };
      }).catch(err => {
        logDebugError('msgSecCheck', err);
        if (typeof callback === 'function') callback(false, safeFallback);
        return { safe: false, text: safeFallback };
      });
    } catch (err) {
      logDebugError('msgSecCheckSync', err);
      if (typeof callback === 'function') callback(false, safeFallback);
      return Promise.resolve({ safe: false, text: safeFallback });
    }
  }

  if (typeof callback === 'function') callback(true, cleaned);
  return Promise.resolve({ safe: true, text: cleaned });
}

// 本地存档重置与缓存彻底清理 (直接调用 clearSavedGame 删除真实存档键并重置核心状态)
function resetUserGameData() {
  if (pendingSaveTimer) {
    clearTimeout(pendingSaveTimer);
    pendingSaveTimer = null;
  }
  clearSavedGame();
  setRandomSeed(Date.now() ^ 0x9E3779B9);
  try {
    const legacyKeys = ['age_sim_save_v1', 'age_sim_stats', 'age_sim_settings', 'age_sim_relics'];
    if (typeof wx !== 'undefined' && typeof wx.removeStorageSync === 'function') {
      legacyKeys.forEach(k => {
        try { wx.removeStorageSync(k); } catch (e) { logDebugError('resetUserGameData.wx', e); }
      });
    } else if (typeof localStorage !== 'undefined') {
      legacyKeys.forEach(k => {
        try { localStorage.removeItem(k); } catch (e) { logDebugError('resetUserGameData.ls', e); }
      });
    }
  } catch (err) {
    logDebugError('resetUserGameData', err);
  }
  state.age = 0;
  state.year = 1972;
  state.capital = 24000;
  state.rep = 10;
  state.clean = 95;
  state.health = 95;
  state.sp = 35;
  state.resilience = 50;
  state.heritageRuns = 0;
  state.heritageBonusTalents = 0;
  state.lifetimeMaxRank = 0;
  state.careerHistory = [];
  state.dynasticInheritance = null;
  state.ancestralShrine = [];
  state.unlockedHeirlooms = [];
  state.unlockedAchievements = [];
  state.memoryAlbum = [];
  state.collectedClippings = [];
  state.causalSeeds = {};
  state.causalEchoes = [];
  state.endgameSettled = false;
  state.earlyRetireReason = null;
  startCharacterCreation(false);
  showToast("本地游戏数据与缓存已安全重置！", "gold");
  playSoundEffect('paper');
  requestRender();
  return true;
}


// ------------------------------------------
// 🎨 宋锦缠枝云纹工笔画框 (Cloud Filigree Borders - 离屏纹理缓存加速)
// ------------------------------------------
function createOffscreenCanvasBuffer(w, h) {
  try {
    const bw = Math.max(1, Math.round(w));
    const bh = Math.max(1, Math.round(h));
    if (typeof wx !== 'undefined' && typeof wx.createOffscreenCanvas === 'function') {
      return wx.createOffscreenCanvas({ type: '2d', width: bw, height: bh });
    }
    if (typeof tt !== 'undefined' && typeof tt.createOffscreenCanvas === 'function') {
      return tt.createOffscreenCanvas({ type: '2d', width: bw, height: bh });
    }
    if (typeof wx !== 'undefined' && typeof wx.createCanvas === 'function') {
      const c = wx.createCanvas();
      c.width = bw;
      c.height = bh;
      return c;
    }
    if (typeof tt !== 'undefined' && typeof tt.createCanvas === 'function') {
      const c = tt.createCanvas();
      c.width = bw;
      c.height = bh;
      return c;
    }
    if (typeof document !== 'undefined' && typeof document.createElement === 'function') {
      const c = document.createElement('canvas');
      c.width = bw;
      c.height = bh;
      return c;
    }
  } catch (_) {}
  return null;
}

const _filigreeBorderCache = new Map();
function drawCloudFiligreeBorders(ctx, x, y, w, h, goldColor = '#f59e0b') {
  const rw = Math.round(w);
  const rh = Math.round(h);
  const cacheKey = `${rw}_${rh}_${goldColor}`;

  let cached = _filigreeBorderCache.get(cacheKey);
  if (!cached) {
    const offCanvas = createOffscreenCanvasBuffer(rw, rh);
    if (offCanvas) {
      const offCtx = offCanvas.getContext('2d');
      if (offCtx) {
        offCtx.save();
        offCtx.strokeStyle = goldColor;
        offCtx.lineWidth = 1;
        const s = 14;
        // 左上
        offCtx.beginPath();
        offCtx.moveTo(4, 4 + s);
        offCtx.lineTo(4, 4);
        offCtx.lineTo(4 + s, 4);
        offCtx.stroke();
        // 右上
        offCtx.beginPath();
        offCtx.moveTo(rw - 4 - s, 4);
        offCtx.lineTo(rw - 4, 4);
        offCtx.lineTo(rw - 4, 4 + s);
        offCtx.stroke();
        // 左下
        offCtx.beginPath();
        offCtx.moveTo(4, rh - 4 - s);
        offCtx.lineTo(4, rh - 4);
        offCtx.lineTo(4 + s, rh - 4);
        offCtx.stroke();
        // 右下
        offCtx.beginPath();
        offCtx.moveTo(rw - 4 - s, rh - 4);
        offCtx.lineTo(rw - 4, rh - 4);
        offCtx.lineTo(rw - 4, rh - 4 - s);
        offCtx.stroke();
        offCtx.restore();

        if (_filigreeBorderCache.size > 20) {
          const firstKey = _filigreeBorderCache.keys().next().value;
          _filigreeBorderCache.delete(firstKey);
        }
        _filigreeBorderCache.set(cacheKey, offCanvas);
        cached = offCanvas;
      }
    }
  }

  if (cached) {
    try {
      ctx.drawImage(cached, x, y);
      return;
    } catch (_) {}
  }

  ctx.save();
  ctx.strokeStyle = goldColor;
  ctx.lineWidth = 1;

  // 四角回字与祥云纹饰
  const s = 14;
  // 左上
  ctx.beginPath();
  ctx.moveTo(x + 4, y + 4 + s);
  ctx.lineTo(x + 4, y + 4);
  ctx.lineTo(x + 4 + s, y + 4);
  ctx.stroke();

  // 右上
  ctx.beginPath();
  ctx.moveTo(x + w - 4 - s, y + 4);
  ctx.lineTo(x + w - 4, y + 4);
  ctx.lineTo(x + w - 4, y + 4 + s);
  ctx.stroke();

  // 左下
  ctx.beginPath();
  ctx.moveTo(x + 4, y + h - 4 - s);
  ctx.lineTo(x + 4, y + h - 4);
  ctx.lineTo(x + 4 + s, y + h - 4);
  ctx.stroke();

  // 右下
  ctx.beginPath();
  ctx.moveTo(x + w - 4 - s, y + h - 4);
  ctx.lineTo(x + w - 4, y + h - 4);
  ctx.lineTo(x + w - 4, y + h - 4 - s);
  ctx.stroke();

  ctx.restore();
}

// ------------------------------------------
// 🌟 大国气运升腾流金飞瀑动效 (National Aura Rising)
// ------------------------------------------
let _auraParticles = [];
function drawNationalAuraRising(ctx) {
  if (state.age < 18 || !state.isStarted || state.activeModal) return;
  while (_auraParticles.length < 18) {
    _auraParticles.push({
      x: 20 + fxRandom() * (screenWidth - 40),
      y: screenHeight - 10 - fxRandom() * 40,
      vy: 0.4 + fxRandom() * 0.6,
      size: 1.2 + fxRandom() * 1.8,
      alpha: 0.6 + fxRandom() * 0.4,
      color: fxRandom() > 0.4 ? '#fef08a' : '#f59e0b'
    });
  }

  ctx.save();
  for (let i = 0; i < _auraParticles.length; i++) {
    const p = _auraParticles[i];
    p.y -= p.vy;
    p.alpha -= 0.005;
    if (p.alpha <= 0.02 || p.y < screenHeight - 160) {
      p.x = 20 + fxRandom() * (screenWidth - 40);
      p.y = screenHeight - 10 - fxRandom() * 40;
      p.vy = 0.4 + fxRandom() * 0.6;
      p.size = 1.2 + fxRandom() * 1.8;
      p.alpha = 0.6 + fxRandom() * 0.4;
      p.color = fxRandom() > 0.4 ? '#fef08a' : '#f59e0b';
    }
    ctx.globalAlpha = p.alpha;
    ctx.fillStyle = p.color;
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
}

