function dispatchRegionalSynergy(synergyType) {
  state.handledSynergies = state.handledSynergies || [];
  if (state.handledSynergies.includes(synergyType)) {
    showToast("该跨区战略调度已落地实施，无需重复调度！", "info");
    return false;
  }
  if (state.ap < 1) {
    showToast("当年精力不足，无法实施跨区战略大调度！", "alert");
    return false;
  }
  state.ap--;
  state.handledSynergies.push(synergyType);
  if (typeof progressThreeYearPact === 'function') {
    progressThreeYearPact(15, '跨区战略调度');
  }

  if (synergyType === 'east_data_west_calc') {
    addStat("iq", 5, 50);
    addStat("rep", 5, 50);
    addChronicleItem(state.age, state.year, '【东数西算】统筹东部算力需求向西部清洁算力枢纽调度，数网一体化提速！', '大国调度', 'promo');
    showToast('东数西算调度落地！智谋+5，声望+5，全国智算网络互联！', 'gold');
  } else if (synergyType === 'west_power_east_trans') {
    addStat("clean", 5, 50);
    addStat("rep", 5, 50);
    addChronicleItem(state.age, state.year, '【西电东送】金沙江梯级水电特高压直流全额送出，点亮东部大都市绿色电网！', '大国调度', 'promo');
    showToast('西电东送调度成功！清廉+5，声望+5，年节约标煤千万吨！', 'gold');
  } else {
    state.capital = (state.capital || 0) + 12000;
    addStat("rep", 4, 50);
    addChronicleItem(state.age, state.year, '【产业协作】组织东部先进装备与核心配套向中西部战略腹地梯度转移！', '大国调度', 'promo');
    showToast('跨省产业协同落实！资产收益增进 ¥12,000，声望+4！', 'gold');
  }
  playSoundEffect('battle_drum_roll');
  playSoundEffect('wax_seal_stamp');
  triggerScreenShake(7, 260);
  spawnInkWashBloom(screenWidth / 2, screenHeight / 2, 95, '#0ea5e9');
  spawnGoldSpiral(screenWidth / 2, screenHeight / 2, 35);
  requestRender();
  return true;
}

