// -------------------------------------------------------------
// 👑 家族万世谱系评级系统 (Clan Legacy Matrix)
// -------------------------------------------------------------
function calcClanLegacyIndex() {
  const f = state.family || {};
  const preceptsCount = ((state.adoptedPrecepts && state.adoptedPrecepts.length) ? state.adoptedPrecepts : (f.adoptedPrecepts || [])).length;
  const medalsCount = (state.awardedMedals || []).length;
  const chroniclesCount = (state.chronicleHistory || []).length;
  const lecturesDelivered = Array.isArray(state.handledLectures) ? state.handledLectures.length : Object.keys(state.handledLectures || {}).length;
  const motionsAdopted = (state.handledMotions || []).length;

  let score = 50;
  score += Math.min(20, (f.prestige || 50) * 0.2);
  score += preceptsCount * 6;
  score += medalsCount * 5;
  score += Math.min(15, Math.floor(chroniclesCount / 5));
  score += lecturesDelivered * 4;
  score += motionsAdopted * 4;
  score += Math.min(20, (state.capital || 0) / 500000);

  score = Math.round(score);

  let tier = '🌾 清流寒素';
  let desc = '守正持身，清白传家，于风霜坎坷中不移本心，士林赞佩。';
  if (score >= 130) {
    tier = '👑 千秋第一勋阀';
    desc = '万流归海，勋名与国同休！出将入相，满门朱紫，天下门生故吏同心敬仰，德配天地！';
  } else if (score >= 105) {
    tier = '🏛️ 治国梁栋世家';
    desc = '执掌国之重枢，参决大政方针；祖训垂范，百世其昌，为共和国栋梁砥柱！';
  } else if (score >= 85) {
    tier = '🏭 实业巨擘望族';
    desc = '实业报国，富润一方；技进于道，造福桑梓，宗族繁衍兴盛！';
  } else if (score >= 65) {
    tier = '📖 诗书甲第名门';
    desc = '耕读济世，翰墨流芳；门风淳正，后进英才辈出！';
  }

  return {
    score,
    tier,
    desc,
    preceptsCount,
    medalsCount,
    chroniclesCount
  };
}

// 1. 四维国力总控中枢计算引擎 (National Grand Strategy Matrix)
function calcNationalPowerMatrix() {
  const yr = state.year || 1992;
  const yearRatio = Math.max(0, Math.min(1, (yr - 1970) / 65));

  // 1. 🛡️ 科技自立与国防安全指数 (30 ~ 100)
  const techBase = Math.round(35 + yearRatio * 45 + getStat("iq", 50) * 0.2);
  const techProg = (state.megaprojectProgress && state.megaprojectProgress['consortia_moon']) ? 10 : 0;
  const defenseTechIndex = Math.min(100, techBase + techProg);

  // 2. 🌾 民生福祉与乡村振兴指数 (30 ~ 100)
  const liveBase = Math.round(30 + yearRatio * 45 + getStat("clean", 50) * 0.15 + ((state.family && state.family.prestige) || 50) * 0.1);
  const livelihoodIndex = Math.min(100, liveBase);

  // 3. 🌐 全球经贸与国际话语权指数 (30 ~ 100)
  const tradeBase = Math.round(25 + yearRatio * 50 + getStat("eq", 50) * 0.15 + Math.min(15, (state.capital || 0) / 500000));
  const globalTradeIndex = Math.min(100, tradeBase);

  // 4. 🌿 生态文明与绿色低碳韧性指数 (30 ~ 100)
  const ecoBase = Math.round(30 + yearRatio * 50 + ((state.handledTours || []).includes('tour_northwest') ? 12 : 0));
  const ecologyGreenIndex = Math.min(100, ecoBase);

  const compositeScore = Math.round((defenseTechIndex + livelihoodIndex + globalTradeIndex + ecologyGreenIndex) / 4);

  return {
    defenseTechIndex,
    livelihoodIndex,
    globalTradeIndex,
    ecologyGreenIndex,
    compositeScore,
    eraTier: compositeScore >= 90 ? '🌟 极智圆满 · 鼎盛乾坤' : (compositeScore >= 75 ? '🚀 奋发突围 · 国运昌盛' : '🌱 砥砺筑基 · 披荆斩棘')
  };
}

