// 2. 国家重大专项工程四阶渐进式机制 (Megaproject Stages)
const MEGAPROJECT_STAGES = [
  { stage: 1, name: '立项调研与可行性论证', color: '#94a3b8', costAp: 1, budget: 50000 },
  { stage: 2, name: '核心关键技术破冰攻坚', color: '#38bdf8', costAp: 1, budget: 80000 },
  { stage: 3, name: '全系统工程试验与总装', color: '#f59e0b', costAp: 1, budget: 100000 },
  { stage: 4, name: '国家验收与圆满投产授勋', color: '#10b981', costAp: 1, budget: 120000 }
];

function getMegaprojectStage(projId) {
  state.megaprojectProgress = state.megaprojectProgress || {};
  return state.megaprojectProgress[projId] || 1;
}

function advanceMegaprojectStage(projId) {
  state.megaprojectProgress = state.megaprojectProgress || {};
  const curStg = state.megaprojectProgress[projId] || 1;
  if (curStg >= 4) {
    showToast("该工程已圆满通过国家最高验收，功在千秋！", "gold");
    return false;
  }
  const stgConfig = MEGAPROJECT_STAGES[curStg - 1];
  if (state.ap < stgConfig.costAp) {
    showToast("当年履职精力不足！", "alert");
    return false;
  }
  if (state.capital < stgConfig.budget) {
    showToast(`工程专项配套预算不足 ¥${stgConfig.budget.toLocaleString()}！`, "alert");
    return false;
  }

  state.ap -= stgConfig.costAp;
  state.capital -= stgConfig.budget;
  const nextStg = curStg + 1;
  state.megaprojectProgress[projId] = nextStg;
  if (typeof progressThreeYearPact === 'function') {
    progressThreeYearPact(18, '大国重器工程攻坚');
  }

  const proj = NATIONAL_MEGAPROJECT_CONSORTIA.find(p => p.id === projId);
  playSoundEffect('battle_drum_roll');
  playSoundEffect('bianqing_chime');
  triggerScreenShake(8, 250);
  spawnInkWashBloom(screenWidth / 2, screenHeight / 2, 100, proj ? proj.color : '#38bdf8');
  spawnGoldSpiral(screenWidth / 2, screenHeight / 2, 35);

  const stageName = MEGAPROJECT_STAGES[nextStg - 1].name;
  addChronicleItem(state.age, state.year, `【大国重器】主持【${proj ? proj.name : '重大专项'}】迈入【阶段${nextStg}：${stageName}】！国家有关部门通报嘉奖！`, '大国重器', 'promo');
  showToast(`工程突破！迈入【${stageName}】！`, 'gold');

  if (nextStg === 4) {
    addStat("rep", 10, 50);
    addStat("iq", 8, 50);
    awardMedal('medal_tech_summit');
    showToast(`🎉【${proj ? proj.name : '大国重器'}】全面竣工投产！获颁国家特级功勋！`, 'gold');
  }
  return true;
}


