// 🌟 V35 感悟心流属性浮字与时代水墨波纹引擎
function spawnFloatingRuneFX(text, x, y, color = '#fef08a') {
  const fxX = x || (screenWidth / 2);
  const fxY = y || (screenHeight / 2 - 40);
  if (typeof addFloatingText === 'function') {
    addFloatingText(text, fxX, fxY, color);
  }
}

function spawnEraPulseWaveFX(x, y, color = '#f59e0b') {
  const cx = x || (screenWidth / 2);
  const cy = y || (screenHeight / 2);
  if (typeof touchRipples !== 'undefined' && Array.isArray(touchRipples)) {
    [32, 54, 76].forEach((rMax, idx) => {
      touchRipples.push({
        x: cx,
        y: cy,
        radius: 4 + idx * 8,
        maxRadius: rMax,
        alpha: 0.9 - idx * 0.15,
        color: color,
        droplets: []
      });
    });
  }
}

