function isMedalAwarded(mId) {
  return (state.awardedMedals || []).includes(mId);
}

function awardMedal(mId) {
  if (isMedalAwarded(mId)) return;
  state.awardedMedals = state.awardedMedals || [];
  state.awardedMedals.push(mId);
  playSoundEffect('fanfare');
  playInstrumentTone('suona_heroic', 587.33, 2.0, 0.25);
  spawnInspirationSparks(screenWidth / 2, screenHeight / 2, 35);
  const m = STATE_MEDALS_DATABASE.find(item => item.id === mId);
  if (m) {
    addChronicleItem(state.age, state.year, `【国家荣誉】荣获【${m.name}】（${m.tier}）！${m.citation}，载入共和国履职功勋史册！`, "国家荣誉", "promo");
    showToast(`🎖️ 荣获【${m.name}】！光耀门楣！`, "gold");
  }
}

