function isRelicUnlocked(relicId) {
  const r = ERA_RELICS_DATABASE.find(item => item.id === relicId);
  if (!r) return false;
  if ((state.unlockedRelics || []).includes(relicId)) return true;
  return (state.year || 1972) >= r.yearUnlock;
}

// 90年代摩托罗拉BP机寻呼液晶微动效状态
let pagerAnim = {
  active: false,
  text: '',
  caller: '发小晓峰',
  code: '8888',
  alpha: 1.0,
  onConfirm: null
};

function triggerPagerCall(caller, code, message, onConfirm) {
  pagerAnim = {
    active: true,
    text: `【${caller} 呼号 ${code}】${message}`,
    caller,
    code,
    alpha: 1.0,
    onConfirm
  };
  playSoundEffect('pager_beep');
  triggerHaptic('medium');
  requestRender();
}

