// 交互热区管理与零分配对象池 (Hitbox Object Pool)
const HITBOX_OBJECT_POOL = [];
function obtainHitboxObj(id, x, y, width, height, handler, priority) {
  let box = HITBOX_OBJECT_POOL.pop();
  if (!box) {
    box = { id: '', x: 0, y: 0, width: 0, height: 0, handler: null, priority: 0 };
  }
  box.id = id;
  box.x = x;
  box.y = y;
  box.width = width;
  box.height = height;
  box.handler = handler;
  box.priority = priority || 0;
  return box;
}

function recycleHitboxes(list) {
  for (let i = 0; i < list.length; i++) {
    const box = list[i];
    box.handler = null;
    if (HITBOX_OBJECT_POOL.length < 300) {
      HITBOX_OBJECT_POOL.push(box);
    }
  }
  list.length = 0;
}

let hitboxes = [];
function registerHitbox(id, x, y, width, height, handler, priority) {
  hitboxes.push(obtainHitboxObj(id, x, y, width, height, handler, priority));
}

let scrollHitboxes = [];
function registerScrollHitbox(id, x, y, width, height, handler, priority) {
  if (state.activeModal) return;
  scrollHitboxes.push(obtainHitboxObj(id, x, y, width, height, handler, priority));
}

// 按钮触控按下沉降态与微质感反馈追踪 (Touch Pressed Visual Feedback)
let pressedHitboxId = null;

/**
 * 标准化微质感触觉按钮绘制器 (Tactile Physical Button Engine)
 * 统一处理按下检测 (pressedHitboxId)、Y轴物理下沉 (translate dy)、底色加深、边框高亮、文本居中排版与 hitbox 注册
 */
function drawTactileButton(contextOrOpts, maybeOpts) {
  let context, opts;
  if (maybeOpts !== undefined) {
    context = contextOrOpts;
    opts = maybeOpts;
  } else {
    context = (typeof ctx !== 'undefined') ? ctx : contextOrOpts;
    opts = contextOrOpts;
  }

  if (!opts || opts.w <= 0 || opts.h <= 0) return false;

  const {
    id, x, y, w, h,
    radius = 6,
    bg = '#1e293b',
    pressedBg = null,
    border = null,
    borderColor = null,
    pressedBorder = null,
    borderWidth = 1,
    text = '',
    font = 'bold 14px ' + FONT_UI,
    textColor = '#fff',
    pressedTextColor = null,
    dy = 1.5,
    onClick = null,
    priority = 10,
    renderContent = null,
    renderCustom = null,
    isScroll = false
  } = opts;

  const isPressed = (pressedHitboxId === id);

  context.save();
  if (isPressed) {
    context.translate(0, dy);
  }

  let finalBg = bg;
  if (isPressed) {
    finalBg = pressedBg || (bg === '#1e293b' ? '#0f172a' : (bg === '#78350f' ? '#592607' : (bg === '#0369a1' ? '#0284c7' : (bg === '#991b1b' ? '#7f1d1d' : bg))));
  }

  const rawBorder = borderColor || border || '#475569';
  let finalBorder = rawBorder;
  if (isPressed) {
    finalBorder = pressedBorder || (rawBorder === '#475569' ? '#94a3b8' : (rawBorder === '#f59e0b' ? '#fef08a' : (rawBorder === '#38bdf8' ? '#7dd3fc' : (rawBorder === '#ef4444' ? '#fca5a5' : rawBorder))));
  }

  if (finalBg && finalBg !== 'transparent') {
    context.fillStyle = finalBg;
    roundRect(context, x, y, w, h, radius, true, !!finalBorder, finalBorder, borderWidth);
  } else if (finalBorder && finalBorder !== 'transparent') {
    roundRect(context, x, y, w, h, radius, false, true, finalBorder, borderWidth);
  }

  if (typeof renderContent === 'function') {
    renderContent(context, isPressed);
  } else if (typeof renderCustom === 'function') {
    renderCustom(isPressed, context);
  } else if (text) {
    context.font = elevateFontSize(font, 12);
    context.fillStyle = isPressed ? (pressedTextColor || '#ffffff') : textColor;
    context.textAlign = 'center';
    context.textBaseline = 'middle';
    context.fillText(text, x + w / 2, y + h / 2);
  }

  context.restore();

  if (onClick) {
    if (isScroll) {
      registerScrollHitbox(id, x, y, w, h, onClick, priority);
    } else {
      registerHitbox(id, x, y, w, h, onClick, priority);
    }
  }
  return isPressed;
}

// 惯性滚动系统
let scrollY = 0;
let targetScrollY = 0;
let maxScrollY = 800;
let isTouching = false;
let touchStartX = 0;
let touchStartY = 0;
let lastTouchY = 0;
let touchLastTime = 0;
let scrollVelocity = 0;
let scrollbarAlpha = 0;
let tabTransition = { progress: 1.0, offsetY: 0 };

// Toast 队列
let toastQueue = [];
function showToast(text, type) {
  toastQueue.push({
    text: text,
    type: type || 'info',
    alpha: 1.0,
    startTime: Date.now()
  });
  if (toastQueue.length > 3) toastQueue.shift();
  requestRender();
}

function addChronicleItem(age, year, text, tag = "履职", type = "history") {
  state.chronicleHistory.unshift({ age, year, text, tag, type });
  if (state.chronicleHistory.length > 120) {
    state.chronicleHistory.length = 120;
  }
}

