// ==========================================
// 📈 V32 人生沉浮走势轨迹系统 (Life Trajectory Graph Engine)
// ==========================================
function recordTrajectoryPoint(eventTag = null, impact = 'normal') {
  if (!state.lifeTrajectory) state.lifeTrajectory = [];
  const score = Math.round(
    getStat("rep", 50) * 0.45 +
    Math.min(50, Math.log10(Math.max(10, state.capital || 100)) * 12) +
    (state.happiness || 80) * 0.2 +
    getStat("resilience", 50) * 0.15
  );
  state.lifeTrajectory.push({
    age: state.age || 18,
    year: state.year || 1992,
    score: score,
    eventTag: eventTag,
    impact: impact // 'crisis', 'echo', 'peak', 'normal'
  });
}

const LIFE_TRAJECTORY_SCRATCH = [];

function drawLifeTrajectoryGraph(ctx, x, y, w, h) {
  const pts = state.lifeTrajectory || [];
  if (pts.length < 2) return;

  ctx.save();
  // 背景底纸
  ctx.fillStyle = '#120d18';
  roundRect(ctx, x, y, w, h, 6, true, true, '#374151', 1);

  // 标题
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 14px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#f59e0b';
  ctx.fillText("📈【人生沉浮走势图 · 半生起落长卷】", x + 10, y + 8);

  ctx.textAlign = 'right';
  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#9ca3af';
  ctx.fillText("● 危机风暴  ★ 因果回响  ◆ 岁月高光", x + w - 10, y + 9);

  // 绘图区域边距
  const padL = 24;
  const padR = 14;
  const padT = 26;
  const padB = 20;
  const plotW = w - padL - padR;
  const plotH = h - padT - padB;

  // 计算极值
  const n = pts.length;
  const minAge = pts[0].age;
  const maxAge = Math.max(minAge + 10, pts[n - 1].age);
  let minScore = 9999, maxScore = -9999;
  for (let i = 0; i < n; i++) {
    const sc = pts[i].score;
    if (sc < minScore) minScore = sc;
    if (sc > maxScore) maxScore = sc;
  }
  minScore = Math.max(0, minScore - 10);
  maxScore = maxScore + 10;
  const scoreSpan = Math.max(20, maxScore - minScore);
  const ageSpan = (maxAge - minAge) || 1;

  // 绘制横向参考虚线
  ctx.save();
  ctx.strokeStyle = 'rgba(75, 85, 99, 0.35)';
  ctx.lineWidth = 0.8;
  ctx.setLineDash([3, 3]);
  for (let s = 0; s <= 2; s++) {
    const ly = y + padT + (plotH / 2) * s;
    ctx.beginPath();
    ctx.moveTo(x + padL, ly);
    ctx.lineTo(x + w - padR, ly);
    ctx.stroke();
  }
  ctx.restore();

  // 复用零分配缓存池计算坐标
  while (LIFE_TRAJECTORY_SCRATCH.length < n) {
    LIFE_TRAJECTORY_SCRATCH.push({ px: 0, py: 0 });
  }
  for (let i = 0; i < n; i++) {
    const p = pts[i];
    const s = LIFE_TRAJECTORY_SCRATCH[i];
    s.px = x + padL + ((p.age - minAge) / ageSpan) * plotW;
    s.py = y + padT + plotH - ((p.score - minScore) / scoreSpan) * plotH;
  }

  // 面积填充
  ctx.save();
  const fillGrad = ctx.createLinearGradient(0, y + padT, 0, y + padT + plotH);
  fillGrad.addColorStop(0, 'rgba(245, 158, 11, 0.25)');
  fillGrad.addColorStop(1, 'rgba(245, 158, 11, 0)');
  ctx.fillStyle = fillGrad;
  ctx.beginPath();
  const baseY = y + padT + plotH;
  ctx.moveTo(LIFE_TRAJECTORY_SCRATCH[0].px, baseY);
  for (let i = 0; i < n; i++) {
    ctx.lineTo(LIFE_TRAJECTORY_SCRATCH[i].px, LIFE_TRAJECTORY_SCRATCH[i].py);
  }
  ctx.lineTo(LIFE_TRAJECTORY_SCRATCH[n - 1].px, baseY);
  ctx.closePath();
  ctx.fill();

  // 水墨描线
  ctx.strokeStyle = '#f59e0b';
  ctx.lineWidth = 1.8;
  ctx.lineJoin = 'round';
  ctx.beginPath();
  ctx.moveTo(LIFE_TRAJECTORY_SCRATCH[0].px, LIFE_TRAJECTORY_SCRATCH[0].py);
  for (let i = 1; i < n; i++) {
    ctx.lineTo(LIFE_TRAJECTORY_SCRATCH[i].px, LIFE_TRAJECTORY_SCRATCH[i].py);
  }
  ctx.stroke();

  // 绘制里程碑特殊节点
  for (let i = 0; i < n; i++) {
    const c = pts[i];
    if (!c.impact) continue;
    const px = LIFE_TRAJECTORY_SCRATCH[i].px;
    const py = LIFE_TRAJECTORY_SCRATCH[i].py;
    if (c.impact === 'crisis') {
      ctx.fillStyle = '#ef4444';
      ctx.beginPath();
      ctx.arc(px, py, 3.5, 0, Math.PI * 2);
      ctx.fill();
      if (c.eventTag) {
        ctx.font = '13.5px ' + FONT_UI;
        ctx.fillStyle = '#fca5a5';
        ctx.textAlign = 'center';
        ctx.fillText(c.eventTag, px, py - 6);
      }
    } else if (c.impact === 'echo') {
      ctx.fillStyle = '#fef08a';
      ctx.beginPath();
      ctx.arc(px, py, 4, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = '#d97706';
      ctx.lineWidth = 1;
      ctx.stroke();
      if (c.eventTag) {
        ctx.font = 'bold 14px ' + FONT_UI;
        ctx.fillStyle = '#fef08a';
        ctx.textAlign = 'center';
        ctx.fillText(c.eventTag, px, py - 7);
      }
    } else if (c.impact === 'peak') {
      ctx.fillStyle = '#38bdf8';
      ctx.beginPath();
      ctx.arc(px, py, 3, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  // 底部年龄轴标尺
  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#94a3b8';
  ctx.textAlign = 'center';
  ctx.fillText(`${minAge}岁`, LIFE_TRAJECTORY_SCRATCH[0].px, y + h - 6);
  ctx.fillText(`${maxAge}岁`, LIFE_TRAJECTORY_SCRATCH[n - 1].px, y + h - 6);

  ctx.restore();
}
function generateProceduralBirth(forcedSurname = null, forcedGender = null) {
  const gender = forcedGender || (seededRandom() < 0.5 ? 'male' : 'female');
  const generated = generateRandomChineseName(gender);
  const surname = forcedSurname || generated.surname;
  const givenName = generated.givenName;

  const region = BIRTH_REGIONS[Math.floor(seededRandom() * BIRTH_REGIONS.length)];
  const compatibleProfs = PARENT_PROFESSIONS.filter(p => !p.regions || p.regions.includes(region.id));
  const profPool = compatibleProfs.length > 0 ? compatibleProfs : PARENT_PROFESSIONS;
  const parentProf = profPool[Math.floor(seededRandom() * profPool.length)];
  const sibling = SIBLING_STATUSES[Math.floor(seededRandom() * SIBLING_STATUSES.length)];

  // 生命自然天年初始基准 (76 ~ 83岁，后续随体魄透支、慢病危机与养生修为在 62 ~ 95 岁间动态演化)
  const lifespanCeiling = 76 + Math.floor(seededRandom() * 8);

  // 父母姓名
  const fatherName = surname + ['建国', '振华', '守诚', '德荣', '海川', '培元'][Math.floor(seededRandom() * 6)];
  const motherSurname = CHINESE_SURNAMES[Math.floor(seededRandom() * CHINESE_SURNAMES.length)];
  const motherName = motherSurname + ['桂兰', '秀珍', '淑芬', '慧英', '玉华', '文清'][Math.floor(seededRandom() * 6)];

  // 随机抽取 2 个正面特质 + 1 个负面特质
  const posTraits = INNATE_TRAIT_POOL.filter(t => t.type === 'pos').sort(() => 0.5 - seededRandom()).slice(0, 2);
  const negTraits = INNATE_TRAIT_POOL.filter(t => t.type === 'neg').sort(() => 0.5 - seededRandom()).slice(0, 1);
  const traits = [...posTraits, ...negTraits];

  // 出生年份固定在 1972 年（伴随尼克松访华、中日建交与时代萌动）
  const birthYear = 1972;

  return {
    surname,
    givenName,
    fullName: surname + givenName,
    gender,
    birthYear,
    lifespanCeiling,
    region,
    parents: {
      father: fatherName,
      mother: motherName,
      fatherRole: parentProf.fatherRole,
      motherRole: parentProf.motherRole,
      classType: parentProf.classType,
      fatherTrait: parentProf.fatherTrait,
      motherTrait: parentProf.motherTrait,
      baseSavings: parentProf.baseSavings + Math.floor(seededRandom() * 50)
    },
    sibling,
    traits,
    elementDestiny: ['gold', 'wood', 'water', 'fire', 'earth'][Math.floor(seededRandom() * 5)]
  };
}

