const NPC_FACTIONS = {
  biz_capital: { key: 'biz_capital', name: '产业资本与商业巨头', color: '#f59e0b', icon: '💼' },
  med_health: { key: 'med_health', name: '现代医学与生命健康', color: '#10b981', icon: '👨‍⚕️' },
  tech_pioneer: { key: 'tech_pioneer', name: '前沿科技与大国重器', color: '#38bdf8', icon: '🔬' },
  agri_roots: { key: 'agri_roots', name: '乡土中国与农业根基', color: '#84cc16', icon: '🌾' },
  culture_arts: { key: 'culture_arts', name: '文化传承与时代气象', color: '#ec4899', icon: '🎭' },
  law_order: { key: 'law_order', name: '法治合规与制度基石', color: '#a855f7', icon: '⚖️' },
  family_kin: { key: 'family_kin', name: '家国门风与至亲温情', color: '#f97316', icon: '🏡' }
};

function getCharacterFaction(c) {
  const id = c.id || '';
  if (['su_qing', 'qian_wanshan', 'lao_jin', 'dong_mishu', 'tang_caigou', 'sun_hangzhang', 'char_angela_hr'].includes(id)) {
    return NPC_FACTIONS.biz_capital;
  }
  if (['gu_jiaoshou', 'zhang_hushizhang', 'qin_zhuren', 'qi_zong', 'zhou_jiaoshou', 'char_dr_zhao_tcm', 'char_pharmacist_lin'].includes(id)) {
    return NPC_FACTIONS.med_health;
  }
  if (['li_lei', 'ding_boshi', 'lao_huang', 'a_lun', 'char_ai_scientist_dr_lu', 'char_quantum_researcher_tang', 'char_security_whitehat_k'].includes(id)) {
    return NPC_FACTIONS.tech_pioneer;
  }
  if (['chen_bo', 'gui_hua_sao', 'li_zhanzhang', 'liu_zong_agri', 'char_seed_breeder_he', 'char_smart_greenhouse_eva'].includes(id)) {
    return NPC_FACTIONS.agri_roots;
  }
  if (['bai_biandao', 'xue_zhipian', 'mo_guanzhang', 'char_game_producer_ark', 'char_heritage_restorer_liu', 'char_pop_singer_aria'].includes(id)) {
    return NPC_FACTIONS.culture_arts;
  }
  if (['hu_dazhuang', 'wei_dalvshi', 'jin_faguan', 'gao_fawu', 'char_arbitrator_victoria', 'char_legal_aid_sister_chen'].includes(id)) {
    return NPC_FACTIONS.law_order;
  }
  return NPC_FACTIONS.family_kin;
}

// 42位名仕四十年时代心境独白文库
