// 🌤️ V35 四时心境天时微气象计算引擎
function getLifeAtmosphere(age, resilience, health, happiness) {
  if (age < 30) {
    return { icon: '🌱', label: '朝气蓬勃 · 潜修立志', desc: '韶华正茂，心怀鸿鹄之志', color: '#38bdf8' };
  } else if (age < 45) {
    if ((resilience || 50) >= 80) {
      return { icon: '☀️', label: '如日中天 · 砥柱中流', desc: '盛年履职，任凭风浪起，稳坐钓鱼船', color: '#f59e0b' };
    } else {
      return { icon: '⚡', label: '激流勇进 · 破浪前行', desc: '时代浪潮奔涌，百舸争流奋楫者先', color: '#fb923c' };
    }
  } else if (age < 60) {
    if ((happiness || 80) >= 80) {
      return { icon: '🍂', label: '沉稳练达 · 融通自如', desc: '半生阅历化作春泥，通达豁达守正笃实', color: '#a855f7' };
    } else {
      return { icon: '⛈️', label: '千锤百炼 · 老骥伏枥', desc: '风雨兼程见初心，关山初度路犹长', color: '#3b82f6' };
    }
  } else {
    return { icon: '🏔️', label: '德劭松鹤 · 晚晴长明', desc: '莫道桑榆晚，为霞尚满天，桃李不言下自成蹊', color: '#34d399' };
  }
}

// ☯️ V36 「精气神三宝」生命元气演化引擎 (Sanbao Life Qi System)
function getSanbaoVitality(st) {
  if (!st) return { jing: 80, qi: 80, shen: 80, isFulfilled: true, statusText: '🌿 生生不息 · 和合安康' };
  const bJing = (st.sanbaoBonusJing || 0);
  const bQi = (st.sanbaoBonusQi || 0);
  const bShen = (st.sanbaoBonusShen || 0);
  const jing = Math.min(100, Math.max(10, Math.round(((st.health || 80) * 0.7 + (st.courage || 50) * 0.3) + bJing)));
  const qi = Math.min(100, Math.max(10, Math.round(((st.ap || 3) / (st.maxAp || 4)) * 50 + ((st.resilience || 50) * 0.5) + bQi)));
  const shen = Math.min(100, Math.max(10, Math.round(((st.iq || 50) * 0.5 + (st.happiness || 80) * 0.5) + bShen)));
  const isFulfilled = (jing >= 75 && qi >= 75 && shen >= 75);
  return {
    jing,
    qi,
    shen,
    isFulfilled,
    statusText: isFulfilled ? '🌟 元神充沛 · 诸邪不侵' : (jing < 40 ? '⚠️ 气血两虚 · 需调养' : (shen < 50 ? '🍂 心神耗竭 · 宜静心' : '🌿 生生不息 · 和合安康'))
  };
}

// 🧭 V37 五行本命与岁运罗盘演化引擎 (Five Elements Meridian Compass)
const FIVE_ELEMENTS_CYCLE = {
  gold:  { name: '金', generate: 'water', overcome: 'wood', generatedBy: 'earth', overcomeBy: 'fire', icon: '⚔️', aura: '#f59e0b' },
  wood:  { name: '木', generate: 'fire',  overcome: 'earth', generatedBy: 'water', overcomeBy: 'gold', icon: '🌿', aura: '#10b981' },
  water: { name: '水', generate: 'wood',  overcome: 'fire',  generatedBy: 'gold',  overcomeBy: 'earth', icon: '🌊', aura: '#38bdf8' },
  fire:  { name: '火', generate: 'earth', overcome: 'gold',  generatedBy: 'wood',  overcomeBy: 'water', icon: '🔥', aura: '#ef4444' },
  earth: { name: '土', generate: 'gold',  overcome: 'water', generatedBy: 'fire',  overcomeBy: 'wood', icon: '⛰️', aura: '#d97706' }
};

function getFiveElementsCompass(destinyKey, year) {
  const selfKey = destinyKey || 'gold';
  const y = year || 1990;
  // 天干五行: 甲乙木(0,1), 丙丁火(2,3), 戊己土(4,5), 庚辛金(6,7), 壬癸水(8,9)
  const stemIdx = Math.abs((y - 4) % 10);
  const stemElements = ['wood', 'wood', 'fire', 'fire', 'earth', 'earth', 'gold', 'gold', 'water', 'water'];
  const stemNames = ['甲木', '乙木', '丙火', '丁火', '戊土', '己土', '庚金', '辛金', '壬水', '癸水'];
  const curStemEle = stemElements[stemIdx];
  const curStemName = stemNames[stemIdx];

  const selfDef = FIVE_ELEMENTS_CYCLE[selfKey] || FIVE_ELEMENTS_CYCLE['gold'];
  const yearDef = FIVE_ELEMENTS_CYCLE[curStemEle] || FIVE_ELEMENTS_CYCLE['gold'];

  let relationship = '同气比肩';
  let desc = '岁运比和，行事沉稳，根基坚实。';
  let badgeColor = '#38bdf8';

  if (curStemEle === selfDef.generatedBy) {
    relationship = '岁运相生 · 逢时借力';
    desc = `${yearDef.name}生${selfDef.name}，时运相生，思绪泉涌，精力充盈！`;
    badgeColor = '#10b981';
  } else if (curStemEle === selfDef.generate) {
    relationship = '开枝散叶 · 功名宣达';
    desc = `${selfDef.name}生${yearDef.name}，才华挥洒，项目结出硕果，声誉提升！`;
    badgeColor = '#f59e0b';
  } else if (curStemEle === selfDef.overcomeBy) {
    relationship = '岁令考验 · 逆境见真';
    desc = `${yearDef.name}克${selfDef.name}，外部标准严苛，淬砺沉毅风骨！`;
    badgeColor = '#e11d48';
  } else if (curStemEle === selfDef.overcome) {
    relationship = '披荆斩棘 · 胜任攻坚';
    desc = `${selfDef.name}克${yearDef.name}，魄力过人，大刀阔斧扫除一切障碍！`;
    badgeColor = '#8b5cf6';
  }

  return {
    selfKey,
    selfName: selfDef.name,
    selfIcon: selfDef.icon,
    selfAura: selfDef.aura,
    yearStem: curStemName,
    relationship,
    desc,
    badgeColor
  };
}

