    const cutoffShift = (state.worldVolatility && state.worldVolatility.gaokaoCutoffShift) || 0;

    // 考场心态与发挥暗骰（同条件同选择也会因考场状态考出截然不同分数！）
    const nerveRoll = seededRandom();
