function getChildhoodNextStep(currentAge) {
  const milestones = [1, 6, 10, 12, 15, 18];
  const nextMs = milestones.find(m => m > currentAge) || 18;
  const dist = nextMs - currentAge;
  if (dist <= 0) return 1;
  if (dist === 3) return 3;
  if (dist >= 2) return 2;
  return dist;
}

function tickChildhoodYear() {
  const step = getChildhoodNextStep(state.age);
  state.age += step;
  state.year += step;
  recordLifeWaveHistoryPoint();

  state.maxAp = 3 + (state.bonusMaxAp || 0);
  state.ap = state.maxAp;
  triggerCalendarTear(state.year);

  const age = state.age;
  const yr = state.year;
  const pClass = (state.birthProfile && state.birthProfile.parents && state.birthProfile.parents.classType) || '工薪模范';

  // 1岁：抓周大典
  if (age === 1 && !state.handledEvents['zhuazhou_done']) {
    state.handledEvents['zhuazhou_done'] = true;
    if (!state.zhuazhouItem && Array.isArray(ZHUAZHOU_ITEMS) && ZHUAZHOU_ITEMS.length > 0) {
      const autoZhua = ZHUAZHOU_ITEMS[Math.floor(seededRandom() * ZHUAZHOU_ITEMS.length)];
      state.zhuazhouItem = autoZhua;
      state.tags = state.tags || {};
      state.tags['seed_' + autoZhua.seed] = true;
    }
    state.activeModal = 'zhuazhou';
    playSoundEffect('bell');
    triggerHaptic('heavy');
    saveGameState();
    requestRender();
    return;
  }

  // 基础童年自然拔节（按跃进步数等比平滑结算学业进度与核心素养）
  if (!state._skippedModalLastTick && age >= 6) {
    const studyPerYear = (pClass === '书香门第' ? 2.2 : 1.6);
    state.studyProgress = (state.studyProgress || 0) + studyPerYear * step;
  }
  const statRounds = Math.max(1, Math.round(step * 0.8));
  for (let s = 0; s < statRounds; s++) {
    addStat("iq", pClass === '书香门第' ? 2 : 1, 32);
    addStat("eq", pClass === '市井弄潮' ? 2 : 1, 32);
    addStat("courage", (pClass === '基层骨干' || pClass === '地质先锋') ? 2 : 1, 32);
    addStat("resilience", 1, 34);
  }
  clampCoreStats(state);

  const friendRolePrefixMap = {
    '基层骨干': '同村玩伴',
    '传统匠人': '老街发小',
    '市井弄潮': '街坊玩伴',
    '工薪模范': '厂矿发小',
    '地质先锋': '矿区玩伴',
    '书香门第': '同窗好友'
  };
  const friendPrefix = friendRolePrefixMap[pClass] || '童年发小';

  // 6岁或8岁：结识符合自身阶层背景的童年玩伴
  if ((age === 6 || age === 8) && (!state.childhoodFriends || state.childhoodFriends.length < 2) && seededRandom() < 0.75) {
    const friend = generateChildhoodFriend();
    state.childhoodFriends = state.childhoodFriends || [];
    state.childhoodFriends.push(friend);
    state.contacts = state.contacts || [];
    state.contacts.push({
      id: friend.id,
      name: friend.name,
      role: `${friendPrefix} · ${friend.label}`,
      avatar: friend.gender === 'male' ? '👦' : '👧',
      affinity: friend.affinity,
      npcFate: (state.worldVolatility && state.worldVolatility.friendFate) || 'reliable',
      isSwornGuardian: false
    });
    addChronicleItem(age, yr, `【童年交游】在${state.family.residenceName}附近结识了${friendPrefix}【${friend.name}】（${friend.label}），两人常常结伴上下学。`, '童年交游', 'promo');
    showToast(`结识${friendPrefix}【${friend.name}】！`, 'good');
  }

  // 11岁或8岁：偶遇同龄对手（概率触发）
  if ((age === 8 || age === 11) && (!state.childhoodRivals || state.childhoodRivals.length < 1) && seededRandom() < 0.65) {
    const rival = generateChildhoodRival();
    state.childhoodRivals = state.childhoodRivals || [];
    state.childhoodRivals.push(rival);
    addChronicleItem(age, yr, `【少年较劲】在班里撞上了处处与你别苗头的【${rival.name}】（${rival.label}），两人暗中较上了劲。`, '少年宿怨', 'alert');
  }

  // 核心里程碑事件：6岁（发蒙）、10岁（立志）、12岁（升学）停下进行深度交互
  if ((age === 6 || age === 10 || age === 12) && !state.handledEvents['child_milestone_' + age]) {
    const milestoneEvt = getChildhoodEventForAge(age);
    if (milestoneEvt) {
      state.handledEvents['child_milestone_' + age] = true;
      state.handledEvents['child_evt_' + (milestoneEvt.id || age)] = true;
      const tagMap = { 6: '发蒙启智', 10: '少年立志', 12: '初中升学' };
      openDecisionModal({
        id: 'childhood_milestone_' + age,
        title: milestoneEvt.title,
        desc: milestoneEvt.desc,
        choices: (milestoneEvt.choices || []).map((c, idx) => ({
          text: c.text,
          outcomeText: c.outcome,
          effects: c.effects,
          tag: tagMap[age] || '成长抉择',
          action: () => {
            if (c.effects) {
              if (c.effects.iq > 0) state.studyProgress = (state.studyProgress || 0) + 3;
              for (const [k, v] of Object.entries(c.effects)) {
                if (k === 'capital') state.capital = (state.capital || 0) + v;
                else addStat(k, v);
              }
            }
            if (c.youthPath) state.youthPath = c.youthPath;
          }
        }))
      });
      saveGameState();
      requestRender();
      return;
    }
  }

  // 15岁：初中毕业人生分流选择（保留，决定高中高考 vs 中专进厂 vs 参军 vs 闯特区 vs 务农）
  if (age === 15 && !state.handledEvents['child_evt_15']) {
    const forkEvt = getChildhoodEventForAge(15);
    if (forkEvt) {
      state.handledEvents['child_evt_15'] = true;
      openDecisionModal({
        id: 'childhood_evt_15',
        title: forkEvt.title,
        desc: forkEvt.desc,
        choices: forkEvt.choices.map(c => ({
          text: c.text,
          outcomeText: c.outcome,
          effects: c.effects,
          tag: '少年分流',
          youthPath: c.youthPath,
          action: () => {
            if (c.youthPath) state.youthPath = c.youthPath;
            if (c.youthPath === 'gaokao') state.studyProgress = (state.studyProgress || 0) + 4;
          }
        }))
      });
      saveGameState();
      requestRender();
      return;
    }
  }

  // 15岁以上若未手动指定分流，按家庭背景与个人特质概率演化
  if (age >= 15 && !state.youthPath) {
    const roll = seededRandom();
    if (pClass === '书香门第') {
      state.youthPath = roll < 0.78 ? 'gaokao' : (roll < 0.90 ? 'vocational' : 'commerce');
    } else if (pClass === '市井弄潮') {
      state.youthPath = roll < 0.45 ? 'commerce' : (roll < 0.80 ? 'gaokao' : 'vocational');
    } else if (pClass === '基层骨干') {
      state.youthPath = roll < 0.42 ? 'gaokao' : (roll < 0.72 ? 'agri' : 'military');
    } else if (pClass === '地质先锋') {
      state.youthPath = roll < 0.40 ? 'military' : (roll < 0.75 ? 'gaokao' : 'vocational');
    } else {
      state.youthPath = roll < 0.48 ? 'gaokao' : (roll < 0.82 ? 'vocational' : 'commerce');
    }
  }

  // 18岁：成人大典与真实高考/基层出路结算
  if (age >= 18 && !state.handledEvents['adult_ceremony_done']) {
    state.handledEvents['adult_ceremony_done'] = true;
    state.handledEvents['gaokao_done'] = true;
    if (!state._unlockedDeskAnnounced) {
      state._unlockedDeskAnnounced = true;
      showToast('🎉 弱冠成年！解锁【📋 案头】履职主线！', 'gold');
      addChronicleItem(age, yr, '【成年启航】弱冠及笄，正式踏入社会！【📋 案头】履职主线已全面解锁。', '系统引导', 'promo');
    }
    saveGameState();
    triggerGaokaoModal();
    return;
  }

  // 童年随机际遇（4~17岁，不再每年固定排表全出！每年约 42% 概率从【阶层专属池 + 年龄段池】中随机抽取，每局只经历 3~5 个不同童年事件）
  const childEventsCount = Object.keys(state.handledEvents || {}).filter(k => k.startsWith('child_evt_')).length;
  if (age >= 3 && age <= 17 && age !== 15 && childEventsCount < 4 && seededRandom() < 0.42) {
    // 优先匹配阶层专属童年事件
    const classMatches = CLASS_SPECIFIC_CHILDHOOD_POOL.filter(e =>
      e.classes.includes(pClass) && age >= e.minAge && age <= e.maxAge && !state.handledEvents['child_evt_' + e.id]
    );
    const pickedEvt = classMatches.length > 0
      ? classMatches[Math.floor(seededRandom() * classMatches.length)]
      : getChildhoodEventForAge(age);

    if (pickedEvt) {
      const evtKey = pickedEvt.id || age;
      if (!state.handledEvents['child_evt_' + evtKey]) {
        state.handledEvents['child_evt_' + evtKey] = true;
        if (state.isStreamlinedMode) {
          // 精简模式：自动采取第一项稳妥决策并记入编年史，不弹窗阻断游戏心流
          const c = pickedEvt.choices && pickedEvt.choices[0];
          if (c) {
            if (c.youthPath) state.youthPath = c.youthPath;
            if (c.effects) {
              if (c.effects.iq > 0) state.studyProgress = (state.studyProgress || 0) + 2;
              for (const [k, v] of Object.entries(c.effects)) {
                if (k === 'capital') state.capital = (state.capital || 0) + v;
                else addStat(k, v);
              }
            }
            if (c.seed) {
              state.childhoodKarmaSeeds = state.childhoodKarmaSeeds || [];
              state.childhoodKarmaSeeds.push({
                id: c.seed.id,
                age,
                year: yr,
                title: c.seed.title,
                desc: c.seed.desc
              });
              state.tags = state.tags || {};
              state.tags['seed_' + c.seed.id] = true;
            }
            addChronicleItem(age, yr, `【童年·${pickedEvt.title}】${c.text}。${c.outcomeText || ''}`, '童年历练', 'normal');
          }
        } else {
          openDecisionModal({
            id: pickedEvt.id || `childhood_evt_${age}`,
            title: pickedEvt.title,
            desc: pickedEvt.desc,
            choices: pickedEvt.choices.map(c => ({
              text: c.text,
              outcomeText: c.outcome,
              effects: c.effects,
              tag: '童年印记',
              youthPath: c.youthPath,
              action: () => {
                if (c.youthPath) state.youthPath = c.youthPath;
                if (c.effects && c.effects.iq > 0) state.studyProgress = (state.studyProgress || 0) + 2;
                if (c.seed) {
                  state.childhoodKarmaSeeds = state.childhoodKarmaSeeds || [];
                  state.childhoodKarmaSeeds.push({
                    id: c.seed.id,
                    age,
                    year: yr,
                    title: c.seed.title,
                    desc: c.seed.desc
                  });
                  state.tags['seed_' + c.seed.id] = true;
                }
              }
            }))
          });
          saveGameState();
          requestRender();
          return;
        }
      }
    }
  }

  // 根据年龄阶段与出身阶层生成符合成长规律的童年日常纪事
  const regionLabel = (state.birthProfile && state.birthProfile.region) ? state.birthProfile.region.name : '家乡';
  let notePool;
  if (age <= 3) {
    notePool = [
      `在父母温暖的牵引下摇摇晃晃走稳了步子，咿呀学语声让【${regionLabel}】的小屋充满欢笑。`,
      `坐在小竹推车里晒着暖阳，好奇地伸出小手去抓院里的蜻蜓与光斑。`,
      `夜里听着母亲轻柔的摇篮曲安然入睡，在家人呵护下一天天结实长大。`
    ];
  } else if (age <= 6) {
    notePool = [
      `缠着下班回家的父母讲过去的故事，蹲在院子里拿小树枝在泥地上画画认字。`,
      `跟街坊邻里的小伙伴在巷口捉迷藏、拍画片，清脆的童音回荡在暮色里。`,
      `冬日围在炉火旁吃着烤红薯，听收音机里的故事广播，对广阔天地充满好奇。`
    ];
  } else {
    const classGrowthNotes = {
      '基层骨干': [
        `清晨跟着父亲去村头自留地浇水除草，露水打湿了粗布裤脚。`,
        `放学后提着竹篮去山坡割青草，坐在田埂上看晚霞漫天。`,
        `煤油灯下趴在木桌前写算术题，母亲在一旁纳着千层底布鞋。`
      ],
      '传统匠人': [
        `放学后在老街铺面后院看父亲做木工竹艺，空气里满是桐油与木屑清香。`,
        `帮母亲把浆洗好的布料晾上竹竿，听街坊四邻聊着镇上的新鲜事。`
      ],
      '市井弄潮': [
        `课余在沿街摊位帮父母搭手看摊，耳濡目染练就了一手打算盘记账的本事。`,
        `听南来北往的客商讲沿海大城市的繁华见闻，心里暗暗向往外面的世界。`
      ],
      '书香门第': [
        `在教工宿舍窗前临摹字帖、背诵古诗，父亲用红笔仔细批改你的读书笔记。`,
        `周末泡在县新华书店角落里看连环画与科普读物，直到打烊才依依不舍离开。`
      ]
    };
    const fallbackNotes = [
      `在【${regionLabel}】的学校操场上迎风奔跑，个头又长高了一截。`,
      `冬日围在煤炉旁烤馒头片，听收音机里的评书连播，课余认真温习功课。`,
      `放学后帮家里去粮店排队买粮称盐，懂得体谅父母操持家计的辛劳。`
    ];
    notePool = classGrowthNotes[pClass] || fallbackNotes;
  }
  const leapTitle = step > 1 ? `光阴箭催 · ${step === 2 ? '两年一跃' : '三载飞逝'}` : '岁月拔节';
  addChronicleItem(age, yr, `${age}岁那年，${notePool[(age + yr) % notePool.length]}`, leapTitle, 'history');
  if (step > 1) {
    showToast(`光阴箭催 · ${step === 2 ? '两年一跃' : '三载飞逝'}，年满 ${age} 岁！`, 'info');
  } else {
    showToast(`度过成长的一年，年满 ${age} 岁！`, 'info');
  }
  playSoundEffect('coin');

  saveGameState();
  requestRender();
}


