// ==========================================
// ⚖️ P0 核心闭环：全量决策事件规范化、代价补齐、三元两难结构与支线联动引擎
// ==========================================
const _STAT_REQ_CYCLE = ['iq', 'courage', 'eq', 'clean', 'resilience', 'rep'];
const _STAT_CN_LABELS = {
  iq: '智谋', eq: '情商', courage: '魄力', clean: '清廉',
  rep: '声望', health: '体魄', resilience: '心性', sp: '精力', capital: '资金'
};

function _hashStrDeterministic(str) {
  const s = String(str || 'evt');
  let h = 2166136261 >>> 0;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return h >>> 0;
}

function formatEffectsSummaryText(eff) {
  if (!eff || typeof eff !== 'object') return '';
  const pos = [];
  const neg = [];
  for (const [k, v] of Object.entries(eff)) {
    if (!v || typeof v !== 'number') continue;
    const label = _STAT_CN_LABELS[k] || k;
    if (k === 'capital') {
      if (v > 0) pos.push(`${label}+¥${Math.abs(v).toLocaleString()}`);
      else neg.push(`${label}-¥${Math.abs(v).toLocaleString()}`);
    } else {
      if (v > 0) pos.push(`${label}+${v}`);
      else neg.push(`${label}${v}`);
    }
  }
  const posStr = pos.length > 0 ? pos.join('，') : '稳守基本盘';
  const negStr = neg.length > 0 ? `；代价：${neg.join('，')}` : '';
  return `${posStr}${negStr}`;
}

function _evalEffectBundleUnits(eff) {
  if (!eff || typeof eff !== 'object') return 0;
  let total = 0;
  for (const [k, v] of Object.entries(eff)) {
    if (typeof v !== 'number' || Number.isNaN(v)) continue;
    if (k === 'sp') continue;
    if (k === 'capital' || k === 'money') total += v / 4000;
    else total += v;
  }
  return total;
}

function enrichAndNormalizeDecisionEvent(evt) {
  if (!evt || typeof evt !== 'object' || !Array.isArray(evt.choices) || evt.choices.length === 0) return evt;
  if (evt.__normalizedP0) return evt;
  const h = _hashStrDeterministic(evt.id || evt.title || 'event');
  const baseAge = evt.minAge || evt.triggerAge || evt.age || (state && typeof state.age === 'number' && state.age > 0 ? state.age : 26);
  const evtIdStr = String(evt.id || '');
  const isChild = baseAge < 18 || evtIdStr.startsWith('child') || evtIdStr.includes('1984');

  // 1. 若事件仅有2个选项，先补齐第3个差异化取舍选项，统一纳入三元帕累托前沿规范化
  if (evt.choices.length === 2) {
    const padMode = (h % 3);
    let thirdChoice;
    if (padMode === 0) {
      thirdChoice = {
        text: isChild
          ? '借机请同伴搭把手走捷径省力气 · 护住体魄人缘但惹来微词'
          : '采取变通暗箱置换 · 违规走捷径换取即时周转（考验操守红线）',
        statReq: _STAT_REQ_CYCLE[(h + 2) % _STAT_REQ_CYCLE.length],
        tag: '急功近利',
        isGreyOption: !isChild,
        effects: isChild
          ? { health: 3, eq: 3, clean: -2, rep: -1 }
          : { capital: 18000, eq: 3, health: 2, clean: -6, rep: -4 },
        outcomeText: isChild
          ? '巧借同伴之力护住了体魄与人缘，但取巧之举令师长暗生微词'
          : '解了燃眉之急并赚得大笔周转，但越界行径让清廉与口碑遭受重挫，埋下问责隐患！',
        failText: '违规暗箱操作未能捂住盖子，反遭审计部门通报问责，不仅资金落空更让操守受损。'
      };
    } else if (padMode === 1) {
      thirdChoice = {
        text: isChild
          ? '随波逐流敷衍了事 · 避开繁难却养成因循懈怠'
          : '【因循苟且】多一事不如少一事 · 敷衍推诿求太平（得不偿失的平庸陷阱）',
        statReq: _STAT_REQ_CYCLE[(h + 3) % _STAT_REQ_CYCLE.length],
        tag: '因循苟且',
        isTrapOption: true,
        effects: isChild
          ? { health: 2, rep: -2, courage: -2, resilience: -1 }
          : { rep: -4, courage: -3, resilience: -2, capital: -2000 },
        outcomeText: isChild
          ? '看似省了力气，却在同伴面前失了担当与锐气'
          : '看似躲过了一时风口浪尖，但消极推诿令同僚失望、错失时代机遇，行业声誉与心性锐气蒙受严厉损耗！',
        failText: '盲目随波逐流不仅未得安稳，反而在责任排查中沦为替罪挡箭牌，全面失分。'
      };
    } else {
      thirdChoice = {
        text: isChild
          ? '主动把风光让给同伴并挑起苦活 · 耗损精力体魄但赢取公道口碑'
          : '自筹经费兜底并严守程序红线 · 耗费积蓄心力但筑牢清白公信',
        statReq: _STAT_REQ_CYCLE[(h + 4) % _STAT_REQ_CYCLE.length],
        tag: '守正兜底',
        effects: isChild
          ? { clean: 3, resilience: 3, health: -2, courage: -1 }
          : { clean: 4, resilience: 3, eq: 2, capital: -6000, courage: -2 },
        outcomeText: isChild
          ? '虽然累得满头大汗，但公道笃实之名深得大院同侪敬重'
          : '自掏腰包贴补缺口，虽折损了钱财锐气，却筑牢了无懈可击的清名与心性',
        failText: '保守兜底因沟通不畅未能平息争议，徒耗心力与经费。'
      };
    }
    evt.choices.push(thirdChoice);
  }

  // 2. 为3个选项分配互不相同的检定属性，消除情商(eq)检定扎堆与属性失衡
  const usedReqs = new Set();
  evt.choices.forEach((c, idx) => {
    if (!c || typeof c !== 'object') return;
    let candidate = c.statReq;
    // 若原检定为扎堆的 eq，按哈希分流一部分到 iq/courage/clean/resilience/rep
    if (candidate === 'eq' && ((h + idx) % 3 !== 0)) {
      candidate = _STAT_REQ_CYCLE[(h + idx * 2) % _STAT_REQ_CYCLE.length];
    }
    if (!candidate || usedReqs.has(candidate) || !_STAT_REQ_CYCLE.includes(candidate)) {
      for (let step = 0; step < _STAT_REQ_CYCLE.length; step++) {
        const tryStat = _STAT_REQ_CYCLE[(h + idx * 2 + step) % _STAT_REQ_CYCLE.length];
        if (!usedReqs.has(tryStat)) {
          candidate = tryStat;
          break;
        }
      }
    }
    c.statReq = candidate || _STAT_REQ_CYCLE[idx % _STAT_REQ_CYCLE.length];
    usedReqs.add(c.statReq);
  });

  // 3. 规范化每个选项（Archetype 0: 高门槛高上限高反噬 | Archetype 1: 中门槛均衡收益中反噬 | Archetype 2: 低门槛稳妥收益轻反噬）
  // 严格消除“两边都赚”虚假选择：在成人期定期引入“明哲保身”与“因循苟且”陷阱选项，奖励识别力
  evt.choices.forEach((c, idx) => {
    if (!c || typeof c !== 'object') return;
    const rawEff = (c.effects && typeof c.effects === 'object') ? { ...c.effects } : {};
    const mainStat = c.statReq || _STAT_REQ_CYCLE[(h + idx) % _STAT_REQ_CYCLE.length];
    const secStatPool = ['iq', 'eq', 'courage', 'clean', 'resilience', 'rep'].filter(k => k !== mainStat);
    const secStat = secStatPool[(h + idx) % secStatPool.length];
    const thirdStatPool = secStatPool.filter(k => k !== secStat);
    const thirdStat = thirdStatPool[(h + idx * 2) % thirdStatPool.length];
    const negRotPool = ['eq', 'resilience', 'courage', 'iq', 'rep'].filter(k => k !== mainStat && k !== secStat && k !== thirdStat);
    const negRotStat = negRotPool[(h + idx) % negRotPool.length] || 'resilience';

    const normEff = {};
    for (const [k, v] of Object.entries(rawEff)) {
      if (typeof v !== 'number' || Number.isNaN(v)) continue;
      if (k === 'sp') continue;
      if (k === 'capital') {
        if (isChild) continue;
        normEff[k] = v > 0
          ? Math.min(18000, Math.max(4000, Math.round(v * 0.55)))
          : Math.max(-4000, Math.min(-1200, Math.round(v * 0.40)));
      } else if (v > 0) {
        normEff[k] = isChild
          ? Math.min(4, Math.max(2, Math.round(v * 0.35)))
          : Math.min(5, Math.max(3, Math.round(v * 0.42)));
      }
    }

    if (idx === 0) {
      // 档位0（锐意攻坚）：最高门槛、最高成功净收益（约 +5.8 ~ +6.5），主属性与第三属性严格最高，带身心与经费投入
      for (const k of Object.keys(normEff)) {
        if (normEff[k] < 0) delete normEff[k];
      }
      normEff[mainStat] = isChild ? 4 : 5;
      normEff[secStat] = isChild ? 2 : 2;
      normEff[thirdStat] = isChild ? 2 : 3;
      if (isChild) {
        normEff[negRotStat] = -1;
      } else {
        normEff.health = -2;
        normEff[negRotStat] = -1;
        normEff.capital = -3200;
      }
    } else if (idx === 1) {
      // 档位1（稳健统筹 / 明哲保身陷阱）：在成人期约 25% 的事件中，将选项1转化为表面安稳实则明显落后的平庸陷阱
      for (const k of Object.keys(normEff)) {
        if (normEff[k] < 0) delete normEff[k];
      }
      if (!isChild && (h % 4 === 1)) {
        normEff[mainStat] = 1;
        normEff.rep = -3;
        normEff.courage = -2;
        normEff.resilience = -1;
        normEff.capital = -1500;
        c.tag = '明哲保身';
        c.isTrapOption = true;
        c.outcomeText = '看似明哲保身躲避了争议，但在重大关口缺乏担当，令上级与同僚看轻，错失声誉前程！';
        c.failText = '一味退缩推诿，终究难逃时代风浪淘汰，口碑与心性双重受损。';
      } else {
        normEff[mainStat] = isChild ? 2 : 3;
        normEff[secStat] = isChild ? 3 : (h % 3 === 1 ? 2 : 3);
        normEff[negRotStat] = isChild ? -1 : (h % 3 === 1 ? -2 : -1);
        if (!isChild) {
          normEff.capital = h % 3 === 1 ? -2200 : -1200;
        }
      }
    } else {
      // 档位2（审时借势/守正调摄/因循苟且陷阱）：最低门槛
      for (const k of Object.keys(normEff)) delete normEff[k];
      if (isChild) {
        normEff[mainStat] = 2;
        normEff.health = 3;
        normEff[negRotStat] = -1;
      } else {
        if (h % 3 === 0 && mainStat !== 'clean') {
          normEff.capital = 18000;
          normEff[mainStat] = 2;
          normEff.health = 2;
          normEff.clean = -6; // 显式灰色暗箱变通选项，直接扣减清廉
          normEff.rep = -3;
          c.isGreyOption = true;
        } else if (!isChild && (h % 4 === 1 || h % 4 === 2)) {
          // 明显更差的陷阱选项：看似低门槛省心，但净收益为负，惩罚平庸推诿，奖励玩家辨识力
          normEff[mainStat] = 1;
          normEff.rep = -4;
          normEff.resilience = -2;
          normEff.courage = -3;
          normEff.capital = -2000;
          c.tag = '因循苟且';
          c.isTrapOption = true;
          c.outcomeText = '看似躲过了一时劳碌，但消极推诿令同僚失望、错失时代机遇，行业声誉与心性锐气蒙受严厉损耗！';
          c.failText = '盲目随波逐流不仅未得安稳，反而在责任排查中沦为替罪挡箭牌。';
        } else {
          normEff[mainStat] = 2;
          normEff.health = 3;
          normEff.capital = 4000; // +1.0 unit
          normEff[negRotStat] = -1;
        }
      }
    }

    // 严格递增/递减的检定门槛（随年龄递增更具挑战性）
    if (isChild) {
      c.reqVal = idx === 0 ? 44 : (idx === 1 ? 37 : 30);
    } else {
      const ageOffset = Math.min(26, Math.max(0, Math.floor((baseAge - 18) * 0.52)));
      c.reqVal = idx === 0
        ? Math.min(86, 62 + ageOffset)
        : (idx === 1 ? Math.min(76, 53 + ageOffset) : Math.min(64, 44 + Math.floor(ageOffset * 0.65)));
    }

    c.effects = normEff;

    const costsObj = {};
    for (const [k, v] of Object.entries(normEff)) {
      if (typeof v === 'number' && v < 0) costsObj[k] = v;
    }
    c.costs = costsObj;

    // 严格分层的失败惩罚：FailLoss(0) < FailLoss(1) < FailLoss(2) < 0
    const fStat = c.statReq || 'iq';
    if (idx === 0) {
      c.failEffects = isChild
        ? { [fStat]: -2, [secStat]: -1, rep: -2, health: -1 }
        : (fStat === 'clean'
            ? { [fStat]: -3, rep: -4, health: -3, clean: -4, capital: -6000 }
            : { [fStat]: -3, [secStat]: -2, rep: -4, health: -3, capital: -6000 });
    } else if (idx === 1) {
      c.failEffects = isChild
        ? { [fStat]: -1, rep: -1, health: -1 }
        : (fStat === 'clean'
            ? { [fStat]: -2, rep: -1, health: -1, clean: -1, capital: -2000 }
            : { [fStat]: -2, rep: -1, health: -1, capital: -2000 });
    } else {
      c.failEffects = isChild
        ? { [fStat]: -1, rep: -1 }
        : (c.isGreyOption || fStat === 'clean'
            ? { [fStat]: -1, rep: -1, clean: -1, capital: -1200 }
            : { [fStat]: -1, rep: -1, capital: -1200 });
    }

    if (!c.failText) {
      c.failText = idx === 0
        ? `强行攻坚遭遇现实阻力反噬，不仅未达预期，更损耗了体魄、声誉与前期投入，并埋下后续追责隐患。`
        : (idx === 1
            ? `折中周旋未能平息各方分歧，耗费心力与经费却陷入被动局面。`
            : `审慎变通未能奏效，折损了部分人情口碑与周转经费。`);
    }

    const baseOutcome = (c.outcomeText || c.successText || c.outcome || '历尽艰辛完成抉择。')
      .replace(/（[^（）]*代价：[^（）]*）/g, '')
      .replace(/(智谋|情商|魄力|清廉|声望|声誉|体魄|健康|心性|抗逆力|动手能力|领袖潜质)\s*[+\-]\s*\d+/g, '')
      .replace(/(资本|资金)\s*[+\-]\s*¥?[\d,]+/g, '')
      .replace(/[，、！!]+$/g, '');
    const summaryStr = formatEffectsSummaryText(c.effects);
    c.outcomeText = `${baseOutcome}！（${summaryStr}）`;
    c.successText = c.outcomeText;
  });

  // 4. 按事件哈希确定性打乱3个选项的展示顺序（消除“无脑选第1项即最优”的位置偏差，同时保证同种子完全可复现）
  if (evt.choices.length === 3 && !evt.__skipChoicePermutation) {
    const perms = [
      [0, 1, 2],
      [0, 2, 1],
      [1, 0, 2],
      [1, 2, 0],
      [2, 0, 1],
      [2, 1, 0]
    ];
    const perm = perms[h % perms.length];
    evt.choices = perm.map(i => evt.choices[i]);
  }

  evt.__normalizedP0 = true;
  return evt;
}

PROCEDURAL_ANNUAL_ENCOUNTER_POOL.forEach(evt => enrichAndNormalizeDecisionEvent(evt));
if (typeof EXTENDED_STORY_ARCS !== 'undefined' && Array.isArray(EXTENDED_STORY_ARCS)) {
  EXTENDED_STORY_ARCS.forEach(evt => enrichAndNormalizeDecisionEvent(evt));
}
if (typeof MODULAR_STORY_DECK !== 'undefined' && Array.isArray(MODULAR_STORY_DECK)) {
  MODULAR_STORY_DECK.forEach(evt => enrichAndNormalizeDecisionEvent(evt));
}
if (typeof URBAN_FOLK_ENCOUNTERS !== 'undefined' && Array.isArray(URBAN_FOLK_ENCOUNTERS)) {
  URBAN_FOLK_ENCOUNTERS.forEach(evt => enrichAndNormalizeDecisionEvent(evt));
}
if (typeof BLACK_SWAN_EVENTS !== 'undefined' && Array.isArray(BLACK_SWAN_EVENTS)) {
  BLACK_SWAN_EVENTS.forEach(evt => enrichAndNormalizeDecisionEvent(evt));
}
if (typeof TRACK_SPECIFIC_STORIES !== 'undefined' && TRACK_SPECIFIC_STORIES && typeof TRACK_SPECIFIC_STORIES === 'object') {
  Object.values(TRACK_SPECIFIC_STORIES).forEach(arr => {
    if (Array.isArray(arr)) arr.forEach(evt => enrichAndNormalizeDecisionEvent(evt));
  });
}

function _matchesProceduralTrack(evtTrack, userTrack) {
  if (evtTrack === 'all') return true;
  if (evtTrack === userTrack) return true;
  const aliasMap = {
    gov: ['gov', 'grassroots'],
    tech: ['tech', 'education'],
    biz: ['biz', 'trade'],
    trade: ['trade', 'biz'],
    industry: ['industry', 'military'],
    military: ['military', 'industry', 'gov'],
    agri: ['agri', 'grassroots'],
    grassroots: ['grassroots', 'agri', 'gov'],
    art: ['art', 'education'],
    education: ['education', 'art', 'tech'],
    med: ['med', 'tech', 'art'],
    law: ['law', 'gov', 'art']
  };
  const allowed = aliasMap[userTrack] || [userTrack];
  return allowed.includes(evtTrack);
}

