function triggerProceduralAnnualEncounter() {
  if (state.activeModal) return false;

  const age = state.age;
  const userTrack = state.track || 'gov';
  const seedNum = (state.worldVolatility && state.worldVolatility.eraEncounterSeed) || _gameSeed || 1;
  const runBucket = Math.abs(seedNum) % 4;

  // 77岁+ 优先从高龄专属时代池 (TWILIGHT_ERA_2050_POOL) 按局内种子分桶抽取，彻底解决77岁后内容断崖
  if (age >= 77) {
    const twilightEligible = TWILIGHT_ERA_2050_POOL.filter((evt, idx) =>
      !(state.handledEvents && (state.handledEvents['proc_enc_' + evt.id] || state.handledEvents['base_evt_' + evt.id])) &&
      age >= (evt.minAge || 77) && age <= (evt.maxAge || 96) &&
      ((idx % 3 === Math.abs(seedNum) % 3) || seededRandom() < 0.35)
    );
    const fallbackTwilight = twilightEligible.length > 0 ? twilightEligible : TWILIGHT_ERA_2050_POOL.filter(evt =>
      !(state.handledEvents && (state.handledEvents['proc_enc_' + evt.id] || state.handledEvents['base_evt_' + evt.id]))
    );
    if (fallbackTwilight.length > 0) {
      const pickedTw = fallbackTwilight[Math.floor(seededRandom() * fallbackTwilight.length)];
      state.handledEvents = state.handledEvents || {};
      state.handledEvents['proc_enc_' + pickedTw.id] = true;
      state.handledEvents['base_evt_' + pickedTw.id] = true;
      state.lastMajorEventAge = age;
      openDecisionModal({
        id: `${userTrack}_${pickedTw.id}_b${runBucket}`,
        title: pickedTw.title,
        desc: pickedTw.desc,
        choices: pickedTw.choices.map(c => ({
          ...c,
          text: c.text,
          outcomeText: c.outcomeText,
          successText: c.outcomeText,
          failText: c.failText,
          statReq: c.statReq,
          reqVal: c.reqVal,
          costs: c.costs,
          effects: c.effects,
          failEffects: c.failEffects,
          tag: c.tag,
          action: () => {
            playSoundEffect('bell_grand_chime');
            showToast(`【${c.tag}】${(c.outcomeText || '').slice(0, 24)}...`, 'gold');
            addChronicleItem(state.age, state.year, `【晚晴抉择】${pickedTw.title}：${c.outcomeText}`, c.tag || '晚晴岁月', 'promo');
          }
        }))
      });
      return true;
    }
  }

  const baseAndExpanded = PROCEDURAL_ANNUAL_ENCOUNTER_POOL.concat(EXPANDED_TRACK_CAREER_POOL);
  const combinedPool = age >= 52
    ? baseAndExpanded.concat(LATE_CAREER_ENCOUNTER_POOL)
    : baseAndExpanded;

  // 优先抽取本赛道且归属本局种子分桶 (_variantBucket) 的专属事件，降低同赛道重玩重合率
  const allEligible = combinedPool.filter(evt => {
    if (state.handledEvents && (state.handledEvents['proc_enc_' + evt.id] || state.handledEvents['base_evt_' + evt.id])) return false;
    if (evt.minAge && age < evt.minAge) return false;
    const effMaxAge = (evt.minAge && evt.minAge < 18) ? (evt.maxAge || 17) : Math.max(evt.maxAge || 92, 95);
    if (age > effMaxAge) return false;
    if (typeof evt._variantBucket === 'number' && evt._variantBucket !== runBucket && seededRandom() > 0.15) return false;
    return _matchesProceduralTrack(evt.track, userTrack);
  });

  if (allEligible.length === 0) return false;

  const exactTrack = allEligible.filter(evt => evt.track === userTrack);
  const lateSpecial = age >= 54 ? allEligible.filter(evt => String(evt.id).startsWith('late_')) : [];
  const trackExclusive = allEligible.filter(evt => evt.track !== 'all');
  const rollPool = seededRandom();
  const poolToPick = (lateSpecial.length > 0 && rollPool < 0.24)
    ? lateSpecial
    : ((exactTrack.length > 0 && age >= 18 && rollPool < 0.82)
        ? exactTrack
        : ((trackExclusive.length > 0 && age >= 18 && rollPool < 0.92) ? trackExclusive : allEligible));
  const picked = enrichAndNormalizeDecisionEvent(poolToPick[Math.floor(seededRandom() * poolToPick.length)]);
  state.handledEvents = state.handledEvents || {};
  state.handledEvents['proc_enc_' + picked.id] = true;
  state.handledEvents['base_evt_' + picked.id] = true;
  state.lastMajorEventAge = age;

  openDecisionModal({
    id: picked.track === userTrack ? `${picked.id}_b${runBucket}` : `${userTrack}_${picked.id}_b${runBucket}`,
    title: picked.title,
    desc: picked.desc,
    choices: picked.choices.map(c => ({
      ...c,
      text: c.text,
      outcomeText: c.outcomeText,
      successText: c.outcomeText,
      failText: c.failText,
      statReq: c.statReq,
      reqVal: c.reqVal,
      costs: c.costs,
      effects: c.effects,
      failEffects: c.failEffects,
      tag: c.tag,
      // P0-1 修复：action 仅做音效/Toast/编年史附加逻辑，绝不重复叠加 c.effects！
      action: () => {
        playSoundEffect('bell_grand_chime');
        showToast(`【${c.tag}】${(c.outcomeText || '').slice(0, 24)}...`, 'gold');
        addChronicleItem(state.age, state.year, `【时代抉择】${picked.title}：${c.outcomeText}`, c.tag || '履职历练', 'promo');
      }
    }))
  });

  return true;
}


