// 🏡 家庭生老病死亲情长卷触发器
function triggerFamilyMortalityEvent() {
  if (state.activeModal) return false;
  const age = state.age;
  const hasSpouse = !!(state.family && state.family.spouseName);
  const hasChildren = !!(state.family && ((state.family.children && state.family.children.length > 0) || state.family.childName));

  for (let evt of FAMILY_MORTALITY_ENGINE.events) {
    if (evt.id === 'fam_grandchild_arrival' && !hasChildren) continue;
    if (evt.id === 'fam_golden_wedding' && !hasSpouse) continue;
    if (age === evt.targetAge && (!state.handledEvents || !state.handledEvents['fam_' + evt.id])) {
      state.handledEvents = state.handledEvents || {};
      state.handledEvents['fam_' + evt.id] = true;
      state.lastMajorEventAge = age;

      if (evt.id === 'fam_parent_farewell') {
        playSoundEffect('erhu_sorrow');
        triggerScreenShake(6, 300);
      } else if (evt.id === 'fam_golden_wedding') {
        playSoundEffect('triumph_brass');
        triggerScreenShake(8, 350);
      } else {
        playSoundEffect('bell_grand_chime');
      }

      openDecisionModal({
        id: evt.id,
        title: evt.title,
        desc: evt.desc,
        choices: evt.choices.map(c => ({
          ...c,
          text: c.text,
          outcomeText: c.outcomeText,
          effects: c.effects,
          tag: c.tag,
          action: () => {
            playSoundEffect('bell_grand_chime');
            showToast(`🏡【人间冷暖·亲情印记】${c.tag}！`, 'gold');
            addChronicleItem(state.age, state.year, `【亲情岁月】${evt.title}：${c.outcomeText}`, c.tag, 'promo');
          }
        }))
      });
      return true;
    }
  }
  return false;
}

