function triggerGrassrootsLetterEvent() {
  if (state.activeModal) return false;
  const age = state.age;

  for (let letData of GRASSROOTS_LETTERS_ENGINE.letters) {
    if (age === letData.targetAge && (!state.handledEvents || !state.handledEvents['letter_' + letData.id])) {
      state.handledEvents = state.handledEvents || {};
      state.handledEvents['letter_' + letData.id] = true;
      state.currentGrassrootsLetter = letData;
      state.activeModal = 'grassroots_letter';

      playSoundEffect('pipa_spring_blossoms');
      triggerHaptic('medium');
      requestRender();
      return true;
    }
  }
  return false;
}

function drawGrassrootsLetterModal() {
  const cardW = Math.min(screenWidth - 28, 350);
  const cardH = 460;
  const startX = (screenWidth - cardW) / 2;
  const startY = (screenHeight - cardH) / 2;

  const letData = state.currentGrassrootsLetter;
  if (!letData) {
    state.activeModal = null;
    return;
  }

  ctx.save();
  // 墨绿竹青卷轴外框
  drawSilkScrollFrame(ctx, startX, startY, cardW, cardH, '#059669', '#d97706');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';

  // 1. 信件邮戳徽章
  ctx.fillStyle = 'rgba(5, 150, 105, 0.35)';
  roundRect(ctx, startX + cardW / 2 - 70, startY + 14, 140, 26, 6, true, true, '#10b981', 1);
  ctx.font = 'bold 14px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#a7f3d0';
  ctx.fillText('📯 ' + letData.stamp, startX + cardW / 2, startY + 20);

  // 2. 信件标题与寄件人
  ctx.font = 'bold 14px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText(letData.title, startX + cardW / 2, startY + 48);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#cbd5e1';
  ctx.fillText('来信人：' + letData.sender, startX + cardW / 2, startY + 68);

  // 3. 信笺正文宣纸底衬
  const letterBoxY = startY + 86;
  const letterBoxH = 175;
  ctx.fillStyle = '#1c1917';
  roundRect(ctx, startX + 16, letterBoxY, cardW - 32, letterBoxH, 6, true, true, '#d97706', 0.8);

  ctx.textAlign = 'left';
  ctx.font = '13.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fde68a';
  drawWrappedText(ctx, letData.desc, startX + 26, letterBoxY + 14, cardW - 52, 17);

  // 4. 两个回复抉择按钮
  const btnW = cardW - 32;
  const btnH = 42;
  let curBtnY = letterBoxY + letterBoxH + 12;

  letData.choices.forEach((ch, idx) => {
    drawTactileButton(ctx, {
      id: 'letter_choice_' + idx,
      x: startX + 16,
      y: curBtnY,
      w: btnW,
      h: btnH,
      radius: 6,
      bg: idx === 0 ? '#064e3b' : '#1e1b4b',
      border: idx === 0 ? '#10b981' : '#6366f1',
      borderWidth: 1,
      priority: 60,
      renderContent: (c) => {
        c.textAlign = 'left';
        c.textBaseline = 'top';
        c.font = 'bold 14px ' + FONT_CHRONICLE;
        c.fillStyle = idx === 0 ? '#a7f3d0' : '#c7d2fe';
        c.fillText('✉️ ' + ch.text, startX + 24, curBtnY + 8);

        c.font = '13.5px ' + FONT_UI;
        c.fillStyle = '#94a3b8';
        const effStr = '【' + ch.tag + '】' + (ch.effects.resilience ? '内省抗逆+' + ch.effects.resilience + ' ' : '') + (ch.effects.rep ? '声望+' + ch.effects.rep : '');
        c.fillText(effStr, startX + 24, curBtnY + 24);
      },
      onClick: () => {
        // 执行回复选项
        addStat("resilience", Math.min(8, ch.effects.resilience || 0), 50);
        if (ch.effects) {
          Object.keys(ch.effects).forEach(k => {
            if (k === 'resilience') return;
            if (k === 'capital' || k === 'money' || k === 'wealth') {
              state.capital = Math.max(0, (state.capital || 0) + ch.effects[k]);
            } else if (typeof state[k] === 'number') {
              addStat(k, Math.min(6, ch.effects[k]), 50);
            }
          });
        }
        playSoundEffect('bell_grand_chime');
        triggerHaptic('medium');
        showToast('💌【见字如面】' + ch.tag + '！内省抗逆力稳步提升！', 'gold');
        addChronicleItem(state.age, state.year, '【民间书简】' + letData.title + '：' + ch.outcomeText, ch.tag, 'promo');
        state.activeModal = null;
        requestRender();
      }
    });

    curBtnY += btnH + 8;
  });

  ctx.restore();
}

