function triggerButterflyNexusStage() {
  if (state.activeModal) return false;
  const age = state.age;
  state.butterflyNexus = state.butterflyNexus || [];

  // 1. 检查是否有已种下的链处于 Stage 1，并在中年触发 Stage 2
  for (let record of state.butterflyNexus) {
    if (record.stage === 1) {
      const chain = CASCADING_BUTTERFLY_NEXUS.chains.find(c => c.id === record.chainId);
      if (chain && chain.stage2 && age >= chain.stage2.minAge && age <= chain.stage2.maxAge && !record.stage2Done) {
        record.stage2Done = true;
        record.stage = 2;
        state.lastMajorEventAge = age;

        playSoundEffect('fanfare');
        playSoundEffect('heartbeat_dilemma');
        triggerScreenShake(6, 250);

        openDecisionModal({
          id: 'butterfly_stage2_' + chain.id,
          title: chain.stage2.title,
          desc: chain.stage2.desc,
          choices: chain.stage2.choices.map(c => ({
            ...c,
            text: c.text,
            outcomeText: c.outcomeText,
            effects: c.effects,
            tag: c.tag,
            action: () => {
              playSoundEffect('bell_grand_chime');
              showToast(`🦋【蝴蝶因果·中阶破茧】${c.tag}！`, 'gold');
              addChronicleItem(state.age, state.year, `【因果回响】${chain.stage2.title}：${c.outcomeText}`, c.tag, 'promo');
            }
          }))
        });
        return true;
      }
    }
  }

  // 2. 检查是否有已处于 Stage 2 的链，在晚年触发 Stage 3 终极大成
  for (let record of state.butterflyNexus) {
    if (record.stage === 2) {
      const chain = CASCADING_BUTTERFLY_NEXUS.chains.find(c => c.id === record.chainId);
      if (chain && chain.stage3 && age >= chain.stage3.minAge && age <= chain.stage3.maxAge && !record.stage3Done) {
        record.stage3Done = true;
        record.stage = 3;
        state.lastMajorEventAge = age;

        playSoundEffect('triumph_brass');
        triggerScreenShake(10, 400);

        openDecisionModal({
          id: 'butterfly_stage3_' + chain.id,
          title: chain.stage3.title,
          desc: chain.stage3.desc,
          choices: chain.stage3.choices.map(c => ({
            ...c,
            text: c.text,
            outcomeText: c.outcomeText,
            effects: c.effects,
            tag: c.tag,
            action: () => {
              playSoundEffect('triumph_brass');
              showToast(`👑【蝴蝶因果·大成圆满】${c.tag}！万世垂范！`, 'gold');
              addChronicleItem(state.age, state.year, `【因果大成】${chain.stage3.title}：${c.outcomeText}`, c.tag, 'promo');
            }
          }))
        });
        return true;
      }
    }
  }

  // 3. 青年期初次种下蝴蝶因果之种 (Age 21~32，若未达到上限)
  if (state.butterflyNexus.length < 2 && age >= 21 && age <= 32 && seededRandom() < 0.55) {
    const existingIds = state.butterflyNexus.map(r => r.chainId);
    const availableChains = CASCADING_BUTTERFLY_NEXUS.chains.filter(c => !existingIds.includes(c.id) && age >= c.stage1.minAge && age <= c.stage1.maxAge);
    if (availableChains.length > 0) {
      const pickedChain = availableChains[Math.floor(seededRandom() * availableChains.length)];
      state.lastMajorEventAge = age;

      playSoundEffect('causal_nexus_echo');
      triggerScreenShake(5, 200);

      openDecisionModal({
        id: 'butterfly_stage1_' + pickedChain.id,
        title: pickedChain.stage1.title,
        desc: pickedChain.stage1.desc,
        choices: pickedChain.stage1.choices.map(c => ({
          ...c,
          text: c.text,
          outcomeText: c.outcomeText,
          effects: c.effects,
          tag: c.tag,
          action: () => {
            state.butterflyNexus.push({
              chainId: pickedChain.id,
              name: pickedChain.name,
              stage: 1,
              seedYear: state.year,
              seedAge: state.age,
              choiceTag: c.tag,
              summary: c.outcomeText
            });
            playSoundEffect('bell_grand_chime');
            showToast(`🌱【蝴蝶因果·种下因由】${pickedChain.name}（伏脉千里，数十年后必有回响）`, 'gold');
            addChronicleItem(state.age, state.year, `【因果初萌】${pickedChain.stage1.title}：${c.outcomeText}`, c.tag, 'promo');
          }
        }))
      });
      return true;
    }
  }

  return false;
}

// 沧海横流无常命运触发器
function triggerVicissitudesEvent() {
  if (state.activeModal) return false;
  const age = state.age;

  const eligible = VICISSITUDES_OF_LIFE_ENGINE.events.filter(e => {
    if (state.handledEvents && state.handledEvents['vic_' + e.id]) return false;
    if (e.minAge && age < e.minAge) return false;
    if (e.maxAge && age > e.maxAge) return false;
    return true;
  });

  if (eligible.length === 0) return false;

  const picked = eligible[Math.floor(seededRandom() * eligible.length)];
  state.handledEvents = state.handledEvents || {};
  state.handledEvents['vic_' + picked.id] = true;
  state.lastMajorEventAge = age;

  playSoundEffect('heartbeat_dilemma');
  playSoundEffect('guqin_melancholy');
  triggerScreenShake(7, 300);

  openDecisionModal({
    id: picked.id,
    title: picked.title,
    desc: picked.desc,
    choices: picked.choices.map(c => ({
      ...c,
      text: c.text,
      outcomeText: c.outcomeText,
      effects: c.effects,
      tag: c.tag,
      action: () => {
        playSoundEffect('bell_grand_chime');
        showToast(`【${c.tag}】历经波澜，心性淬炼！`, 'gold');
        addChronicleItem(state.age, state.year, `【人生波澜】${picked.title}：${c.outcomeText}`, c.tag || '沧海横流', 'promo');
      }
    }))
  });

  return true;
}

// ==========================================
// 🎯 连续性与上瘾感核心引擎：三年攻坚军令状与下一阶段大考倒计时
// ==========================================
const THREE_YEAR_PACT_TEMPLATES = [
  { id: 'pact_tech_core', title: '关键核心工序自主化三年攻坚状', statKey: 'iq', statLabel: '智谋', delta: 4, rewardCap: 6500, rewardRep: 4, desc: '批办案头公文、一线督战或研习算盘可推进攻坚进度' },
  { id: 'pact_clean_model', title: '阳光工程与清廉示范三年军令状', statKey: 'clean', statLabel: '清廉', delta: 3, rewardCap: 5500, rewardRep: 4, desc: '批示重拟、修身内省或钤印立信可推进军令状进度' },
  { id: 'pact_frontline_lead', title: '重大项目一线铁军三年突围状', statKey: 'courage', statLabel: '魄力', delta: 4, rewardCap: 7500, rewardRep: 4, desc: '一线督战、特急容缺或神州巡访可推进攻坚进度' },
  { id: 'pact_people_livelihood', title: '万家灯火民生福祉三年军令状', statKey: 'rep', statLabel: '声誉', delta: 4, rewardCap: 7000, rewardRep: 5, desc: '准予执行、名仕私晤或门庭治家可推进军令状进度' }
];

function ensureThreeYearPact() {
  if ((state.age || 0) < 18) return null;
  if (!state.activeThreeYearPact || state.age > state.activeThreeYearPact.endAge || state.activeThreeYearPact.completed) {
    const idx = Math.abs(Math.floor((state.age - 18) / 3)) % THREE_YEAR_PACT_TEMPLATES.length;
    const tpl = THREE_YEAR_PACT_TEMPLATES[idx];
    const curStat = state[tpl.statKey] || 48;
    state.activeThreeYearPact = {
      id: `${tpl.id}_${state.age}`,
      title: tpl.title,
      statKey: tpl.statKey,
      statLabel: tpl.statLabel,
      targetVal: Math.min(84, curStat + tpl.delta),
      startAge: state.age,
      endAge: state.age + 3,
      progress: 18,
      rewardCap: tpl.rewardCap,
      rewardRep: tpl.rewardRep,
      desc: tpl.desc,
      completed: false
    };
  }
  return state.activeThreeYearPact;
}

function progressThreeYearPact(amount, actionLabel) {
  if ((state.age || 0) < 18) return;
  if (actionLabel && actionLabel !== '准予执行' && actionLabel !== '特急容缺') {
    state.annualActionsTaken = (state.annualActionsTaken || 0) + 1;
    state.threeYearActionCount = (state.threeYearActionCount || 0) + 1;
    state.inactionStreak = 0;
  }
  const pact = ensureThreeYearPact();
  if (!pact || pact.completed) return;
  const prevProgress = pact.progress || 0;
  pact.progress = Math.min(100, prevProgress + amount);
  if (amount > 0 && ((prevProgress < 55 && pact.progress >= 55) || (prevProgress < 92 && pact.progress >= 92))) {
    addStat(pact.statKey, 1, 50);
  }
  const curStat = state[pact.statKey] || 0;
  if (pact.progress >= 100 && curStat >= pact.targetVal) {
    completeThreeYearPact(pact, actionLabel || '主动履职攻坚');
  } else if (actionLabel) {
    if (typeof spawnFloatingRuneFX === 'function') {
      spawnFloatingRuneFX(`🔥 军令状进度 +${amount}% (${pact.progress}%)`, screenWidth / 2, (typeof getDashboardY === 'function' ? getDashboardY() : 180) + 32, '#fbbf24');
    }
  }
}

function completeThreeYearPact(pact, triggerSource) {
  if (!pact || pact.completed) return;
  pact.completed = true;
  state.capital = (state.capital || 0) + (pact.rewardCap || 5500);
  addStat("rep", Math.min(2, pact.rewardRep || 2), 50);
  addStat("sp", 12, 0);
  addStat("resilience", 1, 50);
  state.completedPactsCount = (state.completedPactsCount || 0) + 1;
  clampCoreStats(state);
  playSoundEffect('fanfare');
  triggerHaptic('heavy');
  showToast(`🏆 达成《${pact.title}》！声誉+2，奖金+¥${(pact.rewardCap / 10000).toFixed(1)}万！`, 'gold');
  addChronicleItem(state.age, state.year, `【军令状达成】通过${triggerSource}圆满兑现《${pact.title}》，组织通令嘉奖，获批专项奖励 ¥${pact.rewardCap.toLocaleString()}，声誉+2！`, '军令必达', 'promo');
  // 立即立下下一阶段新军令状，形成无缝连续目标链
  state.activeThreeYearPact = null;
  ensureThreeYearPact();
}

function advanceThreeYearPactAnnual() {
  if ((state.age || 0) < 18) return;
  const pact = ensureThreeYearPact();
  if (!pact) return;
  const isActivelyEngaged = (state.inactionStreak || 0) === 0;
  pact.progress = Math.min(100, (pact.progress || 0) + (isActivelyEngaged ? 20 : 2));
  const curStat = state[pact.statKey] || 0;
  if (pact.progress >= 100 && curStat >= pact.targetVal && isActivelyEngaged) {
    completeThreeYearPact(pact, '年度实干笃行');
  } else if (state.age >= pact.endAge) {
    if (pact.progress >= 88 && curStat >= pact.targetVal && isActivelyEngaged) {
      completeThreeYearPact(pact, '三年期满收官验收');
    } else {
      if ((state.inactionStreak || 0) >= 2) {
        addStat("rep", -4, 50);
        addStat("clean", -3, 80);
        addChronicleItem(state.age, state.year, `【军令状未达标】《${pact.title}》三年期满因履职懈怠未能达标（完成度${pact.progress}%），受到通报批评，声誉-4、清廉-3。`, '问责警示', 'crisis');
      } else {
        addChronicleItem(state.age, state.year, `【三年期满复盘】《${pact.title}》三年期满，虽未全额突破高标（完成度${pact.progress}%），但积累了宝贵一线经验，抗逆力+1。`, '复盘砥砺', 'history');
        addStat("resilience", 1, 50);
      }
      state.activeThreeYearPact = null;
      ensureThreeYearPact();
    }
  }
}

function getNextMilestoneInfo() {
  const age = state.age || 0;
  const yr = state.year || 1980;
  if (age < 18) {
    if (age === 0) {
      return {
        title: '🍼 距离【周岁抓周 · 启蒙礼】仅剩 1 年',
        subTitle: '呱呱坠地沐浴亲恩，点击底部【满周岁 · 抓周礼】迎接周岁庆典',
        progress: 15,
        badge: '襁褓初生',
        color: '#38bdf8'
      };
    }
    if (age < 7) {
      const toSchool = 7 - age;
      return {
        title: `🧸 距离【七岁背上书包正式入学】还有 ${toSchool} 年`,
        subTitle: age >= 3
          ? `学龄前启蒙期：可在下方参与识字、嬉戏与家务，涵养灵性与体魄`
          : `幼年成长期：在父母呵护下学步习语，健康快乐成长`,
        progress: Math.min(100, Math.round((age / 7) * 100)),
        badge: `距入学 ${toSchool} 载`,
        color: '#38bdf8'
      };
    }
    if (age < 15) {
      const toBranch = 15 - age;
      const curIq = state.iq || 50;
      return {
        title: `🎒 距离【十五岁初中毕业 · 志向抉择】还有 ${toBranch} 年`,
        subTitle: `少年求学期：当前才智 ${curIq}，德智体美全面积累，为初中毕业去向打好根基`,
        progress: Math.min(100, Math.round(((age - 7) / 8) * 100)),
        badge: `距毕业 ${toBranch} 载`,
        color: '#38bdf8'
      };
    }
    const yearsLeft = Math.max(1, 18 - age);
    const yp = state.youthPath || 'gaokao';
    const curIq = state.iq || 50;
    const targetIq = 70;
    const pathTitleMap = {
      gaokao: `🎓 距离【18岁全国高考·人生分水岭】仅剩 ${yearsLeft} 年`,
      vocational: `🛠️ 距离【18岁中专出徒·进厂定岗】仅剩 ${yearsLeft} 年`,
      military: `🪖 距离【18岁应征入伍·奔赴军营】仅剩 ${yearsLeft} 年`,
      commerce: `🚢 距离【18岁南下特区·商海立业】仅剩 ${yearsLeft} 年`,
      agri: `🌾 距离【18岁农技试验站·扎根乡土】仅剩 ${yearsLeft} 年`
    };
    const pathSubMap = {
      gaokao: `冲刺重点大学门槛：才智 ${curIq}/${targetIq} (${curIq >= targetIq ? '✓ 已达标，保持优势' : `还差 ${targetIq - curIq} 点，建议多用精力苦读`})`,
      vocational: `实训车间潜心磨炼钳工与机械技艺，备战十八岁正式出徒定岗`,
      military: `坚持体能拉练与作风锤炼（当前体魄 ${state.health || 80}、胆识 ${state.courage || 50}），备战军旅征程`,
      commerce: `积累人情历练与商业嗅觉（当前情商 ${state.eq || 50}、家庭积蓄 ¥${(state.capital || 0).toLocaleString()}），备战特区弄潮`,
      agri: `钻研良种培育与田间实操（当前品行 ${state.clean || 80}、体魄 ${state.health || 80}），备战农技定岗`
    };
    return {
      title: pathTitleMap[yp] || pathTitleMap.gaokao,
      subTitle: pathSubMap[yp] || pathSubMap.gaokao,
      progress: Math.min(100, Math.round(((age - 15) / 3) * 100)),
      badge: `倒计时 ${yearsLeft} 载`,
      color: '#38bdf8'
    };
  }

  // 0. 荣休晚晴状态：已卸下一线案牍，颐养天年
  if (state.isRetired) {
    return {
      title: '🕊️ 光荣荣休 · 离岗静养名宿',
      subTitle: '已卸下一线高压案牍，年领功勋离休年金，生活成本降22%，安享晚晴岁月',
      progress: 100,
      badge: '颐养晚晴',
      color: '#10b981'
    };
  }

  // 1. 查找最近的晋升选拔或履职考核节点
  const promoAges = [28, 35, 42, 50, 60];
  let nextPromoAge = promoAges.find(a => a > age) || (age + (3 - (age % 3)));
  const promoYearsLeft = Math.max(1, nextPromoAge - age);
  const promoTitle = nextPromoAge === 60 ? '60岁荣休功勋评定' : (promoAges.includes(nextPromoAge) ? `${nextPromoAge}岁职务晋升考察` : `${nextPromoAge}岁三年履职考核`);

  // 2. 查找最近的时代历史巨浪关隘
  const epicNodes = [
    { yr: 1984, name: '1984特区春雷抉择', stat: 'courage', label: '魄力', req: 62 },
    { yr: 1992, name: '1992南巡东方风来', stat: 'courage', label: '魄力', req: 68 },
    { yr: 1997, name: '1997亚洲金融风暴', stat: 'iq', label: '智谋', req: 70 },
    { yr: 1999, name: '1999自主技术突围', stat: 'iq', label: '智谋', req: 74 },
    { yr: 2001, name: '2001中国入世浪潮', stat: 'iq', label: '智谋', req: 72 },
    { yr: 2008, name: '2008抗震与四万亿', stat: 'courage', label: '魄力', req: 75 },
    { yr: 2012, name: '2012正风肃纪新风', stat: 'clean', label: '清廉', req: 82 },
    { yr: 2015, name: '2015硬科技双创潮', stat: 'iq', label: '智谋', req: 76 },
    { yr: 2018, name: '2018国产芯破冰战', stat: 'iq', label: '智谋', req: 80 },
    { yr: 2020, name: '2020生命至上抗疫', stat: 'courage', label: '魄力', req: 78 },
    { yr: 2023, name: '2023新质生产力领航', stat: 'iq', label: '智谋', req: 82 },
    { yr: 2027, name: '2027具身智造浪潮', stat: 'iq', label: '智谋', req: 82 },
    { yr: 2032, name: '2032绿氢零碳转型决战', stat: 'courage', label: '魄力', req: 80 },
    { yr: 2038, name: '2038银龄康养与代际交接', stat: 'eq', label: '情商', req: 78 },
    { yr: 2045, name: '2045聚变纪元百年工程', stat: 'clean', label: '清廉', req: 84 }
  ];
  const nextEpic = epicNodes.find(e => e.yr > yr && (e.yr - yr) <= 6);

  const pact = ensureThreeYearPact();
  let subLine = '';
  if (nextEpic) {
    const curVal = state[nextEpic.stat] || 60;
    const gap = Math.max(0, nextEpic.req - curVal);
    subLine = `⚡ ${nextEpic.yr - yr}年后迎【${nextEpic.name}】· 需${nextEpic.label}≥${nextEpic.req} (当前${curVal}${gap > 0 ? `，差${gap}点` : ' ✓达标'})`;
  } else if (pact) {
    const curVal = state[pact.statKey] || 60;
    const gap = Math.max(0, pact.targetVal - curVal);
    subLine = `🔥 军令状《${pact.title}》进度 ${pact.progress}% · 需${pact.statLabel}≥${pact.targetVal} (${gap > 0 ? `差${gap}点` : '✓已达标'})`;
  }

  return {
    title: `🎯 距【${promoTitle}】仅剩 ${promoYearsLeft} 年`,
    subTitle: subLine,
    pact: pact,
    progress: pact ? pact.progress : 50,
    badge: `余 ${promoYearsLeft} 载`,
    color: promoYearsLeft <= 1 ? '#ef4444' : '#f59e0b'
  };
}

// ==========================================
// 🚀 赛道独占核心演进机制 (Track-Exclusive Strategic Engine)
// ==========================================
function settleTrackExclusiveProgression(s) {
  if (!s || s.age < 22 || s.isRetired) return;
  const tr = s.track || 'gov';

  // 1. 科技赛道 (tech): 【国家重大攻关专项 · 技术断代壁垒】
  if (tr === 'tech') {
    if (!s.techRnd) {
      s.techRnd = {
        stage: 1,
        name: '微电子核心指令集与数字信号底座',
        progress: 0,
        target: 100,
        completedCount: 0
      };
    }
    const rndEffort = Math.max(12, Math.round((getStat('iq', 50, s) - 30) / 2.2));
    s.techRnd.progress += rndEffort;
    if (s.techRnd.progress >= s.techRnd.target) {
      s.techRnd.completedCount++;
      const bonusCap = 36000 + s.techRnd.completedCount * 12000;
      s.capital = (s.capital || 0) + bonusCap;
      addStat('iq', 3);
      addStat('rep', 5);
      const nextNames = [
        '深纳米激光干涉光刻与超精密加工',
        '高轨卫星全球时空基准组网星座',
        '通用类脑智能模型与量子纠缠计算'
      ];
      const prevName = s.techRnd.name;
      s.techRnd.stage++;
      s.techRnd.progress = 0;
      s.techRnd.target = 100 + s.techRnd.stage * 25;
      s.techRnd.name = nextNames[s.techRnd.stage - 2] || `前沿战略级课题·第${s.techRnd.stage}代技术壁垒`;
      addChronicleItem(s.age, s.year, `【核心攻关大捷】领衔突破《${prevName}》，打破国外技术垄断，获批国家特惠津贴 ¥${bonusCap.toLocaleString()}！`, '重大攻关', 'promo');
      showToast(`🔬 突破重大技术壁垒《${prevName}》！`, 'gold');
    }
  }

  // 2. 商贸与外贸赛道 (biz / trade): 【宏观景气周期与现金流逆周期杠杆】
  else if (tr === 'biz' || tr === 'trade') {
    if (!s.bizCycle) {
      s.bizCycle = { phase: 'boom', yearsLeft: 3 };
    }
    s.bizCycle.yearsLeft--;
    if (s.bizCycle.yearsLeft <= 0) {
      const nextPhases = { boom: 'slump', slump: 'stable', stable: 'boom' };
      s.bizCycle.phase = nextPhases[s.bizCycle.phase] || 'boom';
      s.bizCycle.yearsLeft = s.bizCycle.phase === 'slump' ? 2 : 3;
      const phaseNames = { boom: '繁荣上升浪潮', slump: '紧缩调整寒冬', stable: '平稳蓄力周期' };
      addChronicleItem(s.age, s.year, `【宏观景气轮动】行业进入《${phaseNames[s.bizCycle.phase]}》，考验企业现金流韧性！`, '经贸周期', 'history');
    }
    if (s.bizCycle.phase === 'boom') {
      const extraDividend = Math.round(Math.max(6000, (s.capital || 0) * 0.04));
      s.capital = (s.capital || 0) + extraDividend;
      addStat('courage', 1);
    } else if (s.bizCycle.phase === 'slump') {
      if ((s.capital || 0) >= 180000) {
        const bargainProfit = Math.round((s.capital || 0) * 0.05);
        s.capital = (s.capital || 0) + bargainProfit;
        addStat('rep', 3);
        addChronicleItem(s.age, s.year, `【逆周期布局】在行业低谷期从容出资逢低整合优质资产，逆势增厚资本 ¥${bargainProfit.toLocaleString()}！`, '逆周期布局', 'promo');
      } else if ((s.capital || 0) < 35000) {
        addStat('resilience', 1);
        addStat('health', -1);
      }
    }
  }

  // 3. 乡村农业与基层治理 (agri / grassroots): 【四时墒情与天灾防灾水利体系】
  else if (tr === 'agri' || tr === 'grassroots') {
    if (!s.ruralReservoir) {
      s.ruralReservoir = { waterConservancy: 50, disasterReadiness: 60 };
    }
    s.ruralReservoir.waterConservancy = Math.min(100, s.ruralReservoir.waterConservancy + 2);
    if (s.year % 4 === 0) {
      if (s.ruralReservoir.waterConservancy >= 56) {
        const agriReward = 18000;
        s.capital = (s.capital || 0) + agriReward;
        addStat('rep', 6);
        addStat('clean', 3);
        addChronicleItem(s.age, s.year, `【大灾之年夺丰收】旱涝灾害来袭，得益于扎实农田水利体系化险为夷，全县大获丰收，荣获表彰与专项补贴 ¥${agriReward.toLocaleString()}！`, '保供稳产', 'promo');
        showToast('🌾 经受旱涝大考夺得大丰收，荣获部级表彰！', 'gold');
      } else {
        addStat('resilience', 3);
        addStat('health', -2);
        addChronicleItem(s.age, s.year, '【抗洪抢险】遭遇特大汛情，日夜奋战在一线筑堤抢险，虽筋疲力尽却保住了乡亲安全！', '抗灾抢险', 'history');
      }
    }
  }

  // 4. 党政与法治赛道 (gov / law): 【民意公信丰碑与巡视巡查无暇度】
  else if (tr === 'gov' || tr === 'law') {
    s.publicTrust = typeof s.publicTrust === 'number' ? s.publicTrust : 62;
    if (getStat('clean', 50, s) >= 72) {
      s.publicTrust = Math.min(100, s.publicTrust + 3);
    } else {
      s.publicTrust = Math.max(30, s.publicTrust - 2);
    }
    if (s.publicTrust >= 82 && s.year % 5 === 0) {
      addStat('rep', 4);
      s.activeShield = true;
      addChronicleItem(s.age, s.year, '【万民拥戴】公生明廉生威，任上办结多起民生积案，群众自发送来万民伞，筑牢公信力防火墙！', '民意丰碑', 'promo');
      showToast('🏛️ 清白为民有口皆碑，筑牢民心防火墙！', 'gold');
    }
  }

  // 5. 制造业与国防军工 (industry / military): 【大国重器零差错交付令】
  else if (tr === 'industry' || tr === 'military') {
    s.engineeringQuality = s.engineeringQuality || { zeroDefectYears: 0 };
    if (getStat('courage', 50, s) >= 60 && getStat('iq', 50, s) >= 58) {
      s.engineeringQuality.zeroDefectYears++;
      if (s.engineeringQuality.zeroDefectYears >= 3) {
        s.engineeringQuality.zeroDefectYears = 0;
        const indBonus = 22000;
        s.capital = (s.capital || 0) + indBonus;
        addStat('rep', 7);
        addStat('courage', 3);
        addChronicleItem(s.age, s.year, `【大国工匠授勋】关键战略装备实现连续三年零差错高质量交付，荣记一等功，获战备重器科技奖金 ¥${indBonus.toLocaleString()}！`, '工匠勋章', 'promo');
        showToast('⚙️ 装备实现零差错交付，荣记大功！', 'gold');
      }
    }
  }

  // 6. 医疗、艺术与教育 (med / art / education): 【大医精诚与桃李满天下谱系】
  else if (tr === 'med' || tr === 'art' || tr === 'education') {
    s.masteryHeritage = s.masteryHeritage || { achievements: 0 };
    if (s.year % 3 === 0) {
      s.masteryHeritage.achievements++;
      addStat('rep', 4);
      addStat('resilience', 2);
      const isMed = tr === 'med';
      const label = isMed ? '抢救危重症疑难患者攻坚' : (tr === 'education' ? '培养的杰出弟子入选国家拔尖英才' : '代表作荣获国家级文艺展金奖');
      addChronicleItem(s.age, s.year, `【立德立言】${label}，声名远播，深得各界敬重！`, '杏林杏坛', 'promo');
    }
  }
}

function settleAnnualCoreProgression() {
  const prevActions = state.annualActionsTaken || 0;
  const skippedModal = !!state._skippedModalLastTick;
  state.annualActionsTaken = 0;
  state._skippedModalLastTick = false;

  // 0. 结转上一年剩余履职精力：若已荣休免除怠政惩戒；在职者主动履职或隔年调养时微幅恢复，不作为时触发怠政损耗
  if (state.isRetired) {
    state.inactionStreak = 0;
  } else if (prevActions > 0 || !skippedModal) {
    if (prevActions > 0) {
      state.inactionStreak = 0;
    }
    if ((state.ap || 0) > 0 && state.age % 2 === 0) {
      addStat('health', 1);
      if (prevActions > 0) addStat('resilience', 1);
    }
  } else {
    state.inactionStreak = (state.inactionStreak || 0) + 1;
    state.inactionYears = (state.inactionYears || 0) + 1;
    const streak = state.inactionStreak;
    const cleanErode = 2 + Math.floor(seededRandom() * 2) + (streak >= 4 ? 1 : 0);
    const repErode = 2 + Math.floor(seededRandom() * 3) + (streak >= 4 ? 1 : 0);
    addStat('clean', -cleanErode);
    addStat('rep', -repErode);
    addStat('resilience', -2);
  }

  // 1. 年龄与纪元先行推进（彻底杜绝同一年份因事件return而原地卡死）
  state.age++;
  state.year++;

  if ([18, 25, 30, 35, 40, 45, 50, 55, 60, 65, 70].includes(state.age)) {
    reportGameMilestone('age_stage_entered', {
      age: state.age,
      track: state.track || 'unset',
      rep: Math.round(getStat('rep', 0)),
      clean: Math.round(getStat('clean', 0)),
      capital: Math.round(state.capital || 0)
    });
  }

  // 渐进式主页签解锁激励与编年记录
  if (state.age === 18 && !state._unlockedDeskAnnounced) {
    state._unlockedDeskAnnounced = true;
    showToast('🎉 弱冠成年！解锁【📋 案头】履职主线！', 'gold');
    addChronicleItem(state.age, state.year, '【成年启航】弱冠及笄，正式踏入社会！【📋 案头】履职主线已全面解锁。', '系统引导', 'promo');
  } else if (state.age === 20 && !state._unlockedSocialAnnounced) {
    state._unlockedSocialAnnounced = true;
    showToast('🌐 广结良友！解锁【🌐 圈子】与【👥 名仕】人脉网络！', 'gold');
    addChronicleItem(state.age, state.year, '【通达四方】涉足社会日久，声气相投，【🌐 圈子】与【👥 名仕】人脉网络已解锁！', '系统引导', 'promo');
  } else if (state.age === 24 && !state._unlockedStrategyAnnounced) {
    state._unlockedStrategyAnnounced = true;
    showToast('📈 成家立业！解锁【📈 工坊】统筹策略！', 'gold');
    addChronicleItem(state.age, state.year, '【自立立人】而立在望，经世致用，【📈 工坊】策略统筹与天赋研习已全面解锁！', '系统引导', 'promo');
  }

  // 保证当前选中的页签处于已解锁状态
  if (typeof isTabUnlocked === 'function' && !isTabUnlocked(state.activeTab, state.age)) {
    state.activeTab = 'timeline';
  }

  // 触发翻页老式日历动效与轨迹记录
  triggerCalendarTear(state.year);
  if (typeof recordTrajectoryPoint === 'function') {
    recordTrajectoryPoint();
  }

  // 2. 刷新当年履职精力（统一计入乾坤独断心法与非遗/造物上限加成）
  state.maxAp = ((hasTalent('decisive') && state.age % 2 === 0) ? 4 : 3) + (state.bonusMaxAp || 0);
  state.ap = state.maxAp;

  // 通晓先机心法：每8年获赠一次铁壁防线
  if (hasTalent('clairvoyance') && state.age % 8 === 0) {
    state.activeShield = true;
  }

  // 刷新年度宏观时代行情大盘、因果伏笔回响与三年攻坚军令状进度
  updateMarketTrends(state.year);
  checkKarmaEchoes(state.age, state.year);
  advanceThreeYearPactAnnual();

  // 2.5 P0-3 结算往年检定失败埋下的延迟“旧患回响” (aftermathQueue)
  if (Array.isArray(state.aftermathQueue) && state.aftermathQueue.length > 0) {
    const remainingAftermath = [];
    for (let i = 0; i < state.aftermathQueue.length; i++) {
      const item = state.aftermathQueue[i];
      if (!item || (state.year || 1992) < (item.triggerYear || 9999)) {
        if (item) remainingAftermath.push(item);
        continue;
      }
      const hStat = item.hazardStat || 'rep';
      const hitVal = item.statHit || -4;
      const capHit = item.capitalHit || 0;
      addStat(hStat, hitVal);
      if (capHit < 0) {
        state.capital = Math.round((state.capital || 0) + capHit);
      }
      addChronicleItem(
        state.age,
        state.year,
        `【旧患爆发】往年《${item.sourceTitle}》（${item.choiceTag}）遗留隐患集中反噬，${_STAT_CN_LABELS[hStat] || hStat}${hitVal}${capHit < 0 ? `，追缴赔付¥${Math.abs(capHit).toLocaleString()}` : ''}！`,
        '旧患反噬',
        'crisis'
      );
    }
    state.aftermathQueue = remainingAftermath;
  }

  // 2.8 P2 支线系统全面接入年度主循环 (茶道/宿敌/传家宝/古琴/蜀锦/本草/非遗/碑林/古玩/文物/家训/相册/书院/勋章)
  let sideInvestBonusRatio = 0;
  let sideHealthRelief = 0;
  let sideSalaryBonus = 0;
  if (state.age >= 18) {
    // 茶道 (teaWayRecords / activeTeaContact) & 古琴 (guqinRecords)：涵养心性、平抑浮躁
    const teaCnt = (Array.isArray(state.teaWayRecords) ? state.teaWayRecords.length : ((state.teaWayRecords && state.teaWayRecords.totalCount) || 0)) + (state.activeTeaContact ? 1 : 0);
    const qinCnt = Array.isArray(state.guqinRecords) ? state.guqinRecords.length : ((state.guqinRecords && state.guqinRecords.totalCount) || 0);
    if ((teaCnt > 0 || qinCnt > 0) && state.year % 4 === 0) {
      addStat('resilience', 1);
    }
    // 本草 (herbalWellness)：缓解中老年体魄自然衰减
    const herbCnt = Array.isArray(state.herbalWellness) ? state.herbalWellness.length : ((state.herbalWellness && state.herbalWellness.totalBrews) || 0);
    if (herbCnt > 0) sideHealthRelief += Math.min(2, herbCnt);
    // 蜀锦 (brocadeRecords) & 名瓷 (kilnPorcelains) & 名砚 (inkstoneRecords) & 古玩 (ownedCurios) & 传家宝 (unlockedHeirlooms / familyHeirloom)：实业与资产增值
    const broCnt = (Array.isArray(state.brocadeRecords) ? state.brocadeRecords.length : ((state.brocadeRecords && state.brocadeRecords.totalCount) || 0))
      + ((state.kilnPorcelains && state.kilnPorcelains.totalCount) || 0)
      + ((state.inkstoneRecords && state.inkstoneRecords.totalCount) || 0);
    const curioCnt = Array.isArray(state.ownedCurios) ? state.ownedCurios.length : 0;
    const heirloomCnt = (Array.isArray(state.unlockedHeirlooms) ? state.unlockedHeirlooms.length : 0) + (state.familyHeirloom ? 1 : 0);
    sideInvestBonusRatio += Math.min(0.05, (broCnt + curioCnt + heirloomCnt) * 0.01);
    // 非遗 (heritageCrafts) / 碑林 (epigraphyRubbings / inscribedMonuments) / 文物 (unlockedRelics)：底蕴熏陶
    const ichCnt = Array.isArray(state.heritageCrafts) ? state.heritageCrafts.length : ((state.heritageCrafts && state.heritageCrafts.totalCount) || 0);
    const steleCnt = (Array.isArray(state.epigraphyRubbings) ? state.epigraphyRubbings.length : ((state.epigraphyRubbings && state.epigraphyRubbings.totalCount) || 0))
      + (Array.isArray(state.inscribedMonuments) ? state.inscribedMonuments.length : (state.inscribedMonuments ? Object.keys(state.inscribedMonuments).length : 0));
    const relicCnt = Array.isArray(state.unlockedRelics) ? state.unlockedRelics.length : 0;
    if ((ichCnt + steleCnt + relicCnt) > 0 && state.year % 5 === 0) {
      addStat('clean', 1);
    }
    // 家训 (adoptedPrecepts) / 书院 (handledLectures) / 勋章 (awardedMedals) / 相册 (memoryAlbum)
    const preceptCnt = (state.family && Array.isArray(state.family.adoptedPrecepts)) ? state.family.adoptedPrecepts.length : (Array.isArray(state.adoptedPrecepts) ? state.adoptedPrecepts.length : 0);
    const lectureCnt = Array.isArray(state.handledLectures) ? state.handledLectures.length : (state.handledLectures ? Object.keys(state.handledLectures).length : 0);
    const medalCnt = Array.isArray(state.awardedMedals) ? state.awardedMedals.length : 0;
    const albumCnt = Array.isArray(state.memoryAlbum) ? state.memoryAlbum.length : 0;
    sideSalaryBonus += Math.min(5500, (preceptCnt + lectureCnt + medalCnt) * 650 + albumCnt * 250);
    // 宿敌 (activeRival / childhoodRivals) 年度动态博弈：随年龄渐进成长，仅当消极躺平时被宿敌压制折损声望
    const rival = state.activeRival || (Array.isArray(state.childhoodRivals) ? state.childhoodRivals[0] : null);
    if (rival && state.year % 3 === 0) {
      rival.power = Math.min(86, 36 + Math.floor((state.age - 18) * 0.9));
      if ((state.inactionStreak || 0) >= 2 && rival.power > getStat('rep', 50) + 12) {
        addStat('rep', -1);
      }
    }
  }

  // 2.9 推进赛道独占核心演进机制（科技攻关/商贸周期/乡村天灾防灾/党政公信/军工交付令）
  settleTrackExclusiveProgression(state);

  // 3. 战略与资本年度结算（按职级阶梯 rankLvl 与赛道特性计薪，并扣除渐进式家庭刚性开支、子女教育、养老医疗与资产维护费）
  const effectiveRep = Math.min(100, Math.max(0, getStat('rep', 35)));
  const rankLvl = Math.max(1, Math.min(6, state.rankIndex || state.govLevel || 1));
  const tr = state.track || 'gov';
  const TRACK_INCOME_MULTIPLIERS = {
    biz: 1.52,
    trade: 1.42,
    tech: 1.28,
    law: 1.22,
    med: 1.16,
    art: 1.12,
    industry: 1.06,
    gov: 1.00,
    education: 0.96,
    military: 0.93,
    agri: 0.88,
    grassroots: 0.85
  };
  const trackIncomeMult = TRACK_INCOME_MULTIPLIERS[tr] || 1.00;
  const bizDividend = (state.inactionStreak || 0) === 0
    ? ((tr === 'biz' || tr === 'trade')
        ? Math.round((getStat('iq', 50) + getStat('courage', 50)) * 28)
        : ((tr === 'tech' || tr === 'law' || tr === 'med' || tr === 'art')
            ? Math.round((getStat('iq', 50) + getStat('rep', 40)) * 16)
            : ((tr === 'agri' || tr === 'grassroots')
                ? Math.round((getStat('resilience', 50) + getStat('rep', 40)) * 8)
                : Math.round((getStat('iq', 50) + getStat('rep', 40)) * 11))))
    : 0;
  let baseSalary = Math.round((13600 + rankLvl * 4600 + Math.floor(effectiveRep * 110) + sideSalaryBonus) * trackIncomeMult) + bizDividend;
  if (state.isRetired) {
    // 退休后转为“离休年金与名宿顾问津贴”，不受怠政打折影响，且按历史最高声望与职级保障晚年现金流
    baseSalary = Math.round((18000 + rankLvl * 3800 + Math.floor(effectiveRep * 95) + sideSalaryBonus) * 0.85);
  }

  // 各赛道专业深耕历练特征分化（每4年温和精进本赛道主辅专业属性，均衡12赛道成长上限）
  if ((state.inactionStreak || 0) === 0 && state.age >= 22 && state.age % 4 === 0) {
    if (tr === 'gov') {
      if (getStat('clean', 70) < 82) addStat('clean', 1);
      if (getStat('eq', 50) < 78) addStat('eq', 1);
    } else if (tr === 'tech') {
      if (getStat('iq', 50) < 82) addStat('iq', 1);
      if (getStat('courage', 50) < 78) addStat('courage', 1);
    } else if (tr === 'biz' || tr === 'trade') {
      if (getStat('courage', 50) < 82) addStat('courage', 1);
      if (getStat('eq', 50) < 78) addStat('eq', 1);
    } else if (tr === 'industry') {
      if (getStat('iq', 50) < 82) addStat('iq', 1);
      if (getStat('courage', 50) < 78) addStat('courage', 1);
    } else if (tr === 'military') {
      if (getStat('courage', 50) < 82) addStat('courage', 1);
      if (getStat('clean', 70) < 82) addStat('clean', 1);
    } else if (tr === 'agri' || tr === 'grassroots') {
      if (getStat('resilience', 50) < 82) addStat('resilience', 1);
      if (getStat('clean', 70) < 82) addStat('clean', 1);
    } else if (tr === 'art') {
      if (getStat('eq', 50) < 80) addStat('eq', 1);
      if (getStat('iq', 50) < 80) addStat('iq', 1);
    } else if (tr === 'med' || tr === 'education') {
      if (getStat('iq', 50) < 80) addStat('iq', 1);
      if (getStat('resilience', 50) < 78) addStat('resilience', 1);
    } else if (tr === 'law') {
      if (getStat('iq', 50) < 80) addStat('iq', 1);
      if (getStat('clean', 70) < 82) addStat('clean', 1);
    }
    if (state.age % 8 === 0 && getStat('rep', 50) < 80) addStat('rep', 1);
  }

  const hasActualChildren = !!(state.family && Array.isArray(state.family.children) && state.family.children.length > 0);
  const childEduCost = (hasActualChildren && state.age >= 25 && state.age <= 50) ? 2600 : 0;
  const elderCareCost = (state.age >= 38 && state.age <= 66) ? 2800 : 0;
  const seniorMedCost = (state.age >= 56) ? 3200 : 0;
  const capVal = state.capital || 0;
  const assetMaintCost = (capVal > 320000 ? Math.round((capVal - 320000) * 0.022) : 0)
    + (capVal > 680000 ? Math.round((capVal - 680000) * 0.032) : 0);
  let annualLivingCost = 11800 + Math.max(0, state.age - 18) * 310 + rankLvl * 1450 + childEduCost + elderCareCost + seniorMedCost + assetMaintCost + Math.floor(seededRandom() * 1500);
  if (state.isRetired) {
    annualLivingCost = Math.round(annualLivingCost * 0.78);
  }
  let healthChange = -1 - (state.age >= 40 ? 1 : 0) - (state.age >= 58 ? 1 : 0) - ((state.inactionStreak || 0) >= 1 ? 2 : 0) + sideHealthRelief;
  if (state.isRetired) {
    // 荣休后卸下职场高压，免除过劳损耗，年均增添一份颐养心性与体魄调摄
    healthChange = Math.max(0, healthChange + 2);
  }
  let spGain = 10;

  if ((state.inactionStreak || 0) >= 2) {
    const retainRatio = Math.max(0.28, 1 - state.inactionStreak * 0.12);
    baseSalary = Math.round(baseSalary * retainRatio);
  }

  // 五大年度施政与人生方针差异化结算（带软上限与明确得失权衡，杜绝单一最优方针）
  const curStrat = (state.strategy === 'overwork') ? 'aggressive' : (state.strategy || 'balanced');
  if (curStrat === 'aggressive') {
    baseSalary = Math.round(baseSalary * 1.24);
    state.overworkYears = (state.overworkYears || 0) + 1;
    healthChange -= 1;
    if ((state.inactionStreak || 0) === 0) {
      if (state.age % 2 === 0 && getStat('courage', 50) < 88) addStat('courage', 2);
      if (state.age % 3 === 0 && getStat('iq', 50) < 86) addStat('iq', 1);
      if (state.age % 3 === 0 && getStat('rep', 50) < 88) addStat('rep', 1);
      if (state.age % 6 === 0 && getStat('clean', 75) > 74) addStat('clean', -1);
    }
  } else if (curStrat === 'clean') {
    baseSalary = Math.round(baseSalary * 0.93);
    if ((state.inactionStreak || 0) === 0) {
      if (state.age % 2 === 0 && getStat('clean', 75) < 95) addStat('clean', 2);
      if (state.age % 3 === 0 && getStat('rep', 50) < 88) addStat('rep', 1);
      if (state.age % 3 === 0 && getStat('eq', 50) < 80) addStat('eq', 1);
      if (state.age % 4 === 0 && getStat('resilience', 50) < 86) addStat('resilience', 1);
      if (state.age % 6 === 0) state.activeShield = true;
    }
  } else if (curStrat === 'network') {
    baseSalary = Math.round(baseSalary * 1.07);
    // 应酬周旋真实代价：酒宴交际与人情往来持续消耗资金
    const socialExpenses = Math.round(Math.min(18000, Math.max(900, baseSalary * 0.08)));
    state.capital = Math.max(0, (state.capital || 0) - socialExpenses);
    if ((state.inactionStreak || 0) === 0) {
      if (state.age % 2 === 0 && getStat('eq', 50) < 90) addStat('eq', 2);
      if (state.age % 3 === 0 && getStat('rep', 50) < 88) addStat('rep', 1);
      if (state.age % 4 === 0 && getStat('courage', 50) < 82) addStat('courage', 1);
      // 应酬周旋有损清名戒律（每2年清廉-2）
      if (state.age % 2 === 0 && getStat('clean', 75) > 60) addStat('clean', -2);
      // 频仍宴饮劳心伤体（每3年体魄-1）
      if (state.age % 3 === 0 && getStat('health', 70) > 35) addStat('health', -1);
      if (Array.isArray(state.contacts) && state.contacts.length > 0 && state.age % 2 === 0) {
        const cIdx = state.age % state.contacts.length;
        if (state.contacts[cIdx]) {
          state.contacts[cIdx].affinity = Math.min(100, (state.contacts[cIdx].affinity || 50) + 4);
        }
      }
    }
  } else if (curStrat === 'wellness') {
    baseSalary = Math.round(baseSalary * 0.90);
    state.wellnessYears = (state.wellnessYears || 0) + 1;
    healthChange += 3;
    if ((state.inactionStreak || 0) === 0) {
      if (state.age % 2 === 0 && getStat('resilience', 50) < 88) addStat('resilience', 2);
      if (state.age % 4 === 0 && getStat('eq', 50) < 80) addStat('eq', 1);
      if (state.age % 5 === 0 && getStat('rep', 50) < 84) addStat('rep', 1);
    }
  } else {
    // 'balanced': 稳健统筹，收入温和增益，每3年均衡补强短板、每5年涵养声望与清廉
    baseSalary = Math.round(baseSalary * 1.03);
    if ((state.inactionStreak || 0) === 0 && state.age % 3 === 0) {
      const coreKeys = ['iq', 'eq', 'courage', 'resilience'];
      let lowestKey = 'resilience';
      let lowestVal = 999;
      for (let i = 0; i < coreKeys.length; i++) {
        const v = getStat(coreKeys[i], 50);
        if (v < lowestVal) {
          lowestVal = v;
          lowestKey = coreKeys[i];
        }
      }
      if (lowestVal < 78) addStat(lowestKey, 1);
      if (state.age % 5 === 0) {
        if (getStat('rep', 50) < 80) addStat('rep', 1);
        if (getStat('clean', 75) < 79) addStat('clean', 1);
      }
    }
  }

  if (hasHeirloom('heirloom_license')) sideInvestBonusRatio += 0.05;
  if (isRelicUnlocked('relic_c919_keychain')) sideInvestBonusRatio += 0.05;
  if (isMedalAwarded('medal_may_first')) sideInvestBonusRatio += 0.04;

  let investReturn = 0;
  if (state.investments && state.investments.realEstate > 0) {
    investReturn += Math.round(state.investments.realEstate * (0.045 + sideInvestBonusRatio));
  }
  if (state.investments && state.investments.bonds > 0) {
    investReturn += Math.round(state.investments.bonds * (0.032 + sideInvestBonusRatio * 0.5));
  }
  if (state.investments && state.investments.ventureTech > 0) {
    let techCritChance = 0.18;
    if (hasTalent('wealth')) techCritChance += 0.06;
    if (state.activeMotto === 'xianxing') techCritChance += 0.12;
    if (hasHeirloom('heirloom_chip') || isRelicUnlocked('relic_vcd_wanyan')) techCritChance = Math.max(techCritChance, 0.45);
    if (seededRandom() < techCritChance) {
      let critGain = Math.round(state.investments.ventureTech * 0.65);
      if (isMedalAwarded('medal_tech_summit')) critGain = Math.round(critGain * 1.35);
      investReturn += critGain;
      addChronicleItem(state.age, state.year, `【硬科技爆发】所投前沿硬科技企业斩获跨国突破，斩获 ¥${critGain} 超额分红！`, "硬核创投", "promo");
    }
  }
  // 家族永续教育慈善信托分红与世代簪缨/官窑三友瓶/大师工作室加成
  if (state.family && (state.family.endowmentFund || 0) > 0) {
    let trustRate = 0.035 + (hasHeirloom('heirloom_vase') ? 0.05 : 0);
    if (hasTalent('dynasty')) trustRate *= 1.35;
    const trustDividend = Math.round(state.family.endowmentFund * trustRate);
    investReturn += trustDividend;
    state.family.endowmentFund += Math.round(trustDividend * 0.25);
  }
  if (state.masterStudio && (state.masterStudio.legacyScore || 0) >= 90 && state.family) {
    state.family.endowmentFund = (state.family.endowmentFund || 0) + 5000;
  }
  if (investReturn > 0 && state.fortuneHexagram && state.fortuneHexagram.buff === 'invest_30') {
    investReturn = Math.round(investReturn * 1.3);
  }

  const totalGain = baseSalary + investReturn - annualLivingCost;
  if ((hasTalent('vitality') || hasHeirloom('heirloom_watch') || isRelicUnlocked('relic_bike_phoenix')) && healthChange < -1 && state.age % 3 === 0) {
    healthChange += 1;
  }

  const curClimate = getMacroClimate(state.year);
  const rawYield = curClimate.yieldMultiplier || 1.0;
  let climateMultiplier = 1.0 + (rawYield - 1.0) * 0.25;
  if (hasTalent('wealth')) {
    climateMultiplier += 0.02;
  }
  const adjustedGain = totalGain >= 0 ? Math.round(totalGain * climateMultiplier) : Math.round(totalGain);

  state.capital += adjustedGain;
  state.health = Math.max(5, Math.min(100, getStat('health', 80) + healthChange));
  addStat('sp', spGain);

  // ⏳ 动态寿命与身心损耗/养生联动：彻底打破“寿命与行为无关”或“颐养100%卡死86岁”的硬上限
  if (typeof state.lifespanCeiling !== 'number') {
    state.lifespanCeiling = (state.birthProfile && state.birthProfile.lifespanCeiling) || 78;
  }
  const personalMaxLifespan = 87 + (((state.birthProfile && state.birthProfile.lifespanCeiling) || 79) % 8);
  if (state.health <= 40) {
    state.overworkYears = (state.overworkYears || 0) + 1;
    if (state.overworkYears % 3 === 0) {
      state.lifespanCeiling = Math.max(62, state.lifespanCeiling - 1);
    }
  } else if (curStrat === 'wellness' || (state.health >= 82 && state.age >= 46)) {
    state.wellnessYears = (state.wellnessYears || 0) + 1;
    if (state.wellnessYears % 3 === 0) {
      state.lifespanCeiling = Math.min(personalMaxLifespan, state.lifespanCeiling + 1);
    }
  }
  if (getStat('clean', 80) < 55 && state.age % 4 === 0) {
    // 长期处于严重违纪问责高压焦虑下，折损寿元
    state.lifespanCeiling = Math.max(62, state.lifespanCeiling - 1);
  }

  // 兑现案头座右铭朱印 (activeMotto)、中堂题匾 (activeCalligraphyInscription) 与传家宝/信物清廉底线保护
  if ((state.inactionStreak || 0) === 0 && state.age % 6 === 0) {
    if ((state.activeMotto === 'shishi' || state.activeCalligraphyInscription === 'insc_clean') && getStat('clean', 75) < 82) addStat('clean', 1);
    if (state.activeMotto === 'limin' && getStat('rep', 50) < 78) addStat('rep', 1);
    if (state.activeMotto === 'shenmou' && getStat('resilience', 50) < 78) addStat('resilience', 1);
    if (state.activeCalligraphyInscription === 'insc_people' && state.family) {
      state.family.prestige = (state.family.prestige || 15) + (hasTalent('dynasty') ? 3 : 2);
    }
  }
  if (hasHeirloom('heirloom_medal') && getStat('clean', 50) < 75) state.clean = 75;
  else if (isRelicUnlocked('relic_tea_mug') && getStat('clean', 50) < 55) state.clean = 55;
  if (isMedalAwarded('medal_july_first')) state.activeShield = true;

  if (adjustedGain >= 0) {
    addFloatingText(`+¥${adjustedGain.toLocaleString()}`, screenWidth / 2, getDashboardY() + 40, "#34d399");
  } else {
    addFloatingText(`-¥${Math.abs(adjustedGain).toLocaleString()}`, screenWidth / 2, getDashboardY() + 40, "#ef4444");
  }
  playSoundEffect('coin');
  triggerHaptic('light');

  // 4. 大国战略支柱年度红利与区域治理四维政策杠杆产出结算（仅在主动履职且每隔6年产出，避免被动数值通胀）
  if ((state.inactionStreak || 0) < 2) {
    const pKey = state.strategicPillar || 'mfg';
    const pillarObj = STRATEGIC_PILLARS.find(p => p.key === pKey);
    if (pillarObj && typeof pillarObj.onTick === 'function' && state.age % 6 === 0) {
      pillarObj.onTick(state);
    }

    const gov = state.governancePolicy || { rd: 25, welfare: 25, infra: 25, audit: 25 };
    if (state.age % 6 === 0) {
      if (gov.rd >= 30 && getStat('iq', 50) < 76) {
        addStat('iq', 1);
      }
      if (gov.welfare >= 30) {
        addStat('health', 1);
        state.happiness = Math.min(100, (state.happiness ?? 80) + 1);
      }
      if (gov.infra >= 30 && state.capital > 0) {
        state.capital += Math.round(Math.min(150000, state.capital) * (gov.infra * 0.0004));
      }
      if (gov.audit >= 30 && getStat('clean', 75) < 82) {
        addStat('clean', 1);
        if (gov.audit >= 35) state.activeShield = true;
      }
    }
    state.governanceScore = Math.min(100, Math.round(
      (gov.rd * 0.25 + gov.welfare * 0.25 + gov.infra * 0.25 + gov.audit * 0.25) * 0.8 + (getStat('clean', 80) * 0.2)
    ));
  }

  const yr = state.year;
  const age = state.age;

  // 5. 传帮带伯乐恩师提携进阶检定 (MENTORSHIP_DATABASE，需保持积极履职方获恩师举荐)
  const trackKey = ['tech', 'med', 'education', 'art'].includes(state.track)
    ? 'academic'
    : (['biz', 'trade', 'industry', 'business'].includes(state.track) ? 'business' : 'politics');
  const mentor = MENTORSHIP_DATABASE[trackKey];
  if (mentor && (state.inactionStreak || 0) < 2) {
    const milestone = mentor.milestones.find(m => m.age === age && !state.handledEvents[m.id]);
    if (milestone) {
      state.handledEvents[milestone.id] = true;
      if (milestone.reward) {
        Object.keys(milestone.reward).forEach(k => {
          const val = milestone.reward[k];
          if (CORE_BOUNDED_STATS[k]) addStat(k, Math.min(2, Math.max(1, Math.round(val * 0.22))));
          else if (k === 'capital') state.capital += Math.min(9000, Math.round(val * 0.30));
          else if (typeof state[k] === 'number') state[k] += val;
          else state[k] = val;
        });
      }
      addChronicleItem(age, yr, `${milestone.title}：${milestone.text}`, '伯乐指引', 'promo');
      showToast(`伯乐恩师【${mentor.name}】：${milestone.title}`, 'gold');
    }
  }

  // 6. 五行命盘共鸣（每个时代窗口仅触发一次，杜绝逐年重复暴涨）、知己平行事件、时代微光、喜得麟儿
  const ele = state.elementDestiny || 'gold';
  if (yr >= 1992 && yr <= 1998 && (ele === 'fire' || ele === '火') && !state.handledEvents['res_era_fire']) {
    state.handledEvents['res_era_fire'] = true;
    addStat('courage', 3);
    addChronicleItem(age, yr, '【天人合一】你的【火命·敢为人先】禀赋与改革拓荒春雷大潮激烈共鸣，敢拼敢闯，魄力精进！', '天命共鸣', 'promo');
  } else if (yr >= 2000 && yr <= 2007 && (ele === 'gold' || ele === '金') && !state.handledEvents['res_era_gold']) {
    state.handledEvents['res_era_gold'] = true;
    state.capital += 8000;
    addChronicleItem(age, yr, '【天人合一】你的【金命·刚毅果决】禀赋与入世制造业黄金大潮同频共振，收获产业红利！', '天命共鸣', 'promo');
  } else if (yr >= 2015 && yr <= 2023 && (ele === 'water' || ele === '水') && !state.handledEvents['res_era_water']) {
    state.handledEvents['res_era_water'] = true;
    addStat('iq', 3);
    addChronicleItem(age, yr, '【天人合一】你的【水命·上善若水】禀赋与互联网数字智能浪潮润物合鸣，才思泉涌！', '天命共鸣', 'promo');
  } else if ((ele === 'wood' || ele === '木') && age === 36 && !state.handledEvents['res_era_wood']) {
    state.handledEvents['res_era_wood'] = true;
    addStat('health', 4);
    addChronicleItem(age, yr, '【天人合一】你的【木命·生机延绵】禀赋沐浴四时风物，生机勃发，身心调畅。', '天命共鸣', 'promo');
  } else if ((ele === 'earth' || ele === '土') && age === 40 && !state.handledEvents['res_era_earth']) {
    state.handledEvents['res_era_earth'] = true;
    addStat('clean', 2);
    addStat('rep', 2);
    addChronicleItem(age, yr, '【天人合一】你的【土命·厚德载物】禀赋滋养基石，德高望重，清誉广受称颂。', '天命共鸣', 'promo');
  }

  if (age === 32 && !state.handledEvents['ally_arc_32']) {
    state.handledEvents['ally_arc_32'] = true;
    const c = (state.contacts && state.contacts[0]) || ENSEMBLE_CHARACTERS[0];
    addChronicleItem(age, yr, `【知己风云】至交名仕【${c.name}】响应改革浪潮赴特区领衔产业突围，双方互通机要电文，声气相通！`, '知己同行', 'promo');
  } else if (age === 44 && !state.handledEvents['ally_arc_44'] && (state.inactionStreak || 0) < 2) {
    state.handledEvents['ally_arc_44'] = true;
    const c = (state.contacts && state.contacts.find(x => x.isSwornGuardian)) || ENSEMBLE_CHARACTERS[1];
    addChronicleItem(age, yr, `【风雨同舟】名仕【${c.name}】面临严苛巡视审查，因你多年清廉合规的公文案卷与信誉力保，助其化解不白之冤！`, '莫逆同盟', 'promo');
    addStat('rep', 2);
  }

  if (yr === 1998 && !state.handledEvents['grassroots_1998']) {
    state.handledEvents['grassroots_1998'] = true;
    addChronicleItem(age, yr, '【时代微光】长江九江决口特大洪灾中，空降兵某部指战员以血肉之躯筑起钢铁长堤。你深入一线调配抢险物资，军民同心力挽狂澜！', '凡人英雄', 'history');
  } else if (yr === 2008 && !state.handledEvents['grassroots_2008']) {
    state.handledEvents['grassroots_2008'] = true;
    addChronicleItem(age, yr, '【时代微光】五十年一遇南方特大冰雪灾害突袭，电力职工高空除冰保电通宵鏖战。你连夜启动应急绿波调度保供煤电，点亮万家灯火。', '凡人英雄', 'history');
  } else if (yr === 2018 && !state.handledEvents['grassroots_2018']) {
    state.handledEvents['grassroots_2018'] = true;
    addChronicleItem(age, yr, '【时代微光】大山深处扎根三代乡村小学的乡村教师获评全国楷模。你代表单位设立专项结对助学基金，点亮大山学子求学之路。', '凡人英雄', 'history');
  }

  if (state.family && state.family.spouseName && age >= 24 && age <= 42 && !state.handledEvents['child_birth'] && (seededRandom() < 0.65 || age === 35)) {
    state.handledEvents['child_birth'] = true;
    const childGender = seededRandom() < 0.5 ? 'male' : 'female';
    const childName = generateRandomChineseName(childGender).fullName;
    state.family.childName = childName;
    state.family.children = [{ name: childName, gender: childGender, birthYear: yr, traits: [] }];
    addChronicleItem(age, yr, `【喜得麟儿】伴侣【${state.family.spouseName}】诞下子嗣【${childName}】，阖家欢乐，门楣添喜！`, '阖家团圆', 'promo');
    showToast(`添丁之喜！子嗣【${childName}】诞生！`, 'gold');
  }

  // 6.5 摩托罗拉BP机商海急件寻呼、家族传家信物确立与命运因果星图伏笔/回响
  if (isRelicUnlocked('relic_pager_moto') && yr >= 1992 && !pagerAnim.active && state.age % 3 === 1) {
    const pagerTips = [
      { caller: '发小晓峰', code: '8888', msg: '深南大道外贸柜台紧俏，速回电！', rewardCap: 4500, stat: 'iq' },
      { caller: '特区老周', code: '1688', msg: '保税区精密配件急单空缺，速洽！', rewardCap: 5200, stat: 'eq' },
      { caller: '科研所林工', code: '9999', msg: '关键工序良品率突破，请审阅参数！', rewardCap: 4800, stat: 'courage' }
    ];
    const pTip = pagerTips[yr % pagerTips.length];
    triggerPagerCall(pTip.caller, pTip.code, pTip.msg, () => {
      state.capital = (state.capital || 0) + pTip.rewardCap;
      addStat(pTip.stat, 1, 50);
      showToast(`📟 已复电【${pTip.caller}】！捕获商海情报收益 +¥${pTip.rewardCap.toLocaleString()}，能力精进+1！`, 'gold');
    });
  }
  if (age >= 36 && !state.familyHeirloom) {
    giveFamilyHeirloom(state);
  }
  if (age >= 24 && getStat('iq', 50) >= 65 && !isCausalSeedActive('seed_hardtech_olympics')) {
    registerCausalSeed('seed_hardtech_olympics', '少小立志数理铸剑', yr, '青年时期潜心钻研核心数理与精密工艺，埋下大国自强种子。');
  }
  if (age >= 25 && (state.track === 'biz' || state.track === 'trade' || getStat('eq', 50) >= 65) && !isCausalSeedActive('seed_global_trade')) {
    registerCausalSeed('seed_global_trade', '扬帆出海商机初萌', yr, '洞悉全球经贸产业链变迁，早早布局跨国合作脉络。');
  }
  if (age >= 26 && getStat('clean', 50) >= 72 && !isCausalSeedActive('seed_integrity_family')) {
    registerCausalSeed('seed_integrity_family', '清风正气立身治家', yr, '恪守清正廉明家训，不染尘埃，树立清流门风。');
  }
  if (age >= 23 && state.childhoodFriends && state.childhoodFriends.length > 0 && !isCausalSeedActive('seed_companion_bond')) {
    registerCausalSeed('seed_companion_bond', '总角之交守望相助', yr, '与大院发小立下莫逆之约，无论顺逆皆肝胆相照。');
  }
  if (yr >= 2018 && isCausalSeedActive('seed_hardtech_olympics')) {
    triggerCausalEcho('echo_chip_backup_activation', 'seed_hardtech_olympics', '自主备胎转正·国之重器破壁', yr, '早年深耕的底层数理与自主技术全面转正，顶住外部断供压力！', () => {
      addStat('iq', 2, 50);
      addStat('rep', 3, 50);
    });
  }
  if (age >= 45 && isCausalSeedActive('seed_people_flood')) {
    triggerCausalEcho('echo_flood_infrastructure_mandate', 'seed_people_flood', '万民伞护航·流域安澜丰碑', yr, '当年抗洪一线与百姓结下的鱼水深情化作万民口碑，重大工程获全力拥护！', () => {
      addStat('rep', 3, 50);
      addStat('resilience', 2, 50);
    });
  }
  if (yr >= 2015 && isCausalSeedActive('seed_global_trade')) {
    triggerCausalEcho('echo_seed_global_trade', 'seed_global_trade', '海纳百川·跨国供应链领航', yr, '早年布局的跨境经贸网络在“一带一路”大潮中结出硕果！', () => {
      state.capital = (state.capital || 0) + 12000;
      addStat('rep', 3, 50);
    });
  }
  if (yr >= 2012 && isCausalSeedActive('seed_integrity_family')) {
    triggerCausalEcho('echo_seed_integrity_family', 'seed_integrity_family', '激浊扬清·清流世家典范', yr, '数十年如一日的清正家风在正风肃纪大潮中获树为行业廉洁标杆！', () => {
      addStat('clean', 3, 50);
      addStat('rep', 3, 50);
    });
  }
  if (age >= 48 && isCausalSeedActive('seed_companion_bond')) {
    triggerCausalEcho('echo_seed_companion_bond', 'seed_companion_bond', '故人万里归来·双璧合流', yr, '昔年守望相助的挚友学成归国成为泰斗，与你携手共推国家重点专项！', () => {
      addStat('eq', 3, 50);
      addStat('rep', 3, 50);
    });
  }

  // 7. 时代勋章、流派光环、生平顺逆折线归档与核心属性钳制
  clampCoreStats(state);
  if (typeof ensureLifeAmbition === 'function' && state.age >= 18) {
    const amb = ensureLifeAmbition(state);
    if (amb && amb.achieved && !state.handledEvents['ambition_toast_' + amb.id]) {
      state.handledEvents['ambition_toast_' + amb.id] = true;
      addStat('rep', 4);
      addStat('resilience', 3);
      addChronicleItem(state.age, state.year, `【夙愿得偿】毕生宏愿「${amb.title}」（${amb.desc}）圆满达成！无愧时代，不负韶华！`, '宏愿大成', 'promo');
      showToast(`🎯 人生立志达成：【${amb.title}】！`, 'gold');
    }
  }
  updateArchetypeAura();
  checkAchievements();
  checkMemoryAlbumMilestones();
  recordLifeWaveHistoryPoint();

  // 8. 三年一届组织综合履职大考
  if (state.age > 20 && state.age % 3 === 0 && !state.handledEvents[`appraisal_${state.age}`]) {
    state.handledEvents[`appraisal_${state.age}`] = true;
    if (state.clean >= 65 && state.rep >= 45) {
      checkOnboardingTask('eval');
    }
    evaluateYearlyAppraisal({ deferPopup: true });
  }

  saveGameState();
}

