function checkAndTriggerCausalEchoEvent() {
  if (state.activeModal || (state.age || 0) < 28) return false;
  if (!state.causalSeeds || typeof CAUSAL_ECHO_EVENT_DECK === 'undefined' || !Array.isArray(CAUSAL_ECHO_EVENT_DECK)) return false;

  const currentYear = state.year;
  const currentAge = state.age;

  for (const echoDef of CAUSAL_ECHO_EVENT_DECK) {
    if (state.handledEvents && state.handledEvents['causal_echo_' + echoDef.id]) continue;

    let matchedSeed = null;
    let matchedSeedId = null;
    if (Array.isArray(echoDef.seedId)) {
      for (const sid of echoDef.seedId) {
        if (state.causalSeeds[sid] && !state.causalSeeds[sid].isEchoed) {
          matchedSeed = state.causalSeeds[sid];
          matchedSeedId = sid;
          break;
        }
      }
    } else if (state.causalSeeds[echoDef.seedId] && !state.causalSeeds[echoDef.seedId].isEchoed) {
      matchedSeed = state.causalSeeds[echoDef.seedId];
      matchedSeedId = echoDef.seedId;
    }

    if (!matchedSeed) continue;

    const seedPlantYear = matchedSeed.year || (currentYear - 15);
    const yearsElapsed = currentYear - seedPlantYear;
    if (yearsElapsed >= (echoDef.minYearsElapsed || 10) && currentAge >= (echoDef.minAge || 28) && currentAge <= (echoDef.maxAge || 85)) {
      state.handledEvents = state.handledEvents || {};
      state.handledEvents['causal_echo_' + echoDef.id] = true;
      state.lastMajorEventAge = currentAge;

      const seedTitle = matchedSeed.title || '当年抉择';
      const seedDesc = matchedSeed.desc || seedTitle;
      const seedPlantAge = matchedSeed.age || Math.max(1, currentAge - yearsElapsed);

      openDecisionModal({
        id: `causal_echo_${echoDef.id}_${currentYear}`,
        title: `⚡【命运回响 · 岁月的伏笔】当年“${seedTitle}”的选择回来找你了！`,
        desc: `【草蛇灰线，伏脉千里 · 历经 ${yearsElapsed} 载历史沧桑】\n在 ${seedPlantYear} 年（你当年 ${seedPlantAge} 岁），你曾做出关键抉择：“${seedDesc}”。\n\n${echoDef.scene}`,
        scene: `【草蛇灰线，伏脉千里 · 历经 ${yearsElapsed} 载历史沧桑】\n在 ${seedPlantYear} 年（你当年 ${seedPlantAge} 岁），你曾做出关键抉择：“${seedDesc}”。\n\n${echoDef.scene}`,
        choices: echoDef.choices.map(c => ({
          text: c.text,
          statReq: c.statReq,
          reqVal: c.reqVal,
          effects: c.effects,
          successText: c.successText,
          failText: c.failText,
          echoSeedId: matchedSeedId,
          echoId: `echo_${echoDef.id}_${currentYear}`,
          action: () => {
            triggerCausalEcho(
              `echo_${echoDef.id}_${currentYear}`,
              matchedSeedId,
              echoDef.title,
              currentYear,
              c.successText || echoDef.title
            );
            if (typeof c.action === 'function') c.action(state);
          }
        }))
      });
      return true;
    }
  }
  return false;
}

function tickOneYear() {
  if (!state.isStarted || state._needsSeedInit) {
    startCharacterCreation();
    return;
  }
  if (state.endgameSettled) {
    state.activeModal = 'endgame';
    requestRender();
    return;
  }
  if (state.activeModal) return;
  if (state.pendingPhoneCrisis) {
    answerRedPhone();
    return;
  }

  // 若上一轮存在未正常抉择而被强行跳过的危机或重大决策弹窗，执行法定兜底结算
  state._skippedModalLastTick = !!(state.unresolvedCrisis || state.unresolvedDecisionEvent);
  if (state.unresolvedCrisis) {
    const skippedCrisis = state.unresolvedCrisis;
    state.unresolvedCrisis = null;
    if (skippedCrisis === 'audit_crisis' && typeof executeAuditChoice === 'function') {
      executeAuditChoice(1);
    } else if (skippedCrisis === 'debt_crisis' && typeof executeDebtChoice === 'function') {
      executeDebtChoice(0);
    } else if (skippedCrisis === 'health_crisis' && typeof executeHealthChoice === 'function') {
      executeHealthChoice();
    }
  }
  if (state.unresolvedDecisionEvent) {
    // 玩家中途意外退出或后台切回，温和执行稳妥兜底，避免惩罚性重创（声望/清廉微调-1，扣减微量日常开销，保留核心底盘）
    state.unresolvedDecisionEvent = null;
    addStat('rep', -1);
    addStat('resilience', 1); // 增补一份经事韧性
    const evasionCost = Math.round(Math.min(3000, Math.max(300, Math.abs(state.capital || 0) * 0.01)));
    state.capital = Math.max(0, (state.capital || 0) - evasionCost);
    clampCoreStats(state);
  }

  // ⏳ 寿命与体魄/过劳/调摄/危机/天赋深度耦合（彻底移除 78 岁下限硬锁，打破终局年龄与种子 0.99 绑定，让体魄与养生真正决定寿算）
  const curHealth = getStat('health', 55);
  const healthLifespanMod = Math.round((curHealth - 50) / 4.5); // 体魄 20->-7岁，体魄 85->+8岁
  const crisisPenalty = (state.healthCrisisCount || 0) * 3;     // 重疾危机每次扣除 3 岁天元
  const overworkPenalty = Math.floor((state.overworkYears || 0) / 3); // 长期过劳每 3 年削减 1 岁
  const wellnessBonus = Math.floor((state.wellnessYears || 0) / 3);   // 长期调摄每 3 年增益 1 岁
  const talentBonus = (typeof hasTalent === 'function' && hasTalent('vitality')) ? 3 : 0; // 【颐养天和】天赋真实延寿 +3 岁

  const rawBaseLifespan = state.baseLifespanSeed || state.lifespanCeiling || 76;
  const naturalCeiling = Math.min(98, Math.max(62, Math.round(rawBaseLifespan + healthLifespanMod - crisisPenalty - overworkPenalty + wellnessBonus + talentBonus)));
  if ((state.health <= 18 && state.age >= 54) || ((state.healthCrisisCount || 0) >= 2 && state.age >= 56 && state.health <= 32)) {
    const maxEmergency = (typeof WECHAT_MONETIZATION_CONFIG !== 'undefined' && WECHAT_MONETIZATION_CONFIG.maxEmergencyMedicalPerRun) || 1;
    const canUseEmergency = (state.emergencyMedicalUsedCount || 0) < maxEmergency &&
      !state.emergencyMedicalUsed &&
      (!state.emergencyMedicalCooldownUntil || state.year >= state.emergencyMedicalCooldownUntil);
    if (canUseEmergency && typeof openEmergencyMedicalModal === 'function') {
      openEmergencyMedicalModal();
      return;
    }
    if (!state.isRetired) {
      state.isRetired = true;
      state.earlyHonorRetire = true;
      state.health = Math.max(48, (state.health || 0) + 20);
      state.jobTitle = '从容荣退 · 功勋名宿';
      addChronicleItem(state.age, state.year, '【从容荣退】半生操劳，大节无亏，经组织关怀从容荣休，离岗静养，安享天年。', '从容荣退', 'promo');
      showToast('🕊️ 组织关怀批准从容荣退，脱离一线高压，安享从容晚晴！', 'gold');
      requestRender();
      return;
    } else {
      state.burnedOutRetire = true;
      state.earlyRetireReason = '岁月沧桑，安详归真';
      triggerEndgameModal();
      return;
    }
  }
  if (state.age >= naturalCeiling) {
    triggerEndgameModal();
    return;
  }

  if (state.age < 18) {
    tickChildhoodYear();
    return;
  }

  // 核心流转：每年必先推进年龄与纪元、结算俸禄/战略/政策/门徒/大考
  settleAnnualCoreProgression();

  const yr = state.year;
  const age = state.age;
  const tr = state.track || 'gov';
  const wv = state.worldVolatility || {};

  // 0. 时代宏观浪潮背景记录与行业景气度修正（每年自动载入编年史，绝不强行抢占所有赛道的个人弹窗）
  const eraWave = ERA_BACKGROUND_WAVES[yr];
  if (eraWave && !state.handledEvents[`era_bg_${yr}`]) {
    state.handledEvents[`era_bg_${yr}`] = true;
    if (eraWave.medal && eraWave.tracks.includes(tr) && (state.rep || 0) >= 68 && (state.clean || 0) >= 72 && (state.annualActionsTaken || 0) > 0) {
      awardMedal(eraWave.medal);
    }
    addChronicleItem(age, yr, `【时代风雷 · ${eraWave.title}】${eraWave.desc}`, '时代浪潮', 'history');
  }

  // ==========================================
  // 优先级 1：高压廉政/债务/重疾红线拦截
  // ==========================================
  if (checkHighStakesConsequences()) {
    state.pendingAppraisalPopup = false;
    return;
  }

  // ==========================================
  // 优先级 2：竞争性干部/职称/业务晋升沙盘 (26, 33, 40, 47, 54, 60岁六个核心台阶，留出失误追赶窗口)
  // ==========================================
  const promoAges = [26, 33, 40, 47, 54, 60];
  if (!state.isRetired && promoAges.includes(age) && !state.handledEvents[`promo_proc_${age}`] && (state.govLevel || 1) < 5) {
    state.handledEvents[`promo_proc_${age}`] = true;
    state.pendingAppraisalPopup = false;
    if (typeof unlockStageContactsForTrack === 'function') {
      unlockStageContactsForTrack(tr, 1);
    }
    const curTrackCfg = TRACK_CONFIGS[tr] || {};
    const ladder = curTrackCfg.ladder || TRACK_MILESTONES[tr] || [];
    const curRankIdx = ladder.findIndex(s => (s.rank || s.targetRank) === state.rankName);
    const nextStep = (curRankIdx >= 0 ? ladder[curRankIdx + 1] : ladder.find(s => s.deadline >= age && (s.rank || s.targetRank) !== state.rankName)) || ladder[ladder.length - 1] || {
      targetRank: "领军骨干",
      targetJob: "核心业务主管"
    };
    const nextLvl = curRankIdx >= 0 ? Math.min(5, curRankIdx + 2) : Math.min(5, (state.govLevel || 1) + 1);
    startPromotionProcess({
      targetRank: nextStep.rank || nextStep.targetRank,
      targetJob: nextStep.job || nextStep.targetJob,
      level: nextLvl
    });
    return;
  }

  // ==========================================
  // 优先级 2.2：花甲交卷 · 光荣退休交接与银发第二曲线 (60岁法定荣休里程碑)
  // ==========================================
  if (age >= 60 && !state.isRetired && !state.handledEvents['retirement_ceremony_milestone']) {
    state.handledEvents['retirement_ceremony_milestone'] = true;
    state.isRetired = true;
    state.lastMajorEventAge = age;
    playSoundEffect('fanfare');
    triggerHaptic('heavy');
    const trCfg = (typeof TRACK_CONFIGS !== 'undefined' && TRACK_CONFIGS[tr]) ? TRACK_CONFIGS[tr] : {};
    const trName = trCfg.name || '行业';

    openDecisionModal({
      id: `retirement_ceremony_${tr}_${age}`,
      title: `🏮 岁月如歌 · 花甲荣退与人生第二曲线`,
      desc: `年满花甲之年，你在【${trName}】战线奋斗数十年，迎来了庄严温馨的光荣退休交接盛典。满堂同仁起立鼓掌，送上鲜花与毕生履职纪念册。面对人生新篇章，你将如何安顿往后岁月？`,
      choices: [
        {
          text: '受聘行业智库与终身顾问 · 倾囊相授扶携门生青年',
          statReq: 'rep', reqVal: 62,
          tag: '余热生辉',
          effects: { rep: 8, eq: 6, resilience: 4, capital: 8000 },
          outcomeText: '受聘为终身特聘顾问，言传身教提携青年英才，在行业内备受尊崇！',
          action: (s) => {
            s.jobTitle = `荣休名宿·特聘顾问`;
            addChronicleItem(age, yr, `【荣休盛典】光荣交接一线职责，受聘为行业终身顾问，门生满天下。`, '光荣退休', 'promo');
          }
        },
        {
          text: '潜心闭门撰述毕生纪实回忆录 · 为时代留下珍贵实录',
          statReq: 'iq', reqVal: 64,
          tag: '著书立说',
          effects: { iq: 8, clean: 6, rep: 6, sp: -4 },
          outcomeText: '数十年实战心得与时代亲历结集成书，成为后生竞相研读的经典篇章！',
          action: (s) => {
            s.jobTitle = `文墨著述·文史撰述人`;
            addChronicleItem(age, yr, `【著书立说】整理毕生履职手稿与时代亲历，出版纪实回忆录，薪火相传。`, '光荣退休', 'promo');
          }
        },
        {
          text: '解甲归田寄情山水草木与琴茶 · 调摄身心颐养天和',
          statReq: 'resilience', reqVal: 55,
          tag: '颐养天和',
          effects: { health: 10, resilience: 8, courage: -2, capital: -3000 },
          outcomeText: '退隐林泉，晨品幽茗暮弄素琴，身心焕然一新，体魄延年益寿！',
          action: (s) => {
            s.jobTitle = `林泉隐逸·颐养名宿`;
            addChronicleItem(age, yr, `【解甲归田】退隐林泉修身养性，寄情琴茶草木，自得悠然之乐。`, '光荣退休', 'promo');
          }
        },
        {
          text: '出资设立家乡青年助学奖励金 · 捐建义渡造福桑梓',
          statReq: 'clean', reqVal: 65,
          tag: '造福桑梓',
          effects: { rep: 12, clean: 10, eq: 5, capital: -22000 },
          outcomeText: '乡亲父老夹道相迎立碑感念，善行传颂四方，积下深厚福报口碑！',
          action: (s) => {
            s.jobTitle = `德高望重·桑梓长者`;
            addChronicleItem(age, yr, `【造福桑梓】出资捐建家乡水利与助学书舍，德馨流芳，乡党交口称赞。`, '光荣退休', 'promo');
          }
        }
      ]
    });
    return;
  }

  // ==========================================
  // 优先级 2.5：时代浪潮生涯转轨十字路口 (29岁与36岁跨界破局机会)
  // ==========================================
  const pivotConfig = CAREER_PIVOT_OPPORTUNITIES.find(p => p.age === age && !state.handledEvents[`career_pivot_${p.id}`]);
  if (pivotConfig) {
    state.handledEvents[`career_pivot_${pivotConfig.id}`] = true;
    state.lastMajorEventAge = age;
    const availableOpts = pivotConfig.options.filter(o => {
      if (!o.reqTrack) return true;
      if (o.reqTrack.startsWith('!') && o.reqTrack.slice(1) === tr) return false;
      return true;
    });
    const pivotChoices = availableOpts.slice(0, 3).map((opt, oIdx) => {
      const isStay = !opt.targetTrack;
      if (isStay) {
        return {
          text: opt.text,
          statReq: 'resilience',
          reqVal: 55,
          tag: '坚守本位',
          effects: { resilience: 5, rep: 4, clean: 3 },
          outcomeText: '坚守本位厚植初心，十年磨剑，在本赛道积累了深厚资历！'
        };
      }
      return {
        text: opt.text,
        statReq: opt.targetTrack === 'biz' || opt.targetTrack === 'trade' ? 'courage' : (opt.targetTrack === 'tech' ? 'iq' : 'eq'),
        reqVal: 58,
        tag: '乘风转轨',
        effects: { courage: 6, rep: 5, capital: 15000 },
        outcomeText: `勇毅跨界破局！成功转入全新赛道【${opt.targetRank}】，开辟人生第二曲线！`,
        action: (s) => {
          s.track = opt.targetTrack;
          s.rankName = opt.targetRank;
          s.jobTitle = opt.targetJob;
          ensureLifeAmbition(s);
          if (typeof unlockStageContactsForTrack === 'function') {
            unlockStageContactsForTrack(s.track, 1);
          }
          reportGameMilestone('career_pivot_executed', { age: s.age, targetTrack: s.track, rank: s.rankName });
        }
      };
    });
    openDecisionModal({
      id: pivotConfig.id,
      title: pivotConfig.title,
      desc: pivotConfig.scene,
      choices: pivotChoices
    });
    return;
  }

  // ==========================================
  // 优先级 3：本局隐藏世界参数驱动的【个人无常暗礁与人脉因果转折】（修复 personalCrisisAges 字段与 3 槽位独立剧本）
  // ==========================================
  const crisisAges = Array.isArray(wv.personalCrisisAges)
    ? wv.personalCrisisAges
    : (Array.isArray(wv.crisisAges) ? wv.crisisAges : [29, 41, 51]);
  const crisisSlotIdx = crisisAges.findIndex((cAge, idx) => age >= cAge && age <= cAge + 2 && !state.handledEvents[`wv_personal_crisis_slot_${idx}`]);
  if (crisisSlotIdx !== -1 && !state.handledEvents[`wv_personal_crisis_${age}`]) {
    state.handledEvents[`wv_personal_crisis_${age}`] = true;
    state.handledEvents[`wv_personal_crisis_slot_${crisisSlotIdx}`] = true;
    state.lastMajorEventAge = age;
    const contactName = (state.contacts && state.contacts.length > 2)
      ? state.contacts[state.contacts.length - 1].name
      : ((state.childhoodFriends && state.childhoodFriends[0]) ? state.childhoodFriends[0].name : '同行旧识');

    if (crisisSlotIdx === 0) {
      if (wv.partnerFate === 'betray') {
        openDecisionModal({
          id: `wv_betrayal_${tr}_${age}`,
          title: `⚡ 人心叵测 · 搭档【${contactName}】私挪账目与背刺风波`,
          desc: `你在【${state.jobTitle}】岗位上全力推进关键项目时，平日称兄道弟的搭档【${contactName}】竟私自截留核心客户资料与账面周转金另起炉灶，还将一笔烂尾责任推到你头上：`,
          choices: [
            {
              text: '连夜封存原始凭证移交法务稽核 · 铁腕追责到底绝不姑息',
              statReq: 'courage', reqVal: 58,
              outcomeText: '铁腕亮剑追回大半损失，震慑宵小，但撕破脸皮亦损耗了大量心力！',
              effects: { courage: 6, clean: 6, health: -4, eq: -2 },
              tag: '铁腕肃清'
            },
            {
              text: '稳住上游合作方先行自掏腰包补齐缺口 · 用实绩保住项目招牌',
              statReq: 'eq', reqVal: 56,
              outcomeText: '项目按期交付赢得口碑，危机化为独立掌舵契机，但个人积蓄大出血！',
              effects: { rep: 7, eq: 6, capital: -8500, health: -3 },
              tag: '忍辱扛鼎'
            }
          ]
        });
      } else {
        openDecisionModal({
          id: `wv_early_reef_${tr}_${age}`,
          title: `🌊 初涉暗礁 · 【${state.jobTitle}】青年期路线分歧与攻坚重压`,
          desc: `年方${age}岁，你首次独立主持【${state.jobTitle}】年度重点项目，却遭遇老资格骨干消极怠工与上游配套断供的双重夹击：`,
          choices: [
            {
              text: '吃住在工位亲自示范关键工序 · 以硬核技术折服老骨干',
              statReq: 'iq', reqVal: 56,
              outcomeText: '过硬本领令全组心服口服，如期攻克难关，但连轴熬夜损耗了体魄！',
              effects: { iq: 6, rep: 6, health: -5, sp: -6 },
              tag: '以技服人'
            },
            {
              text: '重新划分权责绩效并引入外部备选供应商 · 铁腕破除大锅饭',
              statReq: 'courage', reqVal: 57,
              outcomeText: '竞争机制激活团队战斗力，效率大幅提升，唯人情摩擦带来些许非议！',
              effects: { courage: 6, resilience: 5, eq: -3, capital: -4500 },
              tag: '破局立新'
            }
          ]
        });
      }
      return;
    } else if (crisisSlotIdx === 1) {
      if (wv.friendFate === 'crisis') {
        openDecisionModal({
          id: `wv_friend_crisis_${tr}_${age}`,
          title: `🌧️ 故人蒙难 · 昔年挚友【${contactName}】陷入连带担保绝境`,
          desc: `深夜急促敲门声响起，昔年与你同甘共苦的【${contactName}】因行业周期暴雷背上巨额连带债务，满面憔悴恳请你出面担保或借资救急：`,
          choices: [
            {
              text: '不签违规连带担保 · 但拿出个人积蓄赠予其安顿家小渡过难关',
              statReq: 'clean', reqVal: 62,
              outcomeText: '既守住了家庭与岗位防火墙，又全了患难情义，挚友泣不成声！',
              effects: { clean: 6, rep: 7, capital: -9000, resilience: 4 },
              tag: '仁义有度'
            },
            {
              text: '动用行业人脉为其引荐破产重整并购方 · 助其断臂求生东山再起',
              statReq: 'eq', reqVal: 62,
              outcomeText: '巧妙盘活残存资产化解死局，结下生死莫逆之交！',
              effects: { eq: 7, rep: 6, sp: -8, health: -4 },
              tag: '雪中送炭'
            }
          ]
        });
      } else {
        openDecisionModal({
          id: `wv_mid_reef_${tr}_${age}`,
          title: `⚡ 中流击水 · 【${state.jobTitle}】中坚期转型阵痛与越级问责`,
          desc: `步入${age}岁中坚之年，行业技术与监管范式剧烈迭代，你分管的业务模块因历史遗留问题被上级督导组点名问责：`,
          choices: [
            {
              text: '主动扛下历史遗留责任 · 封闭百日彻底重构业务底座',
              statReq: 'resilience', reqVal: 63,
              outcomeText: '壮士断腕彻底根除沉疴，督导组通报表扬，但身心承受极大煎熬！',
              effects: { resilience: 7, rep: 7, health: -6, capital: -5000 },
              tag: '刮骨疗毒'
            },
            {
              text: '详列历年台账厘清责任边界 · 稳妥推进分阶段渐进整改',
              statReq: 'iq', reqVal: 62,
              outcomeText: '有理有据稳住大局，团队免受剧烈震荡，但耗费不少公关协调周折！',
              effects: { iq: 6, clean: 5, eq: -3, sp: -7 },
              tag: '稳中求进'
            }
          ]
        });
      }
      return;
    } else {
      openDecisionModal({
        id: `wv_late_reef_${tr}_${age}`,
        title: `🏔️ 岁寒晚节 · 【${state.jobTitle}】深水区改革阻力与身心极限考验`,
        desc: `年届${age}岁，你在【${state.jobTitle}】任上推进收官之战，既要面对既得利益群体的暗中掣肘，又要应对连月高压带来的心脑血管警报：`,
        choices: [
          {
            text: '带病死磕一线拿出无可辩驳的硬核实绩 · 以战止战正面击碎流言',
            statReq: 'courage', reqVal: 65,
            outcomeText: '硬仗大捷令质疑者哑口无言，行业地位稳如泰山，但身体严重透支！',
            effects: { rep: 8, courage: 7, health: -8, sp: -8 },
            tag: '逆风亮剑'
          },
          {
            text: '主动收敛锋芒退一步休整 · 放手让青年副手挑起大梁并调养身心',
            statReq: 'resilience', reqVal: 62,
            outcomeText: '以退为进避开风口浪尖，团队梯队愈发成熟，体魄心性得以恢复！',
            effects: { resilience: 7, health: 6, rep: -3, capital: -4000 },
            tag: '藏器待时'
          }
        ]
      });
      return;
    }
  }

  // ==========================================
  // 优先级 4：真实婚恋良缘与家庭子女成长闭环（提升适龄触发率与成家吸引力，二婚/再遇使用独立剧本防重复）
  // ==========================================
  const hasSpouse = !!(state.family && state.family.spouseName);
  const hasChildren = !!(hasSpouse && state.family.children && state.family.children.length > 0);

  // 4.1 适龄单身青年婚恋奇遇 (23~36岁未婚时自然触发，27岁与32岁保底触发，第一/二次奇遇剧本完全不同)
  if (!hasSpouse && age >= 23 && age <= 36 && (state.courtshipCount || 0) < 2 && (age - (state.lastCourtshipAge || 0) >= 3) && (seededRandom() < 0.62 || (age >= 26 && !state.courtshipCount) || (age >= 31 && (state.courtshipCount || 0) === 1))) {
    state.courtshipCount = (state.courtshipCount || 0) + 1;
    state.lastCourtshipAge = age;
    state.lastMajorEventAge = age;
    const partnerGender = state.gender === 'female' ? 'male' : 'female';
    const loveName = generateRandomChineseName(partnerGender).fullName;
    const matchName = generateRandomChineseName(partnerGender).fullName;
    const trackPartnerDesc = {
      gov: '机关宣传干事', tech: '研究所同组实验员', biz: '外贸商行会计', trade: '口岸货运代理',
      industry: '厂办广播站播音员', military: '驻地军医护士', agri: '乡文化站青年教师', grassroots: '街道卫生所医生',
      art: '剧团青年画师', med: '邻科住院医师', law: '律所实习书记员', education: '同校语文老师'
    }[tr] || '志同道合的同龄青年';

    const isSecondEncounter = state.courtshipCount >= 2;
    openDecisionModal({
      id: isSecondEncounter ? `rematch_courtship_${tr}_${age}` : `courtship_${tr}_${age}`,
      title: isSecondEncounter ? `🏮 佳期再逢 · 岁月沉淀后的良缘抉择` : `🌸 青春良缘 · 梧桐树下的终身大事抉择`,
      desc: isSecondEncounter
        ? `年满${age}岁，历经数年职场风雨后，你在行业协作中邂逅了知性通透的${trackPartnerDesc}【${loveName}】；与此同时，世交长辈也再次热心撮合条件优越的【${matchName}】：`
        : `年满${age}岁，家中父母频频写信催问个人问题。在日常工作往来中，温婉笃实的${trackPartnerDesc}【${loveName}】与你情投意合；同时热心长辈也为你介绍了家境优渥、能助你事业一臂之力的【${matchName}】：`,
      choices: [
        {
          text: '婉言谢绝婚恋说媒 · 独身一人将全部精力投入业务苦修',
          statReq: 'courage', reqVal: 64,
          outcomeText: '保持单身自由之身，挑灯夜读深耕专业，唯深夜独归偶感清冷劳顿！',
          effects: { iq: 4, courage: 4, eq: -2, health: -2 },
          tag: '独身立业'
        },
        {
          text: `接受长辈撮合与家境优渥的【${matchName}】联姻 · 借家族资源共拓前程`,
          statReq: 'rep', reqVal: 48,
          outcomeText: `与【${matchName}】风光成婚，获得丰厚礼金与人脉支持，唯人情往来需多费心力！`,
          effects: { capital: 18000, rep: 7, eq: 5, clean: -2 },
          action: () => {
            state.family = state.family || {};
            state.family.spouseName = matchName;
            state.family.bond = 72;
            addChronicleItem(age, yr, `【门当户对】经长辈撮合与【${matchName}】结为连理，家族人脉声势大增。`, '世交联姻', 'promo');
          },
          tag: '借势联姻'
        },
        {
          text: `与志同道合的【${loveName}】携手成家 · 在温馨灯火中共筑后方港湾`,
          statReq: 'eq', reqVal: 42,
          outcomeText: `与【${loveName}】喜结连理！虽操办婚宴略有花销，但琴瑟和鸣、身心大安，事业更有后盾！`,
          effects: { resilience: 8, eq: 7, rep: 5, health: 4, capital: -2000 },
          action: () => {
            state.family = state.family || {};
            state.family.spouseName = loveName;
            state.family.bond = 85;
            addChronicleItem(age, yr, `【洞房花烛】与${trackPartnerDesc}【${loveName}】喜结连理，相濡以沫共筑小家！`, '喜结良缘', 'promo');
          },
          tag: '两情相悦'
        }
      ]
    });
    return;
  }

  // 4.2 子嗣启蒙与成人分流（严格校验已婚且有子女，放宽年龄窗口确保不漏触发）
  if (hasChildren) {
    const child = state.family.children[0];
    const childAge = yr - (child.birthYear || (yr - 6));
    if (childAge >= 6 && childAge <= 10 && !state.handledEvents['child_edu_6']) {
      state.handledEvents['child_edu_6'] = true;
      state.lastMajorEventAge = age;
      openDecisionModal({
        id: `child_edu_6_${tr}`,
        title: `🎒 童蒙养正 · 子嗣【${child.name}】入学家风启蒙`,
        desc: `转眼孩儿【${child.name}】背起小书包步入小学，伴侣【${state.family.spouseName}】与你商议孩子的培养重心：`,
        choices: [
          {
            text: '严抓诚实守信与经典诵读 · 宁可慢一点也要打正三观根骨',
            statReq: 'clean', reqVal: 56,
            outcomeText: '孩子自幼明事理知敬畏，清正家风令街坊邻里赞不绝口！',
            effects: { clean: 6, rep: 6, sp: -5, capital: -2500 },
            tag: '立德修身'
          },
          {
            text: '送去少年宫学微机编程与航模拆装 · 激发数理科学探索欲',
            statReq: 'iq', reqVal: 56,
            outcomeText: '孩子动手与数理思维大进，捧回少年科技小发明奖状！',
            effects: { iq: 6, courage: 5, capital: -4000, health: -2 },
            tag: '科学启蒙'
          }
        ]
      });
      return;
    } else if (childAge >= 17 && childAge <= 22 && !state.handledEvents['child_edu_18']) {
      state.handledEvents['child_edu_18'] = true;
      state.lastMajorEventAge = age;
      openDecisionModal({
        id: `child_edu_18_${tr}`,
        title: `🎓 雏凤清声 · 子嗣【${child.name}】十八岁远行志向`,
        desc: `当年襁褓中的【${child.name}】已长大成人，即将迈出独立人生的第一步。灯下促膝长谈，你为其指引方向：`,
        choices: [
          {
            text: '支持孩子继承你的衣钵深耕本行 · 薪火相传守正精进',
            statReq: 'rep', reqVal: 62,
            outcomeText: `【${child.name}】立志接过你的接力棒，两代人同心耕耘，门风声誉大振！`,
            effects: { rep: 7, resilience: 6, capital: -5500, health: -3 },
            tag: '子承父业'
          },
          {
            text: '放手让孩子远赴新兴科技与商贸前沿闯荡 · 海阔凭鱼跃',
            statReq: 'courage', reqVal: 60,
            outcomeText: `【${child.name}】在新兴赛道闯出名堂并反哺家庭，视野格局焕然一新！`,
            effects: { capital: 15000, eq: 6, resilience: -2, sp: -5 },
            tag: '破浪远航'
          }
        ]
      });
      return;
    }
  }

  // ==========================================
  // 优先级 5：赛道专属主线与千人千面程序化遭遇（成年期与 54 岁+ 后半生高密度决策覆盖）
  // ==========================================
  // 5.0 77岁+ 高龄专属世纪回眸与晚晴叙事优先触发（彻底解决77岁后零决策断崖，同时控制年均触发密度在 2.8~4.2 次）
  if (age >= 77) {
    if (!state.activeModal && (age === 77 || (age - (state.lastMajorEventAge || 0) >= 3) || ((age - (state.lastMajorEventAge || 0) >= 2) && seededRandom() < 0.45))) {
      triggerProceduralAnnualEncounter();
    }
    return;
  }

  // 5.1 赛道专属编年大考 (TRACK_SPECIFIC_STORIES，按局内种子抽样触发，降低同赛道剧本固定度)
  const trackStories = TRACK_SPECIFIC_STORIES[tr] || [];
  const trackEvt = trackStories.find(s =>
    (s.year === yr || s.triggerAge === age || s.age === age || (s.triggerAge && Math.abs(age - s.triggerAge) <= 1)) &&
    !state.handledEvents[`track_story_${s.id}`]
  );
  if (trackEvt && (age - (state.lastMajorEventAge || 0) >= 2)) {
    state.handledEvents[`track_story_${trackEvt.id}`] = true;
    if (seededRandom() < 0.35) {
      state.lastMajorEventAge = age;
      const vIdx = ((state.worldVolatility && state.worldVolatility.eraEncounterSeed) || age) % 4;
      const vLabels = ['破局篇', '深耕篇', '抉择篇', '笃行篇'];
      openDecisionModal({
        ...trackEvt,
        id: `${trackEvt.id}_v${vIdx}`,
        title: vIdx === 0 ? trackEvt.title : `${trackEvt.title}（${vLabels[vIdx]}）`
      });
      return;
    }
  }

  // 5.2 54岁六大赛道毕生心血大考 (TRACK_MAGNUM_OPUS_DATABASE，带赛道与局内分支专属ID)
  if (age === 54 && !state.handledEvents['track_magnum_opus']) {
    state.handledEvents['track_magnum_opus'] = true;
    if (seededRandom() < 0.48) {
      state.lastMajorEventAge = age;
      const opusKey = TRACK_MAGNUM_OPUS_DATABASE[tr] ? tr : (tr === 'trade' ? 'biz' : (tr === 'military' ? 'industry' : (tr === 'grassroots' ? 'agri' : 'gov')));
      const opus = TRACK_MAGNUM_OPUS_DATABASE[opusKey] || TRACK_MAGNUM_OPUS_DATABASE.gov;
      const vIdx = ((state.worldVolatility && state.worldVolatility.eraEncounterSeed) || yr) % 4;
      openDecisionModal({
        ...opus,
        id: `opus_${tr}_${opus.id}_v${vIdx}`
      });
      return;
    }
  }

  // 5.3 赛道专属程序化年度遭遇 (PROCEDURAL_ANNUAL_ENCOUNTER_POOL + EXPANDED_TRACK_CAREER_POOL + LATE_CAREER_ENCOUNTER_POOL)
  // 精简模式下降低常规遭遇弹窗密度（3~4 年一次），让单局聚焦核心台阶
  const minProcGap = state.isStreamlinedMode ? 3 : 1;
  const procProb = state.isStreamlinedMode ? 0.38 : (age >= 54 ? 0.82 : 0.74);
  if (!state.activeModal && (age - (state.lastMajorEventAge || 0) >= minProcGap) && seededRandom() < procProb) {
    if (triggerProceduralAnnualEncounter()) return;
  }

  // 5.4 模块化职场故事与市井百态抽样 (MODULAR_STORY_DECK & URBAN_FOLK_ENCOUNTERS，按局内种子分桶防重合)
  const modRunBucket = Math.abs((wv.eraEncounterSeed || _gameSeed || 0)) % 4;
  if (!state.isStreamlinedMode) {
    if (!state.activeModal && (age - (state.lastMajorEventAge || 0) >= 1) && seededRandom() < 0.32) {
      const validModulars = MODULAR_STORY_DECK.filter((m, idx) =>
        (!m.minAge || age >= m.minAge) &&
        (!m.maxAge || age <= Math.max(m.maxAge, 95)) &&
        (!m.tracks || m.tracks.includes(tr)) &&
        ((idx % 3 === modRunBucket % 3) || seededRandom() < 0.25) &&
        !state.handledEvents[`mod_${m.id}`]
      );
      if (validModulars.length > 0) {
        const picked = validModulars[Math.floor(seededRandom() * validModulars.length)];
        state.lastMajorEventAge = age;
        state.handledEvents[`mod_${picked.id}`] = true;
        openDecisionModal({
          ...picked,
          id: `mod_${tr}_${picked.id}_b${modRunBucket}`
        });
        return;
      }
    }

    if (!state.activeModal && (age - (state.lastMajorEventAge || 0) >= 1) && seededRandom() < 0.28) {
      const validFolks = URBAN_FOLK_ENCOUNTERS.filter((item, idx) =>
        ((idx % 3 === modRunBucket % 3) || seededRandom() < 0.25) &&
        !state.handledEvents[`folk_${item.id}`]
      );
      if (validFolks.length > 0) {
        const pickedFolk = validFolks[Math.floor(seededRandom() * validFolks.length)];
        state.handledEvents[`folk_${pickedFolk.id}`] = true;
        state.lastMajorEventAge = age;
        openDecisionModal({
          ...pickedFolk,
          id: `folk_${tr}_${pickedFolk.id}_b${modRunBucket}`
        });
        return;
      }
    }
  }

  // ==========================================
  // 优先级 5.9：时代因果回响大典 (Causal Echo Nexus Trigger - 10~20 年后历史回收)
  // ==========================================
  if (!state.activeModal && (age - (state.lastMajorEventAge || 0) >= 1)) {
    if (checkAndTriggerCausalEchoEvent()) return;
  }

  // ==========================================
  // 优先级 6：时代浪潮与本赛道共振抉择
  // ==========================================
  const storyArc = EXTENDED_STORY_ARCS.find(a =>
    (a.year === yr || (a.triggerAge && age === a.triggerAge)) &&
    !state.handledEvents[`arc_${a.id}`]
  );
  if (storyArc && (age - (state.lastMajorEventAge || 0) >= 1)) {
    state.handledEvents[`arc_${storyArc.id}`] = true;
    const isTrackMatchedEra = eraWave && Array.isArray(eraWave.tracks) && eraWave.tracks.includes(tr);
    if ((isTrackMatchedEra && seededRandom() < 0.45) || seededRandom() < 0.16) {
      state.lastMajorEventAge = age;
      openDecisionModal({
        ...storyArc,
        id: `arc_${tr}_${storyArc.id}_b${modRunBucket}`
      });
      return;
    }
  }

  // ==========================================
  // 优先级 7：精选温情/风浪支线与晚年决策（大幅压缩纯展示确认弹窗，转为编年史自动入档）
  // ==========================================
  // 7.1 夫妻白首手札（已婚且晚年触发真实决策）
  if (hasSpouse && age >= 58 && (age - (state.lastMajorEventAge || 0) >= 1) && seededRandom() < 0.36 && triggerSpousalResonanceEvent()) return;

  // 7.2 亲情生老病死（抽样触发）
  if (!state.activeModal && (age - (state.lastMajorEventAge || 0) >= 1) && seededRandom() < 0.28) {
    if (triggerFamilyMortalityEvent()) return;
  }

  // 7.3 工程/科研/实业伦理与逆境、黑天鹅及民间书简（全12赛道均可触发）
  if ((age - (state.lastMajorEventAge || 0) >= 1) && seededRandom() < 0.26) {
    if (['industry', 'tech', 'military', 'agri', 'biz', 'trade', 'gov', 'law'].includes(tr) && triggerHighStakesConflict()) return;
    if (triggerBlackSwanVicissitude()) return;
    if (triggerGrassrootsLetterEvent()) return;
  }

  // 7.4 多阶因果与沧海横流决策事件
  if (!state.activeModal && (age - (state.lastMajorEventAge || 0) >= 1) && seededRandom() < 0.28 && triggerKarmaNexusStage()) return;
  if (!state.activeModal && (age - (state.lastMajorEventAge || 0) >= 1) && seededRandom() < 0.28 && triggerButterflyNexusStage()) return;
  if (!state.activeModal && (age - (state.lastMajorEventAge || 0) >= 1) && seededRandom() < 0.24 && triggerVicissitudesEvent()) return;

  // 7.45 兜底程序化遭遇：若距上次重大决策已满 1 年且未触发事件，高概率补抽一次赛道程序化决策，消除空转年份
  if (!state.activeModal && ((age - (state.lastMajorEventAge || 0) >= 2) || ((age - (state.lastMajorEventAge || 0) >= 1) && seededRandom() < 0.65))) {
    if (triggerProceduralAnnualEncounter()) return;
  }

  // 7.5 十年评传、节庆与常规考评转为【非阻塞编年史自动铭刻 + 浮动提示】，彻底消除纯确认弹窗冗余点击
  if ([30, 40, 50, 60, 70, 80, 90].includes(age) && !state.handledEvents[`decade_hist_${age}`]) {
    state.handledEvents[`decade_hist_${age}`] = true;
    addStat('resilience', 1);
    addChronicleItem(age, yr, `【太史公十年评传 · ${age}岁纪】行年${age}载，于【${state.jobTitle}】任上砥砺笃行，时代年轮镌刻下坚实足迹。`, '十年评传', 'promo');
  }

  if (age % 8 === 0 && !state.handledEvents[`seasonal_fest_${age}`]) {
    state.handledEvents[`seasonal_fest_${age}`] = true;
    addStat('health', 1);
    addChronicleItem(age, yr, `【岁时佳节】与家人同侪共度佳节，身心俱得宽慰（体魄+1）。`, '岁时温情', 'history');
  }

  if (state.pendingAppraisalPopup) {
    state.pendingAppraisalPopup = false;
    const gStr = (state.lastAppraisal && state.lastAppraisal.grade) ? String(state.lastAppraisal.grade) : '';
    if (!state.activeModal && !state.pendingPhoneCrisis && gStr.startsWith('C') && (state.inactionStreak || 0) >= 2) {
      state.activeModal = 'appraisal';
      playSoundEffect('alert');
      triggerHaptic('heavy');
      requestRender();
      return;
    }
  }

  // 8. 历史编年通史常规纪事
  const epoch = EPOCH_CHRONICLES[yr];
  if (epoch) {
    const epHead = epoch.headline || (epoch.title ? `【${epoch.title}】` : '');
    const epBody = epoch.body || epoch.content || '';
    addChronicleItem(age, yr, `${epHead}${epBody ? ' ' + epBody : ''}`, "时代大潮", "history");
  } else {
    addChronicleItem(age, yr, `${yr}年，坚守在${state.jobTitle}岗位，按【${STRATEGIES[state.strategy] ? STRATEGIES[state.strategy].name : '稳健实干'}】方针深耕，政绩与人资稳步沉淀。`, "岁增一载", "history");
  }

  if (checkHighStakesConsequences()) return;

  saveGameState();
  playSoundEffect('click');
  requestRender();
}

// ==========================================
