function ensureLifeAmbition(st) {
  const s = st || state;
  if (!s) return null;
  const rawTrack = s.track || 'gov';
  const mapKey = LIFE_AMBITION_TARGETS[rawTrack] ? rawTrack : 'gov';
  const tpl = LIFE_AMBITION_TARGETS[mapKey] || LIFE_AMBITION_TARGETS.gov;
  const achieved = tpl.check(s);
  s.lifeAmbition = {
    id: tpl.id,
    trackKey: mapKey,
    title: tpl.title,
    desc: tpl.desc,
    progress: achieved ? 100 : tpl.progress(s),
    achieved
  };
  return s.lifeAmbition;
}

function getEndgameSGradeSuccessRatio(s) {
  const unlockedCount = Array.isArray(s && s.unlockedTalents) ? s.unlockedTalents.length : 0;
  // 化解过危机直接加分：每成功化解1次危机，奖励性降低 0.40 决策比要求
  const resolvedBonus = Math.min(1.20, (s.resolvedCrisesCount || 0) * 0.40);
  return Math.max(3.80, 5.00 - resolvedBonus - Math.min(0.80, Math.sqrt(unlockedCount) * 0.35));
}

function isEligibleForSGradeCrises(s) {
  // 一代国士须亲历亲决，严禁机器代管决策通关 S 级（无头测试除外）
  const isHeadless = typeof wx === 'undefined' || !!s._isHeadlessSimulation;
  if (!isHeadless && (s.delegatedDecisionsCount || 0) > 0) return false;

  const total = (s.auditCrisisCount || 0) + (s.debtCrisisCount || 0) + (s.healthCrisisCount || 0);
  const resolved = s.resolvedCrisesCount || 0;
  // 若危机未妥善处置仍在挂起中，则不合格
  if (s.unresolvedCrisis) return false;
  // 核心规则：生平总危机数 <= 1；或者发生过危机但成功化解（resolved >= 1 且未化解 <= 1），不予一票否决
  if (total <= 1) {
    // 危机总数 <= 1 予以通过
  } else if (total <= 2 && resolved >= 1 && (total - resolved) <= 1) {
    // 曾成功化解过危机，展现卓越危机公关与抗逆力，抵消 1 次危机并予以豁免进入 S 级考核
  } else {
    return false;
  }
  // 从政党政与法治赛道严守清廉底线：重大违规审计危机必须为 0
  if (['gov', 'law'].includes(s.track) && (s.auditCrisisCount || 0) > 0) return false;
  return true;
}

