function getUnlockedEndings() {
  try {
    let raw = null;
    if (typeof wx !== 'undefined' && typeof wx.getStorageSync === 'function') {
      raw = wx.getStorageSync('lifesim_unlocked_endings');
    } else if (typeof localStorage !== 'undefined') {
      raw = localStorage.getItem('lifesim_unlocked_endings');
    }
    if (raw) {
      const arr = typeof raw === 'string' ? JSON.parse(raw) : raw;
      if (Array.isArray(arr)) return arr;
    }
  } catch (e) {}
  return [];
}

function recordUnlockedEnding(endingId) {
  if (!endingId) return [];
  try {
    const list = getUnlockedEndings();
    if (!list.includes(endingId)) {
      list.push(endingId);
      const str = JSON.stringify(list);
      if (typeof wx !== 'undefined' && typeof wx.setStorageSync === 'function') {
        wx.setStorageSync('lifesim_unlocked_endings', str);
      } else if (typeof localStorage !== 'undefined') {
        localStorage.setItem('lifesim_unlocked_endings', str);
      }
    }
    return list;
  } catch (e) {
    return [];
  }
}

function evaluateEndgameArchetype(st) {
  const s = st || state;
  const amb = ensureLifeAmbition(s);
  const matched = ENDGAME_ARCHETYPES_16.find(a => a.cond(s)) || ENDGAME_ARCHETYPES_16[ENDGAME_ARCHETYPES_16.length - 1];
  s.endgameArchetype = matched;
  s.currentEndingArchetype = matched;
  if (typeof recordUnlockedEnding === 'function') {
    recordUnlockedEnding(matched.id);
  }
  s.unlockedEndings = getUnlockedEndings();

  // 准 S 级分析与指引（若达成了 A 级，计算其距离 S 级巅峰还差哪些关键指标）
  if (matched.grade === 'A') {
    const deficits = [];
    if ((s.delegatedDecisionsCount || 0) > 0) {
      deficits.push(`一代国士须亲历亲决(本局曾托管代办决策${s.delegatedDecisionsCount}次)`);
    }
    if (!amb || !amb.achieved) deficits.push(`本命抱负达成度(${amb ? amb.progress : 0}%/100%)`);
    if ((s.completedPactsCount || 0) < 3) deficits.push(`三年军令状攻坚(${s.completedPactsCount || 0}/3个)`);
    if (Math.max(s.rankIndex || 0, s.lifetimeMaxRank || 0) < 4) deficits.push('最高达至高阶职级(需≥第4阶)');
    const totalCrises = (s.auditCrisisCount || 0) + (s.debtCrisisCount || 0) + (s.healthCrisisCount || 0);
    const resolved = s.resolvedCrisesCount || 0;
    if (totalCrises > 1 && !(totalCrises <= 2 && resolved >= 1 && (totalCrises - resolved) <= 1)) {
      deficits.push(`平稳履职危机红线(需生平危机≤1次或成功化解，未化解危机${Math.max(0, totalCrises - resolved)}次)`);
    } else if (['gov', 'law'].includes(s.track) && (s.auditCrisisCount || 0) > 0) {
      deficits.push('政法清廉审计零红线(曾有突发审计危机)');
    }
    if (getStat('rep', 0, s) < 84) deficits.push(`声望积累(${getStat('rep', 0, s)}/84点)`);
    s.nearSBreakdown = {
      isNearS: deficits.length <= 2,
      deficits: deficits
    };
  } else {
    s.nearSBreakdown = null;
  }

  return matched;
}

// 检查配置ID是否为占位符或未配置
function isPlaceholderOrEmpty(id) {
  if (!id || typeof id !== 'string') return true;
  const s = id.trim();
  if (!s) return true;
  if (s.toLowerCase().includes('placeholder')) return true;
  if (s === 'adunit-8f3a9c2e4b1d6075' || s === '1450038291') return true;
  return false;
}

