let _lastRewardedAdTs = 0;

function syncScoreToLeaderboard() {
  try {
    const arch = state.endgameArchetype || evaluateEndgameArchetype(state);
    const gradeScore = arch.grade === 'S' ? 1000 : (arch.grade === 'A' ? 750 : (arch.grade === 'B' ? 500 : 250));
    const rawScore = Math.round(gradeScore + (state.rep || 0) * 5 + (state.clean || 0) * 3 + Math.min(500, Math.floor((state.capital || 0) / 5000)));
    // 自动顾问代管决策扣除 25% 托管折损分以维护排行榜公平
    const delegationPenalty = (state.delegatedDecisionsCount && state.delegatedDecisionsCount > 0) ? 0.75 : 1.0;
    const totalScore = Math.round(rawScore * delegationPenalty);
    if (!Array.isArray(state.leaderboardHistory)) state.leaderboardHistory = [];
    const cleanedName = sanitizeUserInput(state.name || '时代弄潮儿');
    const safeActorName = (!cleanedName || cleanedName.includes('***')) ? '时代弄潮儿' : cleanedName;
    state.leaderboardHistory.push({
      name: safeActorName,
      score: totalScore,
      grade: String(arch.grade || 'B'),
      title: String(arch.title || ''),
      age: state.age || 78,
      year: state.year || 2050,
      track: state.track || 'gov',
      ts: Date.now()
    });
    state.leaderboardHistory.sort((a, b) => (b.score || 0) - (a.score || 0));
    if (state.leaderboardHistory.length > 10) {
      state.leaderboardHistory = state.leaderboardHistory.slice(0, 10);
    }
    if (typeof wx !== 'undefined' && typeof wx.setUserCloudStorage === 'function') {
      wx.setUserCloudStorage({
        KVDataList: [
          { key: 'era_score', value: String(totalScore) },
          { key: 'era_grade', value: String(arch.grade || 'B') },
          { key: 'era_title', value: String(arch.title || '') }
        ]
      });
    }
    if (typeof wx !== 'undefined' && typeof wx.getOpenDataContext === 'function') {
      const openDataContext = wx.getOpenDataContext();
      if (openDataContext && typeof openDataContext.postMessage === 'function') {
        openDataContext.postMessage({ type: 'UPDATE_SCORE', score: totalScore, grade: arch.grade, title: arch.title });
      }
    }
    if (typeof reportGameMilestone === 'function') {
      reportGameMilestone('leaderboard_synced', { score: totalScore, grade: arch.grade });
    }
  } catch (err) {
    logDebugError('syncScoreToLeaderboard', err);
  }
}

function openLeaderboardModal() {
  state._leaderboardReturnModal = state.activeModal === 'endgame' ? 'endgame' : null;
  state.activeModal = 'leaderboard';
  try {
    if (typeof wx !== 'undefined' && typeof wx.getOpenDataContext === 'function') {
      const openDataContext = wx.getOpenDataContext();
      if (openDataContext && typeof openDataContext.postMessage === 'function') {
        openDataContext.postMessage({ type: 'SHOW_LEADERBOARD', width: screenWidth - 48, height: 220 });
      }
    }
  } catch (err) {
    logDebugError('openLeaderboardModal', err);
  }
  playSoundEffect('paper');
  requestRender();
}

function drawLeaderboardModal() {
  if (!ctx) return;
  const cardW = screenWidth - 28;
  const cardH = 470;
  const cardX = 14;
  const cardY = Math.max(12, Math.round((screenHeight - cardH) / 2));

  ctx.save();
  ctx.fillStyle = '#111827';
  roundRect(ctx, cardX, cardY, cardW, cardH, 12, true, true, '#f59e0b', 2);
  drawCornerOrnaments(ctx, cardX, cardY, cardW, cardH, 8, '#f59e0b');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 16px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText("📖 人物志 · 历代履历留档", cardX + cardW / 2, cardY + 14);

  ctx.font = '14px ' + FONT_UI;
  ctx.fillStyle = '#94a3b8';
  ctx.fillText("按终局评定、一生声望、清白家风与家庭积蓄综合计分", cardX + cardW / 2, cardY + 38);

  const listX = cardX + 14;
  const listY = cardY + 62;
  const listW = cardW - 28;
  const listH = 342;
  ctx.fillStyle = '#1e293b';
  roundRect(ctx, listX, listY, listW, listH, 8, true, true, '#334155', 1);

  let drewSharedCanvas = false;
  try {
    if (typeof wx !== 'undefined' && typeof wx.getOpenDataContext === 'function') {
      const openDataContext = wx.getOpenDataContext();
      const sharedCanvas = openDataContext && openDataContext.canvas;
      if (sharedCanvas && sharedCanvas.width > 0 && sharedCanvas.height > 0) {
        ctx.drawImage(sharedCanvas, listX + 6, listY + 6, listW - 12, 145);
        drewSharedCanvas = true;
      }
    }
  } catch (err) {
    logDebugError('drawLeaderboardModal.sharedCanvas', err);
  }

  const localStartY = drewSharedCanvas ? (listY + 158) : (listY + 10);
  const maxRows = drewSharedCanvas ? 4 : 7;
  const defaultRows = [
    { name: '陈守正 (旧档)', grade: 'S', title: '国之柱石·丹青垂范', score: 1960, age: 86 },
    { name: '林致远 (旧档)', grade: 'A', title: '文林泰斗·德艺双馨', score: 1580, age: 82 },
    { name: '苏明玉 (旧档)', grade: 'A', title: '富甲一方·商海名流', score: 1490, age: 84 }
  ];
  const historyRows = (Array.isArray(state.leaderboardHistory) && state.leaderboardHistory.length > 0)
    ? state.leaderboardHistory.slice(0, maxRows)
    : defaultRows.slice(0, maxRows);

  ctx.textAlign = 'left';
  ctx.font = 'bold 14px ' + FONT_UI;
  ctx.fillStyle = '#f59e0b';
  ctx.fillText(drewSharedCanvas ? "📜 本机历代人物留档：" : "📜 历代人物生平留档 (前七名)：", listX + 12, localStartY);

  historyRows.forEach((row, idx) => {
    const ry = localStartY + 24 + idx * 42;
    ctx.fillStyle = idx === 0 ? 'rgba(245, 158, 11, 0.16)' : 'rgba(15, 23, 42, 0.55)';
    roundRect(ctx, listX + 10, ry, listW - 20, 36, 6, true, true, idx === 0 ? '#f59e0b' : '#334155', 1);

    const rankBadge = idx === 0 ? '🥇' : (idx === 1 ? '🥈' : (idx === 2 ? '🥉' : `#${idx + 1}`));
    ctx.textAlign = 'left';
    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = idx === 0 ? '#fde047' : '#e2e8f0';
    const leftText = `${rankBadge} ${row.name || '无名氏'} · [${row.grade || 'B'}级] ${row.title || '平淡一生'}`;
    ctx.fillText(fitText(leftText, listW - 110, 'bold 14px ' + FONT_CHRONICLE), listX + 18, ry + 10);

    ctx.textAlign = 'right';
    ctx.font = 'bold 14px ' + FONT_MONO;
    ctx.fillStyle = '#38bdf8';
    ctx.fillText(`${row.score || 1000}分`, listX + listW - 18, ry + 10);
  });

  const closeBtnW = cardW - 44;
  const closeBtnH = 36;
  const closeBtnX = cardX + 22;
  const closeBtnY = cardY + cardH - closeBtnH - 12;
  drawTactileButton(ctx, {
    id: 'close_leaderboard_modal_btn',
    x: closeBtnX,
    y: closeBtnY,
    w: closeBtnW,
    h: closeBtnH,
    radius: 6,
    bg: '#78350f',
    border: '#f59e0b',
    text: "合上名录 ➔",
    font: 'bold 14px ' + FONT_CHRONICLE,
    textColor: '#fef08a',
    priority: 100,
    onClick: () => {
      state.activeModal = state._leaderboardReturnModal || null;
      state._leaderboardReturnModal = null;
      playSoundEffect('click');
      requestRender();
    }
  });

  ctx.restore();
}

function generateShareCardImageUrl() {
  try {
    const offCanvas = (typeof wx !== 'undefined' && typeof wx.createCanvas === 'function')
      ? wx.createCanvas()
      : (typeof document !== 'undefined' && document.createElement ? document.createElement('canvas') : null);

    if (offCanvas) {
      offCanvas.width = 500;
      offCanvas.height = 400;
      const oCtx = offCanvas.getContext('2d');
      if (oCtx) {
        // 宣纸底衬色与质感
        oCtx.fillStyle = '#F8F4EB';
        oCtx.fillRect(0, 0, 500, 400);

        // 双层复古回纹金线外框
        oCtx.strokeStyle = '#8E7356';
        oCtx.lineWidth = 3;
        oCtx.strokeRect(12, 12, 476, 376);

        oCtx.strokeStyle = '#D1C2A5';
        oCtx.lineWidth = 1;
        oCtx.strokeRect(18, 18, 464, 364);

        // 四角金印折角装饰
        const drawCornerKnot = (cx, cy) => {
          oCtx.fillStyle = '#8E7356';
          oCtx.fillRect(cx - 3, cy - 3, 6, 6);
        };
        drawCornerKnot(18, 18);
        drawCornerKnot(482, 18);
        drawCornerKnot(18, 382);
        drawCornerKnot(482, 382);

        // 顶眉小引
        oCtx.fillStyle = '#856D4D';
        oCtx.font = 'bold 12px sans-serif';
        oCtx.textAlign = 'center';
        oCtx.fillText('✦  大 国 浮 生 录 · 功 业 册  ✦', 250, 40);

        // 人物与享年信息
        const cleanedName = sanitizeUserInput(state.name || '陈守正');
        const safeActorName = (!cleanedName || cleanedName.includes('***')) ? '陈守正' : cleanedName;
        const arch = state.endgameArchetype || evaluateEndgameArchetype(state);
        const trackCfg = TRACK_CONFIGS[state.track || 'biz'];
        const trackTitle = (trackCfg && trackCfg.title) || '人间百态';

        oCtx.textAlign = 'left';
        oCtx.fillStyle = '#221D18';
        oCtx.font = 'bold 22px sans-serif';
        oCtx.fillText(safeActorName, 36, 78);

        oCtx.fillStyle = '#6D5B45';
        oCtx.font = '13px sans-serif';
        oCtx.fillText(`享年 ${state.age || 80} 岁 · 卒于 ${state.year || 2048} 年`, 36, 104);
        oCtx.fillText(`${trackTitle} · ${state.jobTitle || state.rankName || '退休名宿'}`, 36, 126);

        // 右上角朱红印泥评定勋章
        const grade = (arch && arch.grade) || 'B';
        const sealColors = {
          'S': { bg: '#A61B1B', border: '#D4AF37', text: '天赐 S' },
          'A': { bg: '#B83D24', border: '#E29E4B', text: '卓越 A' },
          'B': { bg: '#B36D25', border: '#D1A35B', text: '中坚 B' },
          'C': { bg: '#544F49', border: '#8A8275', text: '平淡 C' }
        };
        const sInfo = sealColors[grade] || sealColors['B'];
        oCtx.save();
        oCtx.fillStyle = sInfo.bg;
        oCtx.strokeStyle = sInfo.border;
        oCtx.lineWidth = 2;
        oCtx.beginPath();
        oCtx.arc(430, 88, 36, 0, Math.PI * 2);
        oCtx.fill();
        oCtx.stroke();
        oCtx.fillStyle = '#FFF8EB';
        oCtx.font = 'bold 16px sans-serif';
        oCtx.textAlign = 'center';
        oCtx.fillText(sInfo.text, 430, 93);
        oCtx.restore();

        // 中间终局评语底衬卡片
        oCtx.fillStyle = '#EFE6D5';
        oCtx.fillRect(36, 144, 428, 76);
        oCtx.strokeStyle = '#D1C2A5';
        oCtx.lineWidth = 1;
        oCtx.strokeRect(36, 144, 428, 76);

        oCtx.fillStyle = '#261B11';
        oCtx.font = 'bold 16px sans-serif';
        oCtx.textAlign = 'left';
        oCtx.fillText(`终局定位：${(arch && arch.title) || '平淡一生'}`, 50, 174);

        oCtx.fillStyle = '#5A4632';
        oCtx.font = '12px sans-serif';
        const ambitionStr = state.lifeAmbitionCompleted ? '终身宏愿已达成' : '宏愿未竞留余韵';
        const capStr = state.capital >= 10000 ? `${(state.capital / 10000).toFixed(1)}万` : `${Math.round(state.capital || 0)}元`;
        oCtx.fillText(`家资累积: ${capStr}  |  ${ambitionStr}  |  决断检定: ${state.decisionSuccessCount || 0}胜`, 50, 202);

        // 下部：命盘同台挑战区域
        const challengeSeed = (state && state.runSeed) || (typeof _initialGameSeed !== 'undefined' ? _initialGameSeed : (_gameSeed || 20260101));
        oCtx.fillStyle = '#E6DCB8';
        oCtx.fillRect(36, 236, 428, 88);
        oCtx.strokeStyle = '#C4A875';
        oCtx.lineWidth = 1.5;
        oCtx.strokeRect(36, 236, 428, 88);

        oCtx.fillStyle = '#6E2C00';
        oCtx.font = 'bold 14px sans-serif';
        oCtx.fillText(`🎯 同 种 子 命 盘 挑 战 码：#${challengeSeed}`, 50, 266);

        oCtx.fillStyle = '#524336';
        oCtx.font = '12px sans-serif';
        oCtx.fillText('身世、考运、时代风云与初始寿元均与此局完全一致', 50, 290);
        oCtx.fillText('同样的起点，换你来执子，能否逆天改命评得天赐S级？', 50, 310);

        // 底部防伪印记
        oCtx.fillStyle = '#A0907A';
        oCtx.font = '11px sans-serif';
        oCtx.textAlign = 'center';
        oCtx.fillText('· 浮生八十载 · 一纸功业录 · 微信小游戏 ·', 250, 354);

        if (typeof offCanvas.toTempFilePathSync === 'function') {
          return offCanvas.toTempFilePathSync({
            fileType: 'jpg',
            quality: 0.9
          });
        }
      }
    }

    // 降级截屏兜底
    if (typeof canvas !== 'undefined' && canvas && typeof canvas.toTempFilePathSync === 'function') {
      return canvas.toTempFilePathSync({
        x: 0,
        y: 0,
        width: screenWidth,
        height: Math.min(screenHeight, Math.round(screenWidth * 0.8)),
        destWidth: 500,
        destHeight: 400,
        fileType: 'jpg',
        quality: 0.88
      });
    }
  } catch (err) {
    logDebugError('generateShareCardImageUrl', err);
  }
  return '';
}

function shareEndgameCard() {
  try {
    const arch = state.endgameArchetype || evaluateEndgameArchetype(state);
    const cleanedName = sanitizeUserInput(state.name || '陈守正');
    const safeActorName = (!cleanedName || cleanedName.includes('***')) ? '陈守正' : cleanedName;
    const challengeSeed = (state && state.runSeed) || (typeof _initialGameSeed !== 'undefined' ? _initialGameSeed : (_gameSeed || 20260101));
    const shareTitle = `${safeActorName}活到了${state.age}岁，最终评定「${arch.title}」（${arch.grade}级）。换你走这一遭，会怎么选？#命盘${challengeSeed}`;
    const imageUrl = generateShareCardImageUrl();
    if (typeof wx !== 'undefined' && typeof wx.shareAppMessage === 'function') {
      const sharePayload = {
        title: shareTitle,
        query: `from=endgame_card&grade=${arch.grade}&seed=${challengeSeed}`
      };
      if (imageUrl) sharePayload.imageUrl = imageUrl;
      wx.shareAppMessage(sharePayload);
    }
    if (typeof reportGameMilestone === 'function') {
      reportGameMilestone('share_endgame_card', { grade: arch.grade, ending_id: arch.id, age: state.age, hasImage: !!imageUrl });
    }
    showToast("📤 生平小传已备好，可发给好友比比眼力", "gold");
  } catch (err) {
    logDebugError('shareEndgameCard', err);
  }
}

function watchRewardedVideoForInspiration(onComplete) {
  try {
    if (typeof onComplete !== 'function') {
      if ((state.rewardedAdWatchedThisRun || 0) >= WECHAT_MONETIZATION_CONFIG.maxAdTalentsPerRun) {
        showToast("📽️ 这一世的旧影已翻阅过了，留待后人再看吧", "info");
        return;
      }
      if ((state.heritageBonusTalents || 0) >= WECHAT_MONETIZATION_CONFIG.maxTotalHeritageTalents) {
        showToast("📽️ 家学底蕴已攒足五分，不必再添了", "gold");
        return;
      }
      const nowTs = Date.now();
      if (_lastRewardedAdTs > 0 && nowTs - _lastRewardedAdTs < WECHAT_MONETIZATION_CONFIG.adCooldownMs) {
        const waitSec = Math.ceil((WECHAT_MONETIZATION_CONFIG.adCooldownMs - (nowTs - _lastRewardedAdTs)) / 1000);
        showToast(`📽️ 往事尚在回味中，稍候 ${waitSec} 秒再翻阅吧`, "info");
        return;
      }
    }
    const grantAdInspiration = () => {
      if (typeof onComplete === 'function') {
        onComplete(true);
        return;
      }
      if ((state.rewardedAdWatchedThisRun || 0) >= WECHAT_MONETIZATION_CONFIG.maxAdTalentsPerRun) return;
      state.rewardedAdWatchedThisRun = (state.rewardedAdWatchedThisRun || 0) + 1;
      state.heritageBonusTalents = Math.min(
        WECHAT_MONETIZATION_CONFIG.maxTotalHeritageTalents,
        (state.heritageBonusTalents || 0) + 1
      );
      _lastRewardedAdTs = Date.now();
      saveGameState(true);
      if (typeof reportGameMilestone === 'function') {
        reportGameMilestone('rewarded_ad_completed', {
          bonusTalents: state.heritageBonusTalents,
          watchedThisRun: state.rewardedAdWatchedThisRun
        });
      }
      showToast("📽️ 翻阅旧影有所得，为后人留下一分家学底蕴（下局天赋+1）", "gold");
      requestRender();
    };

    if (isPlaceholderOrEmpty(WECHAT_MONETIZATION_CONFIG.adUnitId)) {
      console.warn('[LifeSim:Ad] 激励视频广告位ID尚未配置或仍为占位符，启动体验兜底发放。');
      grantAdInspiration();
      return;
    }

    const createAd = (typeof tt !== 'undefined' && typeof tt.createRewardedVideoAd === 'function')
      ? tt.createRewardedVideoAd.bind(tt)
      : ((typeof wx !== 'undefined' && typeof wx.createRewardedVideoAd === 'function') ? wx.createRewardedVideoAd.bind(wx) : null);

    if (createAd) {
      if (!_cachedRewardedVideoAd) {
        _cachedRewardedVideoAd = createAd({ adUnitId: WECHAT_MONETIZATION_CONFIG.adUnitId });
      }
      const videoAd = _cachedRewardedVideoAd;
      if (videoAd) {
        if (_cachedRewardedVideoAdCloseHandler && typeof videoAd.offClose === 'function') {
          videoAd.offClose(_cachedRewardedVideoAdCloseHandler);
        }
        _cachedRewardedVideoAdCloseHandler = (res) => {
          if (!res || res.isEnded) {
            grantAdInspiration();
          } else {
            showToast("📽️ 需完整观阅旧影方可领悟家学点化", "info");
          }
        };
        if (typeof videoAd.onClose === 'function') {
          videoAd.onClose(_cachedRewardedVideoAdCloseHandler);
        }
        if (typeof videoAd.show === 'function') {
          videoAd.show().catch(() => {
            if (typeof videoAd.load === 'function') {
              videoAd.load().then(() => videoAd.show()).catch((e) => {
                logDebugError('videoAd.show', e);
                grantAdInspiration();
              });
            } else {
              grantAdInspiration();
            }
          });
          return;
        }
      }
    }
    grantAdInspiration();
  } catch (err) {
    logDebugError('watchRewardedVideoForInspiration', err);
    if (typeof onComplete === 'function') onComplete(false);
  }
}

function watchAdForEmergencyMedical(onSuccess) {
  const maxEmergency = (typeof WECHAT_MONETIZATION_CONFIG !== 'undefined' && WECHAT_MONETIZATION_CONFIG.maxEmergencyMedicalPerRun) || 1;
  if ((state.emergencyMedicalUsedCount || 0) >= maxEmergency) {
    showToast("🌿 本世已蒙杏林名医悉心调摄过，顺其自然颐养晚晴即可", "info");
    return;
  }
  if (state.emergencyMedicalCooldownUntil && (state.year || 1990) < state.emergencyMedicalCooldownUntil) {
    showToast("🌿 药石调摄需循序渐进，当前尚在温养期中", "info");
    return;
  }
  try {
    const grantAdLife = () => {
      if (typeof onSuccess === 'function') onSuccess();
    };
    if (typeof wx !== 'undefined' && typeof wx.createRewardedVideoAd === 'function') {
      if (!_cachedRewardedVideoAd) {
        _cachedRewardedVideoAd = wx.createRewardedVideoAd({ adUnitId: WECHAT_MONETIZATION_CONFIG.adUnitId });
      }
      const videoAd = _cachedRewardedVideoAd;
      if (videoAd) {
        if (_cachedRewardedVideoAdCloseHandler && typeof videoAd.offClose === 'function') {
          videoAd.offClose(_cachedRewardedVideoAdCloseHandler);
        }
        _cachedRewardedVideoAdCloseHandler = (res) => {
          if (res && res.isEnded === true) {
            grantAdLife();
          } else {
            showToast("📽️ 需完整体会光影方得调摄心得", "info");
          }
        };
        if (typeof videoAd.onClose === 'function') {
          videoAd.onClose(_cachedRewardedVideoAdCloseHandler);
        }
        if (typeof videoAd.show === 'function') {
          videoAd.show().catch(() => {
            if (typeof videoAd.load === 'function') {
              videoAd.load().then(() => videoAd.show()).catch((e) => {
                logDebugError('videoAd.show', e);
                showToast("📽️ 杏林旧影载入未竟，请稍候再试", "info");
              });
            } else {
              showToast("📽️ 杏林旧影载入未竟，请稍候再试", "info");
            }
          });
          return;
        }
      }
    }
    showToast("📽️ 暂无可供翻阅的杏林旧影，请稍候再试", "info");
  } catch (err) {
    logDebugError('watchAdForEmergencyMedical', err);
    showToast("📽️ 翻阅旧影异常，请稍候再试", "info");
  }
}

// ==========================================
// 十二、 每日岁策与晨参吉运回流闭环系统 (Daily Solar Divination Retention Hook)
