let _serverTimeOffsetMs = 0;
let _hasSyncedServerTime = false;

function trySyncNetworkTime() {
  if (typeof wx !== 'undefined' && typeof wx.request === 'function') {
    try {
      wx.request({
        url: 'https://api.weixin.qq.com',
        method: 'HEAD',
        timeout: 3000,
        success: (res) => {
          if (res && res.header) {
            const dateStr = res.header['date'] || res.header['Date'];
            if (dateStr) {
              const serverTs = Date.parse(dateStr);
              if (!Number.isNaN(serverTs) && serverTs > 0) {
                _serverTimeOffsetMs = serverTs - Date.now();
                _hasSyncedServerTime = true;
                recordMaxObservedTime(serverTs);
              }
            }
          }
        },
        fail: () => {}
      });
    } catch (e) {}
  }
}

function recordMaxObservedTime(ts) {
  try {
    let oldMax = 0;
    if (typeof wx !== 'undefined' && typeof wx.getStorageSync === 'function') {
      oldMax = Number(wx.getStorageSync('lifesim_max_observed_time')) || 0;
      if (ts > oldMax) wx.setStorageSync('lifesim_max_observed_time', String(ts));
    } else if (typeof localStorage !== 'undefined') {
      oldMax = Number(localStorage.getItem('lifesim_max_observed_time')) || 0;
      if (ts > oldMax) localStorage.setItem('lifesim_max_observed_time', String(ts));
    }
  } catch (e) {}
}

function getEffectiveTimestampMs() {
  const now = Date.now() + _serverTimeOffsetMs;
  let maxTime = 0;
  try {
    if (typeof wx !== 'undefined' && typeof wx.getStorageSync === 'function') {
      maxTime = Number(wx.getStorageSync('lifesim_max_observed_time')) || 0;
    } else if (typeof localStorage !== 'undefined') {
      maxTime = Number(localStorage.getItem('lifesim_max_observed_time')) || 0;
    }
  } catch (e) {}
  const effective = Math.max(now, maxTime);
  recordMaxObservedTime(effective);
  return effective;
}

function getTodayDateString() {
  const ts = getEffectiveTimestampMs();
  const d = new Date(ts);
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

function getDailyDivinationForToday() {
  const todayStr = getTodayDateString();
  let hash = 0;
  for (let i = 0; i < todayStr.length; i++) {
    hash = ((hash << 5) - hash) + todayStr.charCodeAt(i);
    hash |= 0;
  }
  const idx = Math.abs(hash) % DAILY_DIVINATION_TABLE.length;
  return { ...DAILY_DIVINATION_TABLE[idx], date: todayStr };
}

function isDailyDivinationClaimedToday() {
  try {
    let claimed = '';
    if (typeof wx !== 'undefined' && typeof wx.getStorageSync === 'function') {
      claimed = wx.getStorageSync('daily_divination_claimed_date');
    } else if (typeof localStorage !== 'undefined') {
      claimed = localStorage.getItem('daily_divination_claimed_date');
    }
    return claimed === getTodayDateString();
  } catch (e) {
    return false;
  }
}

function claimDailyDivination() {
  const todayStr = getTodayDateString();
  const div = getDailyDivinationForToday();
  try {
    if (typeof wx !== 'undefined' && typeof wx.setStorageSync === 'function') {
      wx.setStorageSync('daily_divination_claimed_date', todayStr);
      wx.setStorageSync('daily_divination_active_blessing', JSON.stringify(div));
    } else if (typeof localStorage !== 'undefined') {
      localStorage.setItem('daily_divination_claimed_date', todayStr);
      localStorage.setItem('daily_divination_active_blessing', JSON.stringify(div));
    }
  } catch (e) {}

  state.dailyDivinationClaimed = true;
  state.activeDailyBlessing = div;

  // 临时增益通过 getStat 动态附加生效（当日有效，次日自然失效，杜绝污染底层永久属性）
  if (div.effects && typeof div.effects.capital === 'number') {
    state.capital = (state.capital || 0) + div.effects.capital;
  }
  if (div.pactGain && typeof progressThreeYearPact === 'function' && state.age >= 18) {
    progressThreeYearPact(div.pactGain, '今日岁策吉运');
  }

  playSoundEffect('fanfare');
  triggerHaptic('heavy');
  spawnInkWashBloom(screenWidth / 2, screenHeight / 2, 70, 'rgba(245, 158, 11, 0.4)');
  showToast(`🌅 研习今日岁策【${div.solar}·${div.title}】！${div.buffTitle}今日有效加持！`, 'gold');

  if (typeof wx !== 'undefined' && typeof wx.requestSubscribeMessage === 'function') {
    try {
      const tmplId = WECHAT_MONETIZATION_CONFIG.dailySubscribeTemplateId;
      if (tmplId) {
        wx.requestSubscribeMessage({
          tmplIds: [tmplId],
          complete: () => { requestRender(); }
        });
      }
    } catch (e) {}
  }
  saveGameState(true);
  requestRender();
}

function isStreamlinedModeEnabled() {
  if (typeof state !== 'undefined' && typeof state.isStreamlinedMode === 'boolean') {
    return state.isStreamlinedMode;
  }
  try {
    if (typeof wx !== 'undefined' && typeof wx.getStorageSync === 'function') {
      return wx.getStorageSync('lifesim_streamlined_mode') === 'true';
    } else if (typeof localStorage !== 'undefined') {
      return localStorage.getItem('lifesim_streamlined_mode') === 'true';
    }
  } catch (e) {}
  return false;
}

function setStreamlinedModeEnabled(enabled) {
  const val = !!enabled;
  if (typeof state !== 'undefined') {
    state.isStreamlinedMode = val;
  }
  try {
    if (typeof wx !== 'undefined' && typeof wx.setStorageSync === 'function') {
      wx.setStorageSync('lifesim_streamlined_mode', val ? 'true' : 'false');
    } else if (typeof localStorage !== 'undefined') {
      localStorage.setItem('lifesim_streamlined_mode', val ? 'true' : 'false');
    }
  } catch (e) {}
}

function openDailyDivinationModal() {
  state.activeModal = 'daily_divination';
  playSoundEffect('paper');
  triggerHaptic('medium');
  requestRender();
}

function drawDailyDivinationModal() {
  const div = getDailyDivinationForToday();
  const isClaimed = isDailyDivinationClaimedToday();
  const cardW = screenWidth - 28;
  const cardH = 370;
  const cardX = 14;
  const cardY = Math.max(16, Math.round((screenHeight - cardH) / 2));

  ctx.fillStyle = '#0f172a';
  roundRect(ctx, cardX, cardY, cardW, cardH, 10, true, true, '#f59e0b', 2);
  drawCornerOrnaments(ctx, cardX, cardY, cardW, cardH, 8, '#f59e0b');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 16px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText("🌅 岁 时 策 照 · 晨 参 吉 兆", screenWidth / 2, cardY + 16);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#94a3b8';
  ctx.fillText(`${div.date} · 岁令节律：【${div.solar}】`, screenWidth / 2, cardY + 38);

  const hexBoxY = cardY + 62;
  const hexBoxH = 100;
  ctx.fillStyle = '#1e293b';
  roundRect(ctx, cardX + 16, hexBoxY, cardW - 32, hexBoxH, 8, true, true, '#d97706', 1.2);

  ctx.font = 'bold 20px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText(`【 ${div.title} 】`, screenWidth / 2, hexBoxY + 14);

  ctx.font = '13.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#cbd5e1';
  const descLines = wrapTextLines(div.desc, cardW - 52, '13.5px ' + FONT_CHRONICLE);
  descLines.forEach((l, i) => {
    ctx.fillText(l, screenWidth / 2, hexBoxY + 44 + i * 18);
  });

  const bBoxY = hexBoxY + hexBoxH + 12;
  const bBoxH = 75;
  ctx.fillStyle = '#064e3b';
  roundRect(ctx, cardX + 16, bBoxY, cardW - 32, bBoxH, 6, true, true, '#059669', 1);

  ctx.textAlign = 'left';
  ctx.font = 'bold 14px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#a7f3d0';
  ctx.fillText(`【今日吉运·${div.buffTitle}】：`, cardX + 26, bBoxY + 12);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#ecfdf5';
  const effArr = [];
  if (div.effects) {
    const sMap = { courage: '担当魄力', iq: '大局智谋', eq: '人情练达', clean: '清廉操守', resilience: '抗逆心性', health: '体魄强健', rep: '行业声望' };
    for (const [k, v] of Object.entries(div.effects)) {
      if (k === 'capital') effArr.push(`起步资金+¥${v}`);
      else effArr.push(`${sMap[k] || k}+${v}`);
    }
  }
  if (div.pactGain) effArr.push(`履职建功+${div.pactGain}`);
  ctx.fillText(effArr.join(' ✦ '), cardX + 26, bBoxY + 34);

  ctx.font = '12px ' + FONT_UI;
  ctx.fillStyle = '#6ee7b7';
  ctx.fillText("※ 每日首次研习生效（当日有效临时光环，次日自动重置更新，不污染底层属性）。", cardX + 26, bBoxY + 54);

  const okBtnW = cardW - 64;
  const okBtnH = 38;
  const okBtnX = cardX + 32;
  const okBtnY = cardY + cardH - okBtnH - 16;

  drawTactileButton(ctx, {
    id: 'claim_daily_divination_btn',
    x: okBtnX,
    y: okBtnY,
    w: okBtnW,
    h: okBtnH,
    radius: 6,
    bg: isClaimed ? '#1e293b' : '#b45309',
    border: isClaimed ? '#475569' : '#f59e0b',
    borderWidth: 1.5,
    text: isClaimed ? "✓ 今日岁策已领受 · 笃行致远 ➔" : "🌅 领受今日吉策 · 携福启程 ➔",
    font: 'bold 14px ' + FONT_CHRONICLE,
    textColor: isClaimed ? '#94a3b8' : '#fef08a',
    priority: 100,
    onClick: () => {
      if (!isClaimed) {
        claimDailyDivination();
      }
      state.activeModal = null;
      playSoundEffect('stamp');
      requestRender();
    }
  });
}

