function drawChildhoodFastForwardPromptModal() {
  if (!ctx) return;
  const cardW = Math.min(340, screenWidth - 28);
  const cardH = 345;
  const cardX = (screenWidth - cardW) / 2;
  const cardY = Math.max(16, Math.round((screenHeight - cardH) / 2));
  const age = state._childhoodFastForwardAge || 6;
  const is6 = age === 6;

  ctx.save();
  ctx.fillStyle = '#1c1524';
  roundRect(ctx, cardX, cardY, cardW, cardH, 12, true, true, '#f59e0b', 2);
  drawCornerOrnaments(ctx, cardX, cardY, cardW, cardH, 8, '#f59e0b');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 16px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText(is6 ? "📜 发蒙入塾 · 岁月抉择" : "📜 少年立志 · 岁月抉择", cardX + cardW / 2, cardY + 16);

  ctx.font = '12.5px ' + FONT_UI;
  ctx.fillStyle = '#cbd5e1';
  const intro = is6
    ? "已满六岁发蒙启智。是否加速兼程，直奔成年大业？"
    : "十二岁立志入庠。是否加速兼程，直奔高考与大展宏图？";
  ctx.fillText(intro, cardX + cardW / 2, cardY + 42);

  // 选项对比卡片
  const boxW = cardW - 24;
  const boxH = 80;
  const boxX = cardX + 12;
  const box1Y = cardY + 68;

  // 卡片 1: 倍速求学
  ctx.fillStyle = 'rgba(180, 83, 9, 0.2)';
  roundRect(ctx, boxX, box1Y, boxW, boxH, 8, true, true, '#f59e0b', 1);
  ctx.textAlign = 'left';
  ctx.font = 'bold 13px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fde68a';
  ctx.fillText("⚡ 【倍速求学 · 直奔高考】", boxX + 10, box1Y + 10);
  ctx.font = '11.5px ' + FONT_UI;
  ctx.fillStyle = '#94a3b8';
  ctx.fillText("智能模拟补齐童年学业，以均衡素养直接步入18岁", boxX + 10, box1Y + 32);
  ctx.fillText("高考及社会履职，省去漫长前戏，即刻开启核心政商博弈。", boxX + 10, box1Y + 52);

  // 卡片 2: 慢品童年
  const box2Y = box1Y + boxH + 8;
  ctx.fillStyle = 'rgba(30, 41, 59, 0.4)';
  roundRect(ctx, boxX, box2Y, boxW, boxH, 8, true, true, '#475569', 1);
  ctx.textAlign = 'left';
  ctx.font = 'bold 13px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#93c5fd';
  ctx.fillText("📖 【慢品童年 · 逐年历练】", boxX + 10, box2Y + 10);
  ctx.font = '11.5px ' + FONT_UI;
  ctx.fillStyle = '#94a3b8';
  ctx.fillText("保留逐年掷骰、抓周抓阄、发小结交与少年分流，", boxX + 10, box2Y + 32);
  ctx.fillText("细品市井烟火与人情世故，稳扎稳打积累家底。", boxX + 10, box2Y + 52);

  // 操作按钮
  const btnH = 36;
  const btnY = cardY + cardH - btnH - 14;
  const btnW = Math.floor((cardW - 32) / 2);
  const leftX = cardX + 12;
  const rightX = leftX + btnW + 8;

  drawTactileButton(ctx, {
    id: 'childhood_fast_forward_btn',
    x: leftX,
    y: btnY,
    w: btnW,
    h: btnH,
    radius: 6,
    bg: '#b45309',
    border: '#f59e0b',
    borderWidth: 1.5,
    text: "⚡ 倍速求学 ➔",
    font: 'bold 13px ' + FONT_CHRONICLE,
    textColor: '#fef08a',
    priority: 100,
    onClick: () => {
      state.activeModal = null;
      if (typeof skipChildhoodToAdulthood === 'function') {
        skipChildhoodToAdulthood();
      }
    }
  });

  drawTactileButton(ctx, {
    id: 'childhood_continue_normal_btn',
    x: rightX,
    y: btnY,
    w: btnW,
    h: btnH,
    radius: 6,
    bg: '#1e293b',
    border: '#64748b',
    borderWidth: 1.2,
    text: "📖 慢品童年",
    font: 'bold 13px ' + FONT_UI,
    textColor: '#cbd5e1',
    priority: 100,
    onClick: () => {
      state.activeModal = null;
      showToast(is6 ? '📖 笃定心志，细细品味少年光阴。' : '📖 勤学苦读，笃行不怠。', 'info');
      saveGameState(true);
      requestRender();
    }
  });

  ctx.restore();
}

