    ctx.fillStyle = isInscribed ? '#1e1b2e' : '#0f172a';
    roundRect(ctx, startX + 14, iy, cardW - 28, itmH, 6, true, true, isInscribed ? '#f59e0b' : '#38bdf8', 0.8);

