// 🏺 V41 非遗金丝粒子对象池 (Heritage Filigree Particle Pool)
const HERITAGE_FILIGREE_PARTICLE_POOL = [];
function obtainFiligreeParticle(initFn) {
  let p = HERITAGE_FILIGREE_PARTICLE_POOL.pop();
  if (!p) p = {};
  p._poolType = 'filigree';
  if (initFn) initFn(p);
  return p;
}
function releaseFiligreeParticle(p) {
  if (p && HERITAGE_FILIGREE_PARTICLE_POOL.length < 150) {
    HERITAGE_FILIGREE_PARTICLE_POOL.push(p);
  }
}

function spawnHeritageFiligreeFX(cx, cy, count = 22) {
  const startX = cx || (screenWidth / 2);
  const startY = cy || (screenHeight / 2);
  for (let i = 0; i < count; i++) {
    const angle = (i / count) * Math.PI * 2;
    const p = obtainFiligreeParticle((obj) => {
      obj.x = startX;
      obj.y = startY;
      obj.dist = 12 + fxRandom() * 36;
      obj.angle = angle;
      obj.speed = 0.04 + fxRandom() * 0.05;
      obj.size = 2.2 + fxRandom() * 2.0;
      obj.alpha = 1.0;
      obj.color = ['#c084fc', '#e879f9', '#fbbf24', '#fef08a', '#ffffff'][i % 5];
      obj.rotSpeed = 0.03 + fxRandom() * 0.04;
    });
    goldConfettiList.push(p);
  }
}

function openIntangibleHeritageModal() {
  state.activeModal = 'intangible_heritage';
  playSoundEffect('xun_ancient_clay');
  triggerHaptic('medium');
  requestRender();
}

function appreciateHeritageCraft(craftId) {
  const craft = INTANGIBLE_HERITAGE_DATABASE.find(c => c.id === craftId);
  if (!craft) return;

  state.heritageCrafts = state.heritageCrafts || { studied: {}, totalCount: 0 };
  if (state.heritageCrafts.studied[craftId]) {
    showToast(`🏺 已精研掌握【${craft.name}】，百工心法早已融会贯通！`, 'info');
    return;
  }
  if (state.ap < (craft.costAp || 1)) {
    showToast('⚠️ 精力暂竭，稍作调养再潜心研习华夏百工绝艺！', 'gold');
    return;
  }
  if ((state.capital || 0) < craft.costMoney) {
    showToast('⚠️ 研习该项非遗百工绝艺所需拜师研学资费不足！', 'gold');
    return;
  }

  // 扣除消耗
  state.ap -= (craft.costAp || 1);
  state.capital = Math.max(0, (state.capital || 0) - craft.costMoney);
  progressThreeYearPact(12, `非遗研习·${craft.name}`);

  // 研习记录
  state.heritageCrafts.studied[craftId] = 1;
  state.heritageCrafts.totalCount += 1;

  // 生效收益
  if (craft.effects.resilience) addStat("resilience", Math.min(5, craft.effects.resilience), 50);
  if (craft.effects.courage) addStat("courage", Math.min(4, craft.effects.courage), 50);
  if (craft.effects.rep) addStat("rep", Math.min(5, craft.effects.rep), 50);
  if (craft.effects.iq) addStat("iq", Math.min(5, craft.effects.iq), 50);
  if (craft.effects.eq) addStat("eq", Math.min(5, craft.effects.eq), 50);
  if (craft.effects.san) state.san = Math.min(100, (state.san || 80) + craft.effects.san);
  if (craft.effects.sanbaoShen) state.sanbaoBonusShen = Math.min(25, (state.sanbaoBonusShen || 0) + craft.effects.sanbaoShen);
  if (craft.effects.sanbaoJing) state.sanbaoBonusJing = Math.min(25, (state.sanbaoBonusJing || 0) + craft.effects.sanbaoJing);
  if (craft.effects.apMaxBonus) {
    state.bonusMaxAp = Math.min(1, (state.bonusMaxAp || 0) + 1);
    state.maxAp = ((hasTalent('decisive') && state.age % 2 === 0) ? 4 : 3) + state.bonusMaxAp;
  }
  if (craft.effects.legacyScore && state.masterStudio) {
    state.masterStudio.legacyScore = (state.masterStudio.legacyScore || 60) + craft.effects.legacyScore;
  }
  if (craft.effects.clanCulture) {
    state.clanCultureScore = (state.clanCultureScore || 0) + craft.effects.clanCulture;
  }
  if (craft.effects.clanBizBonus) {
    state.clanBizBonus = (state.clanBizBonus || 0) + craft.effects.clanBizBonus;
  }

  playSoundEffect('sheng_reed_pipe');
  triggerHaptic('medium');
  spawnHeritageFiligreeFX(screenWidth / 2, screenHeight / 2, 28);
  spawnEraPulseWaveFX(screenWidth / 2, screenHeight / 2, '#a855f7');
  spawnFloatingRuneFX(`🏺 ${craft.name} · 文脉通达`, screenWidth / 2, screenHeight / 2 - 35, '#f5d0fe');
  showToast(`🏺【${craft.name}】精研入化！${craft.motto}`, 'purple');
  requestRender();
}

function drawIntangibleHeritageModal() {
  const cardW = Math.min(screenWidth - 24, 356);
  const cardH = 510;
  const startX = (screenWidth - cardW) / 2;
  const startY = (screenHeight - cardH) / 2;

  ctx.save();
  drawSilkScrollFrame(ctx, startX, startY, cardW, cardH, '#3b0764', '#a855f7');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';

  // 1. 标题栏
  ctx.font = 'bold 15px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#f3e8ff';
  ctx.fillText('🏺 天工非遗 · 华夏百工绝艺典藏阁', startX + cardW / 2, startY + 16);

  const studiedCount = state.heritageCrafts ? (state.heritageCrafts.totalCount || 0) : 0;
  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#d8b4fe';
  ctx.fillText(fitText(`非物质文化遗产 · 大国匠心文脉长存（已精研 ${studiedCount}/${INTANGIBLE_HERITAGE_DATABASE.length} 项绝艺）`, cardW - 24, '13.5px ' + FONT_UI), startX + cardW / 2, startY + 36);

  // 2. 五大非遗卡片列表 (展示前 3 项当期代表绝艺)
  const listY = startY + 56;
  const itmH = 104;
  const craftCount = Math.min(3, INTANGIBLE_HERITAGE_DATABASE.length);

  for (let idx = 0; idx < craftCount; idx++) {
    const craft = INTANGIBLE_HERITAGE_DATABASE[idx];
    const iy = listY + idx * (itmH + 6);
    const studyTimes = (state.heritageCrafts && state.heritageCrafts.studied && state.heritageCrafts.studied[craft.id]) || 0;

    ctx.fillStyle = '#1e0a38';
    roundRect(ctx, startX + 14, iy, cardW - 28, itmH, 6, true, true, studyTimes > 0 ? '#c084fc' : '#6b21a8', 0.8);

    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#fef08a';
    ctx.fillText(fitText(`${craft.icon} ${craft.name}`, cardW - 115, 'bold 14px ' + FONT_CHRONICLE), startX + 22, iy + 8);

    ctx.textAlign = 'right';
    ctx.font = '13.5px ' + FONT_UI;
    ctx.fillStyle = '#c084fc';
    ctx.fillText(craft.category, startX + cardW - 22, iy + 9);

    ctx.textAlign = 'left';
    ctx.font = '13.5px ' + FONT_UI;
    ctx.fillStyle = '#e9d5ff';
    ctx.fillText(fitText(`载体: ${craft.spec}`, cardW - 44, '13.5px ' + FONT_UI), startX + 22, iy + 26);

    ctx.fillStyle = '#cbd5e1';
    ctx.fillText(fitText(`功效: ${craft.desc}`, cardW - 44, '13.5px ' + FONT_UI), startX + 22, iy + 41);

    ctx.fillStyle = '#fde047';
    ctx.font = 'italic 13.5px ' + FONT_CHRONICLE;
    ctx.fillText(`“${craft.motto}”`, startX + 22, iy + 57);

    // 底部属性与操作按钮
    ctx.fillStyle = '#34d399';
    ctx.font = '13.5px ' + FONT_MONO;
    ctx.fillText(`消耗: 1精力 + ¥${craft.costMoney}  (已研${studyTimes}次)`, startX + 22, iy + 78);

    const btnW = 78;
    const btnH = 22;
    const btnX = startX + cardW - btnW - 20;
    const btnY = iy + 73;

    drawTactileButton(ctx, {
      id: 'appreciate_craft_' + craft.id,
      x: btnX,
      y: btnY,
      w: btnW,
      h: btnH,
      radius: 4,
      bg: '#581c87',
      border: '#c084fc',
      borderWidth: 1,
      font: 'bold 14px ' + FONT_UI,
      textColor: '#faf5ff',
      text: '心领神会 ➔',
      onClick: () => {
        appreciateHeritageCraft(craft.id);
      },
      priority: 45
    });
  }

  // 3. 底部关闭按钮
  const closeBtnW = cardW - 40;
  const closeBtnH = 34;
  const closeBtnX = startX + 20;
  const closeBtnY = startY + cardH - closeBtnH - 12;

  drawTactileButton(ctx, {
    id: 'close_intangible_heritage',
    x: closeBtnX,
    y: closeBtnY,
    w: closeBtnW,
    h: closeBtnH,
    radius: 6,
    bg: '#3b0764',
    border: '#a855f7',
    borderWidth: 1,
    font: 'bold 14px ' + FONT_UI,
    textColor: '#fff',
    text: '百工通达 · 文脉归心 ➔',
    onClick: () => {
      state.activeModal = null;
      playSoundEffect('click');
      requestRender();
    },
    priority: 60
  });

  ctx.restore();
}

