// 🏛️ V42 朱砂墨拓粒子对象池 (Cinnabar Rubbing Particle Pool)
const CINNABAR_RUBBING_PARTICLE_POOL = [];
function obtainRubbingParticle(initFn) {
  let p = CINNABAR_RUBBING_PARTICLE_POOL.pop();
  if (!p) p = {};
  p._poolType = 'rubbing';
  if (initFn) initFn(p);
  return p;
}
function releaseRubbingParticle(p) {
  if (p && CINNABAR_RUBBING_PARTICLE_POOL.length < 150) {
    CINNABAR_RUBBING_PARTICLE_POOL.push(p);
  }
}

function spawnCinnabarRubbingFX(cx, cy, count = 24) {
  const startX = cx || (screenWidth / 2);
  const startY = cy || (screenHeight / 2);
  for (let i = 0; i < count; i++) {
    const angle = (i / count) * Math.PI * 2;
    const p = obtainRubbingParticle((obj) => {
      obj.x = startX;
      obj.y = startY;
      obj.dist = 10 + fxRandom() * 38;
      obj.angle = angle;
      obj.speed = 0.05 + fxRandom() * 0.05;
      obj.size = 2.0 + fxRandom() * 2.2;
      obj.alpha = 1.0;
      obj.color = ['#ef4444', '#dc2626', '#f59e0b', '#fbbf24', '#ffffff'][i % 5];
      obj.rotSpeed = 0.02 + fxRandom() * 0.05;
    });
    goldConfettiList.push(p);
  }
}

function openBronzeEpigraphyModal() {
  state.activeModal = 'bronze_epigraphy';
  playSoundEffect('bronze_ding_chime');
  triggerHaptic('medium');
  requestRender();
}

function rubAndColophonEpigraphy(epigraphyId) {
  const ep = BRONZE_EPIGRAPHY_DATABASE.find(e => e.id === epigraphyId);
  if (!ep) return;

  state.epigraphyRubbings = state.epigraphyRubbings || { rubbed: {}, totalCount: 0 };
  if (state.epigraphyRubbings.rubbed[epigraphyId]) {
    showToast(`🏛️ 已精拓典藏【${ep.name}】，金石铭文早已烂熟于胸！`, 'info');
    return;
  }
  if (state.ap < (ep.costAp || 1)) {
    showToast('⚠️ 精力微耗，请稍事歇息再研磨朱砂拓制金石！', 'gold');
    return;
  }
  if ((state.capital || 0) < ep.costMoney) {
    showToast('⚠️ 购置徽墨特级宣纸与朱砂拓包资费不足！', 'gold');
    return;
  }

  // 扣除消耗
  state.ap -= (ep.costAp || 1);
  state.capital = Math.max(0, (state.capital || 0) - ep.costMoney);
  progressThreeYearPact(12, `金石传拓·${ep.name}`);

  // 记录题跋
  state.epigraphyRubbings.rubbed[epigraphyId] = 1;
  state.epigraphyRubbings.totalCount += 1;

  // 生效收益
  if (ep.effects.resilience) addStat("resilience", Math.min(5, ep.effects.resilience), 50);
  if (ep.effects.rep) addStat("rep", Math.min(5, ep.effects.rep), 50);
  if (ep.effects.iq) addStat("iq", Math.min(5, ep.effects.iq), 50);
  if (ep.effects.eq) addStat("eq", Math.min(5, ep.effects.eq), 50);
  if (ep.effects.clanLuck) state.clanLuckScore = (state.clanLuckScore || 0) + ep.effects.clanLuck;
  if (ep.effects.sanbaoShen) state.sanbaoBonusShen = Math.min(25, (state.sanbaoBonusShen || 0) + ep.effects.sanbaoShen);
  if (ep.effects.sanbaoQi) state.sanbaoBonusQi = Math.min(25, (state.sanbaoBonusQi || 0) + ep.effects.sanbaoQi);
  if (ep.effects.sanbaoJing) state.sanbaoBonusJing = Math.min(25, (state.sanbaoBonusJing || 0) + ep.effects.sanbaoJing);
  if (ep.effects.apMaxBonus) {
    state.bonusMaxAp = Math.min(1, (state.bonusMaxAp || 0) + 1);
    state.maxAp = ((hasTalent('decisive') && state.age % 2 === 0) ? 4 : 3) + state.bonusMaxAp;
  }
  if (ep.effects.legacyScore && state.masterStudio) {
    state.masterStudio.legacyScore = (state.masterStudio.legacyScore || 60) + ep.effects.legacyScore;
  }
  if (ep.effects.heirloomScore && state.familyHeirloom) {
    state.familyHeirloom.value = Math.floor((state.familyHeirloom.value || 10000) * 1.15);
  }

  playSoundEffect('rubbing_pad_tap');
  triggerHaptic('heavy');
  spawnCinnabarRubbingFX(screenWidth / 2, screenHeight / 2, 28);
  spawnEraPulseWaveFX(screenWidth / 2, screenHeight / 2, '#ca8a04');
  spawnFloatingRuneFX(`🏛️ ${ep.name} · 墨拓题跋`, screenWidth / 2, screenHeight / 2 - 35, '#fef08a');
  showToast(`🏛️【${ep.name}】精拓圆成！“${ep.inscription}”`, 'gold');
  requestRender();
}

function drawBronzeEpigraphyModal() {
  const cardW = Math.min(screenWidth - 24, 356);
  const cardH = 510;
  const startX = (screenWidth - cardW) / 2;
  const startY = (screenHeight - cardH) / 2;

  ctx.save();
  drawSilkScrollFrame(ctx, startX, startY, cardW, cardH, '#1c1917', '#ca8a04');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';

  // 1. 标题栏
  ctx.font = 'bold 15px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText('🏛️ 神州金石 · 传世青铜鼎彝碑拓宝斋', startX + cardW / 2, startY + 16);

  const totalRubbed = state.epigraphyRubbings ? (state.epigraphyRubbings.totalCount || 0) : 0;
  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#fde047';
  ctx.fillText(`金石千秋 · 鼎彝吉金名拓垂范（已题跋 ${totalRubbed}/${BRONZE_EPIGRAPHY_DATABASE.length} 项金石）`, startX + cardW / 2, startY + 36);

  // 2. 五大金石宝器列表 (展示前 3 项当期代表金石)
  const listY = startY + 56;
  const itmH = 104;
  const epCount = Math.min(3, BRONZE_EPIGRAPHY_DATABASE.length);

  for (let idx = 0; idx < epCount; idx++) {
    const ep = BRONZE_EPIGRAPHY_DATABASE[idx];
    const iy = listY + idx * (itmH + 6);
    const rubCount = (state.epigraphyRubbings && state.epigraphyRubbings.rubbed && state.epigraphyRubbings.rubbed[ep.id]) || 0;

    ctx.fillStyle = '#181206';
    roundRect(ctx, startX + 14, iy, cardW - 28, itmH, 6, true, true, rubCount > 0 ? '#ca8a04' : '#854d0e', 0.8);

    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#fef08a';
    ctx.fillText(`${ep.icon} ${ep.name}`, startX + 22, iy + 8);

    ctx.textAlign = 'right';
    ctx.font = '13.5px ' + FONT_UI;
    ctx.fillStyle = '#facc15';
    ctx.fillText(ep.dynasty, startX + cardW - 22, iy + 9);

    ctx.textAlign = 'left';
    ctx.font = '13.5px ' + FONT_UI;
    ctx.fillStyle = '#fef9c3';
    ctx.fillText(fitText(`铭文: ${ep.inscription}`, cardW - 44, '13.5px ' + FONT_UI), startX + 22, iy + 26);

    ctx.fillStyle = '#cbd5e1';
    ctx.fillText(fitText(`载体: ${ep.spec}`, cardW - 44, '13.5px ' + FONT_UI), startX + 22, iy + 41);

    ctx.fillStyle = '#86efac';
    ctx.font = '13.5px ' + FONT_UI;
    ctx.fillText(fitText(`功用: ${ep.desc}`, cardW - 44, '13.5px ' + FONT_UI), startX + 22, iy + 57);

    // 底部属性与操作按钮
    ctx.fillStyle = '#34d399';
    ctx.font = '13.5px ' + FONT_MONO;
    ctx.fillText(`消耗: 1精力 + ¥${ep.costMoney}  (已拓${rubCount}次)`, startX + 22, iy + 78);

    const btnW = 78;
    const btnH = 22;
    const btnX = startX + cardW - btnW - 20;
    const btnY = iy + 73;

    drawTactileButton(ctx, {
      id: 'rub_epigraphy_' + ep.id,
      x: btnX,
      y: btnY,
      w: btnW,
      h: btnH,
      radius: 4,
      bg: '#854d0e',
      border: '#facc15',
      borderWidth: 1,
      font: 'bold 14px ' + FONT_UI,
      textColor: '#fffbeb',
      text: '墨拓题跋 ➔',
      onClick: () => {
        rubAndColophonEpigraphy(ep.id);
      },
      priority: 45
    });
  }

  // 3. 底部关闭按钮
  const closeBtnW = cardW - 40;
  const closeBtnH = 34;
  const closeBtnX = startX + 20;
  const closeBtnY = startY + cardH - closeBtnH - 12;

  drawTactileButton(ctx, {
    id: 'close_bronze_epigraphy',
    x: closeBtnX,
    y: closeBtnY,
    w: closeBtnW,
    h: closeBtnH,
    radius: 6,
    bg: '#292524',
    border: '#ca8a04',
    borderWidth: 1,
    font: 'bold 14px ' + FONT_UI,
    textColor: '#fef08a',
    text: '金石长存 · 鼎彝垂范 ➔',
    onClick: () => {
      state.activeModal = null;
      playSoundEffect('click');
      requestRender();
    },
    priority: 60
  });

  ctx.restore();
}

