// 🏺 V43 天青冰裂纹流光粒子对象池 (Celadon Glaze Particle Pool)
const CELADON_GLAZE_PARTICLE_POOL = [];
function obtainCeladonParticle(initFn) {
  let p = CELADON_GLAZE_PARTICLE_POOL.pop();
  if (!p) p = {};
  p._poolType = 'celadon';
  if (initFn) initFn(p);
  return p;
}
function releaseCeladonParticle(p) {
  if (p && CELADON_GLAZE_PARTICLE_POOL.length < 150) {
    CELADON_GLAZE_PARTICLE_POOL.push(p);
  }
}

function spawnCeladonGlazeFX(cx, cy, count = 24) {
  const startX = cx || (screenWidth / 2);
  const startY = cy || (screenHeight / 2);
  for (let i = 0; i < count; i++) {
    const angle = (i / count) * Math.PI * 2;
    const p = obtainCeladonParticle((obj) => {
      obj.x = startX;
      obj.y = startY;
      obj.dist = 12 + fxRandom() * 42;
      obj.angle = angle;
      obj.speed = 0.04 + fxRandom() * 0.05;
      obj.size = 2.0 + fxRandom() * 2.5;
      obj.alpha = 1.0;
      obj.color = ['#5eead4', '#2dd4bf', '#0d9488', '#f0fdfa', '#e0e7ff'][i % 5];
      obj.rotSpeed = 0.02 + fxRandom() * 0.04;
    });
    goldConfettiList.push(p);
  }
}

function openFamousKilnModal() {
  state.activeModal = 'famous_kiln';
  playSoundEffect('porcelain_ping_resonance');
  triggerHaptic('medium');
  requestRender();
}

function appreciateKilnPorcelain(porcelainId) {
  const pItem = FAMOUS_KILN_PORCELAIN_DATABASE.find(p => p.id === porcelainId);
  if (!pItem) return;

  state.kilnPorcelains = state.kilnPorcelains || { appreciated: {}, totalCount: 0 };
  if (state.kilnPorcelains.appreciated[porcelainId]) {
    showToast(`🏺 已雅鉴收藏【${pItem.name}】，名瓷神韵长伴案头！`, 'info');
    return;
  }
  if (state.ap < (pItem.costAp || 1)) {
    showToast('⚠️ 精力暂歇，请稍作调养后再静心品鉴名窑瓷韵！', 'gold');
    return;
  }
  if ((state.capital || 0) < pItem.costMoney) {
    showToast('⚠️ 购置传世名瓷鉴赏专刊与修内司茶资不足！', 'gold');
    return;
  }

  state.ap -= (pItem.costAp || 1);
  state.capital = Math.max(0, (state.capital || 0) - pItem.costMoney);
  progressThreeYearPact(12, `名窑雅鉴·${pItem.name}`);

  state.kilnPorcelains.appreciated[porcelainId] = 1;
  state.kilnPorcelains.totalCount += 1;

  // 生效收益
  if (pItem.effects.resilience) addStat("resilience", Math.min(5, pItem.effects.resilience), 50);
  if (pItem.effects.rep) addStat("rep", Math.min(5, pItem.effects.rep), 50);
  if (pItem.effects.iq) addStat("iq", Math.min(5, pItem.effects.iq), 50);
  if (pItem.effects.eq) addStat("eq", Math.min(5, pItem.effects.eq), 50);
  if (pItem.effects.clanLuck) state.clanLuckScore = (state.clanLuckScore || 0) + pItem.effects.clanLuck;
  if (pItem.effects.clanBizBonus) state.clanBizBonus = (state.clanBizBonus || 0) + pItem.effects.clanBizBonus;
  if (pItem.effects.sanbaoShen) state.sanbaoBonusShen = Math.min(25, (state.sanbaoBonusShen || 0) + pItem.effects.sanbaoShen);
  if (pItem.effects.sanbaoQi) state.sanbaoBonusQi = Math.min(25, (state.sanbaoBonusQi || 0) + pItem.effects.sanbaoQi);
  if (pItem.effects.sanbaoJing) state.sanbaoBonusJing = Math.min(25, (state.sanbaoBonusJing || 0) + pItem.effects.sanbaoJing);
  if (pItem.effects.apMaxBonus) {
    state.bonusMaxAp = Math.min(1, (state.bonusMaxAp || 0) + 1);
    state.maxAp = ((hasTalent('decisive') && state.age % 2 === 0) ? 4 : 3) + state.bonusMaxAp;
  }
  if (pItem.effects.legacyScore && state.masterStudio) {
    state.masterStudio.legacyScore = (state.masterStudio.legacyScore || 60) + pItem.effects.legacyScore;
  }
  if (pItem.effects.heirloomScore && state.familyHeirloom) {
    state.familyHeirloom.value = Math.floor((state.familyHeirloom.value || 10000) * 1.15);
  }

  playSoundEffect('tea_water_pour');
  triggerHaptic('medium');
  spawnCeladonGlazeFX(screenWidth / 2, screenHeight / 2, 28);
  spawnEraPulseWaveFX(screenWidth / 2, screenHeight / 2, '#0d9488');
  spawnFloatingRuneFX(`🏺 ${pItem.name} · 瓷韵心印`, screenWidth / 2, screenHeight / 2 - 35, '#5eead4');
  showToast(`🏺【${pItem.name}】品鉴大成！“${pItem.appreciation}”`, 'cyan');
  requestRender();
}

