// 🍵 V44 茶香云岫青雾粒子对象池 (Tea Aroma Mist Particle Pool)
const TEA_AROMA_MIST_PARTICLE_POOL = [];
function obtainTeaMistParticle(initFn) {
  let p = TEA_AROMA_MIST_PARTICLE_POOL.pop();
  if (!p) p = {};
  p._poolType = 'teamist';
  if (initFn) initFn(p);
  return p;
}
function releaseTeaMistParticle(p) {
  if (p && TEA_AROMA_MIST_PARTICLE_POOL.length < 150) {
    TEA_AROMA_MIST_PARTICLE_POOL.push(p);
  }
}

function spawnTeaAromaMistFX(cx, cy, count = 24) {
  const startX = cx || (screenWidth / 2);
  const startY = cy || (screenHeight / 2);
  for (let i = 0; i < count; i++) {
    const angle = (i / count) * Math.PI * 2;
    const p = obtainTeaMistParticle((obj) => {
      obj.x = startX;
      obj.y = startY;
      obj.dist = 10 + fxRandom() * 40;
      obj.angle = angle;
      obj.speed = 0.03 + fxRandom() * 0.04;
      obj.size = 2.2 + fxRandom() * 2.8;
      obj.alpha = 1.0;
      obj.color = ['#34d399', '#10b981', '#059669', '#a7f3d0', '#ecfdf5'][i % 5];
      obj.rotSpeed = 0.02 + fxRandom() * 0.03;
    });
    goldConfettiList.push(p);
  }
}

function openMasterTeaWayModal() {
  state.activeModal = 'master_tea_way';
  playSoundEffect('bamboo_dipper_water_clack');
  triggerHaptic('medium');
  requestRender();
}

function brewMasterTea(teaId) {
  const tea = MASTER_TEA_WAY_DATABASE.find(t => t.id === teaId);
  if (!tea) return;

  state.teaWayRecords = state.teaWayRecords || { brewed: {}, totalCount: 0 };
  if (state.teaWayRecords.brewed[teaId]) {
    showToast(`🍵 已品鉴参悟【${tea.name}】，七碗茶道余韵长存！`, 'info');
    return;
  }
  if (state.ap < (tea.costAp || 1)) {
    showToast('⚠️ 精力暂歇，请稍作静卧再品茗参禅！', 'gold');
    return;
  }
  if ((state.capital || 0) < tea.costMoney) {
    showToast('⚠️ 购置高山特级泉水与极品头春茶资不足！', 'gold');
    return;
  }

  state.ap -= (tea.costAp || 1);
  state.capital = Math.max(0, (state.capital || 0) - tea.costMoney);
  progressThreeYearPact(12, `茶圣试茗·${tea.name}`);

  state.teaWayRecords.brewed[teaId] = 1;
  state.teaWayRecords.totalCount += 1;

  // 生效收益
  if (tea.effects.resilience) addStat("resilience", Math.min(5, tea.effects.resilience), 50);
  if (tea.effects.rep) addStat("rep", Math.min(5, tea.effects.rep), 50);
  if (tea.effects.iq) addStat("iq", Math.min(5, tea.effects.iq), 50);
  if (tea.effects.eq) addStat("eq", Math.min(5, tea.effects.eq), 50);
  if (tea.effects.clanLuck) state.clanLuckScore = (state.clanLuckScore || 0) + tea.effects.clanLuck;
  if (tea.effects.health) addStat("health", Math.min(6, tea.effects.health), 80);
  if (tea.effects.sanbaoShen) state.sanbaoBonusShen = Math.min(25, (state.sanbaoBonusShen || 0) + tea.effects.sanbaoShen);
  if (tea.effects.sanbaoQi) state.sanbaoBonusQi = Math.min(25, (state.sanbaoBonusQi || 0) + tea.effects.sanbaoQi);
  if (tea.effects.sanbaoJing) state.sanbaoBonusJing = Math.min(25, (state.sanbaoBonusJing || 0) + tea.effects.sanbaoJing);
  if (tea.effects.apMaxBonus) {
    state.bonusMaxAp = Math.min(1, (state.bonusMaxAp || 0) + 1);
    state.maxAp = ((hasTalent('decisive') && state.age % 2 === 0) ? 4 : 3) + state.bonusMaxAp;
  }
  if (tea.effects.lifespanCeilingBonus) {
    state.lifespanCeiling = Math.min(98, (state.lifespanCeiling || 76) + tea.effects.lifespanCeilingBonus);
  }
  if (tea.effects.legacyScore && state.masterStudio) {
    state.masterStudio.legacyScore = (state.masterStudio.legacyScore || 60) + tea.effects.legacyScore;
  }
  if (tea.effects.heirloomScore && state.familyHeirloom) {
    state.familyHeirloom.value = Math.floor((state.familyHeirloom.value || 10000) * 1.15);
  }

  playSoundEffect('wind_in_pines_tea_kettle');
  triggerHaptic('medium');
  spawnTeaAromaMistFX(screenWidth / 2, screenHeight / 2, 28);
  spawnEraPulseWaveFX(screenWidth / 2, screenHeight / 2, '#059669');
  spawnFloatingRuneFX(`🍵 ${tea.name} · 七碗清风`, screenWidth / 2, screenHeight / 2 - 35, '#a7f3d0');
  showToast(`🍵【${tea.name}】烹试圆满！“${tea.motto}”`, 'green');
  requestRender();
}

function drawMasterTeaWayModal() {
  const cardW = Math.min(screenWidth - 24, 356);
  const cardH = 510;
  const startX = (screenWidth - cardW) / 2;
  const startY = (screenHeight - cardH) / 2;

  ctx.save();
  drawSilkScrollFrame(ctx, startX, startY, cardW, cardH, '#064e3b', '#059669');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';

  // 1. 标题栏
  ctx.font = 'bold 15px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#ecfdf5';
  ctx.fillText('🍵 传世茶圣 · 茗经七碗清风阁', startX + cardW / 2, startY + 16);

  const totalBrewed = state.teaWayRecords ? (state.teaWayRecords.totalCount || 0) : 0;
  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#6ee7b7';
  ctx.fillText(fitText(`茶禅一味 · 汲泉煮茗两腋生风（已品试 ${totalBrewed}/${MASTER_TEA_WAY_DATABASE.length} 种名茶）`, cardW - 24, '13.5px ' + FONT_UI), startX + cardW / 2, startY + 36);

  // 2. 名茶列表 (展示前 3 项当期代表名茶)
  const listY = startY + 56;
  const itmH = 104;
  const teaCount = Math.min(3, MASTER_TEA_WAY_DATABASE.length);

  for (let idx = 0; idx < teaCount; idx++) {
    const tea = MASTER_TEA_WAY_DATABASE[idx];
    const iy = listY + idx * (itmH + 6);
    const count = (state.teaWayRecords && state.teaWayRecords.brewed && state.teaWayRecords.brewed[tea.id]) || 0;

    ctx.fillStyle = '#062d24';
    roundRect(ctx, startX + 14, iy, cardW - 28, itmH, 6, true, true, count > 0 ? '#059669' : '#047857', 0.8);

    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#ecfdf5';
    ctx.fillText(fitText(`${tea.icon} ${tea.name}`, cardW - 140, 'bold 14px ' + FONT_CHRONICLE), startX + 22, iy + 8);

    ctx.textAlign = 'right';
    ctx.font = '13.5px ' + FONT_UI;
    ctx.fillStyle = '#34d399';
    ctx.fillText(tea.category, startX + cardW - 22, iy + 9);

    ctx.textAlign = 'left';
    ctx.font = '13.5px ' + FONT_UI;
    ctx.fillStyle = '#a7f3d0';
    ctx.fillText(fitText(`茶韵: ${tea.motto}`, cardW - 44, '13.5px ' + FONT_UI), startX + 22, iy + 26);

    ctx.fillStyle = '#6ee7b7';
    ctx.fillText(fitText(`品级: ${tea.spec}`, cardW - 44, '13.5px ' + FONT_UI), startX + 22, iy + 41);

    ctx.fillStyle = '#fef08a';
    ctx.font = '13.5px ' + FONT_UI;
    ctx.fillText(fitText(`功用: ${tea.desc}`, cardW - 44, '13.5px ' + FONT_UI), startX + 22, iy + 57);

    // 底部属性与操作按钮
    ctx.fillStyle = '#6ee7b7';
    ctx.font = '13.5px ' + FONT_MONO;
    ctx.fillText(`消耗: 1精力 + ¥${tea.costMoney}  (已烹${count}次)`, startX + 22, iy + 78);

    const btnW = 78;
    const btnH = 22;
    const btnX = startX + cardW - btnW - 20;
    const btnY = iy + 73;

    drawTactileButton(ctx, {
      id: 'brew_tea_' + tea.id,
      x: btnX,
      y: btnY,
      w: btnW,
      h: btnH,
      radius: 4,
      bg: '#047857',
      border: '#34d399',
      borderWidth: 1,
      font: 'bold 14px ' + FONT_UI,
      textColor: '#ecfdf5',
      text: '烹泉试茗 ➔',
      onClick: () => {
        brewMasterTea(tea.id);
      },
      priority: 45
    });
  }

  // 3. 底部关闭按钮
  const closeBtnW = cardW - 40;
  const closeBtnH = 34;
  const closeBtnX = startX + 20;
  const closeBtnY = startY + cardH - closeBtnH - 12;

  drawTactileButton(ctx, {
    id: 'close_master_tea_way',
    x: closeBtnX,
    y: closeBtnY,
    w: closeBtnW,
    h: closeBtnH,
    radius: 6,
    bg: '#065f46',
    border: '#10b981',
    borderWidth: 1,
    font: 'bold 14px ' + FONT_UI,
    textColor: '#ecfdf5',
    text: '松风初定 · 两腋清风 ➔',
    onClick: () => {
      state.activeModal = null;
      playSoundEffect('click');
      requestRender();
    },
    priority: 60
  });

  ctx.restore();
}

