// 🧵 V45 七彩霓裳织锦丝光粒子对象池 (Brocade Silk Particle Pool)
const BROCADE_SILK_PARTICLE_POOL = [];
function obtainBrocadeParticle(initFn) {
  let p = BROCADE_SILK_PARTICLE_POOL.pop();
  if (!p) p = {};
  p._poolType = 'brocade';
  if (initFn) initFn(p);
  return p;
}
function releaseBrocadeParticle(p) {
  if (p && BROCADE_SILK_PARTICLE_POOL.length < 150) {
    BROCADE_SILK_PARTICLE_POOL.push(p);
  }
}

function spawnBrocadeSilkFX(cx, cy, count = 24) {
  const startX = cx || (screenWidth / 2);
  const startY = cy || (screenHeight / 2);
  for (let i = 0; i < count; i++) {
    const angle = (i / count) * Math.PI * 2;
    const p = obtainBrocadeParticle((obj) => {
      obj.x = startX;
      obj.y = startY;
      obj.dist = 12 + fxRandom() * 42;
      obj.angle = angle;
      obj.speed = 0.04 + fxRandom() * 0.04;
      obj.size = 2.2 + fxRandom() * 2.6;
      obj.alpha = 1.0;
      obj.color = ['#fbbf24', '#f59e0b', '#dc2626', '#b91c1c', '#fef08a'][i % 5];
      obj.rotSpeed = 0.03 + fxRandom() * 0.03;
    });
    goldConfettiList.push(p);
  }
}

function openMasterBrocadeModal() {
  state.activeModal = 'master_brocade';
  playSoundEffect('wooden_shuttle_loom_clack');
  triggerHaptic('medium');
  requestRender();
}

function weaveAndAppreciateBrocade(brocadeId) {
  const bro = MASTER_BROCADE_HERITAGE_DATABASE.find(b => b.id === brocadeId);
  if (!bro) return;

  state.brocadeRecords = state.brocadeRecords || { woven: {}, totalCount: 0 };
  if (state.brocadeRecords.woven[brocadeId]) {
    showToast(`🧵 已妆花典藏【${bro.name}】，寸锦寸金流光长耀！`, 'info');
    return;
  }
  if (state.ap < (bro.costAp || 1)) {
    showToast('⚠️ 精力暂竭，请稍事休整后再投梭织锦！', 'gold');
    return;
  }
  if ((state.capital || 0) < bro.costMoney) {
    showToast('⚠️ 购置高纯度真金丝与天然蚕丝孔雀羽资费不足！', 'gold');
    return;
  }

  state.ap -= (bro.costAp || 1);
  state.capital = Math.max(0, (state.capital || 0) - bro.costMoney);
  progressThreeYearPact(12, `锦绣妆花·${bro.name}`);

  state.brocadeRecords.woven[brocadeId] = 1;
  state.brocadeRecords.totalCount += 1;

  // 生效收益
  if (bro.effects.resilience) addStat("resilience", Math.min(5, bro.effects.resilience), 50);
  if (bro.effects.rep) addStat("rep", Math.min(5, bro.effects.rep), 50);
  if (bro.effects.iq) addStat("iq", Math.min(5, bro.effects.iq), 50);
  if (bro.effects.eq) addStat("eq", Math.min(5, bro.effects.eq), 50);
  if (bro.effects.clanLuck) state.clanLuckScore = (state.clanLuckScore || 0) + bro.effects.clanLuck;
  if (bro.effects.health) addStat("health", Math.min(6, bro.effects.health), 80);
  if (bro.effects.sanbaoShen) state.sanbaoBonusShen = Math.min(25, (state.sanbaoBonusShen || 0) + bro.effects.sanbaoShen);
  if (bro.effects.sanbaoQi) state.sanbaoBonusQi = Math.min(25, (state.sanbaoBonusQi || 0) + bro.effects.sanbaoQi);
  if (bro.effects.sanbaoJing) state.sanbaoBonusJing = Math.min(25, (state.sanbaoBonusJing || 0) + bro.effects.sanbaoJing);
  if (bro.effects.apMaxBonus) {
    state.bonusMaxAp = Math.min(1, (state.bonusMaxAp || 0) + 1);
    state.maxAp = ((hasTalent('decisive') && state.age % 2 === 0) ? 4 : 3) + state.bonusMaxAp;
  }
  if (bro.effects.legacyScore && state.masterStudio) {
    state.masterStudio.legacyScore = (state.masterStudio.legacyScore || 60) + bro.effects.legacyScore;
  }
  if (bro.effects.heirloomScore && state.familyHeirloom) {
    state.familyHeirloom.value = Math.floor((state.familyHeirloom.value || 10000) * 1.15);
  }

  playSoundEffect('silk_thread_shimmer');
  triggerHaptic('medium');
  spawnBrocadeSilkFX(screenWidth / 2, screenHeight / 2, 28);
  spawnEraPulseWaveFX(screenWidth / 2, screenHeight / 2, '#b91c1c');
  spawnFloatingRuneFX(`🧵 ${bro.name} · 锦绣华章`, screenWidth / 2, screenHeight / 2 - 35, '#fbbf24');
  showToast(`🧵【${bro.name}】妆花织就！“${bro.motto}”`, 'gold');
  requestRender();
}

