// 🎶 V46 高山流水琴韵粒子对象池 (Guqin Soundwave Particle Pool)
const GUQIN_SOUNDWAVE_PARTICLE_POOL = [];
function obtainGuqinParticle(initFn) {
  let p = GUQIN_SOUNDWAVE_PARTICLE_POOL.pop();
  if (!p) p = {};
  p._poolType = 'guqin';
  if (initFn) initFn(p);
  return p;
}
function releaseGuqinParticle(p) {
  if (p && GUQIN_SOUNDWAVE_PARTICLE_POOL.length < 150) {
    GUQIN_SOUNDWAVE_PARTICLE_POOL.push(p);
  }
}

function spawnGuqinSoundwaveFX(cx, cy, count = 24) {
  const startX = cx || (screenWidth / 2);
  const startY = cy || (screenHeight / 2);
  for (let i = 0; i < count; i++) {
    const angle = (i / count) * Math.PI * 2;
    const p = obtainGuqinParticle((obj) => {
      obj.x = startX;
      obj.y = startY;
      obj.dist = 14 + fxRandom() * 45;
      obj.angle = angle;
      obj.speed = 0.035 + fxRandom() * 0.035;
      obj.size = 2.0 + fxRandom() * 2.5;
      obj.alpha = 1.0;
      obj.color = ['#f59e0b', '#fbbf24', '#d97706', '#92400e', '#fef08a'][i % 5];
      obj.rotSpeed = 0.02 + fxRandom() * 0.03;
    });
    goldConfettiList.push(p);
  }
}

function openMasterGuqinModal() {
  state.activeModal = 'master_guqin';
  playSoundEffect('guqin_plucked_harmonics');
  triggerHaptic('medium');
  requestRender();
}

function playAndAppreciateGuqin(qinId) {
  const qin = MASTER_GUQIN_HERITAGE_DATABASE.find(q => q.id === qinId);
  if (!qin) return;

  state.guqinRecords = state.guqinRecords || { played: {}, totalCount: 0 };
  if (state.guqinRecords.played[qinId]) {
    showToast(`🎵 已雅抚参悟【${qin.name}】，大圣遗音长留心间！`, 'info');
    return;
  }
  if (state.ap < (qin.costAp || 1)) {
    showToast('⚠️ 精力暂竭，请稍事休整后再调弦雅奏！', 'gold');
    return;
  }
  if ((state.capital || 0) < qin.costMoney) {
    showToast('⚠️ 备置上等岳山雁足与特制丝弦资费不足！', 'gold');
    return;
  }

  state.ap -= (qin.costAp || 1);
  state.capital = Math.max(0, (state.capital || 0) - qin.costMoney);
  progressThreeYearPact(12, `名琴雅抚·${qin.name}`);

  state.guqinRecords.played[qinId] = 1;
  state.guqinRecords.totalCount += 1;

  // 生效收益
  if (qin.effects.resilience) addStat("resilience", Math.min(5, qin.effects.resilience), 50);
  if (qin.effects.rep) addStat("rep", Math.min(5, qin.effects.rep), 50);
  if (qin.effects.iq) addStat("iq", Math.min(5, qin.effects.iq), 50);
  if (qin.effects.eq) addStat("eq", Math.min(5, qin.effects.eq), 50);
  if (qin.effects.clanTalentSuccessRate) state.clanTalentSuccessRate = Math.min(0.95, (state.clanTalentSuccessRate || 0.6) + qin.effects.clanTalentSuccessRate);
  if (qin.effects.health) addStat("health", Math.min(6, qin.effects.health), 80);
  if (qin.effects.sanbaoShen) state.sanbaoBonusShen = Math.min(25, (state.sanbaoBonusShen || 0) + qin.effects.sanbaoShen);
  if (qin.effects.sanbaoQi) state.sanbaoBonusQi = Math.min(25, (state.sanbaoBonusQi || 0) + qin.effects.sanbaoQi);
  if (qin.effects.sanbaoJing) state.sanbaoBonusJing = Math.min(25, (state.sanbaoBonusJing || 0) + qin.effects.sanbaoJing);
  if (qin.effects.apMaxBonus) {
    state.bonusMaxAp = Math.min(1, (state.bonusMaxAp || 0) + 1);
    state.maxAp = ((hasTalent('decisive') && state.age % 2 === 0) ? 4 : 3) + state.bonusMaxAp;
  }
  if (qin.effects.lifespanCeilingBonus) {
    state.lifespanCeiling = Math.min(98, (state.lifespanCeiling || 76) + qin.effects.lifespanCeilingBonus);
  }
  if (qin.effects.legacyScore && state.masterStudio) {
    state.masterStudio.legacyScore = (state.masterStudio.legacyScore || 60) + qin.effects.legacyScore;
  }
  if (qin.effects.heirloomScore && state.familyHeirloom) {
    state.familyHeirloom.value = Math.floor((state.familyHeirloom.value || 10000) * 1.15);
  }

  playSoundEffect('guqin_deep_resonance_slide');
  triggerHaptic('medium');
  spawnGuqinSoundwaveFX(screenWidth / 2, screenHeight / 2, 28);
  spawnEraPulseWaveFX(screenWidth / 2, screenHeight / 2, '#b45309');
  spawnFloatingRuneFX(`🎵 ${qin.name} · 德音孔昭`, screenWidth / 2, screenHeight / 2 - 35, '#fef08a');
  showToast(`🎵【${qin.name}】清音大和！“${qin.motto}”`, 'gold');
  requestRender();
}

function drawMasterGuqinModal() {
  const cardW = Math.min(screenWidth - 24, 356);
  const cardH = 510;
  const startX = (screenWidth - cardW) / 2;
  const startY = (screenHeight - cardH) / 2;

  ctx.save();
  drawSilkScrollFrame(ctx, startX, startY, cardW, cardH, '#1c1917', '#78350f');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';

  // 1. 标题栏
  ctx.font = 'bold 15px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef3c7';
  ctx.fillText('🎵 传世琴道 · 华夏四大名琴大圣遗音阁', startX + cardW / 2, startY + 16);

  const totalPlayed = state.guqinRecords ? (state.guqinRecords.totalCount || 0) : 0;
  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#fde68a';
  ctx.fillText(fitText(`高山流水 · 泠泠七弦通天地（已雅抚 ${totalPlayed}/${MASTER_GUQIN_HERITAGE_DATABASE.length} 种名琴）`, cardW - 24, '13.5px ' + FONT_UI), startX + cardW / 2, startY + 36);

  // 2. 名琴列表 (展示前 3 项当期代表名琴)
  const listY = startY + 56;
  const itmH = 104;
  const qinCount = Math.min(3, MASTER_GUQIN_HERITAGE_DATABASE.length);

  for (let idx = 0; idx < qinCount; idx++) {
    const qin = MASTER_GUQIN_HERITAGE_DATABASE[idx];
    const iy = listY + idx * (itmH + 6);
    const count = (state.guqinRecords && state.guqinRecords.played && state.guqinRecords.played[qin.id]) || 0;

    ctx.fillStyle = '#292524';
    roundRect(ctx, startX + 14, iy, cardW - 28, itmH, 6, true, true, count > 0 ? '#b45309' : '#57534e', 0.8);

    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#fef3c7';
    ctx.fillText(fitText(`${qin.icon} ${qin.name}`, cardW - 185, 'bold 14px ' + FONT_CHRONICLE), startX + 22, iy + 8);

    ctx.textAlign = 'right';
    ctx.font = '13.5px ' + FONT_UI;
    ctx.fillStyle = '#f59e0b';
    ctx.fillText(qin.category, startX + cardW - 22, iy + 9);

    ctx.textAlign = 'left';
    ctx.font = '13.5px ' + FONT_UI;
    ctx.fillStyle = '#fde047';
    ctx.fillText(fitText(`琴铭: ${qin.motto}`, cardW - 44, '13.5px ' + FONT_UI), startX + 22, iy + 26);

    ctx.fillStyle = '#cbd5e1';
    ctx.fillText(fitText(`斫制: ${qin.spec}`, cardW - 44, '13.5px ' + FONT_UI), startX + 22, iy + 41);

    ctx.fillStyle = '#86efac';
    ctx.font = '13.5px ' + FONT_UI;
    ctx.fillText(fitText(`功用: ${qin.desc}`, cardW - 44, '13.5px ' + FONT_UI), startX + 22, iy + 57);

    // 底部属性与操作按钮
    ctx.fillStyle = '#facc15';
    ctx.font = '13.5px ' + FONT_MONO;
    ctx.fillText(`消耗: 1精力 + ¥${qin.costMoney}  (已奏${count}次)`, startX + 22, iy + 78);

    const btnW = 78;
    const btnH = 22;
    const btnX = startX + cardW - btnW - 20;
    const btnY = iy + 73;

    drawTactileButton(ctx, {
      id: 'play_guqin_' + qin.id,
      x: btnX,
      y: btnY,
      w: btnW,
      h: btnH,
      radius: 4,
      bg: '#78350f',
      border: '#fbbf24',
      borderWidth: 1,
      font: 'bold 14px ' + FONT_UI,
      textColor: '#fffbeb',
      text: '抚琴雅奏 ➔',
      onClick: () => {
        playAndAppreciateGuqin(qin.id);
      },
      priority: 45
    });
  }

  // 3. 底部关闭按钮
  const closeBtnW = cardW - 40;
  const closeBtnH = 34;
  const closeBtnX = startX + 20;
  const closeBtnY = startY + cardH - closeBtnH - 12;

  drawTactileButton(ctx, {
    id: 'close_master_guqin',
    x: closeBtnX,
    y: closeBtnY,
    w: closeBtnW,
    h: closeBtnH,
    radius: 6,
    bg: '#451a03',
    border: '#b45309',
    borderWidth: 1,
    font: 'bold 14px ' + FONT_UI,
    textColor: '#fef3c7',
    text: '高山流水 · 德音孔昭 ➔',
    onClick: () => {
      state.activeModal = null;
      playSoundEffect('click');
      requestRender();
    },
    priority: 60
  });

  ctx.restore();
}

