// 🖋️ V47 墨韵砚池灵辉粒子对象池 (Inkstone Aura Particle Pool)
const INKSTONE_AURA_PARTICLE_POOL = [];
function obtainInkstoneParticle(initFn) {
  let p = INKSTONE_AURA_PARTICLE_POOL.pop();
  if (!p) p = {};
  p._poolType = 'inkstone';
  if (initFn) initFn(p);
  return p;
}
function releaseInkstoneParticle(p) {
  if (p && INKSTONE_AURA_PARTICLE_POOL.length < 150) {
    INKSTONE_AURA_PARTICLE_POOL.push(p);
  }
}

function spawnInkstoneAuraFX(cx, cy, count = 24) {
  const startX = cx || (screenWidth / 2);
  const startY = cy || (screenHeight / 2);
  for (let i = 0; i < count; i++) {
    const angle = (i / count) * Math.PI * 2;
    const p = obtainInkstoneParticle((obj) => {
      obj.x = startX;
      obj.y = startY;
      obj.dist = 12 + fxRandom() * 40;
      obj.angle = angle;
      obj.speed = 0.03 + fxRandom() * 0.035;
      obj.size = 2.0 + fxRandom() * 2.6;
      obj.alpha = 1.0;
      obj.color = ['#a855f7', '#c084fc', '#e9d5ff', '#3b82f6', '#34d399'][i % 5];
      obj.rotSpeed = 0.02 + fxRandom() * 0.03;
    });
    goldConfettiList.push(p);
  }
}

function openMasterInkstoneModal() {
  state.activeModal = 'master_inkstone';
  playSoundEffect('inkstone_jade_water_drip');
  triggerHaptic('medium');
  requestRender();
}

function grindAndAppreciateInkstone(stoneId) {
  const stone = MASTER_INKSTONE_HERITAGE_DATABASE.find(s => s.id === stoneId);
  if (!stone) return;

  state.inkstoneRecords = state.inkstoneRecords || { ground: {}, totalCount: 0 };
  if (state.inkstoneRecords.ground[stoneId]) {
    showToast(`🖋️ 已试磨典藏【${stone.name}】，名砚水岩温润长伴案头！`, 'info');
    return;
  }
  if (state.ap < (stone.costAp || 1)) {
    showToast('⚠️ 精力暂竭，请稍事休整后再运墨试研！', 'gold');
    return;
  }
  if ((state.capital || 0) < stone.costMoney) {
    showToast('⚠️ 备置上等御用松烟古墨与清泉水滴资费不足！', 'gold');
    return;
  }

  state.ap -= (stone.costAp || 1);
  state.capital = Math.max(0, (state.capital || 0) - stone.costMoney);
  progressThreeYearPact(12, `名砚试磨·${stone.name}`);

  state.inkstoneRecords.ground[stoneId] = 1;
  state.inkstoneRecords.totalCount += 1;

  // 生效收益
  if (stone.effects.resilience) addStat("resilience", Math.min(5, stone.effects.resilience), 50);
  if (stone.effects.rep) addStat("rep", Math.min(5, stone.effects.rep), 50);
  if (stone.effects.iq) addStat("iq", Math.min(5, stone.effects.iq), 50);
  if (stone.effects.eq) addStat("eq", Math.min(5, stone.effects.eq), 50);
  if (stone.effects.clanLuck) state.clanLuckScore = (state.clanLuckScore || 0) + stone.effects.clanLuck;
  if (stone.effects.sanbaoShen) state.sanbaoBonusShen = Math.min(25, (state.sanbaoBonusShen || 0) + stone.effects.sanbaoShen);
  if (stone.effects.sanbaoQi) state.sanbaoBonusQi = Math.min(25, (state.sanbaoBonusQi || 0) + stone.effects.sanbaoQi);
  if (stone.effects.sanbaoJing) state.sanbaoBonusJing = Math.min(25, (state.sanbaoBonusJing || 0) + stone.effects.sanbaoJing);
  if (stone.effects.apMaxBonus) {
    state.bonusMaxAp = Math.min(1, (state.bonusMaxAp || 0) + 1);
    state.maxAp = ((hasTalent('decisive') && state.age % 2 === 0) ? 4 : 3) + state.bonusMaxAp;
  }
  if (stone.effects.lifespanCeilingBonus) {
    state.lifespanCeiling = Math.min(98, (state.lifespanCeiling || 76) + stone.effects.lifespanCeilingBonus);
  }
  if (stone.effects.legacyScore && state.masterStudio) {
    state.masterStudio.legacyScore = (state.masterStudio.legacyScore || 60) + stone.effects.legacyScore;
  }
  if (stone.effects.heirloomScore && state.familyHeirloom) {
    state.familyHeirloom.value = Math.floor((state.familyHeirloom.value || 10000) * 1.15);
  }

  playSoundEffect('ink_grinding_whisper');
  triggerHaptic('medium');
  spawnInkstoneAuraFX(screenWidth / 2, screenHeight / 2, 28);
  spawnEraPulseWaveFX(screenWidth / 2, screenHeight / 2, '#581c87');
  spawnFloatingRuneFX(`🖋️ ${stone.name} · 呵气成墨`, screenWidth / 2, screenHeight / 2 - 35, '#e9d5ff');
  showToast(`🖋️【${stone.name}】发墨如油！“${stone.motto}”`, 'gold');
  requestRender();
}

function drawMasterInkstoneModal() {
  const cardW = Math.min(screenWidth - 24, 356);
  const cardH = 510;
  const startX = (screenWidth - cardW) / 2;
  const startY = (screenHeight - cardH) / 2;

  ctx.save();
  drawSilkScrollFrame(ctx, startX, startY, cardW, cardH, '#18181b', '#581c87');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';

  // 1. 标题栏
  ctx.font = 'bold 15px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#f3e8ff';
  ctx.fillText('🖋️ 传世砚道 · 华夏四大名砚石渠金匮阁', startX + cardW / 2, startY + 16);

  const totalGround = state.inkstoneRecords ? (state.inkstoneRecords.totalCount || 0) : 0;
  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#e9d5ff';
  ctx.fillText(fitText(`水岩金星 · 呵气成墨润千秋（已试研 ${totalGround}/${MASTER_INKSTONE_HERITAGE_DATABASE.length} 方名砚）`, cardW - 24, '13.5px ' + FONT_UI), startX + cardW / 2, startY + 36);

  // 2. 名砚列表 (展示前 3 项当期代表名砚)
  const listY = startY + 56;
  const itmH = 104;
  const stoneCount = Math.min(3, MASTER_INKSTONE_HERITAGE_DATABASE.length);

  for (let idx = 0; idx < stoneCount; idx++) {
    const stone = MASTER_INKSTONE_HERITAGE_DATABASE[idx];
    const iy = listY + idx * (itmH + 6);
    const count = (state.inkstoneRecords && state.inkstoneRecords.ground && state.inkstoneRecords.ground[stone.id]) || 0;

    ctx.fillStyle = '#27272a';
    roundRect(ctx, startX + 14, iy, cardW - 28, itmH, 6, true, true, count > 0 ? '#7e22ce' : '#3f3f46', 0.8);

    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#f3e8ff';
    ctx.fillText(fitText(`${stone.icon} ${stone.name}`, cardW - 185, 'bold 14px ' + FONT_CHRONICLE), startX + 22, iy + 8);

    ctx.textAlign = 'right';
    ctx.font = '13.5px ' + FONT_UI;
    ctx.fillStyle = '#c084fc';
    ctx.fillText(stone.category, startX + cardW - 22, iy + 9);

    ctx.textAlign = 'left';
    ctx.font = '13.5px ' + FONT_UI;
    ctx.fillStyle = '#fef08a';
    ctx.fillText(fitText(`砚铭: ${stone.motto}`, cardW - 44, '13.5px ' + FONT_UI), startX + 22, iy + 26);

    ctx.fillStyle = '#cbd5e1';
    ctx.fillText(fitText(`品相: ${stone.spec}`, cardW - 44, '13.5px ' + FONT_UI), startX + 22, iy + 41);

    ctx.fillStyle = '#86efac';
    ctx.font = '13.5px ' + FONT_UI;
    ctx.fillText(fitText(`功用: ${stone.desc}`, cardW - 44, '13.5px ' + FONT_UI), startX + 22, iy + 57);

    // 底部属性与操作按钮
    ctx.fillStyle = '#facc15';
    ctx.font = '13.5px ' + FONT_MONO;
    ctx.fillText(`消耗: 1精力 + ¥${stone.costMoney}  (已研${count}次)`, startX + 22, iy + 78);

    const btnW = 78;
    const btnH = 22;
    const btnX = startX + cardW - btnW - 20;
    const btnY = iy + 73;

    drawTactileButton(ctx, {
      id: 'grind_inkstone_' + stone.id,
      x: btnX,
      y: btnY,
      w: btnW,
      h: btnH,
      radius: 4,
      bg: '#6b21a8',
      border: '#c084fc',
      borderWidth: 1,
      font: 'bold 14px ' + FONT_UI,
      textColor: '#fdf4ff',
      text: '试磨雅鉴 ➔',
      onClick: () => {
        grindAndAppreciateInkstone(stone.id);
      },
      priority: 45
    });
  }

  // 3. 底部关闭按钮
  const closeBtnW = cardW - 40;
  const closeBtnH = 34;
  const closeBtnX = startX + 20;
  const closeBtnY = startY + cardH - closeBtnH - 12;

  drawTactileButton(ctx, {
    id: 'close_master_inkstone',
    x: closeBtnX,
    y: closeBtnY,
    w: closeBtnW,
    h: closeBtnH,
    radius: 6,
    bg: '#3b0764',
    border: '#7e22ce',
    borderWidth: 1,
    font: 'bold 14px ' + FONT_UI,
    textColor: '#f3e8ff',
    text: '文房雅宝 · 润墨留香 ➔',
    onClick: () => {
      state.activeModal = null;
      playSoundEffect('click');
      requestRender();
    },
    priority: 60
  });

  ctx.restore();
}

// ==========================================
// 🏛️ V37-V38 国家大师技能创新工作室传承体系 (Master Studio System)
// ==========================================
function openMasterStudioModal() {
  if (state.age < 30 && (state.rep || 0) < 65) {
    showToast('🏛️ 国家大师创新工作室须年满30岁（或声誉≥65）具备深厚行业资历后挂牌成立！', 'info');
    return;
  }
  if (!state.masterStudio) {
    const trackName = state.track === 'industry' ? '技能' : (state.track === 'military' ? '军工科技' : (state.track === 'agri' ? '神农育种' : (state.track === 'biz' ? '实业创新' : '科技攻坚')));
    state.masterStudio = {
      name: `${state.name}国家${trackName}大师创新工作室`,
      level: (state.rep >= 85 ? '国家级特等示范' : '省部级重点创新'),
      apprentices: 4,
      legacyScore: 60,
      completedProjects: 1
    };
  }
  if (!state.masterStudio.disciples || state.masterStudio.disciples.length === 0) {
    state.masterStudio.disciples = [
      { name: '林承志', specialty: '高精五轴磨削', stage: 1, stageName: '业务骨干' },
      { name: '周立人', specialty: '航空特种合金', stage: 2, stageName: '独当一面总工' },
      { name: '苏清若', specialty: '数字孪生装配', stage: 1, stageName: '业务骨干' }
    ];
  }
  state.activeModal = 'master_studio';
  playSoundEffect('guzheng_cascade');
  triggerHaptic('medium');
  requestRender();
}

function commendDisciple(idx) {
  if (!state.masterStudio) return;
  const list = state.masterStudio.disciples;
  if (!list || !list[idx]) return;

  const d = list[idx];
  if ((d.stage || 1) >= 3) {
    showToast(`🏆 门生【${d.name}】已荣登【领衔大国英才】，独当一面！`, 'info');
    return;
  }
  if (state.lastStudioDiscipleYear === state.year) {
    showToast('🏛️ 本年度已点拨提携过门生，传道授业贵在循序渐进！', 'info');
    return;
  }
  if (state.ap < 1) {
    showToast('⚠️ 精力暂竭，稍作调养后再倾心点拨提携门生！', 'gold');
    return;
  }
  state.ap -= 1;
  state.lastStudioDiscipleYear = state.year;
  progressThreeYearPact(15, `点拨提携·${d.name}`);
  d.stage = (d.stage || 1) + 1;
  if (d.stage === 2) {
    d.stageName = '独当一面总工';
    state.masterStudio.legacyScore = (state.masterStudio.legacyScore || 60) + 20;
    addStat("rep", (3), 50);
    playSoundEffect('guzheng_cascade');
    triggerHaptic('medium');
    spawnFloatingRuneFX(`💡 提携晋升 · ${d.name}出徒`, screenWidth / 2, screenHeight / 2 - 30, '#38bdf8');
    showToast(`💡【点拨提携】门生【${d.name}】突破关键技术瓶颈，荣升【独当一面总工】！传承积分+20！`, 'cyan');
  } else {
    d.stage = 3;
    d.stageName = '领衔大国英才';
    state.masterStudio.legacyScore = (state.masterStudio.legacyScore || 60) + 30;
    addStat("rep", (5), 50);
    playSoundEffect('war_drum_resonance');
    triggerHaptic('heavy');
    spawnInkWashBloom(screenWidth / 2, screenHeight / 2, 70, 'rgba(217, 119, 6, 0.45)');
    spawnFloatingRuneFX(`🏆 栋梁大成 · ${d.name}国家英才`, screenWidth / 2, screenHeight / 2 - 30, '#f59e0b');
    showToast(`🏆【薪火相传】门生【${d.name}】荣获国家青年科技英才称号！声誉+5，传承积分+30！`, 'gold');
  }
  requestRender();
}

function executeStudioDirective(actionKey) {
  if (!state.masterStudio) return;
  if (state.lastStudioDirectiveYear === state.year) {
    showToast('🏛️ 本年度工作室重点攻关或传习任务已圆满推进，请静待来年新课题！', 'info');
    return;
  }
  if (state.ap < 1) {
    showToast('⚠️ 精力已竭，稍作调养或品茗后再指导工作室工作！', 'gold');
    return;
  }
  state.ap -= 1;
  state.lastStudioDirectiveYear = state.year;
  progressThreeYearPact(15, '大师工作室课题传习');
  if (actionKey === 'apprentice') {
    state.masterStudio.apprentices = (state.masterStudio.apprentices || 4) + 1;
    state.masterStudio.legacyScore = (state.masterStudio.legacyScore || 60) + 15;
    addStat("resilience", (3), 50);
    playSoundEffect('guzheng_cascade');
    triggerHaptic('medium');
    spawnFloatingRuneFX('💡 传艺+1 · 传承+15', screenWidth / 2, screenHeight / 2 - 40, '#fde68a');
    showToast('💡【带徒传习】倾囊相授独门绝学，新入选骨干学徒顺利出徒！传承积分+15！', 'gold');
  } else if (actionKey === 'topic') {
    state.masterStudio.completedProjects = (state.masterStudio.completedProjects || 1) + 1;
    state.masterStudio.legacyScore = (state.masterStudio.legacyScore || 60) + 20;
    addStat("rep", (4), 50);
    state.capital = (state.capital || 0) + 8000;
    playSoundEffect('pipa_tremolo');
    triggerHaptic('heavy');
    spawnFloatingRuneFX('🔬 课题结题 · 津贴+8千', screenWidth / 2, screenHeight / 2 - 40, '#38bdf8');
    showToast('🔬【课题攻坚】工作室挂牌攻关课题通过专家组阶段验收！声誉+4，津贴+¥8,000！', 'cyan');
  } else if (actionKey === 'codify') {
    state.masterStudio.legacyScore = (state.masterStudio.legacyScore || 60) + 25;
    addStat("iq", (4), 50);
    state.sanbaoBonusShen = Math.min(25, (state.sanbaoBonusShen || 0) + 3);
    playSoundEffect('seal_stamp_heavy');
    triggerHaptic('heavy');
    spawnInkWashBloom(screenWidth / 2, screenHeight / 2, 60, 'rgba(220, 38, 38, 0.45)');
    spawnFloatingRuneFX('📜 工法立言 · 传承+25', screenWidth / 2, screenHeight / 2 - 40, '#ef4444');
    showToast('📜【工法编纂】国家级实训教材与核心专利指南付梓发行！薪火相传，垂范后世！', 'gold');
  }
  requestRender();
}

