function openMasteryTreeModal() {
  state.activeModal = 'mastery_tree';
  playSoundEffect('guqin_deep_reverie');
  triggerHaptic('medium');
  requestRender();
}

function unlockMastery(m) {
  state.unlockedMasteries = state.unlockedMasteries || {};
  if (state.unlockedMasteries[m.id]) {
    showToast('该工法已大成圆满！', 'gold');
    return;
  }
  if (state.age < 24) {
    showToast('📜 须年满24岁具备一线工程历练后，方可主持重器工法突破！', 'info');
    return;
  }
  if (state.lastMasteryYear === state.year) {
    showToast('📜 本年度已主持攻克过一项重器工法，请沉淀实践后再图突破！', 'info');
    return;
  }
  if ((state.ap || 0) < 1) {
    showToast('⚠️ 精力不足(需1⚡)，请调养生息后再钻研重器工法！', 'gold');
    return;
  }
  if ((state.iq || 0) < 55) {
    showToast('⚠️ 智谋底蕴尚浅(需智谋≥55)，请先潜心研读技术典籍！', 'gold');
    return;
  }
  state.ap -= 1;
  state.lastMasteryYear = state.year;
  state.unlockedMasteries[m.id] = true;
  progressThreeYearPact(15, `工法研创·${m.name}`);
  addStat("resilience", 5, 50);
  addStat("iq", 4, 50);
  playSoundEffect('bianzhong_sacred_hymn');
  triggerHaptic('heavy');
  showToast('🛠️【工法大成】点亮【' + m.name + '】！抗逆与智谋稳步跃升！', 'gold');
  addChronicleItem(state.age, state.year, '【工法研创】主持攻克【' + m.name + '】关键工法，打破壁垒，立言立业！', '工法大成', 'promo');
  requestRender();
}

function drawMasteryTreeModal() {
  const cardW = Math.min(screenWidth - 24, 356);
  const cardH = 470;
  const startX = (screenWidth - cardW) / 2;
  const startY = (screenHeight - cardH) / 2;

  ctx.save();
  drawSilkScrollFrame(ctx, startX, startY, cardW, cardH, '#059669', '#d97706');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';

  // 1. 标题
  ctx.font = 'bold 15px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText('📜 重器工法谱 · 四大自立自强突破树', startX + cardW / 2, startY + 16);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#a7f3d0';
  ctx.fillText('攻坚核心基础工法，为世纪工程筑牢坚不可摧之基石', startX + cardW / 2, startY + 36);

  // 2. 工法项
  const listY = startY + 58;
  const itemH = 68;
  state.unlockedMasteries = state.unlockedMasteries || {};

  ENGINEERING_MASTERY_TREE.forEach((m, idx) => {
    const iy = listY + idx * (itemH + 8);
    const isUnlocked = !!state.unlockedMasteries[m.id];

    drawTactileButton(ctx, {
      id: 'mastery_item_' + m.id,
      x: startX + 14,
      y: iy,
      w: cardW - 28,
      h: itemH,
      radius: 6,
      bg: isUnlocked ? '#064e3b' : '#0f172a',
      border: isUnlocked ? '#10b981' : '#64748b',
      borderWidth: isUnlocked ? 1.5 : 1,
      priority: 60,
      onClick: () => {
        unlockMastery(m);
      },
      renderContent: (c, isPressed) => {
        c.textAlign = 'left';
        c.font = 'bold 14px ' + FONT_CHRONICLE;
        c.fillStyle = isUnlocked ? '#a7f3d0' : '#fef08a';
        c.fillText(m.icon + ' 【' + m.name + '】' + (isUnlocked ? ' · ✦ 已攻克' : ''), startX + 22, iy + 8);

        c.textAlign = 'right';
        c.font = 'bold 14px ' + FONT_UI;
        c.fillStyle = isUnlocked ? '#34d399' : '#38bdf8';
        c.fillText(isUnlocked ? '✔ 工法大成' : '点击参悟点亮 ➔', startX + cardW - 22, iy + 10);

        c.textAlign = 'left';
        c.font = '13.5px ' + FONT_UI;
        c.fillStyle = '#cbd5e1';
        c.fillText(fitText(m.desc, cardW - 44, '13.5px ' + FONT_UI), startX + 22, iy + 27);

        c.font = 'bold 14px ' + FONT_MONO;
        c.fillStyle = isUnlocked ? '#6ee7b7' : '#f59e0b';
        c.fillText('增益：' + m.bonus, startX + 22, iy + 45);
      }
    });
  });

  // 3. 底部关闭按钮
  const closeBtnW = cardW - 40;
  const closeBtnH = 34;
  const closeBtnX = startX + 20;
  const closeBtnY = startY + cardH - closeBtnH - 12;

  drawTactileButton(ctx, {
    id: 'close_mastery_tree',
    x: closeBtnX,
    y: closeBtnY,
    w: closeBtnW,
    h: closeBtnH,
    radius: 6,
    bg: '#065f46',
    border: '#10b981',
    text: '笃行不怠 · 精益求精 ➔',
    font: 'bold 14px ' + FONT_UI,
    textColor: '#fff',
    priority: 60,
    onClick: () => {
      state.activeModal = null;
      playSoundEffect('click');
      requestRender();
    }
  });

  ctx.restore();
}

