function _checkDeskAnnualQuota(itemKey, usedMsg) {
  state.deskItemUsedYear = state.deskItemUsedYear || {};
  if (state.deskItemUsedYear[itemKey] === state.year) {
    showToast(usedMsg, 'info');
    return false;
  }
  if (state.deskQuotaYear !== state.year) {
    state.deskQuotaYear = state.year;
    state.deskQuotaCount = 0;
  }
  if ((state.deskQuotaCount || 0) >= 2) {
    showToast('🖌️ 本年度已在案头雅赏把玩过两件文房器物，过犹不及，请专心主业或来年再赏！', 'info');
    return false;
  }
  state.deskItemUsedYear[itemKey] = state.year;
  state.deskQuotaCount = (state.deskQuotaCount || 0) + 1;
  return true;
}

function interactTeapot() {
  if (!_checkDeskAnnualQuota('teapot', '🍵 今年已在案头烹茶静思过，茶贵清心，请明年再品！')) return;
  let restoredAp = false;
  if (state.ap < state.maxAp && (state.year - (state.lastTeapotApYear || 0)) >= 3) {
    state.ap = Math.min(state.maxAp, state.ap + 1);
    state.lastTeapotApYear = state.year;
    restoredAp = true;
  }
  addStat("resilience", 1, 50);
  state.sanbaoBonusQi = Math.min(25, (state.sanbaoBonusQi || 0) + 3);
  playSoundEffect('tea_pour_trickle');
  triggerHaptic('light');
  spawnFloatingRuneFX(restoredAp ? '🍵 +1 精力充盈 · 元气充沛' : '🍵 +1 心性澄明 · 茶香宁神', screenWidth / 2, (typeof getDashboardY === 'function' ? getDashboardY() : 200) + 40, '#34d399');

  let teaMsg = '🍵【紫砂品茗】清泉煮茗，涤尽尘虑。元气充沛！';
  if (state.youthPath === 'vocational') {
    teaMsg = '🍵【车间茗叙】端起大号搪瓷缸痛饮浓茶，涤荡车间油烟，周身充满一线干劲！';
  } else if (state.youthPath === 'military') {
    teaMsg = '🍵【军旅畅饮】端起行军水壶痛饮甘泉，胸怀祖国万里河山，意志如钢！';
  } else if (state.youthPath === 'commerce') {
    teaMsg = '🍵【潮商工夫茶】在洽谈桌前品一口正宗工夫茶，笑看特区商潮，神清气爽！';
  } else if (state.youthPath === 'agri') {
    teaMsg = '🍵【田埂大麦茶】坐在田埂上品尝乡亲送来的大麦茶，满目稻菽千重浪，神清气爽！';
  }
  showToast(teaMsg, 'gold');
  requestRender();
}

