function triggerSpousalResonanceEvent() {
  if (state.activeModal) return false;
  if (!state.family || !state.family.spouseName) return false;
  const age = state.age;

  for (let evt of SPOUSAL_RESONANCE_ENGINE.events) {
    if (age === evt.targetAge && (!state.handledEvents || !state.handledEvents['spousal_' + evt.id])) {
      state.handledEvents = state.handledEvents || {};
      state.handledEvents['spousal_' + evt.id] = true;
      state.currentSpousalEvent = evt;
      state.activeModal = 'spousal_resonance';

      playSoundEffect('pipa_spring_blossoms');
      triggerHaptic('medium');
      requestRender();
      return true;
    }
  }
  return false;
}

function drawSpousalResonanceModal() {
  const cardW = Math.min(screenWidth - 24, 356);
  const cardH = 460;
  const startX = (screenWidth - cardW) / 2;
  const startY = (screenHeight - cardH) / 2;

  const evt = state.currentSpousalEvent;
  if (!evt) {
    state.activeModal = null;
    return;
  }

  ctx.save();
  drawSilkScrollFrame(ctx, startX, startY, cardW, cardH, '#be185d', '#d97706');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';

  // 1. 标题
  ctx.font = 'bold 15px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText('💍 ' + evt.title, startX + cardW / 2, startY + 16);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#fbcfe8';
  ctx.fillText('“执子之手，与子偕老” · 结发夫妻半个世纪相濡以沫深情', startX + cardW / 2, startY + 36);

  // 2. 正文
  const textBoxY = startY + 58;
  const textBoxH = 175;
  ctx.fillStyle = '#1c1917';
  roundRect(ctx, startX + 16, textBoxY, cardW - 32, textBoxH, 6, true, true, '#d97706', 0.8);

  ctx.textAlign = 'left';
  ctx.font = '13.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fde68a';
  drawWrappedText(ctx, evt.desc, startX + 26, textBoxY + 14, cardW - 52, 17);

  // 3. 抉择按钮
  const btnW = cardW - 32;
  const btnH = 42;
  let curBtnY = textBoxY + textBoxH + 12;

  for (let idx = 0; idx < evt.choices.length; idx++) {
    const ch = evt.choices[idx];
    drawTactileButton(ctx, {
      id: 'spousal_choice_' + idx,
      x: startX + 16,
      y: curBtnY,
      w: btnW,
      h: btnH,
      radius: 6,
      bg: idx === 0 ? '#831843' : '#1e1b4b',
      border: idx === 0 ? '#f43f5e' : '#6366f1',
      priority: 60,
      onClick: () => {
        addStat("resilience", Math.min(8, ch.effects.resilience || 0), 50);
        if (ch.effects) {
          for (const k in ch.effects) {
            if (Object.prototype.hasOwnProperty.call(ch.effects, k) && k !== 'resilience') {
              if (typeof state[k] === 'number') addStat(k, Math.min(6, ch.effects[k]), 50);
            }
          }
        }
        playSoundEffect('bell_grand_chime');
        triggerHaptic('medium');
        showToast('💖【白首相庄】' + ch.tag + '！心性抗逆稳步升华！', 'gold');
        addChronicleItem(state.age, state.year, '【相濡以沫】' + evt.title + '：' + ch.outcomeText, ch.tag, 'promo');
        state.activeModal = null;
        requestRender();
      },
      renderContent: (c, isPressed) => {
        c.textAlign = 'left';
        c.font = 'bold 14px ' + FONT_CHRONICLE;
        c.fillStyle = idx === 0 ? '#fecdd3' : '#c7d2fe';
        c.fillText('💑 ' + ch.text, startX + 24, curBtnY + 13);

        c.font = '13.5px ' + FONT_UI;
        c.fillStyle = '#cbd5e1';
        const effStr = '【' + ch.tag + '】内省抗逆力 +' + ch.effects.resilience + (ch.effects.rep ? ' 声望+' + ch.effects.rep : (ch.effects.eq ? ' 人情+' + ch.effects.eq : (ch.effects.health ? ' 体魄+' + ch.effects.health : '')));
        c.fillText(effStr, startX + 24, curBtnY + 28);
      }
    });

    curBtnY += btnH + 8;
  }

  ctx.restore();
}

