function interactPencil() {
  if (!_checkDeskAnnualQuota('pencil', '✏️ 今年已在案头批阅圈画过重点卷宗，请明年再审！')) return;
  addStat("iq", 1, 50);
  addStat("resilience", 1, 50);
  state.pencilAnnotated = true;
  playSoundEffect('brush_ink_whisper');
  triggerHaptic('light');
  spawnFloatingRuneFX('✏️ +1 智谋圈阅', screenWidth / 2, (typeof getDashboardY === 'function' ? getDashboardY() : 200) + 40, '#f87171');

  const p = state.youthPath || state.track || 'industry';
  let pencilMsg = '🖋️【铅笔圈阅】红蓝双色，字字斟酌。大局把关，审慎周详！';
  if (p === 'vocational' || p === 'industry') {
    pencilMsg = '✏️【工差制图】用2B铅笔在硫酸纸上手绘特种减速箱三视图，公差卡在微米级！';
    spawnMetalSparksFX(screenWidth / 2, getDashboardY() + 60, 10);
  } else if (p === 'military') {
    pencilMsg = '✏️【战备标图】在军事地形图上精确标定隧道开凿爆破点与抢险动线！';
    spawnMilitaryStarsFX(screenWidth / 2, getDashboardY() + 60, 10);
  } else if (p === 'commerce' || p === 'biz') {
    pencilMsg = '✏️【商约审订】在信笺上逐行推敲外贸联营框架协议，严控违约责任！';
    spawnCoinShowerFX(screenWidth / 2, getDashboardY() + 60, 10);
  } else if (p === 'agri') {
    pencilMsg = '✏️【农情日记】用铅笔密密麻麻记录杂交麦穗抽穗期温湿数据与耐盐碱曲线！';
    spawnWheatGlowFX(screenWidth / 2, getDashboardY() + 60, 10);
  } else if (p === 'gaokao' || p === 'tech') {
    pencilMsg = '✏️【公式推导】在草稿纸上飞快推演非线性控制偏微分方程！';
    spawnCircuitPulseFX(screenWidth / 2, getDashboardY() + 60, 10);
  }
  showToast(pencilMsg, 'cyan');
  requestRender();
}

function interactIncense() {
  if (!_checkDeskAnnualQuota('incense', '🪔 今年已在案头焚香调息过，心神已定，请明年再品！')) return;
  addStat("health", 2, 80);
  addStat("resilience", 1, 50);
  state.sanbaoBonusShen = Math.min(25, (state.sanbaoBonusShen || 0) + 3);
  playSoundEffect('sheng_harmonious_reed');
  triggerHaptic('light');
  spawnFloatingRuneFX('🪔 +2 道心澄澈 · 元神内守', screenWidth / 2, (typeof getDashboardY === 'function' ? getDashboardY() : 200) + 40, '#fbbf24');

  const p = state.youthPath || state.track || 'industry';
  let incenseMsg = '🪔【静心调息】宝鼎轻烟，气定神闲。涤荡烦忧，道心澄澈！';
  if (p === 'vocational' || p === 'industry') {
    incenseMsg = '🪔【匠心宁神】铜炉幽香，平复车间繁杂心绪。手稳心静，方能拿捏千分之一毫米！';
  } else if (p === 'military') {
    incenseMsg = '🪔【静夜思危】军旅肃穆，凝视青烟。忆八百里山川险阻，胸中百万兵，坚不可摧！';
  } else if (p === 'commerce' || p === 'biz') {
    incenseMsg = '🪔【商海清心】茶烟袅袅，抚平市场暴涨暴跌之浮躁。守正出奇，方成百年基业！';
  } else if (p === 'agri') {
    incenseMsg = '🪔【禾黍生香】静听窗外风吹麦浪，天地人和。守望大地苍生，心头一片清明！';
  } else if (p === 'gaokao' || p === 'tech') {
    incenseMsg = '🪔【澄心求道】沉香静气，摒除外界喧嚣名利。甘坐冷板凳，求索宇宙真理！';
  }
  showToast(incenseMsg, 'gold');
  requestRender();
}

