function triggerHighStakesConflict() {
  if (state.activeModal) return false;
  const age = state.age;

  for (let c of HIGH_STAKES_ETHICAL_CONFLICTS) {
    if (age === c.targetAge && (!state.handledEvents || !state.handledEvents['conflict_' + c.id])) {
      state.handledEvents = state.handledEvents || {};
      state.handledEvents['conflict_' + c.id] = true;
      state.activeConflictEvent = c;
      state.activeModal = 'high_stakes_conflict';
      playSoundEffect('storm_wind_thunder');
      triggerHaptic('heavy');
      requestRender();
      return true;
    }
  }
  return false;
}

function drawHighStakesConflictModal() {
  const cardW = Math.min(screenWidth - 24, 356);
  const cardH = 460;
  const startX = (screenWidth - cardW) / 2;
  const startY = (screenHeight - cardH) / 2;

  const conf = state.activeConflictEvent;
  if (!conf) {
    state.activeModal = null;
    return;
  }

  ctx.save();
  drawSilkScrollFrame(ctx, startX, startY, cardW, cardH, '#dc2626', '#b91c1c');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';

  // 1. 标题
  ctx.font = 'bold 15px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText('⚔️ ' + conf.title, startX + cardW / 2, startY + 16);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#fca5a5';
  ctx.fillText('“君子有所为，有所不为” · 人生重大现实伦理冲突决断', startX + cardW / 2, startY + 36);

  // 2. 正文
  const textBoxY = startY + 58;
  const textBoxH = 175;
  ctx.fillStyle = '#1c1917';
  roundRect(ctx, startX + 16, textBoxY, cardW - 32, textBoxH, 6, true, true, '#ef4444', 0.8);

  ctx.textAlign = 'left';
  ctx.font = '13.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fde68a';
  drawWrappedText(ctx, conf.desc, startX + 26, textBoxY + 14, cardW - 52, 18);

  // 3. 抉择按钮
  const btnW = cardW - 32;
  const btnH = 42;
  let curBtnY = textBoxY + textBoxH + 12;

  for (let idx = 0; idx < 2; idx++) {
    const ch = idx === 0 ? conf.choiceA : conf.choiceB;
    drawTactileButton(ctx, {
      id: 'conflict_choice_' + idx,
      x: startX + 16,
      y: curBtnY,
      w: btnW,
      h: btnH,
      radius: 6,
      bg: idx === 0 ? '#7f1d1d' : '#1e1b4b',
      border: idx === 0 ? '#ef4444' : '#6366f1',
      priority: 60,
      onClick: () => {
        addStat("resilience", Math.min(8, ch.effects.resilience || 0), 50);
        if (ch.effects) {
          for (const k in ch.effects) {
            if (Object.prototype.hasOwnProperty.call(ch.effects, k) && k !== 'resilience') {
              if (k === 'wealth' || k === 'capital' || k === 'money') {
                state.capital = (state.capital || 0) + ch.effects[k];
              } else if (typeof state[k] === 'number') {
                addStat(k, Math.min(6, ch.effects[k]), 50);
              }
            }
          }
        }
        playSoundEffect('bell_grand_chime');
        triggerHaptic('heavy');
        showToast('⚔️【现实决断】' + ch.tag + '！内省抗逆力稳步升华！', 'gold');
        addChronicleItem(state.age, state.year, '【现实抉择】' + conf.title + '：' + ch.outcomeText, ch.tag, 'promo');
        state.activeModal = null;
        requestRender();
      },
      renderContent: (c, isPressed) => {
        c.textAlign = 'left';
        c.font = 'bold 14px ' + FONT_CHRONICLE;
        c.fillStyle = idx === 0 ? '#fecaca' : '#c7d2fe';
        c.fillText('⚖️ ' + ch.text, startX + 24, curBtnY + 13);

        c.font = '13.5px ' + FONT_UI;
        c.fillStyle = '#cbd5e1';
        c.fillText('【' + ch.tag + '】内省抗逆力 +' + ch.effects.resilience, startX + 24, curBtnY + 28);
      }
    });

    curBtnY += btnH + 8;
  }

  ctx.restore();
}

