// 10.4.6 时代韬略心法与宏观资本工坊 Tab
function drawStrategyTab(startY) {
  ctx.save();
  const padX = 12;
  const w = screenWidth - padX * 2;
  let curY = startY;

  // 1. 毕生阅历与处世心得 (Talents Matrix)
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 14px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText("⚡ 毕生阅历与处世心得", padX + 6, curY);

  ctx.font = 'bold 14px ' + FONT_UI;
  ctx.fillStyle = (state.talentPoints || 0) > 0 ? '#34d399' : '#94a3b8';
  ctx.textAlign = 'right';
  ctx.fillText(`心得点数: ${state.talentPoints || 0} ⚡  (融会: ${(state.unlockedTalents || []).length}/8)`, padX + w - 6, curY + 1);
  curY += 20;

  ctx.textAlign = 'left';
  ctx.font = '13.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#94a3b8';
  ctx.fillText("历经岁月磨砺、职务晋升与卓越考核，可沉淀人生阅历、领悟处世之道。", padX + 6, curY);
  curY += 16;

  const vTop = getContentTop() - 60;
  const vBottom = getContentTop() + getContentH() + 60;

  // 8 Talents in 2 columns
  const tColW = (w - 8) / 2;
  const tCardH = 76;
  const totalTalentRows = Math.ceil(TALENTS_DATABASE.length / 2);

  for (let idx = 0; idx < TALENTS_DATABASE.length; idx++) {
    const t = TALENTS_DATABASE[idx];
    const col = idx % 2;
    const row = Math.floor(idx / 2);
    const tx = padX + col * (tColW + 8);
    const ty = curY + row * (tCardH + 8);

    if (ty + tCardH < vTop || ty > vBottom) {
      continue;
    }

    const isUnlocked = hasTalent(t.id);
    const canUnlock = !isUnlocked && (state.talentPoints || 0) >= (t.cost || 1);

    ctx.fillStyle = isUnlocked ? '#181e2e' : '#141221';
    roundRect(ctx, tx, ty, tColW, tCardH, 6, true, true, isUnlocked ? '#f59e0b' : (canUnlock ? '#38bdf8' : '#334155'), 1);

    // Icon + Name
    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = isUnlocked ? '#fef08a' : (canUnlock ? '#38bdf8' : '#e2e8f0');
    ctx.fillText(`${t.icon} ${t.name}`, tx + 8, ty + 8);

    // Branch tag
    ctx.font = '13.5px ' + FONT_UI;
    ctx.fillStyle = isUnlocked ? '#f59e0b' : '#94a3b8';
    ctx.textAlign = 'right';
    ctx.fillText(t.branch, tx + tColW - 8, ty + 9);

    // Description (2 lines)
    ctx.textAlign = 'left';
    ctx.font = '13.5px ' + FONT_CHRONICLE;
    ctx.fillStyle = isUnlocked ? '#cbd5e1' : '#94a3b8';
    if (!t._lines || t._lastW !== tColW) {
      t._lines = wrapTextLines(t.desc, tColW - 16, '13.5px ' + FONT_CHRONICLE);
      t._lastW = tColW;
    }
    const lines = t._lines;
    const lineLimit = Math.min(2, lines.length);
    for (let li = 0; li < lineLimit; li++) {
      ctx.fillText(lines[li], tx + 8, ty + 26 + li * 13);
    }

    // Status button
    const bW = tColW - 16;
    const bH = 18;
    const bx = tx + 8;
    const by = ty + tCardH - bH - 6;

    if (isUnlocked) {
      ctx.fillStyle = '#064e3b';
      roundRect(ctx, bx, by, bW, bH, 3, true, true, '#10b981', 1);
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.font = 'bold 14px ' + FONT_UI;
      ctx.fillStyle = '#a7f3d0';
      ctx.fillText("✓ 已融会贯通", bx + bW / 2, by + bH / 2);
    } else if (canUnlock) {
      drawTactileButton({
        id: `unlock_talent_${t.id}`,
        x: bx,
        y: by,
        w: bW,
        h: bH,
        radius: 3,
        bg: '#b45309',
        borderColor: '#f59e0b',
        borderWidth: 1,
        isScroll: true,
        priority: 25,
        onClick: () => {
          unlockTalent(t.id);
        },
        renderCustom: () => {
          ctx.textAlign = 'center';
          ctx.textBaseline = 'middle';
          ctx.font = 'bold 14px ' + FONT_UI;
          ctx.fillStyle = '#fef08a';
          ctx.fillText("✨ 点击参悟 (-1⚡)", bx + bW / 2, by + bH / 2);
        }
      });
    } else {
      ctx.fillStyle = '#1e293b';
      roundRect(ctx, bx, by, bW, bH, 3, true, true, '#475569', 1);
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.font = '13.5px ' + FONT_UI;
      ctx.fillStyle = '#64748b';
      ctx.fillText("待心得点开启", bx + bW / 2, by + bH / 2);
    }
  }

  curY += totalTalentRows * (tCardH + 8) + 16;

  // 2. 宏观资本运营与年度财报工坊
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 14px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText("📈 资产配置与实业投资工坊", padX + 6, curY);

  const curClim = getMacroClimate(state.year);
  ctx.font = 'bold 14px ' + FONT_UI;
  ctx.fillStyle = curClim.color || '#38bdf8';
  ctx.textAlign = 'right';
  ctx.fillText(`当前经济景气度: ×${curClim.yieldMultiplier.toFixed(2)}`, padX + w - 6, curY + 2);
  curY += 22;

  for (let i = 0; i < INVEST_PRODUCTS.length; i++) {
    const inv = INVEST_PRODUCTS[i];
    const invVal = (state.investments && state.investments[inv.id]) || 0;
    const cardH = 80;
    if (curY + cardH < vTop || curY > vBottom) {
      curY += cardH + 10;
      continue;
    }

    ctx.fillStyle = '#13111f';
    roundRect(ctx, padX, curY, w, cardH, 6, true, true, inv.color, 1);

    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = inv.color;
    ctx.fillText(inv.title, padX + 12, curY + 10);

    ctx.font = '13.5px ' + FONT_UI;
    ctx.fillStyle = '#cbd5e1';
    ctx.fillText(fitText(inv.desc, w - 110, '13.5px ' + FONT_UI), padX + 12, curY + 30);

    ctx.font = 'bold 14px ' + FONT_MONO;
    ctx.fillStyle = '#94a3b8';
    ctx.fillText(`当前配置总值：¥${(invVal || 0).toLocaleString()}`, padX + 12, curY + 52);

    const bW = 82;
    const bH = 26;
    const bX = padX + w - bW - 12;
    const bY = curY + (cardH - bH) / 2;

    drawTactileButton({
      id: `buy_inv_${inv.id}`,
      x: bX,
      y: bY,
      w: bW,
      h: bH,
      radius: 4,
      bg: '#1e293b',
      borderColor: inv.color,
      borderWidth: 1,
      isScroll: true,
      priority: 20,
      onClick: () => {
        if (state.capital >= inv.price) {
          state.capital -= inv.price;
          state.investments[inv.id] += inv.price;
          playSoundEffect('coin');
          showToast(`成功配置【${inv.title}】！`, 'good');
        } else {
          showToast(`资本不足，需结余 ¥${inv.price.toLocaleString()}`, 'alert');
        }
        requestRender();
      },
      renderCustom: () => {
        ctx.font = 'bold 14px ' + FONT_UI;
        ctx.fillStyle = '#f8fafc';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(`申购 ¥${(inv.price/10000)}万`, bX + bW / 2, bY + bH / 2);
      }
    });

    curY += cardH + 10;
  }

  // 3. 大国战略支柱方针切换 (STRATEGIC_PILLARS)
  const pilCardH = 74;
  if (curY + pilCardH >= vTop && curY <= vBottom) {
    ctx.fillStyle = '#131122';
    roundRect(ctx, padX, curY, w, pilCardH, 6, true, true, '#f59e0b', 1);
    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#fef08a';
    ctx.fillText("🏛️ 大国战略支柱聚焦", padX + 10, curY + 8);

    const pBtnW = Math.floor((w - 32) / STRATEGIC_PILLARS.length);
    const curPillar = state.strategicPillar || 'mfg';
    STRATEGIC_PILLARS.forEach((sp, spIdx) => {
      const spX = padX + 10 + spIdx * (pBtnW + 6);
      const isAct = curPillar === sp.key;
      drawTactileButton(ctx, {
        id: `sel_pillar_${sp.key}`,
        x: spX,
        y: curY + 32,
        w: pBtnW,
        h: 32,
        radius: 4,
        bg: isAct ? '#78350f' : '#1e293b',
        border: isAct ? '#f59e0b' : '#475569',
        text: `${sp.icon} ${sp.name.slice(0, 4)}`,
        font: 'bold 14px ' + FONT_UI,
        textColor: isAct ? '#fef08a' : '#cbd5e1',
        isScroll: true,
        priority: 22,
        onClick: () => {
          selectStrategicPillar(sp.key);
        }
      });
    });
  }
  curY += pilCardH + 10;

  // 4. 时代要素行情交割与潘家园古玩雅集 (buyMarketAsset / sellMarketAsset / curio_market)
  const mktCardH = 118;
  if (curY + mktCardH >= vTop && curY <= vBottom) {
    ctx.fillStyle = '#111624';
    roundRect(ctx, padX, curY, w, mktCardH, 6, true, true, '#38bdf8', 1);
    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#7dd3fc';
    ctx.fillText("📊 时代要素份额交割与古玩信托", padX + 10, curY + 8);

    drawTactileButton(ctx, {
      id: 'open_curio_market_btn',
      x: padX + w - 88,
      y: curY + 6,
      w: 78,
      h: 22,
      radius: 4,
      bg: '#78350f',
      border: '#f59e0b',
      text: "🏺 古玩雅集",
      font: 'bold 14px ' + FONT_UI,
      textColor: '#fef08a',
      isScroll: true,
      priority: 24,
      onClick: () => {
        state.activeModal = 'curio_market';
        playSoundEffect('paper');
        requestRender();
      }
    });

    const mktAssets = [
      { key: 'realEstateShares', name: '地皮份额', chgKey: 'realEstateChange' },
      { key: 'techShares', name: '科技份额', chgKey: 'techChange' },
      { key: 'commodityShares', name: '大宗商品', chgKey: 'commodityChange' }
    ];
    const maW = Math.floor((w - 32) / 3);
    mktAssets.forEach((ma, mIdx) => {
      const mx = padX + 10 + mIdx * (maW + 6);
      const my = curY + 34;
      const held = (state.heldAssets && state.heldAssets[ma.key]) || 0;
      const chg = (state.marketTrends && state.marketTrends[ma.chgKey]) || '+5%';
      ctx.textAlign = 'left';
      ctx.font = '13.5px ' + FONT_UI;
      ctx.fillStyle = '#e2e8f0';
      ctx.fillText(`${ma.name}(${chg})`, mx, my);
      ctx.font = '13.5px ' + FONT_MONO;
      ctx.fillStyle = '#94a3b8';
      ctx.fillText(`持仓:¥${(held / 10000).toFixed(0)}w`, mx, my + 16);

      const halfW = Math.floor((maW - 4) / 2);
      drawTactileButton(ctx, {
        id: `mkt_buy_${ma.key}`,
        x: mx,
        y: my + 34,
        w: halfW,
        h: 24,
        radius: 3,
        bg: '#065f46',
        border: '#10b981',
        text: '+2w',
        font: 'bold 14px ' + FONT_MONO,
        textColor: '#fff',
        isScroll: true,
        priority: 22,
        onClick: () => {
          buyMarketAsset(ma.key, 20000);
        }
      });
      drawTactileButton(ctx, {
        id: `mkt_sell_${ma.key}`,
        x: mx + halfW + 4,
        y: my + 34,
        w: halfW,
        h: 24,
        radius: 3,
        bg: '#7f1d1d',
        border: '#ef4444',
        text: '-2w',
        font: 'bold 14px ' + FONT_MONO,
        textColor: '#fff',
        isScroll: true,
        priority: 22,
        onClick: () => {
          sellMarketAsset(ma.key, 20000);
        }
      });
    });
  }
  curY += mktCardH + 10;

  const sExtraH = 40;
  if (curY + sExtraH >= vTop && curY <= vBottom) {
    const sBtnW = Math.floor((w - 8) / 2);
    drawTactileButton(ctx, {
      id: 'open_national_laurel_btn',
      x: padX,
      y: curY,
      w: sBtnW,
      h: sExtraH,
      radius: 6,
      bg: '#231433',
      border: '#f59e0b',
      borderWidth: 1.2,
      text: '🏛️ 大国脊梁 · 功勋荣典',
      font: 'bold 14px ' + FONT_CHRONICLE,
      textColor: '#fef08a',
      isScroll: true,
      priority: 22,
      onClick: () => {
        if (!triggerNationalLaurelCeremony()) {
          state.activeModal = 'national_laurel';
          requestRender();
        }
      }
    });
    drawTactileButton(ctx, {
      id: 'open_century_benchmark_btn',
      x: padX + sBtnW + 8,
      y: curY,
      w: sBtnW,
      h: sExtraH,
      radius: 6,
      bg: '#1c1812',
      border: '#d97706',
      borderWidth: 1.2,
      text: '🌊 世纪答卷 · 历史检验',
      font: 'bold 14px ' + FONT_CHRONICLE,
      textColor: '#fde68a',
      isScroll: true,
      priority: 22,
      onClick: () => {
        if (!triggerCenturyBenchmarkEvent()) {
          state.activeModal = 'century_benchmark';
          requestRender();
        }
      }
    });
  }
  curY += sExtraH + 10;

  ctx.restore();
  return curY;
}

// ------------------------------------------
// 10.5 底部年度操作栏与推进按钮
// ------------------------------------------
function drawActionBar() {
  ctx.save();
  const barY = screenHeight - getBottomDockTotalH() - actionBarH;
  const padX = 12;
  const w = screenWidth - padX * 2;

  // 1. 自动巡航挂机开关与变速
  const autoBtnW = 74;
  const autoBtnH = 34;
  const autoBtnX = padX;
  const autoBtnY = barY + (actionBarH - autoBtnH) / 2;

  drawTactileButton(ctx, {
    id: 'toggle_autoplay_btn',
    x: autoBtnX,
    y: autoBtnY,
    w: autoBtnW,
    h: autoBtnH,
    radius: 6,
    bg: state.isPlaying ? '#7f1d1d' : '#1e293b',
    border: state.isPlaying ? '#ef4444' : '#475569',
    borderWidth: 1,
    text: state.isPlaying ? "⏸ 暂停" : "▶ 巡航",
    font: 'bold 14px ' + FONT_UI,
    textColor: state.isPlaying ? '#fca5a5' : '#cbd5e1',
    priority: 10,
    onClick: () => {
      togglePlayPause();
    }
  });

  // 倍速切换
  const spdBtnW = 42;
  const spdBtnX = autoBtnX + autoBtnW + 6;

  drawTactileButton(ctx, {
    id: 'cycle_speed_btn',
    x: spdBtnX,
    y: autoBtnY,
    w: spdBtnW,
    h: autoBtnH,
    radius: 6,
    bg: '#1e293b',
    border: '#f59e0b',
    borderWidth: 1,
    text: state.playSpeed + 'x',
    font: 'bold 14px ' + FONT_UI,
    textColor: '#fef08a',
    priority: 10,
    onClick: () => {
      cyclePlaySpeed();
    }
  });

  // 2. 踏入下一年度核心大按钮
  const nextBtnX = spdBtnX + spdBtnW + 8;
  const nextBtnW = padX + w - nextBtnX;
  const nextBtnH = 36;
  const nextBtnY = barY + (actionBarH - nextBtnH) / 2;

  let labelText = (state.ap || 0) > 0
    ? `迈入下一年 (余 ${state.ap}⚡) ➔`
    : `辞旧迎新 · 迈入 ${(state.year || 1990) + 1} 年 ➔`;
  if (state.age < 18) {
    const nextStep = typeof getChildhoodNextStep === 'function' ? getChildhoodNextStep(state.age) : 1;
    const targetAge = state.age + nextStep;
    if (state.age === 0) {
      labelText = "满周岁 · 抓周礼 ➔";
    } else if (targetAge === 6) {
      labelText = "光阴箭催 · 六岁发蒙入小学 ➔";
    } else if (targetAge === 10) {
      labelText = "光阴箭催 · 十岁少年立志 ➔";
    } else if (targetAge === 12) {
      labelText = "光阴箭催 · 十二岁升入初中 ➔";
    } else if (targetAge === 15) {
      labelText = "光阴箭催 · 十五岁人生分流 ➔";
    } else if (targetAge >= 18) {
      if (state.youthPath === 'vocational') {
        labelText = "🏭 期满出徒 · 进厂报到 ➔";
      } else if (state.youthPath === 'military') {
        labelText = "🪖 戴上红花 · 应征入伍 ➔";
      } else if (state.youthPath === 'commerce') {
        labelText = "🚢 背起行囊 · 闯荡商海 ➔";
      } else if (state.youthPath === 'agri') {
        labelText = "🌾 扎根乡土 · 农站报到 ➔";
      } else {
        labelText = "🎓 弱冠成丁 · 奔赴高考放榜 ➔";
      }
    } else if (nextStep > 1) {
      labelText = `光阴箭催 · 两年一跃 (${targetAge}岁) ➔`;
    } else if ((state.ap || 0) > 0) {
      labelText = `迈入下一岁 (余 ${state.ap}⚡) ➔`;
    } else {
      labelText = `寒暑流转 · 迈入 ${targetAge} 岁 ➔`;
    }
  }

  const isRapidActive = typeof isRapidAdvancing !== 'undefined' && isRapidAdvancing;

  // 3.0 未成年阶段跳过按钮：二周目金色常驻浮窗 (NG+ Fast-forward after Zhuazhou)
  if (state.age < 18 && !state.activeModal && !state.endgameSettled) {
    const isNGPlus = (state.lifetimeRunCount > 1 || (state.unlockedEndings && state.unlockedEndings.length > 0) || (typeof getUnlockedEndings === 'function' && getUnlockedEndings().length > 0));
    if (isNGPlus && state.age >= 1 && state.zhuazhouItem) {
      const tipH = 30;
      const tipY = nextBtnY - tipH - 7;
      const tipW = Math.min(nextBtnW + 48, screenWidth - 24);
      const tipX = Math.max(12, nextBtnX + nextBtnW - tipW);

      drawTactileButton(ctx, {
        id: 'ng_plus_skip_childhood_btn',
        x: tipX,
        y: tipY,
        w: tipW,
        h: tipH,
        radius: 15,
        bg: 'rgba(42, 26, 10, 0.96)',
        border: '#f59e0b',
        borderWidth: 1.5,
        text: "⚡ 承此志向 · 直跃18岁高考放榜 ➔",
        font: 'bold 11px ' + FONT_UI,
        textColor: '#fbbf24',
        shadowColor: 'rgba(245, 158, 11, 0.35)',
        shadowBlur: 8,
        priority: 45,
        onClick: () => {
          triggerHaptic('medium');
          playSoundEffect('gold');
          skipChildhoodToAdulthood();
        }
      });
    } else if (state.age >= 6) {
      const tipH = 26;
      const tipY = nextBtnY - tipH - 6;
      const tipW = Math.min(nextBtnW + 32, screenWidth - 24);
      const tipX = Math.max(12, nextBtnX + nextBtnW - tipW);

      drawTactileButton(ctx, {
        id: 'skip_childhood_quick_btn',
        x: tipX,
        y: tipY,
        w: tipW,
        h: tipH,
        radius: 13,
        bg: 'rgba(30, 41, 59, 0.92)',
        border: '#475569',
        borderWidth: 1,
        text: "⚡ 历练已丰 · 直跃成年及冠 ➔",
        font: '10px ' + FONT_UI,
        textColor: '#94a3b8',
        priority: 35,
        onClick: () => {
          skipChildhoodToAdulthood();
        }
      });
    }
  }

  // 3. 成年阶段首次长按快进强引导浮窗 (Adulthood Long-press Fast-forward Discovery Prompt)
  const showFfGuide = state.age >= 18 && !state.fastForwardTutorialDismissed && !state.activeModal && !state.endgameSettled;
  if (showFfGuide) {
    const tipH = 32;
    const tipY = nextBtnY - tipH - 8;
    const tipW = Math.min(nextBtnW + 42, screenWidth - 24);
    const tipX = Math.max(12, nextBtnX + nextBtnW - tipW);

    ctx.save();
    ctx.fillStyle = 'rgba(15, 23, 42, 0.96)';
    roundRect(ctx, tipX, tipY, tipW, tipH, 6, true, true, '#f59e0b', 1.5);

    // 下方指示小三角
    const arrowX = nextBtnX + nextBtnW / 2;
    const bounceY = Math.sin(Date.now() * 0.008) * 2;
    ctx.fillStyle = '#f59e0b';
    ctx.beginPath();
    ctx.moveTo(arrowX - 5, tipY + tipH);
    ctx.lineTo(arrowX + 5, tipY + tipH);
    ctx.lineTo(arrowX, tipY + tipH + 5 + bounceY);
    ctx.closePath();
    ctx.fill();

    // 引导文案与关闭按钮
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';
    ctx.font = 'bold 11.5px ' + FONT_UI;
    ctx.fillStyle = '#fef08a';
    ctx.fillText("⚡ 长按此键可【岁月快进】· 关口自停", tipX + 8, tipY + tipH / 2);

    const dismissText = "〔知晓✕〕";
    ctx.font = '11px ' + FONT_UI;
    const disW = ctx.measureText(dismissText).width + 6;
    const disX = tipX + tipW - disW - 6;
    ctx.fillStyle = '#94a3b8';
    ctx.fillText(dismissText, disX, tipY + tipH / 2);

    registerHitbox('ff_tutorial_dismiss', disX - 4, tipY, disW + 8, tipH, () => {
      state.fastForwardTutorialDismissed = true;
      try {
        if (typeof tt !== 'undefined' && tt.setStorageSync) tt.setStorageSync('lifesim_ff_tutorial_seen', true);
        if (typeof wx !== 'undefined' && wx.setStorageSync) wx.setStorageSync('lifesim_ff_tutorial_seen', true);
      } catch (_) {}
      triggerHaptic('light');
      playSoundEffect('click');
      requestRender();
    }, 40);

    ctx.restore();
  }

  const btnBorder = isRapidActive ? '#fef08a' : (showFfGuide ? '#fde047' : '#f59e0b');
  const btnBorderW = (isRapidActive || showFfGuide) ? 2.0 : 1.5;
  const btnDisplayText = isRapidActive
    ? "⚡ 岁月流转中 · 点击暂停 ⚡"
    : (showFfGuide ? labelText + " (长按速推⚡)" : labelText);

  drawTactileButton(ctx, {
    id: 'tick_year_btn',
    x: nextBtnX,
    y: nextBtnY,
    w: nextBtnW,
    h: nextBtnH,
    radius: 8,
    bg: isRapidActive ? '#b91c1c' : '#991b1b',
    border: btnBorder,
    borderWidth: btnBorderW,
    text: btnDisplayText,
    font: 'bold 14px ' + FONT_CHRONICLE,
    textColor: '#fef08a',
    priority: 10,
    onClick: () => {
      if (!state.fastForwardTutorialDismissed && state.age >= 18) {
        state.fastForwardTutorialDismissed = true;
        try {
          if (typeof tt !== 'undefined' && tt.setStorageSync) tt.setStorageSync('lifesim_ff_tutorial_seen', true);
          if (typeof wx !== 'undefined' && wx.setStorageSync) wx.setStorageSync('lifesim_ff_tutorial_seen', true);
        } catch (_) {}
      }
      if (typeof isRapidAdvancing !== 'undefined' && isRapidAdvancing) {
        stopRapidAdvance();
        showToast("⏸ 已暂停岁月推进", "info");
        return;
      }
      tickOneYear();
    }
  });

  ctx.restore();
}

function _hasDockTabBadge(key) {
  if (key === 'strategy') {
    return (state.talentPoints || 0) > 0;
  } else if (key === 'desk') {
    return state.age >= 18 && (state.ap || 0) > 0;
  } else if (key === 'timeline') {
    return state.age >= 3 && state.age < 18 && (state.ap || 0) > 0;
  }
  return false;
}

function drawDockNav() {
  ctx.save();
  const dockY = screenHeight - getBottomDockTotalH();

  ctx.fillStyle = '#080a12';
  ctx.fillRect(0, dockY, screenWidth, getBottomDockTotalH());

  // 顶部发光微边线
  ctx.strokeStyle = '#2d253b';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(0, dockY);
  ctx.lineTo(screenWidth, dockY);
  ctx.stroke();

  const activeTabs = getActiveDockTabs(state ? state.age : 0);
  const tabW = screenWidth / Math.max(1, activeTabs.length);
  for (let i = 0; i < activeTabs.length; i++) {
    const tb = activeTabs[i];
    const tx = i * tabW;
    const isAct = state.activeTab === tb.key;

    drawTactileButton(ctx, {
      id: 'tab_' + tb.key,
      x: tx,
      y: dockY,
      w: tabW,
      h: dockNavH,
      bg: 'transparent',
      border: null,
      priority: 10,
      onClick: () => {
        switchTab(tb.key);
      },
      renderContent: (c, isPressed) => {
        if (isAct || isPressed) {
          c.fillStyle = isPressed ? 'rgba(245, 158, 11, 0.22)' : 'rgba(245, 158, 11, 0.12)';
          roundRect(c, tx + 4, dockY + 4, tabW - 8, dockNavH - 8, 6, true, false);

          c.fillStyle = '#f59e0b';
          c.fillRect(tx + tabW / 2 - 10, dockY + 2, 20, 2);
        }

        c.textAlign = 'center';
        c.textBaseline = 'top';
        c.font = '16px sans-serif';
        c.fillText(tb.icon, tx + tabW / 2, dockY + 8);

        c.font = isAct ? 'bold 15px ' + FONT_UI : '15px ' + FONT_UI;
        c.fillStyle = isAct ? '#fef08a' : (isPressed ? '#cbd5e1' : '#64748b');
        c.fillText(tb.label, tx + tabW / 2, dockY + 28);

        if (_hasDockTabBadge(tb.key)) {
          c.fillStyle = '#ef4444';
          c.beginPath();
          c.arc(tx + tabW / 2 + 13, dockY + 8, 3, 0, Math.PI * 2);
          c.fill();
        }
      }
    });
  }

  ctx.restore();
}

// ------------------------------------------
// 10.7 模态弹窗系统 (最高覆盖层)
// ------------------------------------------

// ==========================================
// 10.7.10 时代宿敌巅峰对弈决断弹窗 (Rival Showdown Modal)
// ==========================================
function drawRivalShowdownModal() {
  const rival = state.activeRival;
  if (!rival) return;

  const cardW = screenWidth - 28;
  const cardH = 460;
  const cardX = 14;
  const cardY = Math.max(10, Math.round((screenHeight - cardH) / 2));

  // 肃杀深红暗夜底色
  ctx.fillStyle = '#1c0d13';
  roundRect(ctx, cardX, cardY, cardW, cardH, 12, true, true, '#ef4444', 2);
  drawCornerOrnaments(ctx, cardX, cardY, cardW, cardH, 8, '#f87171');

  // 顶部警告旗标
  ctx.fillStyle = '#7f1d1d';
  roundRect(ctx, cardX + 24, cardY + 12, cardW - 48, 24, 4, true, true, '#dc2626', 1);
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.font = 'bold 14px ' + FONT_UI;
  ctx.fillStyle = '#fee2e2';
  ctx.fillText("⚔️ 时代宿敌对弈 · 决断命运之战 ⚔️", screenWidth / 2, cardY + 24);

  // 宿敌头像与头衔
  ctx.textAlign = 'center';
  ctx.font = '26px sans-serif';
  ctx.fillText(rival.avatar || '👤', screenWidth / 2, cardY + 54);

  ctx.font = 'bold 14px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText(rival.name, screenWidth / 2, cardY + 80);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#fca5a5';
  ctx.fillText(rival.title, screenWidth / 2, cardY + 98);

  // 挑战背景卡
  ctx.fillStyle = '#2a111a';
  roundRect(ctx, cardX + 16, cardY + 114, cardW - 32, 74, 6, true, true, '#991b1b', 1);

  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 14px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#f87171';
  ctx.fillText(rival.challengeTitle, cardX + 24, cardY + 122);

  ctx.font = '13.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fecaca';
  const cLines = wrapTextLines(rival.challengeDesc, cardW - 52, '13.5px ' + FONT_CHRONICLE);
  const cLimit = Math.min(3, cLines.length);
  for (let i = 0; i < cLimit; i++) {
    ctx.fillText(cLines[i], cardX + 24, cardY + 140 + i * 14);
  }

  // 3 项反制决断分支
  let optY = cardY + 196;
  (rival.options || []).forEach((opt, idx) => {
    const optH = 76;
    ctx.fillStyle = '#241219';
    roundRect(ctx, cardX + 16, optY, cardW - 32, optH, 6, true, true, '#b91c1c', 1);

    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#fef08a';
    ctx.fillText(opt.title, cardX + 24, optY + 8);

    ctx.font = '13.5px ' + FONT_UI;
    ctx.fillStyle = '#94a3b8';
    const attrMap = { clean: '清廉操守', iq: '大局智谋', eq: '人情练达', courage: '担当魄力', rep: '时代声誉' };
    const attrName = attrMap[opt.reqAttr] || opt.reqAttr;
    const pVal = state[opt.reqAttr] || 60;
    ctx.fillText(`门槛: ${attrName} ≥ ${opt.reqVal} (当前 ${pVal}) | 胜算: ${opt.successRate}%`, cardX + 24, optY + 26);

    ctx.font = '13.5px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#cbd5e1';
    ctx.fillText(fitText(opt.successText, cardW - 56, '13.5px ' + FONT_CHRONICLE), cardX + 24, optY + 40);

    // 决断反击按钮
    const bW = cardW - 48;
    const bH = 22;
    const bx = cardX + 24;
    const by = optY + optH - bH - 4;

    drawTactileButton(ctx, {
      id: `rival_opt_${idx}`,
      x: bx,
      y: by,
      w: bW,
      h: bH,
      radius: 4,
      bg: '#991b1b',
      border: '#ef4444',
      borderWidth: 1,
      text: "⚔️ 施展此韬略破敌反制",
      font: 'bold 14px ' + FONT_UI,
      textColor: '#fee2e2',
      priority: 120,
      onClick: () => {
        const curAttr = state[opt.reqAttr] || 60;
        let finalRate = opt.successRate || 75;
        if (curAttr >= opt.reqVal) finalRate = Math.min(98, finalRate + 15);
        if (hasTalent('breakthrough')) finalRate = Math.min(98, finalRate + 5);
        if (hasHeirloom('heirloom_notes')) finalRate = Math.min(98, finalRate + 10);

        const isSuccess = seededRandom() * 100 <= finalRate;
        state.activeModal = null;
        state.activeRival = null;

        if (isSuccess) {
          playSoundEffect('fanfare');
          triggerHaptic('heavy');
          spawnDustParticles(screenWidth / 2, screenHeight / 2, '#f59e0b', 32);
          if (typeof opt.onSuccess === 'function') opt.onSuccess(state);
          showToast(`🎉 成功击溃宿敌【${rival.name}】！声望大噪！`, 'gold');
          addChronicleItem(state.age, state.year, `【荡平宿敌】以绝对实力瓦解了宿敌【${rival.name}】发起的《${rival.challengeTitle}》！全行业为之侧目！`, "宿敌博弈", "promo");
          if (rival.rewardHeirloom) {
            unlockHeirloom(rival.rewardHeirloom);
          }
        } else {
          playSoundEffect('alert');
          triggerHaptic('medium');
          addStat("rep", -6, 10);
          addStat("health", -5, 10);
          showToast(`反制受阻，被宿敌【${rival.name}】牵制波及！`, 'alert');
          addChronicleItem(state.age, state.year, `【博弈曲折】在与宿敌【${rival.name}】的《${rival.challengeTitle}》交锋中遭遇阻滞，声誉与精力受损。`, "博弈曲折", "crisis");
        }
        requestRender();
      }
    });

    optY += optH + 8;
  });
}


// ==========================================
// 10.7.11 家国春秋 · 宗族府邸与后代培优弹窗 (Family Estate Modal)
// ==========================================


function drawFamilyEstateModal() {
  const cardW = screenWidth - 28;
  const cardH = 460;
  const cardX = 14;
  const cardY = Math.max(10, Math.round((screenHeight - cardH) / 2));

  // 古典紫檀祥云底色
  ctx.fillStyle = '#16111e';
  roundRect(ctx, cardX, cardY, cardW, cardH, 12, true, true, '#d97706', 2);
  drawCornerOrnaments(ctx, cardX, cardY, cardW, cardH, 8, '#f59e0b');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 16px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText("🏡 家国春秋 · 宗族门风与后院修身", screenWidth / 2, cardY + 12);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#94a3b8';
  const f = state.family || {};
  ctx.fillText(`府邸：【${f.residenceName || '石库门祖居'}】(Lv.${f.residenceLevel || 1}) · 门第声望: ${f.prestige || 45}`, screenWidth / 2, cardY + 34);

  // 1. 堂前家训牌匾
  const mottoY = cardY + 52;
  ctx.fillStyle = '#221929';
  roundRect(ctx, cardX + 16, mottoY, cardW - 32, 44, 6, true, true, '#9333ea', 1);

  ctx.textAlign = 'center';
  ctx.font = 'bold 14px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText(`“ ${f.motto || '耕读传家 · 崇实守正'} ”`, screenWidth / 2, mottoY + 10);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#c084fc';
  ctx.fillText("家风纯正 · 子孙蒙荫 · 涵养身心底蕴并深得名仕敬重", screenWidth / 2, mottoY + 26);

  // 2. 子女前程与培优专栏
  const childY = mottoY + 52;
  const childH = 150;
  ctx.fillStyle = '#0f111c';
  roundRect(ctx, cardX + 16, childY, cardW - 32, childH, 8, true, true, '#334155', 1);

  const hasChildEstate = (f.children && f.children.length > 0) || !!f.childName;
  const firstChildEstate = (f.children && f.children.length > 0) ? f.children[0] : null;
  const childAge = firstChildEstate && firstChildEstate.birthYear ? Math.max(0, state.year - firstChildEstate.birthYear) : Math.max(1, state.age - 26);
  const dispChildName = f.childName || (firstChildEstate && firstChildEstate.name) || '';

  ctx.textAlign = 'left';
  ctx.font = 'bold 14px ' + FONT_UI;
  ctx.fillStyle = '#fef08a';
  if (hasChildEstate) {
    ctx.fillText(`✦ 子嗣培育：【${dispChildName}】(${childAge}岁) · 学力 Lv.${f.educationLevel || 1}/5 ✦`, cardX + 26, childY + 10);
  } else {
    ctx.fillText(`✦ 子嗣培育：膝下尚无子嗣 · 静候成家立业喜添麟儿 ✦`, cardX + 26, childY + 10);
  }

  ctx.font = '13.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#cbd5e1';
  let descText = hasChildEstate ? "少年求学期：崇尚诗书，稳步筑基通识与品德素养。" : "青年打拼期：先行涵养家风、积蓄门第基业，为未来后辈打下坚实根基。";
  if (hasChildEstate && f.educationLevel >= 4) descText = "国家重点名校拔尖新秀：屡获奥赛与创新大奖，前途不可限量！";
  else if (hasChildEstate && f.educationLevel >= 2) descText = "省属重点学府优等生：兼顾文理，积极参与社会调查与实践。";
  ctx.fillText(descText, cardX + 26, childY + 28);

  // 培优指令 1: 名师私塾培优 (-¥2万, 1⚡)
  const btn1Y = childY + 48;
  const actW = cardW - 52;
  drawTactileButton(ctx, {
    id: 'family_act_study',
    x: cardX + 26,
    y: btn1Y,
    w: actW,
    h: 40,
    radius: 5,
    bg: '#1e1b2e',
    border: hasChildEstate ? '#38bdf8' : '#475569',
    priority: 120,
    onClick: () => {
      if (!hasChildEstate) { showToast("膝下尚无子嗣，待喜添麟儿后再延请名师培优！", "info"); return; }
      if (f.educationLevel >= 5) { showToast("子嗣教育已达满级 Lv.5！", "info"); return; }
      if (state.ap < 1) { showToast("当年精力不足！", "alert"); return; }
      if (state.capital < 20000) { showToast("结余资金不足 ¥20,000！", "alert"); return; }
      state.ap--;
      state.capital -= 20000;
      f.educationLevel = Math.min(5, (f.educationLevel || 1) + 1);
      addStat("iq", 3, 0);
      addStat("rep", 3, 0);
      progressThreeYearPact(12, '名师私塾培优');
      playSoundEffect('paper');
      showToast(`名师悉心点拨！子嗣教育提升至 Lv.${f.educationLevel}！`, 'gold');
      addChronicleItem(state.age, state.year, `【名师培优】延请特级名师为子嗣【${dispChildName}】悉心辅导，学力升至 Lv.${f.educationLevel}。`, "子嗣成长", "promo");
      requestRender();
    },
    renderContent: (c) => {
      c.textAlign = 'left';
      c.font = 'bold 14px ' + FONT_CHRONICLE;
      c.fillStyle = hasChildEstate ? '#f8fafc' : '#94a3b8';
      c.fillText(hasChildEstate ? "📖 延请名师私塾培优 (-¥2万, 消耗1⚡)" : "📖 名师私塾培优 (待育有子嗣后开启)", cardX + 34, btn1Y + 8);
      c.font = '13.5px ' + FONT_UI;
      c.fillStyle = hasChildEstate ? '#38bdf8' : '#64748b';
      c.fillText("教育学力+1 · 大局智谋+3 · 荣誉声誉+3", cardX + 34, btn1Y + 24);
    }
  });

  // 培优指令 2: 言传身教亲授家风 (消耗 1⚡)
  const btn2Y = btn1Y + 46;
  drawTactileButton(ctx, {
    id: 'family_act_teach',
    x: cardX + 26,
    y: btn2Y,
    w: actW,
    h: 40,
    radius: 5,
    bg: '#1e1b2e',
    border: '#10b981',
    priority: 120,
    onClick: () => {
      if (state.ap < 1) { showToast("当年精力不足！", "alert"); return; }
      if (state.lastFamilyTeachYear === state.year) { showToast("本年度已在书房涵养家风，请明年再续！", "info"); return; }
      state.ap--;
      state.lastFamilyTeachYear = state.year;
      addStat("clean", 4, 0);
      addStat("eq", 4, 0);
      f.prestige = (f.prestige || 15) + 5;
      progressThreeYearPact(12, '言传身教亲授家风');
      playSoundEffect('tea');
      showToast("家风浩然长存！清廉+4，人情+4，门望+5！", 'good');
      addChronicleItem(state.age, state.year, hasChildEstate ? `【清风传家】于书房与子嗣【${dispChildName}】围炉夜话、传授修身齐家准则。` : "【修身立训】于书房静思省身、手书治家格言，涵养清正门风。", "家国春秋", "history");
      requestRender();
    },
    renderContent: (c) => {
      c.textAlign = 'left';
      c.font = 'bold 14px ' + FONT_CHRONICLE;
      c.fillStyle = '#f8fafc';
      c.fillText(hasChildEstate ? "🌿 案头言传身教亲授家风 (消耗1⚡)" : "🌿 书房涵养门风手书格言 (消耗1⚡)", cardX + 34, btn2Y + 8);
      c.font = '13.5px ' + FONT_UI;
      c.fillStyle = '#34d399';
      c.fillText("清廉操守+4 · 人情练达+4 · 门第声望+5", cardX + 34, btn2Y + 24);
    }
  });

  // 3. 家族信托与府邸晋升
  const trustY = childY + childH + 10;
  const trustH = 120;
  ctx.fillStyle = '#0f111c';
  roundRect(ctx, cardX + 16, trustY, cardW - 32, trustH, 8, true, true, '#334155', 1);

  ctx.textAlign = 'left';
  ctx.font = 'bold 14px ' + FONT_UI;
  ctx.fillStyle = '#fef08a';
  ctx.fillText(`✦ 家族信托与府邸修缮 (信托现存: ¥${(f.endowmentFund || 0).toLocaleString()}) ✦`, cardX + 26, trustY + 10);

  // 按钮 1: 注资教育信托
  const tBtn1Y = trustY + 30;
  drawTactileButton(ctx, {
    id: 'family_act_trust',
    x: cardX + 26,
    y: tBtn1Y,
    w: actW,
    h: 36,
    radius: 4,
    bg: '#1e1b2e',
    border: '#f59e0b',
    text: "💰 注资信托基金 ¥50,000 (1⚡) · 永续分红收益",
    font: 'bold 14px ' + FONT_CHRONICLE,
    textColor: '#fef08a',
    priority: 120,
    onClick: () => {
      if (state.ap < 1) { showToast("当年精力不足！", "alert"); return; }
      if (state.capital < 50000) { showToast("结余资金不足 ¥50,000！", "alert"); return; }
      state.ap--;
      state.capital -= 50000;
      f.endowmentFund = (f.endowmentFund || 0) + 50000;
      f.prestige = (f.prestige || 15) + 10;
      progressThreeYearPact(12, '注资家族信托');
      playSoundEffect('coin');
      showToast("成功注资信托！信托规模扩充 ¥50,000！", 'gold');
      addChronicleItem(state.age, state.year, "【家族信托】注资家族教育信托基金，保障后代数代求学深造与实业创业。", "信托基石", "promo");
      requestRender();
    }
  });

  // 按钮 2: 府邸晋升
  const tBtn2Y = tBtn1Y + 42;
  const nextResName = f.residenceLevel === 1 ? "机关福利商品房" : (f.residenceLevel === 2 ? "核心区花园洋房" : "钟鸣鼎食林泉庄园");
  const costRes = (f.residenceLevel || 1) * 80000;
  drawTactileButton(ctx, {
    id: 'family_act_upgrade_res',
    x: cardX + 26,
    y: tBtn2Y,
    w: actW,
    h: 36,
    radius: 4,
    bg: '#1e1b2e',
    border: '#10b981',
    text: `🏡 府邸迁居至【${nextResName}】(-¥${(costRes/10000)}万)`,
    font: 'bold 14px ' + FONT_CHRONICLE,
    textColor: '#a7f3d0',
    priority: 120,
    onClick: () => {
      if (f.residenceLevel >= 4) { showToast("府邸已达最高林泉庄园境界！", "info"); return; }
      if (state.capital < costRes) { showToast(`资金不足 ¥${costRes.toLocaleString()}！`, "alert"); return; }
      state.capital -= costRes;
      f.residenceLevel = (f.residenceLevel || 1) + 1;
      f.livingLevel = f.residenceLevel;
      f.residenceName = nextResName;
      f.prestige = (f.prestige || 15) + 20;
      addStat("health", 10, 0);
      playSoundEffect('fanfare');
      triggerHaptic('heavy');
      showToast(`府邸迁居升格为【${nextResName}】！门望+20，身心回润！`, 'gold');
      addChronicleItem(state.age, state.year, `【府邸迁居】家族迁入【${nextResName}】，门庭光耀，宗族名望享誉一方。`, "华堂落成", "promo");
      requestRender();
    }
  });

  // 4. 关闭按钮
  const cBtnW = cardW - 48;
  const cBtnH = 34;
  const cBtnX = cardX + 24;
  const cBtnY = cardY + cardH - cBtnH - 10;

  drawTactileButton(ctx, {
    id: 'close_family_estate',
    x: cBtnX,
    y: cBtnY,
    w: cBtnW,
    h: cBtnH,
    radius: 6,
    bg: '#b91c1c',
    border: '#ef4444',
    text: "合上家门 · 履职国事 ➔",
    font: 'bold 14px ' + FONT_CHRONICLE,
    textColor: '#fff',
    priority: 100,
    onClick: () => {
      state.activeModal = null;
      state.activeFamilyEvent = null;
      playSoundEffect('click');
      requestRender();
    }
  });
}


// 名仕知己茶室夜话与煮酒论道交互系统 (Tea-House Banquets & Oath of Brotherhood)
function openTeaBanquetsModal(contact) {
  state.activeTeaContact = contact || (state.contacts && state.contacts[0]) || ENSEMBLE_CHARACTERS[0];
  state.activeModal = 'tea_banquet';
  playSoundEffect('bell');
  triggerHaptic('medium');
  requestRender();
}

function drawTeaBanquetsModal() {
  const cardW = screenWidth - 28;
  const cardH = 435;
  const cardX = 14;
  const cardY = Math.max(20, Math.round((screenHeight - cardH) / 2));
  const contact = state.activeTeaContact || ENSEMBLE_CHARACTERS[0];

  ctx.fillStyle = '#16111f';
  roundRect(ctx, cardX, cardY, cardW, cardH, 12, true, true, '#d97706', 2);
  drawCornerOrnaments(ctx, cardX, cardY, cardW, cardH, 8, '#f59e0b');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 17px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText("🏮 茶室夜话 · 煮酒论道", screenWidth / 2, cardY + 16);

  ctx.font = '13.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#cbd5e1';
  ctx.fillText(`客座名仕：【${contact.name}】· ${contact.role}`, screenWidth / 2, cardY + 42);

  // 茶案环境卡片
  const envH = 74;
  const envY = cardY + 68;
  ctx.fillStyle = '#221526';
  roundRect(ctx, cardX + 16, envY, cardW - 32, envH, 6, true, true, '#f59e0b', 1);

  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.font = '28px sans-serif';
  ctx.fillText(contact.avatar || '🍵', cardX + 26, envY + 16);

  ctx.font = 'bold 14px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText(`${contact.name} (${contact.isSwornGuardian ? '🛡️ 莫逆同盟' : '友好名仕'})`, cardX + 70, envY + 14);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#94a3b8';
  ctx.fillText(fitText(`“月朗泉清，推杯品茗。天下大势与机要玄机，尽付杯盏之中。”`, cardW - 96, '13.5px ' + FONT_UI), cardX + 70, envY + 34);
  ctx.fillStyle = '#fbbf24';
  ctx.fillText(`当前默契交情：${contact.affinity || 45}/100`, cardX + 70, envY + 52);

  // 3 大茶室交互选项
  const optH = 64;
  const optStartY = envY + envH + 12;
  const teaOptions = [
    {
      key: 'tea_insight',
      title: '🍵 品茗探风 (消耗 1 ⚡ 精力)',
      desc: '促膝长谈，洞察宏观考核动向与政策风向。悟性+4，情商+3，好感+10。',
      action: () => {
        if (contact.lastTeaYear === state.year) {
          showToast(`今年已与【${contact.name}】在茶室深谈过，请明年再约！`, "info");
          return;
        }
        if (state.ap < 1) {
          showToast("今年精力已耗尽，请先迈入下一年！", "alert");
          playSoundEffect('alert');
          return;
        }
        state.ap--;
        contact.lastTeaYear = state.year;
        contact.affinity = Math.min(100, (contact.affinity || 45) + 10);
        addStat("iq", 4, 0);
        addStat("eq", 3, 0);
        addStat("rep", 2, 0);
        progressThreeYearPact(12, `茶室品茗·${contact.name}`);
        playSoundEffect('bell');
        showToast("茶香扑鼻，名仕指点迷津！悟性+4，情商+3！", "good");
        addChronicleItem(state.age, state.year, `【茶室夜话】与名仕【${contact.name}】煮茗深谈，洞察政策风向与大局先机。`, "名仕结交", "promo");
        requestRender();
      }
    },
    {
      key: 'tea_brotherhood',
      title: '🍶 煮酒盟誓 (消耗 1 ⚡ 精力)',
      desc: '畅叙生平抱负，风雨同舟。好感+15，交情达85可缔结【莫逆金兰同盟】！',
      action: () => {
        if (contact.lastTeaYear === state.year) {
          showToast(`今年已与【${contact.name}】在茶室深谈过，请明年再约！`, "info");
          return;
        }
        if (state.ap < 1) {
          showToast("今年精力已耗尽，请先迈入下一年！", "alert");
          playSoundEffect('alert');
          return;
        }
        state.ap--;
        contact.lastTeaYear = state.year;
        contact.affinity = Math.min(100, (contact.affinity || 45) + 15);
        progressThreeYearPact(12, `煮酒盟誓·${contact.name}`);
        if (contact.affinity >= 85 && !contact.isSwornGuardian) {
          contact.isSwornGuardian = true;
          addStat("rep", 8, 0);
          playSoundEffect('fanfare');
          showToast(`倾盖如故！与【${contact.name}】正式缔结为莫逆金兰同盟！`, "gold");
          addChronicleItem(state.age, state.year, `【莫逆之交】与名仕【${contact.name}】煮酒论英雄，推心置腹正式缔结为莫逆挚友！`, "莫逆金兰同盟", "promo");
        } else {
          playSoundEffect('fanfare');
          showToast("豪气干云！双方交情提升+15！", "gold");
        }
        requestRender();
      }
    },
    {
      key: 'tea_joint_venture',
      title: '🤝 联合课题与产业协作 (消耗 1 ⚡ · 投入 ¥20,000)',
      desc: '共同出资推进技术攻关或实业协作。成败取决于双方智谋与市场周期。',
      action: () => {
        if (contact.lastTeaYear === state.year) {
          showToast(`今年已与【${contact.name}】在茶室深谈过，请明年再约！`, "info");
          return;
        }
        if (state.ap < 1) {
          showToast("今年精力已耗尽，请先迈入下一年！", "alert");
          playSoundEffect('alert');
          return;
        }
        if (state.capital < 20000) {
          showToast("资金储备不足 ¥20,000！", "alert");
          playSoundEffect('alert');
          return;
        }
        state.ap--;
        contact.lastTeaYear = state.year;
        state.capital -= 20000;
        progressThreeYearPact(15, `产业协作·${contact.name}`);
        const successProb = Math.min(0.82, 0.45 + ((state.iq || 50) - 50) * 0.005 + ((contact.affinity || 45) / 250));
        if (seededRandom() < successProb) {
          state.capital += 28000;
          addStat("rep", 4, 0);
          playSoundEffect('coin');
          showToast("协作顺利结项！收回本金并获净收益 ¥8,000，声誉+4！", "good");
          addChronicleItem(state.age, state.year, `【产业协作】与【${contact.name}】联合推进协作项目顺利结项，斩获实业回报！`, "携手共进", "promo");
        } else {
          state.capital += 15000;
          addStat("resilience", 2, 0);
          playSoundEffect('alert');
          showToast("市场周期波动！协作项目小幅折损 ¥5,000，抗逆+2！", "alert");
          addChronicleItem(state.age, state.year, `【协作磨砺】与【${contact.name}】联合推进项目遭遇周期波动，虽小有折损但积累了宝贵经验。`, "实业历练", "history");
        }
        requestRender();
      }
    }
  ];

  teaOptions.forEach((opt, idx) => {
    const oy = optStartY + idx * (optH + 8);
    drawTactileButton(ctx, {
      id: `tea_opt_${opt.key}`,
      x: cardX + 16,
      y: oy,
      w: cardW - 32,
      h: optH,
      radius: 6,
      bg: '#201930',
      border: '#475569',
      borderWidth: 1,
      priority: 100,
      renderContent: (c) => {
        c.textAlign = 'left';
        c.textBaseline = 'top';
        c.font = 'bold 14px ' + FONT_CHRONICLE;
        c.fillStyle = '#fef08a';
        c.fillText(fitText(opt.title, cardW - 56, 'bold 14px ' + FONT_CHRONICLE), cardX + 28, oy + 10);

        c.font = '13.5px ' + FONT_UI;
        c.fillStyle = '#cbd5e1';
        c.fillText(fitText(opt.desc, cardW - 56, '13.5px ' + FONT_UI), cardX + 28, oy + 32);
      },
      onClick: () => {
        opt.action();
      }
    });
  });

  // 底部席间博弈与起身告辞双按钮
  const bottomBtnW = (cardW - 44) / 2;
  const closeBtnH = 34;
  const closeBtnY = cardY + cardH - closeBtnH - 14;

  drawTactileButton(ctx, {
    id: 'tea_banquet_minigame_btn',
    x: cardX + 16,
    y: closeBtnY,
    w: bottomBtnW,
    h: closeBtnH,
    radius: 6,
    bg: '#7f1d1d',
    border: '#ef4444',
    borderWidth: 1.5,
    text: "🍷 席间纵横博弈 (1⚡)",
    font: 'bold 14px ' + FONT_CHRONICLE,
    textColor: '#fef08a',
    priority: 100,
    onClick: () => {
      if (state.lastBanquetYear === state.year) {
        showToast("本年度已赴过一次重要席间博弈，请待来年再战！", "info");
        return;
      }
      if ((state.ap || 0) < 1) {
        showToast("今年精力已耗尽，请先迈入下一年！", "alert");
        playSoundEffect('alert');
        return;
      }
      state.ap = Math.max(0, state.ap - 1);
      state.lastBanquetYear = state.year;
      banquetState.guestName = contact.name || '李副司长';
      banquetState.guestRole = contact.role || '重大项目综合评审专家组组长';
      triggerBanquetMiniGame();
    }
  });

  drawTactileButton(ctx, {
    id: 'tea_modal_close',
    x: cardX + 28 + bottomBtnW,
    y: closeBtnY,
    w: bottomBtnW,
    h: closeBtnH,
    radius: 6,
    bg: '#78350f',
    border: '#f59e0b',
    borderWidth: 1.5,
    text: "起身告辞 ➔",
    font: 'bold 14px ' + FONT_CHRONICLE,
    textColor: '#fef08a',
    priority: 100,
    onClick: () => {
      state.activeModal = null;
      requestRender();
    }
  });
}


const HALL_OF_CHRONICLES_TABS = [
  { label: '🏅 功勋盛典', tab: 0 },
  { label: '🏺 时代信物', tab: 1 },
  { label: '📜 传世祖训', tab: 2 },
  { label: '🖼️ 岁月相册', tab: 3 }
];

// ------------------------------------------
// 🏛️ 文华典藏大殿统一全景弹窗 (Hall of Chronicles Unified Palace)
// ------------------------------------------
function drawHallOfChroniclesModal() {
  state.hallOfChroniclesTab = state.hallOfChroniclesTab || 0;
  const padX = 12;
  const cardW = screenWidth - padX * 2;
  const cardH = 445;
  const startX = padX;
  const startY = (screenHeight - cardH) / 2;

  ctx.save();
  ctx.fillStyle = '#141022';
  roundRect(ctx, startX, startY, cardW, cardH, 12, true, true, '#d97706', 2);
  drawCornerOrnaments(ctx, startX, startY, cardW, cardH, 8, '#f59e0b');

  // 顶部大标题
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 15.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText("🏛️ 共和国文华典藏殿 · 岁月长卷", startX + cardW / 2, startY + 12);

  // 4 大 Tab 切换栏 (🏅功勋盛典 | 🏺时代信物 | 📜传世祖训 | 🖼️岁月相册)
  const tabW = (cardW - 32) / 4;
  const tabH = 26;
  const tabY = startY + 34;

  for (let i = 0; i < HALL_OF_CHRONICLES_TABS.length; i++) {
    const tb = HALL_OF_CHRONICLES_TABS[i];
    const tx = startX + 16 + i * tabW;
    const isAct = state.hallOfChroniclesTab === tb.tab;
    drawTactileButton(ctx, {
      id: `hall_tab_${tb.tab}`,
      x: tx,
      y: tabY,
      w: tabW - 4,
      h: tabH,
      radius: 4,
      bg: isAct ? '#78350f' : '#1e1a2c',
      border: isAct ? '#f59e0b' : '#334155',
      borderWidth: isAct ? 1.5 : 0.8,
      text: tb.label,
      font: isAct ? 'bold 14px ' + FONT_CHRONICLE : '13.5px ' + FONT_UI,
      textColor: isAct ? '#fef08a' : '#94a3b8',
      priority: 110,
      onClick: () => {
        state.hallOfChroniclesTab = tb.tab;
        playSoundEffect('paper');
        requestRender();
      }
    });
  }

  const contentY = tabY + tabH + 8;
  const contentH = 315;

  if (state.hallOfChroniclesTab === 0) {
    // 🏅 功勋盛典 (8 项勋章)
    const colW = (cardW - 32) / 2;
    const rowH = 68;
    for (let idx = 0; idx < STATE_MEDALS_DATABASE.length; idx++) {
      const md = STATE_MEDALS_DATABASE[idx];
      const col = idx % 2;
      const row = Math.floor(idx / 2);
      const mx = startX + 12 + col * (colW + 8);
      const my = contentY + row * (rowH + 8);
      const isAwd = isMedalAwarded(md.id);

      ctx.fillStyle = isAwd ? '#221b33' : '#14121e';
      roundRect(ctx, mx, my, colW, rowH, 6, true, true, isAwd ? md.ribbonColor : '#334155', isAwd ? 1.5 : 0.8);
      if (isAwd) {
        ctx.fillStyle = md.ribbonColor;
        roundRect(ctx, mx, my, 4, rowH, 2, true, false);
      }
      ctx.textAlign = 'left';
      ctx.textBaseline = 'top';
      ctx.font = '16px sans-serif';
      ctx.fillText(isAwd ? md.icon : '🔒', mx + 8, my + 8);

      ctx.font = 'bold 14px ' + FONT_CHRONICLE;
      ctx.fillStyle = isAwd ? '#fef08a' : '#64748b';
      ctx.fillText(fitText(md.name, colW - 36, 'bold 14px ' + FONT_CHRONICLE), mx + 30, my + 8);

      ctx.font = 'bold 14px ' + FONT_UI;
      ctx.fillStyle = isAwd ? md.ribbonColor : '#475569';
      ctx.fillText(`【${md.tier}】`, mx + 30, my + 24);

      ctx.font = '13.5px ' + FONT_UI;
      ctx.fillStyle = isAwd ? '#cbd5e1' : '#475569';
      ctx.fillText(fitText(isAwd ? md.buffText : md.condition, colW - 16, '13.5px ' + FONT_UI), mx + 8, my + 44);
    }
  } else if (state.hallOfChroniclesTab === 1) {
    // 🏺 时代信物 (10 项信物)
    const colW = (cardW - 32) / 2;
    const rowH = 55;
    const maxRelics = Math.min(10, ERA_RELICS_DATABASE.length);
    for (let idx = 0; idx < maxRelics; idx++) {
      const rl = ERA_RELICS_DATABASE[idx];
      const col = idx % 2;
      const row = Math.floor(idx / 2);
      const rx = startX + 12 + col * (colW + 8);
      const ry = contentY + row * (rowH + 6);
      const isUnl = isRelicUnlocked(rl.id);

      ctx.fillStyle = isUnl ? '#231e33' : '#14121e';
      roundRect(ctx, rx, ry, colW, rowH, 6, true, true, isUnl ? rl.color : '#334155', isUnl ? 1.2 : 0.8);
      ctx.textAlign = 'left';
      ctx.textBaseline = 'top';
      ctx.font = '16px sans-serif';
      ctx.fillText(isUnl ? rl.icon : '🔒', rx + 8, ry + 8);

      ctx.font = 'bold 14px ' + FONT_CHRONICLE;
      ctx.fillStyle = isUnl ? '#fef08a' : '#64748b';
      ctx.fillText(fitText(rl.name, colW - 34, 'bold 14px ' + FONT_CHRONICLE), rx + 30, ry + 8);

      ctx.font = '13.5px ' + FONT_UI;
      ctx.fillStyle = isUnl ? rl.color : '#475569';
      ctx.fillText(fitText(isUnl ? rl.buff : rl.desc, colW - 16, '13.5px ' + FONT_UI), rx + 8, ry + 32);
    }
  } else if (state.hallOfChroniclesTab === 2) {
    // 📜 传世家训 (ANCESTRAL_PRECEPTS_DATABASE)
    const pW = cardW - 32;
    const pH = 54;
    for (let idx = 0; idx < ANCESTRAL_PRECEPTS_DATABASE.length; idx++) {
      const pc = ANCESTRAL_PRECEPTS_DATABASE[idx];
      const py = contentY + idx * (pH + 8);
      const isAdopt = isPreceptAdopted(pc.id);

      ctx.fillStyle = isAdopt ? '#261b33' : '#171322';
      roundRect(ctx, startX + 16, py, pW, pH, 6, true, true, isAdopt ? pc.color : '#475569', isAdopt ? 1.5 : 0.8);

      ctx.textAlign = 'left';
      ctx.textBaseline = 'top';
      ctx.font = '16px sans-serif';
      ctx.fillText(pc.badge, startX + 26, py + 8);

      ctx.font = 'bold 14px ' + FONT_CHRONICLE;
      ctx.fillStyle = isAdopt ? '#fef08a' : '#cbd5e1';
      ctx.fillText(fitText(`${pc.name} · “${pc.motto}”`, pW - 110, 'bold 14px ' + FONT_CHRONICLE), startX + 50, py + 8);

      ctx.font = '13.5px ' + FONT_UI;
      ctx.fillStyle = isAdopt ? pc.color : '#94a3b8';
      ctx.fillText(fitText(pc.desc, pW - 110, '13.5px ' + FONT_UI), startX + 50, py + 26);
      ctx.fillText(fitText(`⚡ 传世加持：${pc.buffText}`, pW - 110, '13.5px ' + FONT_UI), startX + 50, py + 39);

      const aBtnW = 54;
      const aBtnH = 24;
      const aBtnX = startX + 16 + pW - aBtnW - 8;
      const aBtnY = py + 15;

      if (isAdopt) {
        ctx.fillStyle = '#065f46';
        roundRect(ctx, aBtnX, aBtnY, aBtnW, aBtnH, 4, true, true, '#10b981', 1);
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.font = 'bold 14px ' + FONT_UI;
        ctx.fillStyle = '#fff';
        ctx.fillText("已入谱", aBtnX + aBtnW / 2, aBtnY + aBtnH / 2);
      } else {
        drawTactileButton(ctx, {
          id: `adopt_precept_${pc.id}`,
          x: aBtnX,
          y: aBtnY,
          w: aBtnW,
          h: aBtnH,
          radius: 4,
          bg: '#78350f',
          border: '#f59e0b',
          borderWidth: 1,
          text: "立此训",
          font: 'bold 14px ' + FONT_UI,
          textColor: '#fff',
          priority: 110,
          onClick: () => {
            adoptAncestralPrecept(pc.id);
            requestRender();
          }
        });
      }
    }
  } else if (state.hallOfChroniclesTab === 3) {
    // 🖼️ 岁月相册 (MEMORY_ALBUM_DATABASE)
    const colW = (cardW - 32) / 2;
    const rowH = 68;
    const maxPhotos = Math.min(8, MEMORY_ALBUM_DATABASE.length);
    for (let idx = 0; idx < maxPhotos; idx++) {
      const card = MEMORY_ALBUM_DATABASE[idx];
      const col = idx % 2;
      const row = Math.floor(idx / 2);
      const mx = startX + 12 + col * (colW + 8);
      const my = contentY + row * (rowH + 8);
      const isUnl = (state.memoryAlbum || state.unlockedMemories || []).includes(card.id);

      ctx.fillStyle = isUnl ? '#221b33' : '#14121e';
      roundRect(ctx, mx, my, colW, rowH, 6, true, true, isUnl ? '#f59e0b' : '#334155', isUnl ? 1.2 : 0.8);
      ctx.textAlign = 'left';
      ctx.textBaseline = 'top';
      ctx.font = '16px sans-serif';
      ctx.fillText(isUnl ? card.icon : '🔒', mx + 8, my + 8);

      ctx.font = 'bold 14px ' + FONT_CHRONICLE;
      ctx.fillStyle = isUnl ? '#fef08a' : '#64748b';
      ctx.fillText(fitText(card.title, colW - 36, 'bold 14px ' + FONT_CHRONICLE), mx + 30, my + 8);

      ctx.font = '13.5px ' + FONT_UI;
      ctx.fillStyle = isUnl ? '#cbd5e1' : '#475569';
      ctx.fillText(fitText(isUnl ? card.quote : card.condition, colW - 16, '13.5px ' + FONT_UI), mx + 8, my + 44);
    }
  }

  // 底部荣誉阁、勋章图谱与退出按钮
  const subBtnW = Math.floor((cardW - 44) / 3);
  const closeBtnH = 34;
  const closeBtnY = startY + cardH - closeBtnH - 10;

  drawTactileButton(ctx, {
    id: 'hall_open_medal_gallery',
    x: startX + 16,
    y: closeBtnY,
    w: subBtnW,
    h: closeBtnH,
    radius: 6,
    bg: '#4c1d95',
    border: '#fbbf24',
    text: "🎖️ 荣誉阁",
    font: 'bold 14px ' + FONT_UI,
    textColor: '#fef08a',
    priority: 100,
    onClick: () => {
      openMedalGalleryModal();
    }
  });

  drawTactileButton(ctx, {
    id: 'hall_open_achievements',
    x: startX + 22 + subBtnW,
    y: closeBtnY,
    w: subBtnW,
    h: closeBtnH,
    radius: 6,
    bg: '#78350f',
    border: '#f59e0b',
    text: "🏆 成就谱",
    font: 'bold 14px ' + FONT_UI,
    textColor: '#fef08a',
    priority: 100,
    onClick: () => {
      state.activeModal = 'achievements';
      playSoundEffect('paper');
      requestRender();
    }
  });

  drawTactileButton(ctx, {
    id: 'hall_of_chronicles_close',
    x: startX + 28 + subBtnW * 2,
    y: closeBtnY,
    w: subBtnW,
    h: closeBtnH,
    radius: 6,
    bg: '#221e33',
    border: '#475569',
    text: "收起华卷 ➔",
    font: 'bold 14px ' + FONT_UI,
    textColor: '#fef08a',
    priority: 100,
    onClick: () => {
      state.activeModal = null;
      playSoundEffect('click');
      requestRender();
    }
  });

  ctx.restore();
}

// ------------------------------------------
// 🍵 工夫茶道煮茶论道交互仪式 (Gongfu Tea Ceremony Modal)
// ------------------------------------------
function openGongfuTeaModal(contact) {
  state.activeTeaContact = contact || (state.contacts && state.contacts[0]) || ENSEMBLE_CHARACTERS[0];
  state.activeModal = 'gongfu_tea';
  state.teaPourStep = 0;
  playSoundEffect('bell');
  requestRender();
}

const GONGFU_TEAS = [
  { id: 'longjing', name: '🍃 西湖龙井', tag: '高冲醒脑', desc: '消耗1⚡ · 智谋+3，心境澄明', applyBuff: (s, c) => { addStat("iq", 3, 0); c.affinity = Math.min(100, (c.affinity || 45) + 6); } },
  { id: 'dahongpao', name: '🍂 武夷大红袍', tag: '温润通情', desc: '消耗1⚡ · 人情+4，默契交情+10', applyBuff: (s, c) => { addStat("eq", 4, 0); c.affinity = Math.min(100, (c.affinity || 45) + 10); } },
  { id: 'puer', name: '🍵 云南老班章', tag: '深煮铭心', desc: '消耗1⚡ · 清廉+3，默契交情+8', applyBuff: (s, c) => { addStat("clean", 3, 0); c.affinity = Math.min(100, (c.affinity || 45) + 8); if (c.affinity >= 85) c.isSwornGuardian = true; } }
];

function drawGongfuTeaModal() {
  const cardW = screenWidth - 28;
  const cardH = 435;
  const cardX = 14;
  const cardY = Math.max(20, Math.round((screenHeight - cardH) / 2));
  const contact = state.activeTeaContact || ENSEMBLE_CHARACTERS[0];

  ctx.save();
  ctx.fillStyle = '#16111e';
  roundRect(ctx, cardX, cardY, cardW, cardH, 12, true, true, '#d97706', 2);
  drawCornerOrnaments(ctx, cardX, cardY, cardW, cardH, 8, '#f59e0b');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 16px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText("🍵 紫砂工夫茶道 · 煮茶论道", cardX + cardW / 2, cardY + 16);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#34d399';
  ctx.fillText(`推杯品茗对座：【${contact.name}】· ${contact.role}`, cardX + cardW / 2, cardY + 38);

  // 茶案紫砂壶示意卡片
  const teaH = 110;
  const teaY = cardY + 62;
  ctx.fillStyle = '#221528';
  roundRect(ctx, cardX + 16, teaY, cardW - 32, teaH, 8, true, true, '#f59e0b', 1);

  ctx.textAlign = 'center';
  ctx.font = '36px sans-serif';
  ctx.fillText('🫖 🍵', cardX + cardW / 2, teaY + 14);

  ctx.font = '13.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  const dialogue = state.teaOutcomeText || "“一沸如鱼目，二沸如涌泉。天下机密大事，且化一壶清茗之中。”";
  ctx.fillText(fitText(dialogue, cardW - 48, '13.5px ' + FONT_CHRONICLE), cardX + cardW / 2, teaY + 70);

  // 三款名茶选泡
  const tBtnW = cardW - 48;
  const tBtnH = 50;
  const startBtnsY = teaY + teaH + 12;

  for (let i = 0; i < GONGFU_TEAS.length; i++) {
    const t = GONGFU_TEAS[i];
    const by = startBtnsY + i * (tBtnH + 8);
    ctx.fillStyle = '#1c162a';
    roundRect(ctx, cardX + 24, by, tBtnW, tBtnH, 6, true, true, '#475569', 1);

    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#fef08a';
    ctx.fillText(`${t.name} 【${t.tag}】`, cardX + 36, by + 9);

    ctx.font = '13.5px ' + FONT_UI;
    ctx.fillStyle = '#94a3b8';
    ctx.fillText(t.desc, cardX + 36, by + 28);

    const pourBtnW = 58;
    const pourBtnH = 26;
    const pourBtnX = cardX + 24 + tBtnW - pourBtnW - 10;
    const pourBtnY = by + 12;

    drawTactileButton(ctx, {
      id: `pour_tea_${t.id}`,
      x: pourBtnX,
      y: pourBtnY,
      w: pourBtnW,
      h: pourBtnH,
      radius: 4,
      bg: '#78350f',
      border: '#f59e0b',
      borderWidth: 1,
      text: "注水冲泡",
      font: 'bold 14px ' + FONT_UI,
      textColor: '#fff',
      priority: 110,
      onClick: () => {
        if (state.lastGongfuTeaYear === state.year) {
          showToast("本年度已品茗论道，茶道贵在适度从容！", "info");
          return;
        }
        if ((state.ap || 0) < 1) {
          showToast("今年精力已耗尽，请先迈入下一年！", "alert");
          return;
        }
        state.ap--;
        state.lastGongfuTeaYear = state.year;
        progressThreeYearPact(12, `工夫茶道·${t.name}`);
        playSoundEffect('tea_pour');
        triggerHaptic('medium');
        spawnInkWashBloom(screenWidth / 2, screenHeight / 2, 70, 'rgba(16, 185, 129, 0.45)');
        t.applyBuff(state, contact);
        state.teaOutcomeText = `茶香四溢！与【${contact.name}】对饮甚欢，${t.desc}！`;
        showToast(`冲泡【${t.name}】成功！`, 'gold');
        requestRender();
      }
    });
  }

  // 底部关闭
  const cBtnW = cardW - 48;
  const cBtnH = 32;
  const cBtnX = cardX + 24;
  const cBtnY = cardY + cardH - cBtnH - 10;

  drawTactileButton(ctx, {
    id: 'gongfu_tea_close',
    x: cBtnX,
    y: cBtnY,
    w: cBtnW,
    h: cBtnH,
    radius: 6,
    bg: '#221e33',
    border: '#475569',
    text: "起身告辞 ➔",
    font: 'bold 14px ' + FONT_UI,
    textColor: '#fef08a',
    priority: 100,
    onClick: () => {
      state.activeModal = null;
      state.teaOutcomeText = null;
      playSoundEffect('click');
      requestRender();
    }
  });

  ctx.restore();
}



// ------------------------------------------
// 🗺️ 四海巡历宏图全景弹窗 (Provincial Tour Modal)
// ------------------------------------------
function openProvincialTourModal() {
  state.activeModal = 'provincial_tour';
  playSoundEffect('paper');
  requestRender();
}

function executeProvincialTour(regionId) {
  state.handledTours = state.handledTours || [];
  if (state.handledTours.includes(regionId)) {
    showToast("该战略大区已完成驻点调研！", "info");
    return;
  }
  if (state.ap < 1) {
    showToast("今年精力已耗尽，请先迈入下一年！", "alert");
    return;
  }
  const reg = PROVINCIAL_REGIONS_DATABASE.find(r => r.id === regionId);
  if (!reg) return;

  state.ap--;
  progressThreeYearPact(15, `四海巡历·${reg.name}`);
  if (reg.effects) {
    if (reg.effects.capital) state.capital = (state.capital || 0) + reg.effects.capital;
    if (reg.effects.rep) addStat("rep", (reg.effects.rep), 50);
    if (reg.effects.clean) addStat("clean", (reg.effects.clean), 50);
    if (reg.effects.iq) addStat("iq", (reg.effects.iq), 50);
    if (reg.effects.eq) addStat("eq", (reg.effects.eq), 50);
    if (reg.effects.courage) addStat("courage", (reg.effects.courage), 50);
  }

  playSoundEffect('battle_drum_roll');
  triggerScreenShake(7, 240);
  spawnInkWashBloom(screenWidth / 2, screenHeight / 2, 95, reg.color);
  spawnGoldSpiral(screenWidth / 2, screenHeight / 2, 30);

  state.handledTours.push(regionId);

  addChronicleItem(state.age, state.year, `【四海巡历】深入【${reg.name}】一线驻点调研！${reg.inspectionText} 荣膺好评！`, '实地调研', 'promo');
  showToast(`调研【${reg.name}】圆满完成！${reg.rewardText}`, 'gold');
  state.activeModal = null;
  requestRender();
}

function drawProvincialTourModal() {
  const padX = 12;
  const cardW = screenWidth - padX * 2;
  const cardH = 450;
  const startX = padX;
  const startY = Math.max(16, (screenHeight - cardH) / 2);

  ctx.save();
  ctx.fillStyle = '#141122';
  roundRect(ctx, startX, startY, cardW, cardH, 12, true, true, '#d97706', 2);
  drawCornerOrnaments(ctx, startX, startY, cardW, cardH, 8, '#f59e0b');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 16px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText("🗺️ 四海巡历宏图 · 深入基层驻点调研", startX + cardW / 2, startY + 14);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#34d399';
  ctx.fillText(`“脚下沾有多少泥土，心中便沉淀多少真情” · 可用精力: ${state.ap || 0}⚡`, startX + cardW / 2, startY + 36);

  // 5 个战略大区卡片
  const listY = startY + 56;
  const rH = 62;
  PROVINCIAL_REGIONS_DATABASE.forEach((rg, idx) => {
    const ry = listY + idx * (rH + 8);
    const isDone = (state.handledTours || []).includes(rg.id);

    ctx.fillStyle = isDone ? '#1c1628' : '#221932';
    roundRect(ctx, startX + 14, ry, cardW - 28, rH, 6, true, true, isDone ? '#475569' : rg.color, isDone ? 0.8 : 1.2);

    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.font = '20px sans-serif';
    ctx.fillText(rg.badge, startX + 24, ry + 10);

    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = isDone ? '#94a3b8' : '#fef08a';
    ctx.fillText(fitText(`${rg.name} 【${rg.role}】`, cardW - 145, 'bold 14px ' + FONT_CHRONICLE), startX + 66, ry + 9);

    ctx.font = '13.5px ' + FONT_UI;
    ctx.fillStyle = isDone ? '#64748b' : '#cbd5e1';
    ctx.fillText(fitText(rg.desc, cardW - 145, '13.5px ' + FONT_UI), startX + 66, ry + 27);
    ctx.fillStyle = rg.color;
    ctx.fillText(fitText(`⚡ 走访所得：${rg.rewardText}`, cardW - 145, '13.5px ' + FONT_UI), startX + 66, ry + 42);

    // 调研按钮
    const tBtnW = 54;
    const tBtnH = 26;
    const tBtnX = startX + cardW - tBtnW - 24;
    const tBtnY = ry + 18;

    if (isDone) {
      ctx.fillStyle = '#334155';
      roundRect(ctx, tBtnX, tBtnY, tBtnW, tBtnH, 4, true, true, '#475569', 1);
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.font = 'bold 14px ' + FONT_UI;
      ctx.fillStyle = '#94a3b8';
      ctx.fillText("已踏访", tBtnX + tBtnW / 2, tBtnY + tBtnH / 2);
    } else {
      drawTactileButton(ctx, {
        id: `tour_reg_${rg.id}`,
        x: tBtnX,
        y: tBtnY,
        w: tBtnW,
        h: tBtnH,
        radius: 4,
        bg: '#78350f',
        border: '#f59e0b',
        borderWidth: 1,
        text: "驻点调研",
        font: 'bold 14px ' + FONT_UI,
        textColor: '#fff',
        priority: 110,
        onClick: () => {
          executeProvincialTour(rg.id);
        }
      });
    }
  });

  // 底部关闭按钮
  const closeBtnW = cardW - 48;
  const closeBtnH = 32;
  const closeBtnX = startX + 24;
  const closeBtnY = startY + cardH - closeBtnH - 8;

  drawTactileButton(ctx, {
    id: 'close_provincial_tour',
    x: closeBtnX,
    y: closeBtnY,
    w: closeBtnW,
    h: closeBtnH,
    radius: 6,
    bg: '#221e33',
    border: '#475569',
    text: "收起巡历宏图 ➔",
    font: 'bold 14px ' + FONT_UI,
    textColor: '#fef08a',
    priority: 100,
    onClick: () => {
      state.activeModal = null;
      playSoundEffect('click');
      requestRender();
    }
  });

  ctx.restore();
}

// ------------------------------------------
// ✍️ 书房文房泼墨题匾雅集弹窗 (Calligraphy Inscription Modal)
// ------------------------------------------
function openCalligraphyModal() {
  state.activeModal = 'calligraphy_studio';
  playSoundEffect('paper');
  requestRender();
}

function executeCalligraphyInscription(inscId) {
  const insc = CALLIGRAPHY_INSCRIPTIONS.find(c => c.id === inscId);
  if (!insc) return;
  if (state.activeCalligraphyInscription === insc.id) {
    showToast(`匾额${insc.name}已高悬中堂！`, "info");
    return;
  }
  if (state.lastCalligraphyYear === state.year) {
    showToast("本年度已在书斋挥毫换匾，请待来年再题新词！", "info");
    return;
  }
  state.lastCalligraphyYear = state.year;
  state.activeCalligraphyInscription = insc.id;
  addStat("resilience", 2, 50);
  playSoundEffect('brush_stroke_foley');
  playSoundEffect('dongxiao_whisper');
  spawnInkWashBloom(screenWidth / 2, screenHeight / 2, 85, 'rgba(15, 23, 42, 0.65)');
  spawnGoldSpiral(screenWidth / 2, screenHeight / 2, 28);

  addChronicleItem(state.age, state.year, `【泼墨题匾】亲笔手书正气匾额${insc.name}：“${insc.motto}”！高悬厅堂，砥砺后人！`, '文房题词', 'promo');
  showToast(`手书匾额${insc.name}已悬挂！${insc.buffText}`, 'gold');
  state.activeModal = null;
  requestRender();
}

function drawCalligraphyModal() {
  const padX = 14;
  const cardW = screenWidth - padX * 2;
  const cardH = 430;
  const startX = padX;
  const startY = Math.max(16, (screenHeight - cardH) / 2);

  ctx.save();
  ctx.fillStyle = '#16111f';
  roundRect(ctx, startX, startY, cardW, cardH, 12, true, true, '#d97706', 2);
  drawCornerOrnaments(ctx, startX, startY, cardW, cardH, 8, '#f59e0b');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 16px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText("✍️ 文房书斋 · 亲笔泼墨挥毫题匾", startX + cardW / 2, startY + 16);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#34d399';
  ctx.fillText("“胸中有丘壑，笔底起风雷” · 题词昭示初心志向", startX + cardW / 2, startY + 38);

  const startListY = startY + 62;
  const bH = 68;

  CALLIGRAPHY_INSCRIPTIONS.forEach((insc, idx) => {
    const by = startListY + idx * (bH + 8);
    const isChosen = state.activeCalligraphyInscription === insc.id;

    ctx.fillStyle = isChosen ? '#2d1b26' : '#1c1628';
    roundRect(ctx, startX + 16, by, cardW - 32, bH, 6, true, true, isChosen ? insc.color : '#475569', isChosen ? 1.5 : 0.8);

    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = isChosen ? '#fef08a' : '#cbd5e1';
    ctx.fillText(insc.name, startX + 28, by + 10);

    ctx.font = '13.5px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#94a3b8';
    ctx.fillText(fitText(`“${insc.motto}”`, cardW - 120, '13.5px ' + FONT_CHRONICLE), startX + 28, by + 30);

    ctx.font = '13.5px ' + FONT_UI;
    ctx.fillStyle = insc.color;
    ctx.fillText(fitText(`⚡ 题词气象：${insc.buffText}`, cardW - 120, '13.5px ' + FONT_UI), startX + 28, by + 48);

    const btnW = 54;
    const btnH = 26;
    const btnX = startX + cardW - btnW - 28;
    const btnY = by + 21;

    if (isChosen) {
      ctx.fillStyle = '#065f46';
      roundRect(ctx, btnX, btnY, btnW, btnH, 4, true, true, '#10b981', 1);
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.font = 'bold 14px ' + FONT_UI;
      ctx.fillStyle = '#fff';
      ctx.fillText("高悬中堂", btnX + btnW / 2, btnY + btnH / 2);
    } else {
      drawTactileButton(ctx, {
        id: `write_insc_${insc.id}`,
        x: btnX,
        y: btnY,
        w: btnW,
        h: btnH,
        radius: 4,
        bg: '#78350f',
        border: '#f59e0b',
        borderWidth: 1,
        text: "亲笔挥毫",
        font: 'bold 14px ' + FONT_UI,
        textColor: '#fff',
        priority: 110,
        onClick: () => {
          executeCalligraphyInscription(insc.id);
        }
      });
    }
  });

  // 底部关闭
  const closeBtnW = cardW - 48;
  const closeBtnH = 34;
  const closeBtnX = startX + 24;
  const closeBtnY = startY + cardH - closeBtnH - 12;

  drawTactileButton(ctx, {
    id: 'close_calligraphy',
    x: closeBtnX,
    y: closeBtnY,
    w: closeBtnW,
    h: closeBtnH,
    radius: 6,
    bg: '#221e33',
    border: '#475569',
    text: "搁笔收案 ➔",
    font: 'bold 14px ' + FONT_UI,
    textColor: '#fef08a',
    priority: 100,
    onClick: () => {
      state.activeModal = null;
      playSoundEffect('click');
      requestRender();
    }
  });

  ctx.restore();
}

