function openMegaprojectConsortiaModal() {
  state.activeModal = 'megaproject_consortia';
  playSoundEffect('blueprint_unroll_foley');
  requestRender();
}

function drawMegaprojectConsortiaModal() {
  const padX = 12;
  const cardW = screenWidth - padX * 2;
  const cardH = 450;
  const startX = padX;
  const startY = Math.max(16, (screenHeight - cardH) / 2);

  ctx.save();
  // 经典工程深青色晒蓝图背景
  ctx.fillStyle = '#081726';
  roundRect(ctx, startX, startY, cardW, cardH, 12, true, true, '#0ea5e9', 2);
  drawCornerOrnaments(ctx, startX, startY, cardW, cardH, 8, '#38bdf8');

  // 工程网格暗纹 (单次合批绘制，省去数十次 stroke 调用)
  ctx.strokeStyle = 'rgba(14, 165, 233, 0.12)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  for (let x = startX + 10; x < startX + cardW; x += 20) {
    ctx.moveTo(x, startY + 10);
    ctx.lineTo(x, startY + cardH - 10);
  }
  for (let y = startY + 10; y < startY + cardH; y += 20) {
    ctx.moveTo(startX + 10, y);
    ctx.lineTo(startX + cardW - 10, y);
  }
  ctx.stroke();

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 15.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#38bdf8';
  ctx.fillText("🚀 国家战略重大专项 · 工程总览图", startX + cardW / 2, startY + 14);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#7dd3fc';
  ctx.fillText(fitText(`“铸大国重器，挺民族脊梁” · 专项统筹精力: ${state.ap || 0}⚡ | 结余资金: ¥${(state.capital || 0).toLocaleString()}`, cardW - 24, '13.5px ' + FONT_UI), startX + cardW / 2, startY + 36);

  const startListY = startY + 56;
  const bH = 80;

  for (let idx = 0; idx < NATIONAL_MEGAPROJECT_CONSORTIA.length; idx++) {
    const proj = NATIONAL_MEGAPROJECT_CONSORTIA[idx];
    const py = startListY + idx * (bH + 8);
    const curStg = getMegaprojectStage(proj.id);
    const stgInfo = MEGAPROJECT_STAGES[curStg - 1];

    ctx.fillStyle = curStg >= 4 ? '#064e3b' : '#0c2338';
    roundRect(ctx, startX + 12, py, cardW - 24, bH, 6, true, true, curStg >= 4 ? '#10b981' : proj.color, 1.2);

    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.font = '22px sans-serif';
    ctx.fillText(proj.badge, startX + 20, py + 12);

    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#f8fafc';
    ctx.fillText(fitText(`${proj.name} 【${proj.field}】`, cardW - 130, 'bold 14px ' + FONT_CHRONICLE), startX + 52, py + 10);

    ctx.font = '13.5px ' + FONT_UI;
    ctx.fillStyle = '#94a3b8';
    ctx.fillText(fitText(proj.desc, cardW - 130, '13.5px ' + FONT_UI), startX + 52, py + 28);

    // 四阶进度指示条
    const pBarW = cardW - 145;
    const pBarH = 6;
    const pBarX = startX + 52;
    const pBarY = py + 48;
    ctx.fillStyle = '#1e293b';
    roundRect(ctx, pBarX, pBarY, pBarW, pBarH, 3, true, false);
    ctx.fillStyle = curStg >= 4 ? '#10b981' : '#38bdf8';
    roundRect(ctx, pBarX, pBarY, Math.max(6, (curStg / 4) * pBarW), pBarH, 3, true, false);

    ctx.font = '13.5px ' + FONT_UI;
    ctx.fillStyle = curStg >= 4 ? '#34d399' : '#38bdf8';
    ctx.fillText(`阶段 ${curStg}/4：【${stgInfo.name}】`, pBarX, py + 58);

    // 攻坚推进按钮
    const btnW = 58;
    const btnH = 32;
    const btnX = startX + cardW - btnW - 20;
    const btnY = py + 24;

    if (curStg >= 4) {
      ctx.fillStyle = '#047857';
      roundRect(ctx, btnX, btnY, btnW, btnH, 4, true, true, '#10b981', 1);
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.font = 'bold 14px ' + FONT_UI;
      ctx.fillStyle = '#fff';
      ctx.fillText("已投产", btnX + btnW / 2, btnY + btnH / 2);
    } else {
      drawTactileButton(ctx, {
        id: `advance_proj_${proj.id}`,
        x: btnX,
        y: btnY,
        w: btnW,
        h: btnH,
        radius: 4,
        bg: '#0369a1',
        border: '#38bdf8',
        borderWidth: 1,
        text: "攻坚推进",
        font: 'bold 14px ' + FONT_UI,
        textColor: '#fff',
        priority: 110,
        onClick: () => {
          advanceMegaprojectStage(proj.id);
        }
      });
    }
  }

  // 底部关闭
  const closeBtnW = cardW - 48;
  const closeBtnH = 32;
  const closeBtnX = startX + 24;
  const closeBtnY = startY + cardH - closeBtnH - 8;

  drawTactileButton(ctx, {
    id: 'close_megaproject_modal',
    x: closeBtnX,
    y: closeBtnY,
    w: closeBtnW,
    h: closeBtnH,
    radius: 6,
    bg: '#0f2742',
    border: '#38bdf8',
    text: "收起工程图纸 ➔",
    font: 'bold 14px ' + FONT_UI,
    textColor: '#7dd3fc',
    priority: 100,
    onClick: () => {
      state.activeModal = null;
      playSoundEffect('click');
      requestRender();
    }
  });

  ctx.restore();
}

