    ctx.fillText(lec.badge, startX + 26, ly + 10);

    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = isDone ? '#94a3b8' : '#fef08a';
    ctx.fillText(fitText(lec.title, cardW - 135, 'bold 14px ' + FONT_CHRONICLE), startX + 52, ly + 10);

    ctx.font = '13.5px ' + FONT_CHRONICLE;
    ctx.fillStyle = isDone ? '#64748b' : '#cbd5e1';
    ctx.fillText(fitText(lec.motto, cardW - 135, '13.5px ' + FONT_CHRONICLE), startX + 52, ly + 28);

    ctx.font = '13.5px ' + FONT_UI;
    ctx.fillStyle = '#94a3b8';
    ctx.fillText(fitText(lec.desc, cardW - 130, '13.5px ' + FONT_UI), startX + 52, ly + 46);

    ctx.fillStyle = lec.color;
    ctx.fillText(fitText(`⚡ 讲学回响：${lec.effectsText}`, cardW - 135, '13.5px ' + FONT_UI), startX + 52, ly + 64);

    const btnW = 54;
