// ------------------------------------------
// ⚙️ 系统设置与数据管理弹窗 (Settings Modal)
// ------------------------------------------
function openSettingsModal() {
  state.activeModal = 'system_settings';
  playSoundEffect('click');
  requestRender();
}

const SETTINGS_ITEMS_DEF = [
  { id: 'bgm', title: '🎼 时代沉浸背景音乐' },
  { id: 'sfx', title: '🔔 拟真声效与钟磬礼乐' },
  { id: 'haptic', title: '📳 震屏触觉与指压反馈' },
  { id: 'cloud', title: '☁️ 平台用户云存档 (换机防丢保护)' },
  { id: 'power', title: '🔋 极智动态节电降耗' }
];

function drawSettingsModal() {
  const padX = 14;
  const cardW = screenWidth - padX * 2;
  const cardH = 472;
  const startX = padX;
  const startY = Math.max(12, (screenHeight - cardH) / 2);

  ctx.save();
  ctx.fillStyle = '#181224';
  roundRect(ctx, startX, startY, cardW, cardH, 12, true, true, '#d97706', 2);
  drawCornerOrnaments(ctx, startX, startY, cardW, cardH, 8, '#f59e0b');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 16px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText("⚙️ 系统设置 · 合规与数据管理", startX + cardW / 2, startY + 16);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#94a3b8';
  ctx.fillText(`${HEALTHY_GAMING_ADVICE.version} · 安全合规运行中`, startX + cardW / 2, startY + 38);

  // 设置项列表区
  const listY = startY + 60;

  for (let idx = 0; idx < SETTINGS_ITEMS_DEF.length; idx++) {
    const it = SETTINGS_ITEMS_DEF[idx];
    let val = '', color = '';
    if (it.id === 'bgm') {
      const on = typeof bgmEnabled !== 'undefined' ? bgmEnabled : state.bgmEnabled !== false;
      val = on ? '已开启' : '已静音';
      color = on ? '#10b981' : '#64748b';
    } else if (it.id === 'sfx') {
      const on = typeof sfxEnabled !== 'undefined' ? sfxEnabled : state.sfxEnabled !== false;
      val = on ? '已开启' : '已静音';
      color = on ? '#10b981' : '#64748b';
    } else if (it.id === 'haptic') {
      const on = state.hapticEnabled !== false;
      val = on ? '已启用' : '已关闭';
      color = on ? '#0ea5e9' : '#64748b';
    } else if (it.id === 'cloud') {
      val = '已同步 (换机不丢档)';
      color = '#38bdf8';
    } else {
      val = '智能超低功耗 60FPS';
      color = '#f59e0b';
    }

    const iy = listY + idx * 44;
    drawTactileButton(ctx, {
      id: `toggle_setting_${it.id}`,
      x: startX + 16,
      y: iy,
      w: cardW - 32,
      h: 36,
      radius: 6,
      bg: '#261a35',
      border: '#47325e',
      priority: 100,
      renderContent: (c) => {
        c.textAlign = 'left';
        c.textBaseline = 'middle';
        c.font = 'bold 13.5px ' + FONT_UI;
        c.fillStyle = '#f1f5f9';
        c.fillText(it.title, startX + 28, iy + 18);

        c.textAlign = 'right';
        c.font = 'bold 13px ' + FONT_UI;
        c.fillStyle = color;
        c.fillText(val, startX + cardW - 28, iy + 18);
      },
      onClick: () => {
        if (it.id === 'bgm') {
          bgmEnabled = !bgmEnabled;
          state.bgmEnabled = bgmEnabled;
          if (bgmEnabled && typeof startBGM === 'function') startBGM();
          else if (typeof stopBGM === 'function') stopBGM();
        } else if (it.id === 'sfx') {
          sfxEnabled = !sfxEnabled;
          state.sfxEnabled = sfxEnabled;
        } else if (it.id === 'haptic') {
          state.hapticEnabled = !(state.hapticEnabled !== false);
        } else if (it.id === 'cloud') {
          saveGameState(true);
          showToast("☁️ 已与云端同步存档，换机重装即可恢复！", "gold");
          playSoundEffect('stamp');
          triggerHaptic('medium');
        }
        playSoundEffect('click');
        requestRender();
      }
    });
  }

  // 底部重置、合规中心、隐私协议与典藏支持按钮
  const actY = listY + SETTINGS_ITEMS_DEF.length * 44 + 8;
  const btnW = Math.floor((cardW - 50) / 4);
  const btnH = 34;

  // 隐私协议查阅
  drawTactileButton(ctx, {
    id: 'settings_open_privacy',
    x: startX + 16,
    y: actY,
    w: btnW,
    h: btnH,
    radius: 6,
    bg: '#0284c7',
    border: '#38bdf8',
    text: "📜 隐私",
    font: 'bold 14px ' + FONT_UI,
    textColor: '#fff',
    priority: 100,
    onClick: () => {
      openPrivacyComplianceModal();
    }
  });

  // 合规中心查阅
  drawTactileButton(ctx, {
    id: 'settings_open_compliance_center',
    x: startX + 22 + btnW,
    y: actY,
    w: btnW,
    h: btnH,
    radius: 6,
    bg: '#047857',
    border: '#34d399',
    text: "🛡️ 合规",
    font: 'bold 14px ' + FONT_UI,
    textColor: '#fff',
    priority: 100,
    onClick: () => {
      openComplianceCenterModal();
    }
  });

  // 修史典藏支持
  drawTactileButton(ctx, {
    id: 'settings_sponsor_support',
    x: startX + 28 + btnW * 2,
    y: actY,
    w: btnW,
    h: btnH,
    radius: 6,
    bg: '#78350f',
    border: '#f59e0b',
    text: "🕯️ 添灯",
    font: 'bold 14px ' + FONT_UI,
    textColor: '#fef08a',
    priority: 100,
    onClick: () => {
      requestSponsorSupport();
    }
  });

  // 清除本地数据
  drawTactileButton(ctx, {
    id: 'settings_reset_cache',
    x: startX + 34 + btnW * 3,
    y: actY,
    w: btnW,
    h: btnH,
    radius: 6,
    bg: '#991b1b',
    border: '#ef4444',
    text: "🗑️ 清缓存",
    font: 'bold 14px ' + FONT_UI,
    textColor: '#fff',
    priority: 100,
    onClick: () => {
      resetUserGameData();
    }
  });

  // 底部风云榜入口与返回按钮
  const closeBtnW = Math.floor((cardW - 48) / 2);
  const closeBtnH = 32;
  const closeBtnX = startX + 18;
  const closeBtnY = startY + cardH - closeBtnH - 12;

  drawTactileButton(ctx, {
    id: 'settings_open_leaderboard',
    x: closeBtnX,
    y: closeBtnY,
    w: closeBtnW,
    h: closeBtnH,
    radius: 6,
    bg: '#78350f',
    border: '#f59e0b',
    text: "📖 历代人物志",
    font: 'bold 14px ' + FONT_UI,
    textColor: '#fef08a',
    priority: 100,
    onClick: () => {
      openLeaderboardModal();
    }
  });

  drawTactileButton(ctx, {
    id: 'close_system_settings',
    x: closeBtnX + closeBtnW + 12,
    y: closeBtnY,
    w: closeBtnW,
    h: closeBtnH,
    radius: 6,
    bg: '#334155',
    border: '#64748b',
    text: "保存并返回 ➔",
    font: 'bold 14px ' + FONT_UI,
    textColor: '#fff',
    priority: 100,
    onClick: () => {
      state.activeModal = null;
      playSoundEffect('click');
      requestRender();
    }
  });

  ctx.restore();
}

