function openApprenticeModal() {
  state.activeModal = 'apprentice_modal';
  state.apprentices = state.apprentices || [];
  playSoundEffect('pipa_spring_blossoms');
  spawnInkWashBloom(screenWidth / 2, screenHeight / 2, 110, '#38bdf8');
  requestRender();
}

function recruitApprentice(candidateId) {
  if (state.age < 28) {
    showToast('🏛️ 须年满28岁具备深厚业务积淀后，方可开门收徒传道授业！', 'info');
    return;
  }
  state.apprentices = state.apprentices || [];
  if (state.apprentices.some(a => a.id === candidateId)) {
    showToast('该青年英才已在师门受业！', 'warn');
    return;
  }
  const cand = APPRENTICE_CANDIDATES.find(c => c.id === candidateId);
  if (!cand) return;

  state.apprentices.push({
    id: cand.id,
    name: cand.name,
    type: cand.type,
    badge: cand.badge,
    color: cand.color,
    mastery: 20,
    isGraduated: false
  });

  playSoundEffect('pipa_spring_blossoms');
  showToast(`🏛️【开门纳徒】收录【${cand.name}】入室受业！`, 'gold');
  addChronicleItem(state.age, state.year, `【师徒开宗】开门招收【${cand.name}】入室授业，薪火传承。`, '薪火相传', 'promo');
  requestRender();
}

function mentorApprentice(candidateId) {
  if (state.lastMentorApprenticeYear === state.year) {
    showToast('📖 本年度已悉心指点过门徒，教学相长贵在日常磨砺，请来年再授！', 'info');
    return;
  }
  if ((state.ap || 0) < 1) {
    showToast('当年履职精力已耗尽，静待来年！', 'warn');
    return;
  }
  state.apprentices = state.apprentices || [];
  const app = state.apprentices.find(a => a.id === candidateId);
  if (!app) return;

  state.ap = Math.max(0, state.ap - 1);
  state.lastMentorApprenticeYear = state.year;
  app.mastery = (app.mastery || 0) + 35;
  progressThreeYearPact(12, '杏坛传薪');

  if (app.mastery >= 100 && !app.isGraduated) {
    app.isGraduated = true;
    app.mastery = 100;
    addStat("resilience", 8, 50);
    addStat("rep", 6, 50);
    playSoundEffect('bianzhong_sacred_hymn');
    showToast(`👑【桃李成蹊】门徒【${app.name}】出师独当一面！声望与抗逆力跃升！`, 'gold');
    addChronicleItem(state.age, state.year, `【门徒出师】弟子【${app.name}】学成出师，担纲国家重点工程骨干！`, '桃李成蹊', 'promo');
  } else {
    playSoundEffect('bell_grand_chime');
    showToast(`📖【传道授业】悉心指点【${app.name}】，造诣提升至 ${app.mastery}%！`, 'gold');
  }
  requestRender();
}

function drawApprenticeModal() {
  const padX = 14;
  const cardW = screenWidth - padX * 2;
  const cardH = Math.min(520, screenHeight - 32);
  const startX = padX;
  const startY = Math.max(16, (screenHeight - cardH) / 2);

  // 使用 V24 水墨卷轴装裱
  drawSilkScrollFrame(ctx, startX, startY, cardW, cardH, '#0284c7', '#d97706');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 15px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText("🏛️ 杏坛传薪 · 师徒传道受业阁", startX + cardW / 2, startY + 14);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#bae6fd';
  ctx.fillText(fitText("“师者，所以传道受业解惑也” · 培育大国栋梁后辈，关键时刻反哺护航", cardW - 24, '13.5px ' + FONT_UI), startX + cardW / 2, startY + 34);

  const itemH = 74;
  const listStartY = startY + 54;
  state.apprentices = state.apprentices || [];

  APPRENTICE_CANDIDATES.forEach((cand, idx) => {
    const iy = listStartY + idx * (itemH + 8);
    const existing = state.apprentices.find(a => a.id === cand.id);

    ctx.fillStyle = '#0f172a';
    roundRect(ctx, startX + 12, iy, cardW - 24, itemH, 6, true, true, cand.color, 1);

    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = cand.color;
    ctx.fillText(`${cand.badge} ${cand.name} · ${cand.type}`, startX + 20, iy + 8);

    ctx.textAlign = 'right';
    ctx.font = 'bold 14px ' + FONT_UI;
    ctx.fillStyle = existing ? (existing.isGraduated ? '#34d399' : '#fef08a') : '#94a3b8';
    ctx.fillText(existing ? (existing.isGraduated ? '👑 独当一面 (已出师)' : `造诣: ${existing.mastery}%`) : '待拜入师门', startX + cardW - 20, iy + 8);

    ctx.textAlign = 'left';
    ctx.font = '13.5px ' + FONT_UI;
    ctx.fillStyle = '#cbd5e1';
    ctx.fillText(`绝技：${cand.skill}`, startX + 20, iy + 26);

    ctx.font = 'italic 13.5px ' + FONT_UI;
    ctx.fillStyle = '#94a3b8';
    ctx.fillText(fitText(cand.motto, cardW - 120, 'italic 13.5px ' + FONT_UI), startX + 20, iy + 42);

    // 交互操作按钮
    const btnW = 76;
    const btnH = 26;
    const btnX = startX + cardW - btnW - 20;
    const btnY = iy + 40;

    if (!existing) {
      drawTactileButton(ctx, {
        id: 'recruit_app_' + cand.id,
        x: btnX,
        y: btnY,
        w: btnW,
        h: btnH,
        radius: 4,
        bg: '#0369a1',
        border: '#38bdf8',
        text: '纳为门徒 ➔',
        font: 'bold 14px ' + FONT_UI,
        textColor: '#fff',
        priority: 100,
        onClick: () => {
          recruitApprentice(cand.id);
        }
      });
    } else if (!existing.isGraduated) {
      const hasAp = (state.ap || 0) >= 1;
      drawTactileButton(ctx, {
        id: 'mentor_app_' + cand.id,
        x: btnX,
        y: btnY,
        w: btnW,
        h: btnH,
        radius: 4,
        bg: hasAp ? '#047857' : '#334155',
        border: hasAp ? '#10b981' : '#64748b',
        text: '授业(1⚡) ➔',
        font: 'bold 14px ' + FONT_UI,
        textColor: hasAp ? '#fef08a' : '#94a3b8',
        priority: 100,
        onClick: () => {
          mentorApprentice(cand.id);
        }
      });
    } else {
      ctx.fillStyle = '#1e1b4b';
      roundRect(ctx, btnX, btnY, btnW, btnH, 4, true, true, '#818cf8', 1);
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.font = 'bold 14px ' + FONT_UI;
      ctx.fillStyle = '#c7d2fe';
      ctx.fillText('桃李反哺 ✨', btnX + btnW / 2, btnY + btnH / 2);
    }
  });

  // 底部关闭
  const closeBtnW = cardW - 40;
  const closeBtnH = 32;
  const closeBtnX = startX + 20;
  const closeBtnY = startY + cardH - closeBtnH - 12;

  drawTactileButton(ctx, {
    id: 'close_apprentice',
    x: closeBtnX,
    y: closeBtnY,
    w: closeBtnW,
    h: closeBtnH,
    radius: 6,
    bg: '#1e293b',
    border: '#64748b',
    text: "暂别师席 · 返回案头 ➔",
    font: 'bold 14px ' + FONT_UI,
    textColor: '#fff',
    priority: 100,
    onClick: () => {
      state.activeModal = null;
      playSoundEffect('click');
      requestRender();
    }
  });

  ctx.restore();
}

