function drawLifeWaveModal() {
  const padX = 14;
  const cardW = screenWidth - padX * 2;
  const cardH = Math.min(530, screenHeight - 32);
  const startX = padX;
  const startY = Math.max(16, (screenHeight - cardH) / 2);

  ctx.save();
  ctx.fillStyle = '#080c16';
  roundRect(ctx, startX, startY, cardW, cardH, 12, true, true, '#6366f1', 2);
  drawCornerOrnaments(ctx, startX, startY, cardW, cardH, 8, '#fbbf24');
  drawCloudFiligreeBorders(ctx, startX, startY, cardW, cardH, '#818cf8');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 15px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText("🌊 命途波澜 · 生平顺逆水墨长卷", startX + cardW / 2, startY + 14);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#c7d2fe';
  ctx.fillText(fitText("“莫听穿林打叶声，何妨吟啸且徐行” · 记录一生顺遂峰值与至暗逆境淬炼", cardW - 24, '13.5px ' + FONT_UI), startX + cardW / 2, startY + 34);

  // 绘制折线图
  const chartW = cardW - 24;
  const chartH = 200;
  const chartX = startX + 12;
  const chartY = startY + 54;
  drawLifeTrajectoryWaveChart(ctx, chartX, chartY, chartW, chartH, state.lifeWaveHistory || []);

  // 📖 V25 命途折点历史回眸手札 (Interactive Node Retrospection)
  const statsY = chartY + chartH + 10;
  if (state.selectedWavePoint) {
    const p = state.selectedWavePoint;
    const cardH = 68;
    ctx.fillStyle = '#1e1b4b';
    roundRect(ctx, startX + 12, statsY, cardW - 24, cardH, 6, true, true, '#fbbf24', 1.2);

    ctx.textAlign = 'left';
    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#fef08a';
    ctx.fillText(fitText('📜【' + (p.year || (1980 + p.age)) + '年 · ' + p.age + '岁手札】顺逆气象：' + p.score + '分 · 抗逆：' + (p.resilience || 50) + '点', cardW - 40, 'bold 14px ' + FONT_CHRONICLE), startX + 20, statsY + 15);

    ctx.font = '13.5px ' + FONT_UI;
    ctx.fillStyle = '#cbd5e1';
    const noteText = p.note ? (p.note.length > 50 ? p.note.slice(0, 48) + '...' : p.note) : '坚守岗位，履职尽责。';
    drawWrappedText(ctx, '实纪：“' + noteText + '”', startX + 20, statsY + 32, cardW - 40, 14);

    ctx.font = 'italic 13.5px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#a5b4fc';
    const motto = p.score >= 80 ? '春风得意马蹄疾，攻坚克难建新功' : (p.score <= 45 ? '千磨万击还坚劲，任尔东西南北风' : '行稳致远不移志，淡泊明志铸平生');
    ctx.fillText('心境：“' + motto + '”', startX + 20, statsY + 58);
  }

  const resVal = state.resilience || 50;
  const resTier = resVal >= 100 ? '泰山不坠 · 大器晚成' : (resVal >= 80 ? '沉毅笃定 · 沧海横流' : (resVal >= 65 ? '劲草疾风 · 坚韧不拔' : '潜修立心 · 经受磨砺'));

  const statItems = [
    { title: '内省抗逆力', val: resVal + ' 点', color: '#818cf8' },
    { title: '命途心性评级', val: resTier, color: '#fef08a' }
  ];

  const statItemH = 28;
  statItems.forEach((st, idx) => {
    const sy = (state.selectedWavePoint ? statsY + 74 : statsY) + idx * (statItemH + 6);
    ctx.fillStyle = '#0f172a';
    roundRect(ctx, startX + 12, sy, cardW - 24, statItemH, 5, true, true, st.color, 0.8);

    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';
    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#cbd5e1';
    ctx.fillText(st.title, startX + 22, sy + statItemH / 2);

    ctx.textAlign = 'right';
    ctx.font = 'bold 14px ' + FONT_MONO;
    ctx.fillStyle = st.color;
    ctx.fillText(st.val, startX + cardW - 22, sy + statItemH / 2);
  });

  // 底部关闭按钮
  const closeBtnW = cardW - 40;
  const closeBtnH = 34;
  const closeBtnX = startX + 20;
  const closeBtnY = startY + cardH - closeBtnH - 12;

  drawTactileButton(ctx, {
    id: 'close_life_wave',
    x: closeBtnX,
    y: closeBtnY,
    w: closeBtnW,
    h: closeBtnH,
    radius: 6,
    bg: '#312e81',
    border: '#6366f1',
    text: "领悟平生 · 笃定前行 ➔",
    font: 'bold 14px ' + FONT_UI,
    textColor: '#fff',
    priority: 100,
    onClick: () => {
      state.activeModal = null;
      playSoundEffect('click');
      requestRender();
    }
  });

  ctx.restore();
}

