// 十.A 名仕私晤密室全屏深度交互弹窗 (Private Chamber Dialog Modal)
// ==========================================
const NPC_CHAT_BRANCHES = [
  { id: 1, tag: "🍵 论道大势 · 时代初心", desc: "畅叙宏观局势，推心置腹共鸣初心 (好感+12/声望+3/智谋+2/情商+2)", color: '#f59e0b', border: '#d97706' },
  { id: 2, tag: "🤝 互惠共赢 · 资源联结", desc: "促成产业实质合作，置换核心资本/技术/良医调理/合规护盾", color: '#38bdf8', border: '#0284c7' },
  { id: 3, tag: "🛡️ 委婉提点 · 守正控险", desc: "提点合规规矩红线，明哲保身，好感+8/清廉+5并激活免灾神盾", color: '#10b981', border: '#059669' }
];

function drawNpcChatModal() {
  const chat = state.activeNpcChat;
  if (!chat) return;

  const cardW = screenWidth - 24;
  const cardH = 480;
  const cardX = 12;
  const cardY = Math.max(16, Math.round((screenHeight - cardH) / 2));

  ctx.fillStyle = '#13111f';
  roundRect(ctx, cardX, cardY, cardW, cardH, 12, true, true, chat.isSworn ? '#f59e0b' : '#6366f1', 2);
  drawCornerOrnaments(ctx, cardX, cardY, cardW, cardH, 8, chat.isSworn ? '#f59e0b' : '#818cf8');

  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.font = '28px sans-serif';
  ctx.fillText(chat.avatar || '👤', cardX + 16, cardY + 16);

  ctx.font = 'bold 15px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText(chat.name, cardX + 54, cardY + 16);

  ctx.font = 'bold 14px ' + FONT_UI;
  ctx.fillStyle = chat.faction ? chat.faction.color : '#f59e0b';
  ctx.fillText(`【${chat.faction ? chat.faction.name : '时代贤达'}】`, cardX + 54 + ctx.measureText(chat.name).width + 8, cardY + 18);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#94a3b8';
  ctx.fillText(fitText(chat.role, cardW - 70, '13.5px ' + FONT_UI), cardX + 54, cardY + 36);

  const affBarW = cardW - 32;
  const affY = cardY + 62;
  ctx.fillStyle = '#1e293b';
  roundRect(ctx, cardX + 16, affY, affBarW, 6, 3, true, false);

  const affRatio = Math.min(1.0, (chat.affinity || 35) / 100);
  ctx.fillStyle = chat.isSworn ? '#f59e0b' : '#38bdf8';
  roundRect(ctx, cardX + 16, affY, affBarW * affRatio, 6, 3, true, false);

  ctx.font = 'bold 14px ' + FONT_UI;
  ctx.fillStyle = chat.isSworn ? '#fef08a' : '#cbd5e1';
  ctx.textAlign = 'left';
  ctx.fillText(chat.isSworn ? "🛡️ 境界：【生死莫逆 · 护航庇护】" : `交情境界：【${chat.affinity >= 60 ? '志同道合' : (chat.affinity >= 30 ? '相谈甚欢' : '点头之交')} (${chat.affinity}/100)】`, cardX + 16, affY + 10);

  const monoY = affY + 28;
  const monoH = 92;
  ctx.fillStyle = '#1c182a';
  roundRect(ctx, cardX + 16, monoY, cardW - 32, monoH, 8, true, true, '#334155', 1);
  ctx.font = 'bold 14px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#f59e0b';
  ctx.fillText(`📜 ${state.year}年时代心声：`, cardX + 24, monoY + 10);

  ctx.font = '13.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#e2e8f0';
  const monoLines = wrapTextLines(chat.monologue, cardW - 48, '13.5px ' + FONT_CHRONICLE);
  const monoCount = Math.min(3, monoLines.length);
  for (let idx = 0; idx < monoCount; idx++) {
    ctx.fillText(monoLines[idx], cardX + 24, monoY + 30 + idx * 18);
  }

  if (chat.step === 'reaction') {
    const resY = monoY + monoH + 12;
    const resH = 180;
    ctx.fillStyle = '#0f172a';
    roundRect(ctx, cardX + 16, resY, cardW - 32, resH, 8, true, true, '#10b981', 1.5);
    ctx.textAlign = 'left';
    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#34d399';
    ctx.fillText("💬 名仕真挚回语：", cardX + 26, resY + 14);
    ctx.font = '13.5px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#f8fafc';
    const repLines = wrapTextLines(chat.reactionText, cardW - 52, '13.5px ' + FONT_CHRONICLE);
    const repCount = Math.min(3, repLines.length);
    for (let idx = 0; idx < repCount; idx++) {
      ctx.fillText(repLines[idx], cardX + 26, resY + 36 + idx * 19);
    }
    ctx.font = 'bold 14px ' + FONT_UI;
    ctx.fillStyle = '#fef08a';
    ctx.fillText(chat.perkText, cardX + 26, resY + 105);
    const okBtnW = cardW - 64;
    const okBtnH = 34;
    const okBtnX = cardX + 32;
    const okBtnY = resY + resH - okBtnH - 12;

    drawTactileButton(ctx, {
      id: 'npc_reaction_dismiss',
      x: okBtnX,
      y: okBtnY,
      w: okBtnW,
      h: okBtnH,
      radius: 6,
      bg: '#065f46',
      border: '#10b981',
      text: "铭记情谊 · 礼毕作别 ➔",
      font: 'bold 14px ' + FONT_CHRONICLE,
      textColor: '#fff',
      priority: 100,
      onClick: () => {
        dismissNpcChatModal();
      }
    });
    return;
  }

  let bY = monoY + monoH + 12;
  NPC_CHAT_BRANCHES.forEach((b) => {
    const bH = 56;
    const branchId = `npc_branch_${b.id}`;
    drawTactileButton(ctx, {
      id: branchId,
      x: cardX + 16,
      y: bY,
      w: cardW - 32,
      h: bH,
      radius: 6,
      bg: '#1c182a',
      border: b.border,
      priority: 100,
      renderContent: (c) => {
        c.textAlign = 'left';
        c.textBaseline = 'top';
        c.font = 'bold 14px ' + FONT_CHRONICLE;
        c.fillStyle = b.color;
        c.fillText(b.tag, cardX + 26, bY + 8);
        c.font = '13.5px ' + FONT_UI;
        c.fillStyle = '#cbd5e1';
        c.fillText(fitText(b.desc, cardW - 110, '13.5px ' + FONT_UI), cardX + 26, bY + 28);
        const btnW = 68;
        const btnH = 26;
        const btnX = cardX + cardW - btnW - 26;
        const btnY = bY + (bH - btnH) / 2;
        c.fillStyle = '#2d1b38';
        roundRect(c, btnX, btnY, btnW, btnH, 4, true, true, b.color, 1);
        c.font = 'bold 14px ' + FONT_CHRONICLE;
        c.fillStyle = '#fef08a';
        c.textAlign = 'center';
        c.textBaseline = 'middle';
        c.fillText("进言商榷", btnX + btnW / 2, btnY + btnH / 2);
      },
      onClick: () => {
        executeNpcDialogue(b.id);
      }
    });
    bY += bH + 8;
  });

  const closeBtnW = cardW - 64;
  const closeBtnH = 30;
  const closeBtnX = cardX + 32;
  const closeBtnY = cardY + cardH - closeBtnH - 12;

  drawTactileButton(ctx, {
    id: 'npc_modal_close',
    x: closeBtnX,
    y: closeBtnY,
    w: closeBtnW,
    h: closeBtnH,
    radius: 5,
    bg: '#1e293b',
    border: '#475569',
    text: "暂且作别 · 返回名仕录",
    font: 'bold 14px ' + FONT_UI,
    textColor: '#94a3b8',
    priority: 100,
    onClick: () => {
      dismissNpcChatModal();
    }
  });
}

