function drawFamilyEventModal() {
  const evt = state.activeFamilyEvent;
  if (!evt) return;
  const cardW = screenWidth - 28;
  const cardH = 460;
  const cardX = 14;
  const cardY = Math.max(20, Math.round((screenHeight - cardH) / 2));
  ctx.fillStyle = '#17111e';
  roundRect(ctx, cardX, cardY, cardW, cardH, 12, true, true, '#f59e0b', 2);
  drawCornerOrnaments(ctx, cardX, cardY, cardW, cardH, 8, '#f59e0b');
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 14px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText(fitText(evt.title, cardW - 32, 'bold 14px ' + FONT_CHRONICLE), cardX + 16, cardY + 16);
  ctx.font = '13.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#cbd5e1';
  const lines = wrapTextLines(evt.context, cardW - 32, '13.5px ' + FONT_CHRONICLE);
  const lineLimit = Math.min(4, lines.length);
  for (let i = 0; i < lineLimit; i++) {
    ctx.fillText(lines[i], cardX + 16, cardY + 42 + i * 18);
  }
  let optY = cardY + 124;
  evt.choices.forEach((c, idx) => {
    const optH = 76;
    const choiceId = `family_choice_${idx}`;
    drawTactileButton(ctx, {
      id: choiceId,
      x: cardX + 16,
      y: optY,
      w: cardW - 32,
      h: optH,
      radius: 8,
      bg: '#1c182a',
      border: '#475569',
      priority: 100,
      renderContent: (cCtx) => {
        cCtx.textAlign = 'left';
        cCtx.textBaseline = 'top';
        cCtx.font = 'bold 14px ' + FONT_CHRONICLE;
        cCtx.fillStyle = '#fef08a';
        cCtx.fillText(fitText(c.title, cardW - 52, 'bold 14px ' + FONT_CHRONICLE), cardX + 24, optY + 10);
        cCtx.font = '13.5px ' + FONT_UI;
        cCtx.fillStyle = '#cbd5e1';
        const cLines = wrapTextLines(c.desc, cardW - 135, '13.5px ' + FONT_UI);
        const cLimit = Math.min(2, cLines.length);
        for (let ci = 0; ci < cLimit; ci++) {
          cCtx.fillText(cLines[ci], cardX + 24, optY + 30 + ci * 16);
        }
        const btnW = 76;
        const btnH = 24;
        const btnX = cardX + cardW - btnW - 24;
        const btnY = optY + optH - btnH - 8;
        cCtx.fillStyle = '#78350f';
        roundRect(cCtx, btnX, btnY, btnW, btnH, 4, true, true, '#f59e0b', 1);
        cCtx.font = 'bold 14px ' + FONT_UI;
        cCtx.fillStyle = '#fff';
        cCtx.textAlign = 'center';
        cCtx.textBaseline = 'middle';
        cCtx.fillText("拍板敲定", btnX + btnW / 2, btnY + btnH / 2);
      },
      onClick: () => {
        executeFamilyChoice(idx);
      }
    });
    optY += optH + 10;
  });
  const closeBtnW = cardW - 64;
  const closeBtnH = 30;
  const closeBtnX = cardX + 32;
  const closeBtnY = cardY + cardH - closeBtnH - 12;

  drawTactileButton(ctx, {
    id: 'family_event_dismiss',
    x: closeBtnX,
    y: closeBtnY,
    w: closeBtnW,
    h: closeBtnH,
    radius: 5,
    bg: '#1e293b',
    border: '#475569',
    text: "审慎搁置 · 暂不操办",
    font: 'bold 14px ' + FONT_UI,
    textColor: '#94a3b8',
    priority: 100,
    onClick: () => {
      state.activeModal = null;
      state.activeFamilyEvent = null;
      requestRender();
    }
  });
}

// ==========================================
// 十.C 一线现场排险破局弹窗 (Frontline Event Modal)
// ==========================================
function drawFrontlineEventModal() {
  const evt = state.activeFrontlineEvent;
  if (!evt) return;
  const cardW = screenWidth - 28;
  const cardH = 460;
  const cardX = 14;
  const cardY = Math.max(20, Math.round((screenHeight - cardH) / 2));
  ctx.fillStyle = '#1f1317';
  roundRect(ctx, cardX, cardY, cardW, cardH, 12, true, true, '#ef4444', 2);
  drawCornerOrnaments(ctx, cardX, cardY, cardW, cardH, 8, '#ef4444');
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 14px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fca5a5';
  ctx.fillText(fitText(evt.title, cardW - 32, 'bold 14px ' + FONT_CHRONICLE), cardX + 16, cardY + 16);
  ctx.font = '13.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#cbd5e1';
  const lines = wrapTextLines(evt.context, cardW - 32, '13.5px ' + FONT_CHRONICLE);
  const lineLimit = Math.min(4, lines.length);
  for (let i = 0; i < lineLimit; i++) {
    ctx.fillText(lines[i], cardX + 16, cardY + 42 + i * 18);
  }
  let optY = cardY + 124;
  evt.choices.forEach((c, idx) => {
    const optH = 76;
    const fChoiceId = `frontline_choice_${idx}`;
    drawTactileButton(ctx, {
      id: fChoiceId,
      x: cardX + 16,
      y: optY,
      w: cardW - 32,
      h: optH,
      radius: 8,
      bg: '#22161b',
      border: '#7f1d1d',
      priority: 100,
      renderContent: (cCtx) => {
        cCtx.textAlign = 'left';
        cCtx.textBaseline = 'top';
        cCtx.font = 'bold 14px ' + FONT_CHRONICLE;
        cCtx.fillStyle = '#fef08a';
        cCtx.fillText(fitText(c.title, cardW - 52, 'bold 14px ' + FONT_CHRONICLE), cardX + 24, optY + 10);
        cCtx.font = '13.5px ' + FONT_UI;
        cCtx.fillStyle = '#cbd5e1';
        const cLines = wrapTextLines(c.desc, cardW - 135, '13.5px ' + FONT_UI);
        const cLimit = Math.min(2, cLines.length);
        for (let ci = 0; ci < cLimit; ci++) {
          cCtx.fillText(cLines[ci], cardX + 24, optY + 30 + ci * 16);
        }
        const btnW = 76;
        const btnH = 24;
        const btnX = cardX + cardW - btnW - 24;
        const btnY = optY + optH - btnH - 8;
        cCtx.fillStyle = '#7f1d1d';
        roundRect(cCtx, btnX, btnY, btnW, btnH, 4, true, true, '#ef4444', 1);
        cCtx.font = 'bold 14px ' + FONT_UI;
        cCtx.fillStyle = '#fff';
        cCtx.textAlign = 'center';
        cCtx.textBaseline = 'middle';
        cCtx.fillText("一线指令", btnX + btnW / 2, btnY + btnH / 2);
      },
      onClick: () => {
        executeFrontlineChoice(idx);
      }
    });
    optY += optH + 10;
  });
  const bottomBtnW = (cardW - 44) / 2;
  const closeBtnH = 30;
  const closeBtnY = cardY + cardH - closeBtnH - 12;

  drawTactileButton(ctx, {
    id: 'frontline_inspection_btn',
    x: cardX + 16,
    y: closeBtnY,
    w: bottomBtnW,
    h: closeBtnH,
    radius: 5,
    bg: '#78350f',
    border: '#f59e0b',
    text: "🔍 启动雷霆飞检 (1⚡)",
    font: 'bold 14px ' + FONT_UI,
    textColor: '#fef08a',
    priority: 100,
    onClick: () => {
      if (state.lastInspectionYear === state.year) {
        showToast("本年度已完成一次特大工程雷霆飞检，请待来年再巡查！", "info");
        return;
      }
      if ((state.ap || 0) < 1) {
        showToast("今年精力已耗尽，请先迈入下一年！", "alert");
        playSoundEffect('alert');
        return;
      }
      state.ap = Math.max(0, state.ap - 1);
      state.lastInspectionYear = state.year;
      state.activeFrontlineEvent = null;
      triggerInspectionMiniGame();
    }
  });

  drawTactileButton(ctx, {
    id: 'frontline_event_dismiss',
    x: cardX + 28 + bottomBtnW,
    y: closeBtnY,
    w: bottomBtnW,
    h: closeBtnH,
    radius: 5,
    bg: '#1e293b',
    border: '#475569',
    text: "暂退二线 · 研判险情",
    font: 'bold 14px ' + FONT_UI,
    textColor: '#94a3b8',
    priority: 100,
    onClick: () => {
      state.activeModal = null;
      state.activeFrontlineEvent = null;
      requestRender();
    }
  });
}


// ==========================================
// 十.D 三年一届组织履职考评报告弹窗 (Yearly Appraisal Modal)
// ==========================================
function drawAppraisalModal() {
  const app = state.lastAppraisal;
  if (!app) return;

  const cardW = screenWidth - 28;
  const cardH = 460;
  const cardX = 14;
  const cardY = Math.max(20, Math.round((screenHeight - cardH) / 2));

  ctx.fillStyle = '#171220';
  roundRect(ctx, cardX, cardY, cardW, cardH, 12, true, true, app.color || '#f59e0b', 2);
  drawCornerOrnaments(ctx, cardX, cardY, cardW, cardH, 8, app.color || '#f59e0b');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 15px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText(`📋 【${app.year}年度·${app.age}岁】三年履职届满考核报告`, cardX + cardW / 2, cardY + 16);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#94a3b8';
  ctx.fillText(`考核职务：【${state.rankName}】${state.jobTitle}`, cardX + cardW / 2, cardY + 38);

  // 考评等第徽章
  const bY = cardY + 62;
  ctx.fillStyle = '#0f172a';
  roundRect(ctx, cardX + cardW / 2 - 80, bY, 160, 44, 8, true, true, app.color || '#f59e0b', 1.5);

  ctx.font = 'bold 18px ' + FONT_CHRONICLE;
  ctx.fillStyle = app.color || '#f59e0b';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(app.grade, cardX + cardW / 2, bY + 22);

  // 综合得分与六维考评
  const rY = bY + 54;
  ctx.font = 'bold 14px ' + FONT_MONO;
  ctx.fillStyle = '#cbd5e1';
  ctx.fillText(`综合督考得分：${app.score} / 100 分`, cardX + cardW / 2, rY);

  // 考评督办鉴定评语
  const fBoxY = rY + 18;
  const fBoxH = 140;
  ctx.fillStyle = '#1c182a';
  roundRect(ctx, cardX + 16, fBoxY, cardW - 32, fBoxH, 8, true, true, '#334155', 1);

  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 14px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText("📜 组织部综合考核鉴定结论：", cardX + 26, fBoxY + 12);

  ctx.font = '13.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#e2e8f0';
  const lines = wrapTextLines(app.feedback, cardW - 52, '13.5px ' + FONT_CHRONICLE);
  lines.forEach((l, i) => {
    ctx.fillText(l, cardX + 26, fBoxY + 34 + i * 18);
  });

  // 实体组织部朱砂印泥盖印
  drawSeal(ctx, cardX + cardW - 60, fBoxY + fBoxH - 30, "组织审定", `${app.year}年`, 26);

  // 确认领受按钮
  const closeBtnW = cardW - 64;
  const closeBtnH = 36;
  const closeBtnX = cardX + 32;
  const closeBtnY = cardY + cardH - closeBtnH - 14;

  drawTactileButton(ctx, {
    id: 'appraisal_modal_close',
    x: closeBtnX,
    y: closeBtnY,
    w: closeBtnW,
    h: closeBtnH,
    radius: 6,
    bg: '#78350f',
    border: '#f59e0b',
    text: "领受评定 · 赓续奋斗 ➔",
    font: 'bold 14px ' + FONT_CHRONICLE,
    textColor: '#fef08a',
    priority: 100,
    onClick: () => {
      state.activeModal = null;
      playSoundEffect('click');
      requestRender();
    }
  });
}

// ==========================================
// 十.E 局内五大韬略主动技全景弹窗 (Skills Modal)
// ==========================================
function drawSkillsModal() {
  const cardW = screenWidth - 28;
  const cardH = 460;
  const cardX = 14;
  const cardY = Math.max(20, Math.round((screenHeight - cardH) / 2));

  ctx.fillStyle = '#101424';
  roundRect(ctx, cardX, cardY, cardW, cardH, 12, true, true, '#38bdf8', 2);
  drawCornerOrnaments(ctx, cardX, cardY, cardW, cardH, 8, '#38bdf8');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 15px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText("⚡ 临机应策 · 五大处世方略", cardX + cardW / 2, cardY + 16);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#38bdf8';
  ctx.fillText(`当前蓄积谋略心力：${state.sp || 35} / 100`, cardX + cardW / 2, cardY + 36);

  const skills = [
    { key: 'insight', icon: '🔍', title: '【深度洞察】', cost: 20, desc: '透视因果大势，下次重大决策事件成功率直接提升 +30%！' },
    { key: 'shield', icon: '🛡️', title: '【铁壁防线】', cost: 25, desc: '构筑严密防线，全面免疫本年度一次黑天鹅突发冲击！' },
    { key: 'resolve', icon: '⚡', title: '【雷厉风行】', cost: 30, desc: '排山倒海强力攻坚破局！大局声誉 +8，开拓魄力 +5！' },
    { key: 'network', icon: '🤝', title: '【八面来风】', cost: 25, desc: '统筹各界人脉朋友圈！全体名仕好感 +8，筹措应急资本 ¥1.2万！' },
    { key: 'rest', icon: '🌿', title: '【闭门调息】', cost: 20, desc: '养元固本静坐修身！生理健康精力回升 +12！' }
  ];

  let sy = cardY + 60;
  const usedSkillThisYear = state.lastSkillCastYear === state.year;
  skills.forEach((sk) => {
    const sH = 64;
    const canCast = !usedSkillThisYear && getStat("sp", 0) >= sk.cost;

    ctx.fillStyle = canCast ? '#1e293b' : '#0f172a';
    roundRect(ctx, cardX + 16, sy, cardW - 32, sH, 6, true, true, canCast ? '#38bdf8' : '#334155', 1);

    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = canCast ? '#fef08a' : '#94a3b8';
    ctx.fillText(`${sk.icon} ${sk.title}`, cardX + 26, sy + 10);

    ctx.font = '13.5px ' + FONT_UI;
    ctx.fillStyle = canCast ? '#cbd5e1' : '#64748b';
    ctx.fillText(fitText(sk.desc, cardW - 120, '13.5px ' + FONT_UI), cardX + 26, sy + 32);

    const btnW = 68;
    const btnH = 26;
    const btnX = cardX + cardW - btnW - 26;
    const btnY = sy + (sH - btnH) / 2;

    if (canCast) {
      drawTactileButton(ctx, {
        id: `skill_cast_modal_${sk.key}`,
        x: btnX,
        y: btnY,
        w: btnW,
        h: btnH,
        radius: 4,
        bg: '#0369a1',
        border: '#38bdf8',
        text: `施展(${sk.cost})`,
        font: 'bold 14px ' + FONT_UI,
        textColor: '#fff',
        priority: 100,
        onClick: () => {
          castSkill(sk.key);
        }
      });
    } else {
      ctx.fillStyle = '#1e293b';
      roundRect(ctx, btnX, btnY, btnW, btnH, 4, true, true, '#475569', 1);
      ctx.font = 'bold 14px ' + FONT_UI;
      ctx.fillStyle = '#64748b';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(usedSkillThisYear ? '本年已用' : `施展(${sk.cost})`, btnX + btnW / 2, btnY + btnH / 2);
    }

    sy += sH + 8;
  });

  const closeBtnW = cardW - 64;
  const closeBtnH = 32;
  const closeBtnX = cardX + 32;
  const closeBtnY = cardY + cardH - closeBtnH - 12;

  drawTactileButton(ctx, {
    id: 'skills_modal_close',
    x: closeBtnX,
    y: closeBtnY,
    w: closeBtnW,
    h: closeBtnH,
    radius: 5,
    bg: '#1e293b',
    border: '#475569',
    text: "收起方略策卷",
    font: 'bold 14px ' + FONT_UI,
    textColor: '#94a3b8',
    priority: 100,
    onClick: () => {
      state.activeModal = null;
      playSoundEffect('click');
      requestRender();
    }
  });
}

// ==========================================
// 十.F 时代功勋勋章图鉴弹窗 (Achievements Modal)
// ==========================================
function drawAchievementsModal() {
  const cardW = screenWidth - 28;
  const cardH = 460;
  const cardX = 14;
  const cardY = Math.max(20, Math.round((screenHeight - cardH) / 2));

  ctx.fillStyle = '#17131a';
  roundRect(ctx, cardX, cardY, cardW, cardH, 12, true, true, '#f59e0b', 2);
  drawCornerOrnaments(ctx, cardX, cardY, cardW, cardH, 8, '#f59e0b');

  const unlocked = state.unlockedAchievements || [];

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 15px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText("🏆 时代二十大至高功勋勋章", cardX + cardW / 2, cardY + 16);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#fbbf24';
  ctx.fillText(`已载入生平史册：${unlocked.length} / ${ACHIEVEMENTS_LIST.length} 项`, cardX + cardW / 2, cardY + 36);

  let ay = cardY + 60;
  const achCount = Math.min(6, ACHIEVEMENTS_LIST.length);
  for (let idx = 0; idx < achCount; idx++) {
    const ach = ACHIEVEMENTS_LIST[idx];
    const aH = 50;
    const isDone = unlocked.includes(ach.id);

    ctx.fillStyle = isDone ? '#271a17' : '#14121a';
    roundRect(ctx, cardX + 16, ay, cardW - 32, aH, 6, true, true, isDone ? '#f59e0b' : '#334155', 1);

    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = isDone ? '#fef08a' : '#94a3b8';
    ctx.fillText(ach.title, cardX + 26, ay + 8);

    ctx.font = '13.5px ' + FONT_UI;
    ctx.fillStyle = isDone ? '#cbd5e1' : '#64748b';
    ctx.fillText(fitText(ach.desc, cardW - 120, '13.5px ' + FONT_UI), cardX + 26, ay + 26);

    ctx.textAlign = 'right';
    ctx.font = 'bold 14px ' + FONT_UI;
    ctx.fillStyle = isDone ? '#34d399' : '#64748b';
    ctx.fillText(isDone ? "✓ 已载入国史" : "⏳ 尚未达成", cardX + cardW - 26, ay + 18);

    ay += aH + 6;
  }

  const closeBtnW = cardW - 64;
  const closeBtnH = 32;
  const closeBtnX = cardX + 32;
  const closeBtnY = cardY + cardH - closeBtnH - 12;

  drawTactileButton(ctx, {
    id: 'achievements_modal_close',
    x: closeBtnX,
    y: closeBtnY,
    w: closeBtnW,
    h: closeBtnH,
    radius: 5,
    bg: '#1e293b',
    border: '#475569',
    text: "阖上勋章图谱",
    font: 'bold 14px ' + FONT_UI,
    textColor: '#94a3b8',
    priority: 100,
    onClick: () => {
      state.activeModal = null;
      playSoundEffect('click');
      requestRender();
    }
  });
}

// 10.7.1 宿命抓周创角弹窗
function drawFateModal() {
  const cardW = screenWidth - 24;
  const cardH = 525;
  const cardX = 12;
  const cardY = Math.max(10, Math.round((screenHeight - cardH) / 2));
  const profile = state.birthProfile || generateProceduralBirth();
  state.birthProfile = profile;

  ctx.fillStyle = '#111220';
  roundRect(ctx, cardX, cardY, cardW, cardH, 12, true, true, '#d97706', 2);
  drawCornerOrnaments(ctx, cardX, cardY, cardW, cardH, 8, '#f59e0b');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 16px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText("🌟 命途肇始 · 降生家世与先天气禀", screenWidth / 2, cardY + 12);

  ctx.font = '12.5px ' + FONT_UI;
  ctx.fillStyle = '#94a3b8';
  ctx.fillText("每一次降生皆是天地机缘，绝无相同宿命", screenWidth / 2, cardY + 32);

  // 时间成本与随时存档提示 (针对玩家时间成本透明与防丢档保障)
  ctx.font = 'bold 11px ' + FONT_UI;
  ctx.fillStyle = '#38bdf8';
  ctx.fillText("⏳ 本局预计时长：约 15~20 分钟 · 💾 实时自动存档，随时可中断退出", screenWidth / 2, cardY + 48);

  // 1. 婴儿身份信息卡
  const idBarY = cardY + 66;
  const idBarH = 50;
  ctx.fillStyle = '#1c172e';
  roundRect(ctx, cardX + 12, idBarY, cardW - 24, idBarH, 6, true, true, '#c084fc', 1);

  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  ctx.font = 'bold 14px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  const genIcon = profile.gender === 'male' ? '♂ 乾男' : '♀ 坤女';
  drawTraditionalSealBadge(ctx, 'baby', cardX + 30, idBarY + 18, 7, '#fef08a');
  ctx.fillText(`【初度命盘】${profile.fullName} · ${genIcon}`, cardX + 42, idBarY + 18);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#cbd5e1';
  ctx.fillText(`生于 1972年 (0岁) · 五行本命：【${FIVE_ELEMENTS_DESTINY[profile.elementDestiny].name}】`, cardX + 22, idBarY + 36);

  // 2. 出生地与家庭阶级卡片
  const regY = idBarY + idBarH + 8;
  const regH = 104;
  ctx.fillStyle = '#161426';
  roundRect(ctx, cardX + 12, regY, cardW - 24, regH, 6, true, true, '#f59e0b', 1);

  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 14px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText(`【出生风土】${profile.region.name}`, cardX + 20, regY + 10);

  ctx.font = '13px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#94a3b8';
  ctx.fillText(fitText(profile.region.desc, cardW - 44, '13px ' + FONT_CHRONICLE), cardX + 20, regY + 28);

  ctx.font = '13px ' + FONT_UI;
  ctx.fillStyle = '#e2e8f0';
  const p = profile.parents;
  ctx.fillText(fitText(`【严父】${p.father}（${p.fatherRole} · ${p.fatherTrait}）`, cardW - 40, '13px ' + FONT_UI), cardX + 20, regY + 50);
  ctx.fillText(fitText(`【慈母】${p.mother}（${p.motherRole} · ${p.motherTrait}）`, cardW - 40, '13px ' + FONT_UI), cardX + 20, regY + 68);
  ctx.fillText(fitText(`【门楣家风】${(profile.sibling || '').replace(/\s*\(.*?\)/g, '')} · 家底结余: ¥${p.baseSavings}元`, cardW - 40, '13px ' + FONT_UI), cardX + 20, regY + 86);

  // 3. 先天双刃剑特质卡片 (2正1负)
  const trtY = regY + regH + 8;
  const trtH = 142;
  ctx.fillStyle = '#18121f';
  roundRect(ctx, cardX + 12, trtY, cardW - 24, trtH, 6, true, true, '#38bdf8', 1);

  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 14px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#7dd3fc';
  ctx.fillText("〔先天禀赋与早年性情〕", cardX + 20, trtY + 10);

  (profile.traits || []).forEach((t, i) => {
    const ty = trtY + 30 + i * 35;
    const isPos = (t.type === 'pos');
    ctx.fillStyle = isPos ? 'rgba(16, 185, 129, 0.2)' : 'rgba(239, 68, 68, 0.2)';
    roundRect(ctx, cardX + 20, ty, 74, 20, 3, true, true, isPos ? '#10b981' : '#ef4444', 1);

    ctx.font = 'bold 12px ' + FONT_UI;
    ctx.fillStyle = isPos ? '#34d399' : '#f87171';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(t.name, cardX + 20 + 37, ty + 10);

    ctx.textAlign = 'left';
    ctx.font = '12px ' + FONT_UI;
    ctx.fillStyle = '#cbd5e1';
    ctx.fillText(fitText(t.desc, cardW - 130, '12px ' + FONT_UI), cardX + 102, ty + 10);
  });

  // 4. 操作按钮区：上方【⚡ 跳过童年 · 直奔仕途 (直接18岁成年)】+ 下方双按钮【更易身世】与【呱呱坠地】
  const skipBtnH = 34;
  const skipBtnY = cardY + cardH - skipBtnH - 46;
  drawTactileButton(ctx, {
    id: 'skip_childhood_fate_btn',
    x: cardX + 12,
    y: skipBtnY,
    w: cardW - 24,
    h: skipBtnH,
    radius: 6,
    bg: 'rgba(30, 41, 59, 0.95)',
    border: '#38bdf8',
    borderWidth: 1.5,
    text: "⚡ 跳过童年 · 直入仕途 (给默认均衡出身，直接18岁及冠立世) ➔",
    font: 'bold 12.5px ' + FONT_UI,
    textColor: '#38bdf8',
    priority: 100,
    onClick: () => {
      skipChildhoodToAdulthood();
    }
  });

  const btnW = (cardW - 36) / 2;
  const btnH = 32;
  const btnY = cardY + cardH - btnH - 10;

  // 重新投胎按钮
  const rBtnX = cardX + 12;
  drawTactileButton(ctx, {
    id: 'reroll_birth_btn',
    x: rBtnX,
    y: btnY,
    w: btnW,
    h: btnH,
    radius: 6,
    bg: '#261b36',
    border: '#a855f7',
    text: "更易身世 · 重开",
    font: 'bold 13px ' + FONT_CHRONICLE,
    textColor: '#e9d5ff',
    priority: 100,
    onClick: () => {
      state.birthProfile = generateProceduralBirth();
      state.creation.surname = state.birthProfile.surname;
      state.creation.givenName = state.birthProfile.givenName;
      state.creation.gender = state.birthProfile.gender;
      state.creation.elementDestiny = state.birthProfile.elementDestiny;
      finishCharacterCreation({ keepFateModal: true });
      playSoundEffect('click');
      triggerHaptic('light');
      requestRender();
    }
  });

  // 确认出生按钮
  const cBtnX = rBtnX + btnW + 12;
  drawTactileButton(ctx, {
    id: 'confirm_birth_btn',
    x: cBtnX,
    y: btnY,
    w: btnW,
    h: btnH,
    radius: 6,
    bg: '#78350f',
    border: '#f59e0b',
    text: "呱呱坠地 · 踏入人世 ➔",
    font: 'bold 13px ' + FONT_CHRONICLE,
    textColor: '#fef08a',
    priority: 100,
    onClick: () => {
      finishCharacterCreation();
    }
  });
}

function drawDecisionModal() {
  const evt = state.activeDecisionEvent;
  if (!evt) return;

  const choices = evt.choices || [
    { text: "稳妥应对 · 按部就班", successRate: 85, successText: "经受住了风浪考验，履职扎实稳健。", failText: "略有曲折，但守住了基本盘。" },
    { text: "力排众议 · 敢为人先", successRate: 55, successText: "惊天破局！赢得上级首肯与全行业声望飞升！", failText: "阻力重重，背负了一定组织非议。" }
  ];

  const cardW = screenWidth - 28;
  const isDoneResult = state.diceResult && state.diceResult.isDone;
  const isRolling = state.isRollingDice;
  const contentCardH = isDoneResult ? 410 : (isRolling ? 390 : Math.max(430, 160 + choices.length * 88));
  const cardH = Math.min(screenHeight - 32, contentCardH);
  const cardX = 14;
  const cardY = Math.max(16, Math.round((screenHeight - cardH) / 2));

  const isSwan = !!evt.isBlackSwan;
  ctx.fillStyle = '#13111f';
  roundRect(ctx, cardX, cardY, cardW, cardH, 12, true, true, isSwan ? '#ef4444' : '#f59e0b', 2);
  drawCornerOrnaments(ctx, cardX, cardY, cardW, cardH, 8, isSwan ? '#ef4444' : '#f59e0b');

  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';

  ctx.font = 'bold 16px ' + FONT_CHRONICLE;
  ctx.fillStyle = isSwan ? '#fca5a5' : '#fef08a';
  ctx.fillText(fitText((isSwan ? "🚨 突发危机考评：" : "📜 重大历史关口抉择：") + evt.title, cardW - 32, 'bold 16px ' + FONT_CHRONICLE), cardX + 16, cardY + 16);

  // 完整呈现剧情描述 (scene / content / desc)
  ctx.font = '14px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#cbd5e1';
  const rawScene = evt.scene || evt.content || evt.desc || '时代大潮奔涌而至，成败系于此刻决断！';
  const descLines = wrapTextLines(rawScene, cardW - 32, '14px ' + FONT_CHRONICLE);
  const dLimit = Math.min(4, descLines.length);
  for (let i = 0; i < dLimit; i++) {
    ctx.fillText(descLines[i], cardX + 16, cardY + 42 + i * 20);
  }

  if (state.diceResult && state.diceResult.isDone) {
    const resY = cardY + 140;
    const resH = cardH - 156;
    ctx.fillStyle = '#0f172a';
    roundRect(ctx, cardX + 16, resY, cardW - 32, resH, 8, true, true, state.diceResult.color || '#10b981', 1.5);

    ctx.textAlign = 'center';
    ctx.textBaseline = 'top';
    ctx.font = 'bold 16px ' + FONT_CHRONICLE;
    ctx.fillStyle = state.diceResult.color || '#10b981';
    ctx.fillText(state.diceResult.title, cardX + cardW / 2, resY + 16);

    ctx.textAlign = 'left';
    ctx.font = '14px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#e2e8f0';
    const lines = wrapTextLines(state.diceResult.desc, cardW - 60, '14px ' + FONT_CHRONICLE);
    const rLimit = Math.min(5, lines.length);
    for (let i = 0; i < rLimit; i++) {
      ctx.fillText(lines[i], cardX + 30, resY + 48 + i * 20);
    }

    const closeBtnW = cardW - 64;
    const closeBtnH = 38;
    const closeBtnX = cardX + 32;
    const closeBtnY = resY + resH - closeBtnH - 12;

    drawTactileButton(ctx, {
      id: 'dismiss_decision',
      x: closeBtnX,
      y: closeBtnY,
      w: closeBtnW,
      h: closeBtnH,
      radius: 6,
      bg: '#b91c1c',
      border: '#ef4444',
      text: "盖印定论 · 迈入新篇章 ➔",
      font: 'bold 14px ' + FONT_CHRONICLE,
      textColor: '#fff',
      priority: 100,
      onClick: () => {
        dismissDecisionModal();
      }
    });
    return;
  }

  if (state.isRollingDice) {
    const rollY = cardY + 140;
    ctx.fillStyle = '#0f172a';
    roundRect(ctx, cardX + 16, rollY, cardW - 32, 180, 8, true, true, '#38bdf8', 1);

    const cx = cardX + cardW / 2;
    const cy = rollY + 65;
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(diceAnim.angle);
    ctx.fillStyle = '#1e293b';
    roundRect(ctx, -26, -26, 52, 52, 8, true, true, '#38bdf8', 2);
    ctx.font = 'bold 22px ' + FONT_MONO;
    ctx.fillStyle = '#fef08a';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(diceAnim.displayNum, 0, 0);
    ctx.restore();

    ctx.textAlign = 'center';
    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#38bdf8';
    ctx.fillText("🎲 命运之骰激烈翻滚中……", cardX + cardW / 2, rollY + 115);

    ctx.font = '13.5px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#94a3b8';
    ctx.fillText("考量大局智谋、气运与组织信任度", cardX + cardW / 2, rollY + 140);
    return;
  }

  // 三阶朱批公文批示体系 (Executive Endorsements)
  state.activeEndorsement = state.activeEndorsement || 'deep_wisdom';
  const endY = cardY + 120;
  const endBtnW = (cardW - 44) / 3;
  EXECUTIVE_ENDORSEMENTS.forEach((end, eIdx) => {
    const ex = cardX + 16 + eIdx * (endBtnW + 6);
    const isAct = state.activeEndorsement === end.id;
    drawTactileButton(ctx, {
      id: `endorse_${end.id}`,
      x: ex,
      y: endY,
      w: endBtnW,
      h: 24,
      radius: 3,
      bg: isAct ? '#2d1b24' : '#141424',
      border: isAct ? end.color : '#334155',
      text: end.stamp,
      font: isAct ? 'bold 14px ' + FONT_CHRONICLE : '13.5px ' + FONT_UI,
      textColor: isAct ? '#fef08a' : '#94a3b8',
      priority: 110,
      onClick: () => {
        state.activeEndorsement = end.id;
        playSoundEffect('seal_stamp_heavy');
        showToast(`已加盖批注【${end.name}】！${end.desc}`, 'gold');
        requestRender();
      }
    });
  });

  let optY = cardY + 150;
  const optH = choices.length >= 3 ? 74 : 82;
  const optGap = choices.length >= 3 ? 7 : 10;
  choices.forEach((c, cIdx) => {
    const optId = 'choose_opt_' + cIdx + '_' + (c.text || '').slice(0, 4);

    // 科学属性检定与支线协同成功率测算（胜率透明化公式条）
    const detailedRate = (typeof calcChoiceSuccessRateDetailed === 'function')
      ? calcChoiceSuccessRateDetailed(c, state)
      : null;
    const sRate = detailedRate ? detailedRate.rate : calcChoiceSuccessRate(c, state);

    drawTactileButton(ctx, {
      id: optId,
      x: cardX + 16,
      y: optY,
      w: cardW - 32,
      h: optH,
      radius: 8,
      bg: '#1c182a',
      border: cIdx === 2 ? '#a855f7' : '#334155',
      priority: 100,
      renderContent: (cCtx) => {
        cCtx.textAlign = 'left';
        cCtx.textBaseline = 'top';

        cCtx.font = 'bold 14px ' + FONT_CHRONICLE;
        cCtx.fillStyle = cIdx === 2 ? '#e9d5ff' : '#fef08a';
        const stanceBadge = c.tag ? `【${c.tag}】` : '';
        cCtx.fillText(fitText(stanceBadge + c.text, cardW - 52, 'bold 14px ' + FONT_CHRONICLE), cardX + 26, optY + 8);

        cCtx.font = '13.5px ' + FONT_CHRONICLE;
        cCtx.fillStyle = '#cbd5e1';
        const sub = formatEffectsSummaryText(c.effects) || c.effectText || c.successText || "直面关键抉择，成败系于一念之间。";
        cCtx.fillText(fitText(sub, cardW - 140, '13.5px ' + FONT_CHRONICLE), cardX + 26, optY + 28);

        // 第3行：透明化胜率拆解微标签
        const formulaStr = detailedRate ? `🎲 胜率${sRate}% · [${detailedRate.formulaText}]` : `🎲 胜率: ${sRate}%`;
        cCtx.font = 'bold 11px ' + FONT_MONO;
        cCtx.fillStyle = sRate >= 70 ? '#10b981' : (sRate >= 50 ? '#f59e0b' : '#f87171');
        cCtx.fillText(fitText(formulaStr, cardW - 120, 'bold 11px ' + FONT_MONO), cardX + 26, optY + 49);

        const btnW = 84;
        const btnH = 26;
        const btnX = cardX + cardW - btnW - 24;
        const btnY = optY + optH - btnH - 6;

        cCtx.fillStyle = cIdx === 2 ? '#581c87' : '#7f1d1d';
        roundRect(cCtx, btnX, btnY, btnW, btnH, 5, true, true, cIdx === 2 ? '#c084fc' : '#ef4444', 1);

        cCtx.font = 'bold 14px ' + FONT_UI;
        cCtx.fillStyle = '#fff';
        cCtx.textAlign = 'center';
        cCtx.textBaseline = 'middle';
        cCtx.fillText("掷骰决断 ➔", btnX + btnW / 2, btnY + btnH / 2);
      },
      onClick: () => {
        executeDiceChoice(c, sRate);
      }
    });

    optY += optH + optGap;
  });
}

const PROMOTION_STEPS = ['1.同行民主', '2.操守风控', '3.专家票决', '4.全网公示'];

const PROMOTION_MEMBERS_DEF = [
  {
    title: "评审委员会主席",
    check: (s) => {
      const curLvl = Math.max(1, s.govLevel || s.rankIndex || 1);
      const req = getPromotionLadderRequirements(s.track, curLvl + 1);
      return (s.rep || 0) >= (req.repReq > 0 ? req.repReq : 55);
    }
  },
  { title: "行业战略首席专家", check: (s) => (s.courage || 0) >= 58 },
  { title: "学术技术委员会主任", check: (s) => (s.iq || 0) >= 58 },
  { title: "合规风控首席", check: (s) => (s.clean || 0) >= 68 },
  { title: "领军人才评审专员", check: (s) => (s.resilience || 50) >= 55 },
  { title: "行业协会代表", check: (s) => (s.eq || 0) >= 54 },
  {
    title: "产业资本与投融资顾问",
    check: (s) => {
      const curLvl = Math.max(1, s.govLevel || s.rankIndex || 1);
      const req = getPromotionLadderRequirements(s.track, curLvl + 1);
      const reqCap = Math.round((req.capReq || 0) * 0.55);
      return reqCap <= 0 || (s.capital || 0) >= reqCap;
    }
  }
];

const PROMOTION_STEP_BTNS = [
  "进入第二阶段：操守风控审查 ➔",
  "进入第三阶段：专家委员会票决 ➔",
  "进入第四阶段：全网任前公示 ➔"
];

// 10.7.3 组织任用四部曲沙盘考评弹窗 (4-Step Promotion Modal)
function drawPromotionModal() {
  const promo = state.pendingPromotion;
  if (!promo) return;

  const cardW = screenWidth - 28;
  const cardH = 436;
  const cardX = 14;
  const cardY = Math.max(16, Math.round((screenHeight - cardH) / 2));

  ctx.fillStyle = '#171424';
  roundRect(ctx, cardX, cardY, cardW, cardH, 12, true, true, '#f59e0b', 2);
  drawCornerOrnaments(ctx, cardX, cardY, cardW, cardH, 8, '#f59e0b');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 16px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText(`🏆 ${promo.targetRank} 干部竞争性考评`, screenWidth / 2, cardY + 16);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#94a3b8';
  ctx.fillText(fitText(`考察对象：${state.name}同志（拟提拔：${promo.targetJob}）`, cardW - 32, '13.5px ' + FONT_UI), screenWidth / 2, cardY + 38);

  // 阶段指示器 (1 -> 2 -> 3 -> 4)
  const sW = (cardW - 40) / 4;
  for (let idx = 0; idx < PROMOTION_STEPS.length; idx++) {
    const st = PROMOTION_STEPS[idx];
    const stepNum = idx + 1;
    const sx = cardX + 16 + idx * (sW + 2);
    const sy = cardY + 58;
    const isCur = stepNum === state.currentPromotionStep;
    const isDone = stepNum < state.currentPromotionStep;

    ctx.fillStyle = isCur ? '#78350f' : (isDone ? '#064e3b' : '#1e293b');
    roundRect(ctx, sx, sy, sW, 22, 4, true, true, isCur ? '#f59e0b' : (isDone ? '#10b981' : '#334155'), 1);

    ctx.font = 'bold 14px ' + FONT_UI;
    ctx.fillStyle = isCur ? '#fef08a' : (isDone ? '#a7f3d0' : '#64748b');
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(st, sx + sW / 2, sy + 11);
  }

  // 核心内容区根据阶段呈现
  const contentY = cardY + 90;
  const contentH = 260;
  ctx.fillStyle = '#0f111c';
  roundRect(ctx, cardX + 16, contentY, cardW - 32, contentH, 8, true, true, '#334155', 1);

  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';

  if (state.currentPromotionStep === 1) {
    const rate = Math.min(95, Math.max(40, Math.round(50 + (state.eq - 65) * 1.5)));
    state.promoVerdictSuccess = evaluatePromotionStepVerdict(1);

    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#fef08a';
    ctx.fillText("【第一阶段：行业同行无记名民主推荐评议】", cardX + 28, contentY + 14);

    ctx.font = '13.5px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#cbd5e1';
    ctx.fillText("考察同行骨干与下属无记名评议推荐得票率。", cardX + 28, contentY + 42);
    ctx.fillText(`测评基准赞成率：${rate}% (由情商 ${state.eq} 与声望 ${state.rep} 共同决定)`, cardX + 28, contentY + 64);
    ctx.fillText("投递有效选票：120 票（需赞成过半数方可列入考察对象）", cardX + 28, contentY + 86);

    ctx.fillStyle = state.promoVerdictSuccess ? '#064e3b' : '#7f1d1d';
    roundRect(ctx, cardX + 28, contentY + 120, cardW - 56, 44, 6, true, true, state.promoVerdictSuccess ? '#10b981' : '#ef4444', 1);

    ctx.font = 'bold 14px ' + FONT_UI;
    ctx.fillStyle = state.promoVerdictSuccess ? '#a7f3d0' : '#fca5a5';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(state.promoVerdictSuccess ? "🟢 民主推荐顺利过半！列为首选拟任人选！" : "🔴 推荐票未达标，未能进入下一轮考察！", cardX + cardW / 2, contentY + 142);

  } else if (state.currentPromotionStep === 2) {
    const isCleanPass = evaluatePromotionStepVerdict(2);
    state.promoVerdictSuccess = isCleanPass;

    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#fef08a';
    ctx.fillText("【第二阶段：职业操守与诚信风控穿透审查】", cardX + 28, contentY + 14);

    ctx.font = '13.5px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#cbd5e1';
    ctx.fillText("审查廉政底线、资产往来、海外账户及历史重大签字公文。", cardX + 28, contentY + 42);
    ctx.fillText(`廉政清白指数：${state.clean} / 100`, cardX + 28, contentY + 64);
    ctx.fillText("审计档案状态：台账清楚合规，出具清廉审查报告。", cardX + 28, contentY + 86);

    ctx.fillStyle = isCleanPass ? '#064e3b' : '#7f1d1d';
    roundRect(ctx, cardX + 28, contentY + 120, cardW - 56, 44, 6, true, true, isCleanPass ? '#10b981' : '#ef4444', 1);

    ctx.font = 'bold 14px ' + FONT_UI;
    ctx.fillStyle = isCleanPass ? '#a7f3d0' : '#fca5a5';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(isCleanPass ? "🟢 档案核查一清二白！全票出具清廉合规证明！" : "🔴 个人合规事项存疑，依规暂缓任用程序！", cardX + cardW / 2, contentY + 142);

  } else if (state.currentPromotionStep === 3) {
    // 7位泰斗专家实木会议桌 + 桌牌沙盘闭门表决
    let yesCount = 0;
    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#fef08a';
    ctx.fillText("【第三阶段：专家委员会闭门无记名票决】", cardX + 28, contentY + 12);

    // 会议桌桌牌沙盘排布
    const tColW = (cardW - 68) / 3;
    for (let idx = 0; idx < PROMOTION_MEMBERS_DEF.length; idx++) {
      const m = PROMOTION_MEMBERS_DEF[idx];
      const pass = m.check(state);
      if (pass) yesCount++;
      const row = Math.floor(idx / 3);
      const col = idx % 3;
      const tx = cardX + 26 + col * (tColW + 6);
      const ty = contentY + 34 + row * 40;

      ctx.fillStyle = '#1c1917';
      roundRect(ctx, tx, ty, tColW, 34, 4, true, true, '#78350f', 1);

      ctx.font = 'bold 14px ' + FONT_UI;
      ctx.fillStyle = '#fef08a';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'top';
      ctx.fillText(fitText(m.title, tColW - 6, 'bold 14px ' + FONT_UI), tx + tColW / 2, ty + 5);

      ctx.font = 'bold 14px ' + FONT_UI;
      ctx.fillStyle = pass ? '#10b981' : '#ef4444';
      ctx.fillText(pass ? "🟢 举牌赞成" : "🔴 按灭弃权", tx + tColW / 2, ty + 18);
    }
    state.promoVerdictSuccess = yesCount >= 4 || evaluatePromotionStepVerdict(3);

    // 票决结果条
    const resBoxY = contentY + 168;
    ctx.fillStyle = state.promoVerdictSuccess ? '#064e3b' : '#7f1d1d';
    roundRect(ctx, cardX + 28, resBoxY, cardW - 56, 38, 6, true, true, state.promoVerdictSuccess ? '#10b981' : '#ef4444', 1);

    ctx.font = 'bold 14px ' + FONT_UI;
    ctx.fillStyle = state.promoVerdictSuccess ? '#a7f3d0' : '#fca5a5';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(state.promoVerdictSuccess ? `🎉 常委会高票通过！赞成票 ${yesCount} / 7 票！` : `🔴 赞成票仅 ${yesCount} / 7 票，未过半数！`, cardX + cardW / 2, resBoxY + 19);

  } else if (state.currentPromotionStep === 4) {
    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#fef08a';
    ctx.fillText("【第四阶段：全网任前公示与正式荣耀授牌】", cardX + 28, contentY + 14);

    ctx.font = '13.5px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#cbd5e1';
    ctx.fillText("主流权威媒体向全社会公示履职考察成果。", cardX + 28, contentY + 44);
    ctx.fillText("公示期满五日零异议，正式颁发终身荣誉聘任书！", cardX + 28, contentY + 68);
    ctx.fillText(`即将正式履新：【${promo.targetRank} · ${promo.targetJob}】`, cardX + 28, contentY + 92);

    ctx.fillStyle = '#78350f';
    roundRect(ctx, cardX + 28, contentY + 130, cardW - 56, 50, 6, true, true, '#f59e0b', 1.5);

    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#fef08a';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText("🌟 权威机构正式颁发聘书 · 走向时代先锋舞台！", cardX + cardW / 2, contentY + 155);
  }

  // 底部推进按钮
  const nBtnW = cardW - 64;
  const nBtnH = 38;
  const nBtnX = cardX + 32;
  const nBtnY = cardY + cardH - nBtnH - 14;

  let promoText = "服从决议 · 留任蓄力";
  if (state.promoVerdictSuccess) {
    if (state.currentPromotionStep === 4) {
      promoText = `正式履新【${promo.targetJob}】➔`;
    } else {
      promoText = PROMOTION_STEP_BTNS[state.currentPromotionStep - 1];
    }
  }

  drawTactileButton(ctx, {
    id: 'advance_promo_btn',
    x: nBtnX,
    y: nBtnY,
    w: nBtnW,
    h: nBtnH,
    radius: 6,
    bg: state.promoVerdictSuccess ? '#b91c1c' : '#475569',
    border: state.promoVerdictSuccess ? '#ef4444' : '#64748b',
    text: promoText,
    font: 'bold 14px ' + FONT_CHRONICLE,
    textColor: '#fff',
    priority: 100,
    onClick: () => {
      advancePromotionStep();
    }
  });
}

// 10.7.4 时代号外特刊弹窗 (Historical Newspaper Modal)
function drawHeadlineModal() {
  const h = state.activeHeadline;
  if (!h) return;

  const cardW = screenWidth - 28;
  const cardH = 410;
  const cardX = 14;
  const cardY = Math.max(20, Math.round((screenHeight - cardH) / 2));

  // 泛黄复古宣纸背景
  ctx.fillStyle = '#fbf7ee';
  roundRect(ctx, cardX, cardY, cardW, cardH, 8, true, true, '#b45309', 2);

  // 双红杠报头栏
  ctx.strokeStyle = '#dc2626';
  ctx.lineWidth = 2.5;
  ctx.beginPath();
  ctx.moveTo(cardX + 16, cardY + 36);
  ctx.lineTo(cardX + cardW - 16, cardY + 36);
  ctx.stroke();

  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(cardX + 16, cardY + 40);
  ctx.lineTo(cardX + cardW - 16, cardY + 40);
  ctx.stroke();

  // 报刊名与日期
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 16px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#dc2626';
  ctx.fillText(h.paper || '时代观察报 · 号外', cardX + 16, cardY + 14);

  ctx.textAlign = 'right';
  ctx.font = 'bold 14px ' + FONT_MONO;
  ctx.fillStyle = '#78350f';
  ctx.fillText(h.date || `${h.year}年特刊`, cardX + cardW - 16, cardY + 18);

  // 醒目粗体大头条
  ctx.textAlign = 'center';
  ctx.font = 'bold 16.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#1c1917';
  ctx.fillText(fitText(h.headline, cardW - 32, 'bold 16.5px ' + FONT_CHRONICLE), screenWidth / 2, cardY + 54);

  // 副标题
  ctx.font = '13.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#78350f';
  const subLines = wrapTextLines(h.sub, cardW - 36, '13.5px ' + FONT_CHRONICLE);
  const subLimit = Math.min(3, subLines.length);
  for (let i = 0; i < subLimit; i++) {
    ctx.fillText(subLines[i], screenWidth / 2, cardY + 84 + i * 18);
  }

  // 历史述评正文框
  const comY = cardY + 148;
  ctx.fillStyle = '#f4ede0';
  roundRect(ctx, cardX + 16, comY, cardW - 32, 110, 6, true, true, '#d6c7b2', 1);

  ctx.textAlign = 'left';
  ctx.font = 'bold 14px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#78350f';
  ctx.fillText("【时代观察员社评】：", cardX + 26, comY + 12);

  ctx.font = '13.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#292524';
  const cLines = wrapTextLines(h.comment, cardW - 52, '13.5px ' + FONT_CHRONICLE);
  const cLimit = Math.min(4, cLines.length);
  for (let i = 0; i < cLimit; i++) {
    ctx.fillText(cLines[i], cardX + 26, comY + 34 + i * 18);
  }

  // 朱红历史见证公章
  drawSeal(ctx, cardX + cardW - 52, comY + 55, "时代号外", `${h.year}年`, 30);

  // 双按钮组：【剪报珍藏】与【投身新征程】
  const btnW = (cardW - 48) / 2;
  const btnH = 36;
  const btnY = cardY + cardH - btnH - 14;
  const alreadyClipped = (state.collectedClippings || []).some(c => c && c.year === h.year);

  // 1. 剪报珍藏按钮
  const b1X = cardX + 18;
  drawTactileButton(ctx, {
    id: 'collect_headline_clip',
    x: b1X,
    y: btnY,
    w: btnW,
    h: btnH,
    radius: 5,
    bg: alreadyClipped ? '#334155' : '#78350f',
    border: alreadyClipped ? '#64748b' : '#f59e0b',
    text: alreadyClipped ? "✓ 已收入剪报册" : "📰 剪报珍藏 (+3声望)",
    font: 'bold 14px ' + FONT_CHRONICLE,
    textColor: alreadyClipped ? '#94a3b8' : '#fef08a',
    priority: 100,
    onClick: () => {
      if (!state.collectedClippings) state.collectedClippings = [];
      if (alreadyClipped) {
        state.activeModal = null;
        state.activeHeadline = null;
        showToast(`《${h.paper}》本年度号外已收录于剪报册中！`, 'info');
        requestRender();
        return;
      }
      state.collectedClippings.push({ year: h.year, headline: h.headline, paper: h.paper });
      addStat("rep", 3, 0);
      state.activeModal = null;
      state.activeHeadline = null;
      playSoundEffect('paper');
      triggerHaptic('medium');
      showToast(`📰 成功珍藏《${h.paper}》特刊号外！声誉+3！`, 'gold');
      addChronicleItem(state.age, state.year, `【历史剪报】珍藏国家级号外专刊《${h.headline}》，丰富个人时代档案馆。`, "时代剪影", "promo");
      requestRender();
    }
  });

  // 2. 投身新征程按钮
  const b2X = b1X + btnW + 12;
  drawTactileButton(ctx, {
    id: 'close_headline_modal',
    x: b2X,
    y: btnY,
    w: btnW,
    h: btnH,
    radius: 5,
    bg: '#b91c1c',
    border: '#ef4444',
    text: "铭记历史 · 投身新征程 ➔",
    font: 'bold 14px ' + FONT_CHRONICLE,
    textColor: '#fff',
    priority: 100,
    onClick: () => {
      state.activeModal = null;
      state.activeHeadline = null;
      playSoundEffect('paper');
      requestRender();
    }
  });
}

// 10.7.6 高端宴席三轮博弈弹窗
function drawBanquetModal() {
  const cardW = screenWidth - 28;
  const cardH = 380;
  const cardX = 14;
  const cardY = Math.max(20, Math.round((screenHeight - cardH) / 2));

  ctx.fillStyle = '#1a101b';
  roundRect(ctx, cardX, cardY, cardW, cardH, 12, true, true, '#d97706', 2);
  drawCornerOrnaments(ctx, cardX, cardY, cardW, cardH, 8, '#f59e0b');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 16px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText(`🍷 领袖高峰宴饮推杯换盏 (第${banquetState.round}/3轮)`, screenWidth / 2, cardY + 16);

  ctx.font = '13.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#cbd5e1';
  ctx.fillText(`主宾席：${banquetState.guestName} (${banquetState.guestRole})`, screenWidth / 2, cardY + 40);

  // 状态仪表：清醒度 vs 对方好感度
  const mY = cardY + 68;
  ctx.fillStyle = '#120c15';
  roundRect(ctx, cardX + 16, mY, cardW - 32, 60, 6, true, true, '#451a03', 1);

  ctx.textAlign = 'left';
  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#94a3b8';
  ctx.fillText(`自身清醒度：${banquetState.sobriety}%`, cardX + 26, mY + 14);
  ctx.fillText(`对方好感度：${banquetState.favor}%`, cardX + cardW / 2 + 10, mY + 14);

  // 进度条
  ctx.fillStyle = '#1e293b';
  roundRect(ctx, cardX + 26, mY + 34, cardW / 2 - 40, 6, 3, true, false);
  ctx.fillStyle = '#38bdf8';
  roundRect(ctx, cardX + 26, mY + 34, Math.max(2, (banquetState.sobriety / 100) * (cardW / 2 - 40)), 6, 3, true, false);

  ctx.fillStyle = '#1e293b';
  roundRect(ctx, cardX + cardW / 2 + 10, mY + 34, cardW / 2 - 40, 6, 3, true, false);
  ctx.fillStyle = '#f59e0b';
  roundRect(ctx, cardX + cardW / 2 + 10, mY + 34, Math.max(2, (banquetState.favor / 100) * (cardW / 2 - 40)), 6, 3, true, false);

  // 三项酒桌对策按钮
  const bW = cardW - 32;
  const bH = 50;
  let by = cardY + 148;

  const actions = [
    { type: 'drink', title: '🍶 主动豪饮敬酒', desc: '清醒度 -25%，迅速打破隔阂，好感度 +30%' },
    { type: 'tea', title: '🍵 以茶代酒试探', desc: '清醒度 +10%，稳步探听内幕虚实，好感度 +10%' },
    { type: 'promise', title: '🤝 许诺鼎力相助', desc: '消耗行业声望，好感度 +35%，缔结长期战略伙伴！' }
  ];

  actions.forEach((act) => {
    drawTactileButton(ctx, {
      id: 'banquet_act_' + act.type,
      x: cardX + 16,
      y: by,
      w: bW,
      h: bH,
      radius: 6,
      bg: '#221626',
      border: '#6b21a8',
      priority: 100,
      renderContent: (c) => {
        c.textAlign = 'left';
        c.textBaseline = 'top';
        c.font = 'bold 14px ' + FONT_CHRONICLE;
        c.fillStyle = '#fef08a';
        c.fillText(act.title, cardX + 28, by + 10);

        c.font = '13.5px ' + FONT_UI;
        c.fillStyle = '#cbd5e1';
        c.fillText(act.desc, cardX + 28, by + 28);
      },
      onClick: () => {
        handleBanquetAction(act.type);
      }
    });

    by += bH + 12;
  });
}

// 10.7.7 工程安全飞检三点排查弹窗
function drawInspectionModal() {
  const cardW = screenWidth - 28;
  const cardH = 360;
  const cardX = 14;
  const cardY = Math.max(20, Math.round((screenHeight - cardH) / 2));

  ctx.fillStyle = '#101726';
  roundRect(ctx, cardX, cardY, cardW, cardH, 12, true, true, '#38bdf8', 2);
  drawCornerOrnaments(ctx, cardX, cardY, cardW, cardH, 8, '#38bdf8');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 16px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#38bdf8';
  ctx.fillText("🛡️ 特大工程质量安全雷霆飞检", screenWidth / 2, cardY + 16);

  ctx.font = '13.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#94a3b8';
  ctx.fillText("上级突击抽检特大项目工地！现场逐项排险问责：", screenWidth / 2, cardY + 40);

  const items = [
    { key: 'log', title: '1. 隐蔽工程施工日志台账', ok: inspectionState.checkLog },
    { key: 'labor', title: '2. 劳务外包用工资质与实名穿透', ok: inspectionState.checkLabor },
    { key: 'material', title: '3. 特种合金钢材超声波探伤报告', ok: inspectionState.checkMaterial }
  ];

  let iy = cardY + 74;
  items.forEach((it) => {
    const iH = 64;
    drawTactileButton(ctx, {
      id: 'insp_item_' + it.key,
      x: cardX + 16,
      y: iy,
      w: cardW - 32,
      h: iH,
      radius: 6,
      bg: it.ok ? '#064e3b' : '#1e293b',
      border: it.ok ? '#10b981' : '#475569',
      priority: 100,
      renderContent: (c) => {
        c.textAlign = 'left';
        c.textBaseline = 'top';
        c.font = 'bold 14px ' + FONT_CHRONICLE;
        c.fillStyle = it.ok ? '#a7f3d0' : '#f8fafc';
        c.fillText(it.title, cardX + 28, iy + 14);

        c.font = '13.5px ' + FONT_UI;
        c.fillStyle = it.ok ? '#6ee7b7' : '#94a3b8';
        c.fillText(it.ok ? "✓ 现场核验无误 · 台账严丝合缝" : "⚠️ 待调取原始底册核查", cardX + 28, iy + 36);

        const btnW = 76;
        const btnH = 26;
        const btnX = cardX + cardW - btnW - 28;
        const btnY = iy + (iH - btnH) / 2;
        c.fillStyle = it.ok ? '#047857' : '#0284c7';
        roundRect(c, btnX, btnY, btnW, btnH, 4, true, true, '#38bdf8', 1);
        c.font = 'bold 14px ' + FONT_UI;
        c.fillStyle = '#fff';
        c.textAlign = 'center';
        c.textBaseline = 'middle';
        c.fillText(it.ok ? "已排查" : "抽检核验", btnX + btnW / 2, btnY + btnH / 2);
      },
      onClick: () => {
        handleInspectionCheck(it.key);
      }
    });

    iy += iH + 12;
  });
}

// 10.7.8 主角生平全景档案弹窗 (Dossier Modal)
function drawDossierModal() {
  const cardW = screenWidth - 28;
  const cardH = 430;
  const cardX = 14;
  const cardY = Math.max(16, Math.round((screenHeight - cardH) / 2));

  ctx.fillStyle = '#161426';
  roundRect(ctx, cardX, cardY, cardW, cardH, 12, true, true, '#f59e0b', 2);
  drawCornerOrnaments(ctx, cardX, cardY, cardW, cardH, 8, '#f59e0b');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 16px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  const isChildDossier = (state.age || 0) < 18;
  ctx.fillText(isChildDossier ? `📁 ${state.name} · 少年成长档案` : `📁 ${state.name} 同志生平履职档案`, screenWidth / 2, cardY + 16);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#94a3b8';
  ctx.fillText(isChildDossier ? `【${state.rankName || '成长少年'}】· ${state.jobTitle || '故土求学'}` : `【${state.rankName}】· 现任【${state.jobTitle}】`, screenWidth / 2, cardY + 38);

  // 六维雷达能力评估展示
  const rY = cardY + 66;
  const radarH = 130;
  ctx.fillStyle = '#0f111e';
  roundRect(ctx, cardX + 16, rY, cardW - 32, radarH, 8, true, true, '#334155', 1);

  ctx.textAlign = 'left';
  ctx.font = 'bold 14px ' + FONT_UI;
  ctx.fillStyle = '#fef08a';
  ctx.fillText(isChildDossier ? "✦ 少年身心六维成长素养 ✦" : "✦ 履职综合六维全景能力条 ✦", cardX + 28, rY + 12);
  const colW = (cardW - 60) / 2;
  const _RAD_KEYS = [
    { label: isChildDossier ? "聪慧才智" : "大局智谋", key: "iq", color: '#38bdf8' },
    { label: isChildDossier ? "亲和人缘" : "人情练达", key: "eq", color: '#a855f7' },
    { label: isChildDossier ? "少年胆识" : "担当魄力", key: "courage", color: '#f59e0b' },
    { label: isChildDossier ? "品行操守" : "清廉操守", key: "clean", color: '#10b981' },
    { label: isChildDossier ? "邻里口碑" : "时代声望", key: "rep", color: '#fbbf24' },
    { label: "身心体魄", key: "health", color: '#f43f5e' }
  ];
  for (let idx = 0; idx < _RAD_KEYS.length; idx++) {
    const rb = _RAD_KEYS[idx];
    const val = state[rb.key];
    const row = Math.floor(idx / 2);
    const col = idx % 2;
    const rx = cardX + 28 + col * colW;
    const ry = rY + 36 + row * 28;

    ctx.font = '13.5px ' + FONT_UI;
    ctx.fillStyle = '#cbd5e1';
    ctx.textAlign = 'left';
    ctx.fillText(`${rb.label}: ${val}`, rx, ry);

    ctx.fillStyle = '#1e293b';
    roundRect(ctx, rx + 65, ry + 2, colW - 75, 6, 3, true, false);
    ctx.fillStyle = rb.color;
    roundRect(ctx, rx + 65, ry + 2, Math.max(2, (val / 100) * (colW - 75)), 6, 3, true, false);
  }

  // 宗族门风与天资
  const zY = cardY + 208;
  const zH = 140;
  ctx.fillStyle = '#0f111e';
  roundRect(ctx, cardX + 16, zY, cardW - 32, zH, 8, true, true, '#334155', 1);

  ctx.textAlign = 'left';
  ctx.font = 'bold 14px ' + FONT_UI;
  ctx.fillStyle = '#fef08a';
  ctx.fillText("✦ 原生宗族、地域与生辰禀赋 ✦", cardX + 28, zY + 12);

  const origInfo = FAMILY_ORIGINS[state.originKey] || {};
  const regInfo = REGIONAL_SETTINGS[state.regionKey] || {};

  let swornGuardianCount = 0;
  const cList = state.contacts || [];
  for (let ci = 0; ci < cList.length; ci++) {
    if (cList[ci].isSwornGuardian) swornGuardianCount++;
  }

  ctx.font = '13.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#e2e8f0';
  ctx.fillText(`门第出身：【${origInfo.name || '耕读传家'}】`, cardX + 28, zY + 36);
  ctx.fillText(`起步地域：【${regInfo.name || '沿海热土'}】`, cardX + 28, zY + 58);
  ctx.fillText(`获颁时代勋章：${(state.unlockedAchievements || []).length} 枚`, cardX + 28, zY + 80);
  ctx.fillText(`莫逆名仕同盟：${swornGuardianCount} 位`, cardX + 28, zY + 102);

  // 朱砂官方验印
  drawCinnabarSeal(ctx, state.clean >= 75 ? "廉洁奉公" : (state.rep >= 70 ? "大国栋梁" : "实干兴邦"), cardX + cardW - 65, zY + 68, 32, -0.12);

  // 双按钮组：【💾 手动封卷】与【合上档案卷宗】
  const btnW = (cardW - 48) / 2;
  const btnH = 36;
  const btnY = cardY + cardH - btnH - 14;

  // 1. 存档按钮
  const sBtnX = cardX + 18;
  drawTactileButton(ctx, {
    id: 'dossier_save_btn',
    x: sBtnX,
    y: btnY,
    w: btnW,
    h: btnH,
    radius: 6,
    bg: '#0f766e',
    border: '#14b8a6',
    text: "💾 手动封卷留档",
    font: 'bold 14px ' + FONT_CHRONICLE,
    textColor: '#ccfbf1',
    priority: 100,
    onClick: () => {
      saveGameState();
      playSoundEffect('paper');
      showToast("📁 档案与生平履职已永久封存在档！", "gold");
    }
  });

  // 2. 关闭按钮
  const cBtnX = sBtnX + btnW + 12;
  drawTactileButton(ctx, {
    id: 'close_dossier_btn',
    x: cBtnX,
    y: btnY,
    w: btnW,
    h: btnH,
    radius: 6,
    bg: '#b91c1c',
    border: '#ef4444',
    text: "合上档案卷宗 ➔",
    font: 'bold 14px ' + FONT_CHRONICLE,
    textColor: '#fff',
    priority: 100,
    onClick: () => {
      state.activeModal = null;
      playSoundEffect('paper');
      requestRender();
    }
  });
}

// 10.7.9 时代终局结算殿堂弹窗 (Endgame Modal)

// 六十岁传世人生回忆录全景画卷系统 (Procedural Lifetime Memoir Scroll)
function generateLifetimeMemoir() {
  const tConf = TRACK_CONFIGS[state.track] || {};
  let epitaph = "【勤勉持正 · 不负平生】";
  if (state.rep >= 90) epitaph = "【清风亮节 · 众望所归】";
  else if (state.capital >= 1000000) epitaph = "【白手兴家 · 散财有道】";

  const rawName = sanitizeUserInput(state.name || '陈守正');
  const safeMemoirName = (!rawName || rawName.includes('***')) ? '陈守正' : rawName;
  const rawMotto = sanitizeUserInput(state.clanMotto || '清廉奉公，实业报国');
  const safeMotto = (!rawMotto || rawMotto.includes('***')) ? '清廉奉公，实业报国' : rawMotto;

  const careerYears = Math.max(1, (state.age || 60) - 18);
  const startYear = (state.year || 2032) - careerYears;
  const origInfo = FAMILY_ORIGINS[state.originKey] || {};
  const trackTitle = tConf.name || state.track || '基层一线';

  const keyMoments = [
    `【初入世途】${startYear}年自「${origInfo.name || '寻常人家'}」起步，投身${trackTitle}一线；`,
    `【半生耕耘】从业${careerYears}载，历任至「${state.rankName || '业务骨干'} · ${state.jobTitle || '资深专员'}」；`,
    `【立身持家】晚年清誉评分 ${state.clean}，以「${safeMotto}」训诫儿孙；`,
    `【平生故交】一生得 ${(state.contacts && state.contacts.filter(c => c.isSwornGuardian).length) || 1} 位知交故旧扶持相伴；`,
    `【经手实绩】历年主政与业务考评折合 ${state.governanceScore || 82} 分，桩桩件件皆有案可查。`
  ];

  const customPoem = generateCustomEndgamePoem(state);
  const memoirObj = {
    name: safeMemoirName,
    yearStart: startYear,
    yearEnd: state.year,
    careerYears: careerYears,
    epitaph: epitaph,
    keyMoments: keyMoments,
    poem: customPoem,
    dynasticGeneration: state.dynasticGeneration || 1,
    clanPrestige: state.family.prestige || 60,
    capital: state.capital,
    sealText: "平生无愧"
  };

  checkTextContentSafety(safeMemoirName, (isSafe, checkedName) => {
    if (!isSafe || !checkedName || checkedName.includes('***')) {
      memoirObj.name = '陈守正';
      state.name = '陈守正';
      requestRender();
    }
  }, '陈守正');

  return memoirObj;
}

function drawMemoirModal() {
  const cardW = screenWidth - 24;
  const cardH = 475;
  const cardX = 12;
  const cardY = Math.max(16, Math.round((screenHeight - cardH) / 2));
  const memoir = state.activeMemoir || generateLifetimeMemoir();
  const spanYears = memoir.careerYears || Math.max(1, (state.age || 60) - 18);

  // 古典宣纸长卷质感
  ctx.fillStyle = '#21181c';
  roundRect(ctx, cardX, cardY, cardW, cardH, 12, true, true, '#f59e0b', 2);
  drawCornerOrnaments(ctx, cardX, cardY, cardW, cardH, 8, '#f59e0b');

  // 画轴木轴两端质感装饰
  ctx.fillStyle = '#78350f';
  roundRect(ctx, cardX - 4, cardY - 5, cardW + 8, 10, 3, true, true, '#f59e0b', 1);
  roundRect(ctx, cardX - 4, cardY + cardH - 5, cardW + 8, 10, 3, true, true, '#f59e0b', 1);

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 16px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText(`📜 ${memoir.name} · ${spanYears}年履历小传`, screenWidth / 2, cardY + 16);

  ctx.font = 'bold 14px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#f59e0b';
  ctx.fillText(memoir.epitaph, screenWidth / 2, cardY + 40);

  // 卷轴正文古朴暗框
  const bodyH = 320;
  const bodyY = cardY + 64;
  ctx.fillStyle = '#181216';
  roundRect(ctx, cardX + 12, bodyY, cardW - 24, bodyH, 6, true, true, '#334155', 1);

  ctx.textAlign = 'left';
  ctx.font = 'bold 14px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText(`《生平五记》：`, cardX + 22, bodyY + 14);

  memoir.keyMoments.forEach((km, idx) => {
    ctx.font = '13.5px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#cbd5e1';
    ctx.fillText(fitText(km, cardW - 44, '13.5px ' + FONT_CHRONICLE), cardX + 22, bodyY + 36 + idx * 42);
  });

  if (memoir.poem && memoir.poem.couplets) {
    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#fde68a';
    ctx.fillText(`《${memoir.poem.title}》`, cardX + 22, bodyY + 240);
    ctx.font = 'italic 13.5px ' + FONT_CHRONICLE;
    ctx.fillText(fitText(memoir.poem.couplets.join('  '), cardW - 90, 'italic 13.5px ' + FONT_CHRONICLE), cardX + 22, bodyY + 258);
  }
  drawCinnabarSeal(ctx, "平生无愧", cardX + cardW - 54, bodyY + bodyH - 46, 32, -0.12);

  // 收纳长卷返回按钮
  const backBtnW = 140;
  const backBtnH = 32;
  const backBtnX = cardX + (cardW - backBtnW) / 2;
  const backBtnY = cardY + cardH - backBtnH - 12;

  drawTactileButton(ctx, {
    id: 'memoir_close_btn',
    x: backBtnX,
    y: backBtnY,
    w: backBtnW,
    h: backBtnH,
    radius: 6,
    bg: '#78350f',
    border: '#f59e0b',
    text: "合上小传 · 返回 ➔",
    font: 'bold 14px ' + FONT_CHRONICLE,
    textColor: '#fef08a',
    priority: 100,
    onClick: () => {
      state.activeModal = 'endgame';
      requestRender();
    }
  });
}

function drawEndgameModal() {
  const cardW = screenWidth - 28;
  const cardH = 500;
  const cardX = 14;
  const cardY = Math.max(10, Math.round((screenHeight - cardH) / 2));

  ctx.save();
  ctx.fillStyle = '#170c14';
  roundRect(ctx, cardX, cardY, cardW, cardH, 12, true, true, '#f59e0b', 2);
  drawCornerOrnaments(ctx, cardX, cardY, cardW, cardH, 8, '#f59e0b');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 16.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText("📖 盖棺定论 · 一生履历结卷", screenWidth / 2, cardY + 14);

  ctx.font = '13.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#cbd5e1';

  let subText = `${state.year}年，行年${state.age}岁。半生奔忙，终得闲坐庭前看落叶。`;
  if (state.earlyRetireReason) {
    subText = `${state.year}年，因${state.earlyRetireReason}提前卸任。浮名散尽，且把余生还给家人。`;
  } else if (state.age >= 85) {
    subText = `${state.year}年，寿登${state.age}岁。亲历几十年风雨变迁，回首已是万重山。`;
  }
  ctx.fillText(subText, screenWidth / 2, cardY + 36);

  // 🌟 16型多元终局历史定位与 S/A/B/C 综合评级展示
  const arch = state.endgameArchetype || (typeof evaluateEndgameArchetype === 'function' ? evaluateEndgameArchetype(state) : null);
  let philTitle = arch ? `【${arch.grade}级终局 · ${arch.title}】` : "【勤勉中坚 · 平安致仕】";
  let philMotto = arch && arch.summary ? arch.summary : "一步一脚印走过几十年，抬头无愧于天，低头无愧于人。";

  const gradeColorMap = { S: '#fbbf24', A: '#34d399', B: '#38bdf8', C: '#cbd5e1' };
  ctx.font = 'bold 14px ' + FONT_CHRONICLE;
  ctx.fillStyle = (arch && gradeColorMap[arch.grade]) || '#f59e0b';
  ctx.fillText(philTitle, screenWidth / 2, cardY + 58);

  ctx.font = '13.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef3c7';
  ctx.fillText(fitText(philMotto, cardW - 36, '13.5px ' + FONT_CHRONICLE), screenWidth / 2, cardY + 76);

  // 1. 核心数据摘要卡
  const achY = cardY + 96;
  const achH = 110;
  ctx.fillStyle = '#0f111c';
  roundRect(ctx, cardX + 14, achY, cardW - 28, achH, 6, true, true, '#334155', 1);

  ctx.textAlign = 'left';
  ctx.font = '13.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#e2e8f0';

  let ageDesc = `终年岁数：行年 ${state.age} 岁 (平顺安康)`;
  if (state.earlyRetireReason) {
    ageDesc = `终年岁数：行年 ${state.age} 岁 (提前退养：${state.earlyRetireReason})`;
  } else if (state.age >= 90) {
    ageDesc = `终年岁数：寿登 ${state.age} 岁 (期颐高寿 · 儿孙绕膝)`;
  } else if (state.age >= 80) {
    ageDesc = `终年岁数：寿登 ${state.age} 岁 (杖朝之年 · 晚景安宁)`;
  }

  // 终身多样化职业赛道称号评定（优先匹配 12 赛道）
  const trKey = state.track || '';
  const path = state.youthPath || 'gaokao';
  const highRep = (state.rep || 0) >= 85;
  const trackCareerTitles = {
    gov: highRep ? "中流砥柱 · 一方主政表率" : "勤政为民 · 基层政务骨干",
    tech: highRep ? "潜心格物 · 重点工程总师" : "埋头治学 · 科研攻关学者",
    biz: highRep ? "白手兴家 · 民营实业名宿" : "特区闯海 · 实业办厂当家人",
    trade: highRep ? "通商四海 · 远洋外贸掌舵人" : "扬帆出海 · 外贸拓荒老兵",
    industry: highRep ? "百工之师 · 首席功勋技师" : "精益求精 · 车间劳模大师傅",
    military: highRep ? "铁血戌边 · 功勋老兵楷模" : "不负戎装 · 一线建设老兵",
    agri: highRep ? "大地耕者 · 良种推广带头人" : "扎根田间 · 乡土致富领头雁",
    grassroots: highRep ? "万家灯火 · 街巷治保模范" : "枝叶关情 · 社区百姓贴心人",
    art: highRep ? "守艺传薪 · 丹青文脉名家" : "匠心独运 · 传统手艺传承人",
    med: highRep ? "大医精诚 · 杏林仁心国手" : "悬壶济世 · 临床一线名医",
    law: highRep ? "明镜高悬 · 律政辩护大家" : "持平守正 · 涉外法务骨干",
    education: highRep ? "桃李满园 · 杏坛传道先生" : "春风化雨 · 三尺讲台名师"
  };
  let trackCareerTitle = trackCareerTitles[trKey] || ((state.rankName || '资深骨干') + ' · ' + (state.jobTitle || '技术专员'));
  if (!trackCareerTitles[trKey]) {
    if (path === 'vocational') {
      trackCareerTitle = highRep ? "百工之师 · 首席功勋技师" : "精益求精 · 车间劳模大师傅";
    } else if (path === 'agri') {
      trackCareerTitle = highRep ? "大地耕者 · 良种推广带头人" : "扎根田间 · 乡土致富领头雁";
    } else if (path === 'military') {
      trackCareerTitle = highRep ? "铁血戍边 · 功勋老兵楷模" : "不负戎装 · 一线建设老兵";
    } else if (path === 'commerce') {
      trackCareerTitle = highRep ? "白手兴家 · 民营实业名宿" : "特区闯海 · 实业办厂当家人";
    } else if (path === 'gaokao') {
      trackCareerTitle = highRep ? "潜心格物 · 重点工程总师" : "埋头治学 · 科研攻关学者";
    }
  }

  const heirloomStr = state.familyHeirloom ? `案头旧物：${state.familyHeirloom.name} · ${state.familyHeirloom.buff}` : '传家风范：耕读传家 · 清白立身';
  const echoesCount = state.causalEchoes ? state.causalEchoes.length : 0;
  const medalsCount = state.awardedMedals ? state.awardedMedals.length : 0;

  ctx.fillStyle = '#e2e8f0';
  ctx.fillText(`半生行当：${trackCareerTitle}`, cardX + 24, achY + 12);
  ctx.fillText(ageDesc, cardX + 24, achY + 32);
  ctx.fillText(`结余积蓄：¥${(state.capital || 0).toLocaleString()} 元 · 乡里口碑：${getStat("rep", 50)} 分`, cardX + 24, achY + 52);
  const durSec = state.runDurationSec || 0;
  const durText = durSec > 0 ? ` · 历时 ${Math.floor(durSec / 60)}分${durSec % 60}秒` : '';
  ctx.fillText(`生平所历：留下 ${echoesCount} 桩世事回响 · 获授 ${medalsCount} 枚纪念奖章${durText}`, cardX + 24, achY + 72);
  ctx.fillStyle = '#fde68a';
  ctx.fillText(heirloomStr, cardX + 24, achY + 92);

  // 2. 📈 V32 人生沉浮走势折线图 (Canvas Ink Trajectory Graph)
  const graphY = achY + achH + 8;
  const graphH = 135;
  if (typeof drawLifeTrajectoryGraph === 'function') {
    drawLifeTrajectoryGraph(ctx, cardX + 14, graphY, cardW - 28, graphH);
  }

  // 3. 底部按钮组
  const btnW = (cardW - 44) / 2;
  const btnH = 36;
  const btnY = cardY + cardH - btnH - 12;

  // 展开传世长卷、宿命图鉴、风云榜、走势海报、分享结局卡与激励参悟按钮行 (6 键均分排布)
  const mBtnCount = 6;
  const mBtnGap = 4;
  const mBtnW = Math.floor((cardW - 28 - (mBtnCount - 1) * mBtnGap) / mBtnCount);
  const mBtnH = 28;
  const mBtnX = cardX + 14;
  const mBtnY = btnY - mBtnH - 8;

  drawTactileButton(ctx, {
    id: 'view_memoir_btn',
    x: mBtnX,
    y: mBtnY,
    w: mBtnW,
    h: mBtnH,
    radius: 5,
    bg: '#221526',
    border: '#f59e0b',
    text: "📜 生平",
    font: 'bold 11px ' + FONT_CHRONICLE,
    textColor: '#fef08a',
    priority: 100,
    onClick: () => {
      state.activeMemoir = generateLifetimeMemoir();
      state.activeModal = 'memoir_scroll';
      playSoundEffect('paper');
      requestRender();
    }
  });

  drawTactileButton(ctx, {
    id: 'open_endgame_codex_btn',
    x: mBtnX + (mBtnW + mBtnGap) * 1,
    y: mBtnY,
    w: mBtnW,
    h: mBtnH,
    radius: 5,
    bg: '#311042',
    border: '#e879f9',
    text: "📜 图鉴",
    font: 'bold 11px ' + FONT_CHRONICLE,
    textColor: '#f5d0fe',
    priority: 100,
    onClick: () => {
      openEndgameCodexModal();
    }
  });

  drawTactileButton(ctx, {
    id: 'open_leaderboard_btn',
    x: mBtnX + (mBtnW + mBtnGap) * 2,
    y: mBtnY,
    w: mBtnW,
    h: mBtnH,
    radius: 5,
    bg: '#78350f',
    border: '#fbbf24',
    text: "📖 名志",
    font: 'bold 11px ' + FONT_CHRONICLE,
    textColor: '#fde68a',
    priority: 100,
    onClick: () => {
      openLeaderboardModal();
    }
  });

  drawTactileButton(ctx, {
    id: 'open_life_trajectory_poster_btn',
    x: mBtnX + (mBtnW + mBtnGap) * 3,
    y: mBtnY,
    w: mBtnW,
    h: mBtnH,
    radius: 5,
    bg: '#1c1917',
    border: '#f59e0b',
    text: "🖼️ 海报",
    font: 'bold 11px ' + FONT_CHRONICLE,
    textColor: '#fde68a',
    priority: 100,
    onClick: () => {
      openLifeTrajectoryPosterModal();
    }
  });

  drawTactileButton(ctx, {
    id: 'share_endgame_card_btn',
    x: mBtnX + (mBtnW + mBtnGap) * 4,
    y: mBtnY,
    w: mBtnW,
    h: mBtnH,
    radius: 5,
    bg: '#064e3b',
    border: '#34d399',
    text: "📤 寄友",
    font: 'bold 11px ' + FONT_CHRONICLE,
    textColor: '#a7f3d0',
    priority: 100,
    onClick: () => {
      shareEndgameCard();
    }
  });

  const adCapReached = (state.rewardedAdWatchedThisRun || 0) >= WECHAT_MONETIZATION_CONFIG.maxAdTalentsPerRun ||
    (state.heritageBonusTalents || 0) >= WECHAT_MONETIZATION_CONFIG.maxTotalHeritageTalents;
  drawTactileButton(ctx, {
    id: 'rewarded_ad_inspiration_btn',
    x: mBtnX + (mBtnW + mBtnGap) * 5,
    y: mBtnY,
    w: mBtnW,
    h: mBtnH,
    radius: 5,
    bg: adCapReached ? '#1e293b' : '#1e1b4b',
    border: adCapReached ? '#475569' : '#818cf8',
    text: "旧影拾遗",
    font: 'bold 11px ' + FONT_CHRONICLE,
    textColor: adCapReached ? '#94a3b8' : '#e0e7ff',
    priority: 100,
    onClick: () => {
      watchRewardedVideoForInspiration();
    }
  });

  // 子嗣接棒
  const sBtnX = cardX + 16;
  drawTactileButton(ctx, {
    id: 'succession_heir_btn',
    x: sBtnX,
    y: btnY,
    w: btnW,
    h: btnH,
    radius: 6,
    bg: '#78350f',
    border: '#f59e0b',
    text: "后人接棒 · 续写家风 ➔",
    font: 'bold 14px ' + FONT_CHRONICLE,
    textColor: '#fef08a',
    priority: 100,
    onClick: () => {
      state.activeModal = null;
      successionToNextGeneration();
    }
  });

  // 重开新一生
  const cBtnX = sBtnX + btnW + 12;
  drawTactileButton(ctx, {
    id: 'restart_game_btn',
    x: cBtnX,
    y: btnY,
    w: btnW,
    h: btnH,
    radius: 6,
    bg: '#991b1b',
    border: '#ef4444',
    text: "🔄 重新落笔 · 另择一生 ➔",
    font: 'bold 14px ' + FONT_CHRONICLE,
    textColor: '#fee2e2',
    priority: 100,
    onClick: () => {
      state.activeModal = null;
      state.gameScene = 'title';
      state.dynasticInheritance = null;
      state.dynasticGeneration = 1;
      startCharacterCreation(false);
    }
  });

  ctx.restore();
}

// 10.8 特效层 (粒子、浮字、水波纹、落槌印章)
// ------------------------------------------

// 水墨晕染转场动效状态机
let inkWashAnim = {
  active: false,
  radius: 0,
  maxRadius: 600,
  alpha: 0.88,
  onMidpoint: null,
  onFinish: null
};

function triggerInkWashTransition(onMidpoint, onFinish) {
  inkWashAnim.active = true;
  inkWashAnim.radius = 0;
  inkWashAnim.alpha = 0.88;
  inkWashAnim.onMidpoint = onMidpoint;
  inkWashAnim.onFinish = onFinish;
  requestRender();
}

function drawEffectsLayer() {

  // 0.V13 动态日夜四时微光滤镜 (Diurnal Ambient Lighting Layer)
  ctx.save();
  const currentHour = (new Date()).getHours();
  let diurnalColor = 'rgba(255, 255, 255, 0)';
  if (currentHour >= 6 && currentHour < 11) {
    diurnalColor = 'rgba(251, 191, 36, 0.04)'; // 晨曦暖金
  } else if (currentHour >= 11 && currentHour < 16) {
    diurnalColor = 'rgba(255, 255, 255, 0.02)'; // 正午朗朗
  } else if (currentHour >= 16 && currentHour < 19) {
    diurnalColor = 'rgba(217, 70, 239, 0.05)'; // 晚霞金紫
  } else {
    diurnalColor = 'rgba(30, 27, 75, 0.12)';  // 华灯初上月华如练
  }
  ctx.fillStyle = diurnalColor;
  ctx.fillRect(0, 0, screenWidth, screenHeight);
  ctx.restore();


  // 当模态弹窗展开（如大事件重大抉择结算页、终局殿堂）或全屏水墨转场进行时，
  // 智能剔除底层被暗度遮罩覆盖的微光与四时粒子，彻底遏制多层特效叠加时的 GPU 填充率与 CPU 计算峰值
  const isHeavyModalActive = (!!state.activeModal && typeof modalAnimState !== 'undefined' && modalAnimState.progress >= 0.7) || (typeof inkWashAnim !== 'undefined' && inkWashAnim.active);
  if (!isHeavyModalActive && !_perfTracker.isLowEndMode) {
    // 0.V24 天候晨昏四时微光系统 (Diurnal Sky Ambient Lighting)
    if (typeof renderDiurnalSkyAura === 'function') {
      renderDiurnalSkyAura(ctx);
    }

    // 0.V23 四时流转动态粒子系统 (Four-Season Dynamic Particle Ambiance)
    if (typeof updateAndRenderSeasonalParticles === 'function') {
      updateAndRenderSeasonalParticles(ctx);
    }
  }

  // 0.V12 宣纸水墨晕染绽放动效 (Ink-Wash Bloom - 轻量级双阶同心圆填充，彻底消除 createRadialGradient 内存抖动)
  if (typeof inkWashBlooms !== 'undefined' && inkWashBlooms.length > 0) {
    ctx.save();
    const nowTime = Date.now();
    const bloomCap = _perfTracker.isLowEndMode ? 2 : 4;
    if (inkWashBlooms.length > bloomCap) inkWashBlooms.length = bloomCap;
    for (let i = inkWashBlooms.length - 1; i >= 0; i--) {
      const b = inkWashBlooms[i];
      const elapsed = (nowTime - b.birthTime) / 1000;
      b.radius = Math.min(b.maxRadius, b.radius + 3.2);
      b.alpha = Math.max(0, 0.88 - elapsed * 0.9);
      if (b.alpha <= 0.01) {
        inkWashBlooms.splice(i, 1);
        continue;
      }
      ctx.globalAlpha = b.alpha;
      ctx.fillStyle = b.color || 'rgba(15, 23, 42, 0.45)';
      ctx.beginPath();
      ctx.arc(b.x, b.y, b.radius * 0.55, 0, Math.PI * 2);
      ctx.fill();

      ctx.globalAlpha = b.alpha * 0.32;
      ctx.beginPath();
      ctx.arc(b.x, b.y, b.radius, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.restore();
  }

  // 0.V12 金箔星辉阿基米德螺旋汇聚粒子 (Gold Spiral Confetti)
  if (typeof goldConfettiList !== 'undefined' && goldConfettiList.length > 0) {
    ctx.save();
    for (let i = goldConfettiList.length - 1; i >= 0; i--) {
      const p = goldConfettiList[i];
      p.angle += p.speed;
      p.dist = Math.max(2, p.dist - 0.4);
      p.alpha -= 0.018;
      if (p.alpha <= 0.01 || p.dist <= 2) {
        if (p._poolType === 'aroma') releaseAromaParticle(p);
        else if (p._poolType === 'filigree') releaseFiligreeParticle(p);
        else if (p._poolType === 'rubbing') releaseRubbingParticle(p);
        else if (p._poolType === 'celadon') releaseCeladonParticle(p);
        else if (p._poolType === 'teamist') releaseTeaMistParticle(p);
        else if (p._poolType === 'brocade') releaseBrocadeParticle(p);
        else if (p._poolType === 'guqin') releaseGuqinParticle(p);
        else if (p._poolType === 'inkstone') releaseInkstoneParticle(p);
        goldConfettiList.splice(i, 1);
        continue;
      }
      const px = p.x + Math.cos(p.angle) * p.dist;
      const py = p.y + Math.sin(p.angle) * p.dist;
      ctx.globalAlpha = p.alpha;
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.arc(px, py, p.size, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.restore();
  }

  // 0.V32 命运黑天鹅气象与破晓晨曦粒子流
  if (typeof renderAtmosphericFX === 'function') {
    renderAtmosphericFX(ctx);
  }

  // 0. 四时微气候动态粒子穹顶 (春雨 / 夏萤 / 秋枫 / 冬雪 - 模态大事件弹窗展开或低端机模式时智能剔除)
  if (!isHeavyModalActive && !_perfTracker.isLowEndMode) {
    const curTerm = getSolarTerm(state.year, state.age);
    const curSeason = curTerm ? curTerm.season : '春';
    const climateNow = Date.now();

    if (curSeason === '春') {
      // 春雨如酥细雨丝 (单路径批处理)
      ctx.save();
      ctx.strokeStyle = 'rgba(147, 197, 253, 0.28)';
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      for (let i = 0; i < 22; i++) {
        const rx = (climateNow * 0.25 + i * 43) % screenWidth;
        const ry = (climateNow * 0.75 + i * 37) % screenHeight;
        ctx.moveTo(rx, ry);
        ctx.lineTo(rx - 3, ry + 12);
      }
      ctx.stroke();
      ctx.restore();
    } else if (curSeason === '夏') {
      // 盛夏夜空流萤微光
      ctx.save();
      for (let i = 0; i < 14; i++) {
        const fx = (Math.sin(climateNow * 0.001 + i * 2) * 35 + i * 28 + screenWidth) % screenWidth;
        const fy = (Math.cos(climateNow * 0.0012 + i) * 25 + i * 55 + screenHeight) % screenHeight;
        const fAlpha = 0.35 + 0.35 * Math.sin(climateNow * 0.004 + i);
        ctx.fillStyle = `rgba(190, 242, 100, ${fAlpha})`;
        ctx.beginPath();
        ctx.arc(fx, fy, 2, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.restore();
    } else if (curSeason === '秋') {
      // 金秋银杏枫叶飘落 (按琥珀金/丹枫红双色分批)
      ctx.save();
      ctx.beginPath();
      ctx.fillStyle = 'rgba(245, 158, 11, 0.45)';
      for (let i = 0; i < 14; i += 2) {
        const lx = (Math.sin(climateNow * 0.0008 + i) * 30 + i * 33) % screenWidth;
        const ly = (climateNow * 0.12 + i * 61) % screenHeight;
        ctx.moveTo(lx + 2.5, ly);
        ctx.arc(lx, ly, 2.5, 0, Math.PI * 2);
      }
      ctx.fill();

      ctx.beginPath();
      ctx.fillStyle = 'rgba(239, 68, 68, 0.4)';
      for (let i = 1; i < 14; i += 2) {
        const lx = (Math.sin(climateNow * 0.0008 + i) * 30 + i * 33) % screenWidth;
        const ly = (climateNow * 0.12 + i * 61) % screenHeight;
        ctx.moveTo(lx + 2.5, ly);
        ctx.arc(lx, ly, 2.5, 0, Math.PI * 2);
      }
      ctx.fill();
      ctx.restore();
    } else if (curSeason === '冬') {
      // 岁暮飞雪晶莹飘洒 (单路径批处理)
      ctx.save();
      ctx.fillStyle = 'rgba(248, 250, 252, 0.55)';
      ctx.beginPath();
      for (let i = 0; i < 20; i++) {
        const sx = (Math.sin(climateNow * 0.0006 + i * 1.5) * 25 + i * 23) % screenWidth;
        const sy = (climateNow * 0.16 + i * 47) % screenHeight;
        const sr = (i % 3) * 0.8 + 1.2;
        ctx.moveTo(sx + sr, sy);
        ctx.arc(sx, sy, sr, 0, Math.PI * 2);
      }
      ctx.fill();
      ctx.restore();
    }
  }
  // 0.0 摩托罗拉汉显BP机点阵寻呼浮窗微动效
  if (pagerAnim.active && pagerAnim.alpha > 0.01) {
    ctx.save();
    ctx.globalAlpha = Math.max(0, pagerAnim.alpha);
    const pW = 220;
    const pH = 56;
    const px = screenWidth - pW - 12;
    const py = getTopBarH() + 8;

    drawTactileButton(ctx, {
      id: 'pager_notification_hit',
      x: px,
      y: py,
      w: pW,
      h: pH,
      radius: 6,
      bg: '#0f172a',
      pressedBg: '#090d16',
      border: '#334155',
      pressedBorder: '#475569',
      borderWidth: 1.5,
      priority: 45,
      onClick: () => {
        pagerAnim.active = false;
        if (pagerAnim.onConfirm) {
          pagerAnim.onConfirm();
        }
        playSoundEffect('phone');
        requestRender();
      },
      renderContent: (c, isPressed) => {
        // 摩托罗拉标志凹印
        c.textAlign = 'left';
        c.font = 'bold 14px sans-serif';
        c.fillStyle = '#64748b';
        c.fillText("MOTOROLA · 汉显寻呼", px + 8, py + 10);

        // 绿色背光点阵LCD视窗
        c.fillStyle = '#022c22';
        roundRect(c, px + 6, py + 14, pW - 12, 34, 3, true, true, '#059669', 1);

        c.font = 'bold 14px ' + FONT_MONO;
        c.fillStyle = '#34d399';
        c.textBaseline = 'middle';
        c.fillText(fitText(pagerAnim.text, pW - 20, 'bold 14px ' + FONT_MONO), px + 10, py + 31);
      }
    });

    ctx.restore();
  }
  // 0.A 老式手撕黄历翻页飞舞动效
  if (calendarTearAnim.active && calendarTearAnim.alpha > 0.01) {
    ctx.save();
    ctx.translate(calendarTearAnim.x + 58, calendarTearAnim.y + 70);
    ctx.rotate(calendarTearAnim.rot);
    ctx.globalAlpha = Math.max(0, calendarTearAnim.alpha);

    const calW = 116;
    const calH = 138;
    // 怀旧泛黄老宣纸
    ctx.fillStyle = '#fef3c7';
    roundRect(ctx, -calW / 2, -calH / 2, calW, calH, 6, true, true, '#b45309', 1.5);

    // 顶部撕历齿痕红条
    ctx.fillStyle = '#b91c1c';
    roundRect(ctx, -calW / 2, -calH / 2, calW, 26, 4, true, false);

    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#fef08a';
    ctx.fillText("中国老黄历 · 岁律更新", 0, -calH / 2 + 13);

    // 年份大字
    ctx.font = 'bold 26px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#7f1d1d';
    ctx.fillText(String(calendarTearAnim.year), 0, -10);

    // 干支生肖
    ctx.font = 'bold 14px ' + FONT_UI;
    ctx.fillStyle = '#b45309';
    ctx.fillText(`${calendarTearAnim.ganzhi} · 肖${calendarTearAnim.zodiac}`, 0, 18);

    // 宜忌吉言
    ctx.font = 'bold 14px ' + FONT_UI;
    ctx.fillStyle = '#451a03';
    ctx.fillText(calendarTearAnim.yiji, 0, 44);

    ctx.restore();

    calendarTearAnim.x += calendarTearAnim.vx;
    calendarTearAnim.y += calendarTearAnim.vy;
    calendarTearAnim.rot += calendarTearAnim.vrot;
    calendarTearAnim.alpha -= 0.022;
    if (calendarTearAnim.alpha <= 0.01) {
      calendarTearAnim.active = false;
    }
  }

  // 0.B 灵光一闪金色火花粒子 (单次 save/restore 批处理)
  if (typeof inspirationSparks !== 'undefined' && inspirationSparks.length > 0) {
    ctx.save();
    for (let i = inspirationSparks.length - 1; i >= 0; i--) {
      const sp = inspirationSparks[i];
      ctx.fillStyle = sp.color;
      ctx.globalAlpha = Math.max(0, sp.alpha);
      ctx.beginPath();
      ctx.arc(sp.x, sp.y, sp.radius, 0, Math.PI * 2);
      ctx.fill();

      sp.x += sp.vx;
      sp.y += sp.vy;
      sp.vy += 0.08; // 微重力
      sp.alpha -= sp.decay;
      if (sp.alpha <= 0.02) {
        inspirationSparks.splice(i, 1);
      }
    }
    ctx.restore();
  }

  // 1. 触控东方水墨晕染涟漪与墨滴飞溅
  for (let ri = 0; ri < touchRipples.length; ri++) {
    const r = touchRipples[ri];
    ctx.save();
    // A. 柔和墨晕扩散内环
    ctx.fillStyle = r.color;
    ctx.globalAlpha = Math.max(0, r.alpha * 0.18);
    ctx.beginPath();
    ctx.arc(r.x, r.y, r.radius, 0, Math.PI * 2);
    ctx.fill();

    // B. 水墨外轮廓细致毛笔晕边
    ctx.strokeStyle = r.color;
    ctx.lineWidth = 1.6;
    ctx.globalAlpha = Math.max(0, r.alpha * 0.82);
    ctx.beginPath();
    ctx.arc(r.x, r.y, r.radius, 0, Math.PI * 2);
    ctx.stroke();

    // C. 飞白墨滴外漾微动效
    if (r.droplets) {
      ctx.globalAlpha = Math.max(0, r.alpha * 0.65);
      const factor = r.radius / 16;
      for (let di = 0; di < r.droplets.length; di++) {
        const d = r.droplets[di];
        ctx.beginPath();
        ctx.arc(r.x + d.dx * factor, r.y + d.dy * factor, d.r, 0, Math.PI * 2);
        ctx.fill();
      }
    }
    ctx.restore();
  }

  // 2. 墨泥朱砂喷射粒子
  for (let pi = 0; pi < inkParticles.length; pi++) {
    const p = inkParticles[pi];
    ctx.save();
    ctx.fillStyle = p.color;
    ctx.globalAlpha = Math.max(0, p.alpha);
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  // 3. 浮空上升文字
  for (let fi = 0; fi < floatingTexts.length; fi++) {
    const f = floatingTexts[fi];
    ctx.save();
    ctx.font = 'bold 14px ' + FONT_MONO;
    ctx.fillStyle = f.color;
    ctx.globalAlpha = Math.max(0, f.alpha);
    ctx.textAlign = 'center';
    ctx.fillText(f.text, f.x, f.y);
    ctx.restore();
  }

  // 4. 朱砂大印飞落砸下动画
  if (stampAnim.active) {
    ctx.save();
    const curScale = stampAnim.scale;
    ctx.translate(stampAnim.x, stampAnim.y);
    ctx.scale(curScale, curScale);
    ctx.globalAlpha = stampAnim.alpha;

    drawSeal(ctx, 0, 0, stampAnim.text, stampAnim.subText, 40);
    ctx.restore();

    stampAnim.scale -= (stampAnim.scale - stampAnim.targetScale) * 0.28;
    stampAnim.alpha = Math.min(1.0, stampAnim.alpha + 0.15);

    if (Math.abs(stampAnim.scale - stampAnim.targetScale) < 0.05) {
      stampAnim.active = false;
      spawnDustParticles(stampAnim.x, stampAnim.y, '#dc2626', 16);
      if (typeof spawnCinnabarRubbingFX === 'function') {
        spawnCinnabarRubbingFX(stampAnim.x, stampAnim.y, 22);
      }
      triggerHaptic('medium');
      playSoundEffect('seal_stamp_heavy');
      if (stampAnim.onFinish) {
        stampAnim.onFinish();
        stampAnim.onFinish = null;
      }
    }
  }

  // 5. 极端历史灾异气象粒子 (1998特大洪灾暴雨 / 2008南方雪灾飘雪)
  if (state.year === 1998) {
    ctx.save();
    ctx.strokeStyle = 'rgba(147, 197, 253, 0.35)';
    ctx.lineWidth = 1.5;
    for (let i = 0; i < 24; i++) {
      const rx = (Date.now() * 0.4 + i * 47) % screenWidth;
      const ry = (Date.now() * 0.9 + i * 31) % screenHeight;
      ctx.beginPath();
      ctx.moveTo(rx, ry);
      ctx.lineTo(rx - 6, ry + 16);
      ctx.stroke();
    }
    ctx.restore();
  } else if (state.year === 2008) {
    ctx.save();
    ctx.fillStyle = 'rgba(255, 255, 255, 0.55)';
    for (let i = 0; i < 20; i++) {
      const sx = (Math.sin(Date.now() * 0.001 + i) * 20 + i * 39) % screenWidth;
      const sy = (Date.now() * 0.15 + i * 53) % screenHeight;
      ctx.beginPath();
      ctx.arc(sx, sy, (i % 3) + 1.5, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.restore();
  }

  // 6. 水墨晕染转场动效 (Ink Wash Radial Dissolve)
  if (inkWashAnim.active) {
    ctx.save();
    ctx.fillStyle = `rgba(15, 12, 19, ${Math.max(0, inkWashAnim.alpha)})`;
    ctx.beginPath();
    ctx.arc(screenWidth / 2, screenHeight / 2, inkWashAnim.radius, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    inkWashAnim.radius += (inkWashAnim.maxRadius - inkWashAnim.radius) * 0.18 + 15;
    if (inkWashAnim.radius > inkWashAnim.maxRadius * 0.5 && inkWashAnim.onMidpoint) {
      inkWashAnim.onMidpoint();
      inkWashAnim.onMidpoint = null;
    }
    if (inkWashAnim.radius >= inkWashAnim.maxRadius) {
      inkWashAnim.alpha -= 0.08;
      if (inkWashAnim.alpha <= 0.05) {
        inkWashAnim.active = false;
        if (inkWashAnim.onFinish) {
          inkWashAnim.onFinish();
          inkWashAnim.onFinish = null;
        }
      }
    }
    requestRender();
  }
}

// ------------------------------------------
// 10.9 浮动 Toast
// ------------------------------------------
function drawToasts() {
  if (toastQueue.length === 0) return;
  const t = toastQueue[0];
  const tAge = Date.now() - t.startTime;

  if (tAge > 2400) {
    toastQueue.shift();
    return;
  }

  const alpha = tAge > 1800 ? (2400 - tAge) / 600 : Math.min(1.0, tAge / 200);
  const toastY = getTopHeaderBottom() + 14;

  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.font = 'bold 14px ' + FONT_UI;
  const rawTw = ctx.measureText(t.text).width + 28;
  const tw = Math.min(screenWidth - 24, rawTw);
  const tx = (screenWidth - tw) / 2;

  ctx.fillStyle = t.type === 'alert' ? 'rgba(127, 29, 29, 0.95)' : 'rgba(15, 23, 42, 0.95)';
  const borderCol = t.type === 'gold' ? '#f59e0b' : (t.type === 'good' ? '#10b981' : (t.type === 'alert' ? '#ef4444' : '#38bdf8'));
  roundRect(ctx, tx, toastY, tw, 28, 14, true, true, borderCol, 1.5);

  ctx.fillStyle = t.type === 'alert' ? '#fca5a5' : '#f8fafc';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(fitText(t.text, tw - 20, 'bold 14px ' + FONT_UI), tx + tw / 2, toastY + 14);

  ctx.restore();
}

// ==========================================
// 十一、 触控事件与交互处理
// ==========================================

let isRapidAdvancing = false;
let rapidAdvanceTimer = null;
let longPressTimer = null;

function stopRapidAdvance() {
  isRapidAdvancing = false;
  if (rapidAdvanceTimer) {
    clearInterval(rapidAdvanceTimer);
    rapidAdvanceTimer = null;
  }
  if (longPressTimer) {
    clearTimeout(longPressTimer);
    longPressTimer = null;
  }
  saveGameState(true);
  requestRender();
}

if (typeof wx !== 'undefined' && typeof wx.onTouchStart === 'function') {
  wx.onTouchStart(e => {
    const touch = (e.touches && e.touches[0]) || (e.changedTouches && e.changedTouches[0]);
    if (!touch) return;
    const x = typeof touch.clientX !== 'undefined' ? touch.clientX : (typeof touch.x !== 'undefined' ? touch.x : touch.pageX || 0);
    const y = typeof touch.clientY !== 'undefined' ? touch.clientY : (typeof touch.y !== 'undefined' ? touch.y : touch.pageY || 0);

    getAudioContext(); // 交互时自动唤醒音频上下文
    addTouchRipple(x, y);

    // 检测长按新岁推进按钮 (Long-Press Rapid Progression)
    const barY = screenHeight - getBottomDockTotalH() - actionBarH;
    const nextBtnX = 12 + 74 + 6 + 42 + 8;
    const nextBtnW = screenWidth - 12 - nextBtnX;
    const nextBtnH = 36;
    const nextBtnY = barY + (actionBarH - nextBtnH) / 2;

    if (x >= nextBtnX && x <= nextBtnX + nextBtnW && y >= nextBtnY && y <= nextBtnY + nextBtnH && !state.activeModal) {
      if (!state.fastForwardTutorialDismissed && state.age >= 18) {
        state.fastForwardTutorialDismissed = true;
        try {
          if (typeof tt !== 'undefined' && tt.setStorageSync) tt.setStorageSync('lifesim_ff_tutorial_seen', true);
          if (typeof wx !== 'undefined' && wx.setStorageSync) wx.setStorageSync('lifesim_ff_tutorial_seen', true);
        } catch (_) {}
      }
      if (longPressTimer) clearTimeout(longPressTimer);
      longPressTimer = setTimeout(() => {
        isRapidAdvancing = true;
        triggerHaptic('medium');
        playSoundEffect('click');
        showToast("⚡ 韶华奔流 · 岁月连续快进中 (随时点击可暂停)", "good");
        requestRender();
        if (rapidAdvanceTimer) clearInterval(rapidAdvanceTimer);
        rapidAdvanceTimer = setInterval(() => {
          // 严禁机器托管重大历史关口、红线危机与重大弹窗：一旦触发立刻强制暂停快进，交由玩家亲决！
          const CRITICAL_FAST_FORWARD_MODALS = [
            'decision', 'promotion', 'integrity_audit', 'debt_crisis', 'health_crisis',
            'emergency_medical', 'fate', 'zhuazhou', 'rival_showdown', 'historical_wave',
            'conflict', 'high_stakes_conflict', 'three_year_pact_eval', 'gaokao_result'
          ];
          if (state.pendingPhoneCrisis || (state.activeModal && CRITICAL_FAST_FORWARD_MODALS.includes(state.activeModal))) {
            stopRapidAdvance();
            showToast("⚠️ 遭遇重大人生关口，快进已自动暂停请亲自决断！", "alert");
            return;
          }
          if (state.autoAdvisorEnabled && (state.activeModal || state.pendingPhoneCrisis)) {
            resolveCurrentModalByPolicy('strategic');
          }
          if (state.activeModal || state.pendingPhoneCrisis || state.endgameSettled || !state.isStarted) {
            stopRapidAdvance();
            return;
          }
          tickOneYear();
          triggerHaptic('light');
          requestRender();
        }, 280);
      }, 350);
    }

    isTouching = true;
    touchStartX = x;
    touchStartY = y;
    lastTouchY = y;
    touchLastTime = Date.now();
    scrollVelocity = 0;

    // 按钮触控按下态检测 (Button Active Depression) - 统一最高优先级匹配
    pressedHitboxId = null;
    let bestStartBox = null;
    for (let box of hitboxes) {
      if (x >= box.x && x <= box.x + box.width && y >= box.y && y <= box.y + box.height) {
        if (!bestStartBox || (box.priority || 0) > (bestStartBox.priority || 0)) {
          bestStartBox = box;
        }
      }
    }
    if (bestStartBox) {
      pressedHitboxId = bestStartBox.id;
    } else if (!state.activeModal) {
      let bestScrollBox = null;
      for (let box of scrollHitboxes) {
        if (box.y + box.height < -40 || box.y > screenHeight + 40) continue;
        if (x >= box.x && x <= box.x + box.width && y >= box.y && y <= box.y + box.height) {
          if (!bestScrollBox || (box.priority || 0) > (bestScrollBox.priority || 0)) {
            bestScrollBox = box;
          }
        }
      }
      if (bestScrollBox) {
        pressedHitboxId = bestScrollBox.id;
      }
    }
    requestRender();
  });
}

if (typeof wx !== 'undefined' && typeof wx.onTouchMove === 'function') {
  wx.onTouchMove(e => {
    const touch = (e.touches && e.touches[0]) || (e.changedTouches && e.changedTouches[0]);
    if (!touch) return;
    const x = typeof touch.clientX !== 'undefined' ? touch.clientX : (typeof touch.x !== 'undefined' ? touch.x : touch.pageX || 0);
    const y = typeof touch.clientY !== 'undefined' ? touch.clientY : (typeof touch.y !== 'undefined' ? touch.y : touch.pageY || 0);
    const now = Date.now();

    const dy = y - lastTouchY;

    // 橡皮筋阻尼抗拉伸衰减 (Rubber-Band Resistance at Bounds)
    let effectiveDy = dy;
    if (targetScrollY < 0 && dy > 0) {
      const over = -targetScrollY;
      effectiveDy = dy * Math.max(0.12, 1 / (1 + over / 50));
    } else if (targetScrollY > maxScrollY && dy < 0) {
      const over = targetScrollY - maxScrollY;
      effectiveDy = dy * Math.max(0.12, 1 / (1 + over / 50));
    }

    targetScrollY -= effectiveDy;
    scrollY = targetScrollY;

    const dt = now - touchLastTime;
    if (dt > 0) {
      const rawVel = -dy * (16 / dt);
      scrollVelocity = Math.max(-30, Math.min(30, rawVel));
    }

    lastTouchY = y;
    touchLastTime = now;
    scrollbarAlpha = 1.0;

    // 滑动位移超过阈值时取消按钮按下态
    if (pressedHitboxId && (Math.abs(x - touchStartX) > 8 || Math.abs(y - touchStartY) > 8)) {
      pressedHitboxId = null;
      requestRender();
    }
  });
}

if (typeof wx !== 'undefined' && typeof wx.onTouchEnd === 'function') {
  wx.onTouchEnd(e => {
    isTouching = false;
    const now = Date.now();
    if (longPressTimer) {
      clearTimeout(longPressTimer);
      longPressTimer = null;
    }
    if (isRapidAdvancing) {
      stopRapidAdvance();
      return;
    }
    const touch = (e.changedTouches && e.changedTouches[0]) || (e.touches && e.touches[0]);
    if (!touch) {
      pressedHitboxId = null;
      return;
    }
    const x = typeof touch.clientX !== 'undefined' ? touch.clientX : (typeof touch.x !== 'undefined' ? touch.x : touch.pageX || 0);
    const y = typeof touch.clientY !== 'undefined' ? touch.clientY : (typeof touch.y !== 'undefined' ? touch.y : touch.pageY || 0);
    pressedHitboxId = null;

    // 手指若停顿超过 80ms 再抬起，清除惯性速度 (Stop fling on hold)
    if (now - touchLastTime > 80) {
      scrollVelocity = 0;
    }

    const dx = x - touchStartX;
    const dy = y - touchStartY;
    const isDrag = Math.abs(dx) > 10 || Math.abs(dy) > 10;

    // 横向轻扫手势：丝滑切换相邻 Tab
    if (!state.activeModal && Math.abs(dx) > 65 && Math.abs(dy) < 45) {
      const tabs = ['timeline', 'desk', 'moments', 'contacts', 'family', 'strategy'];
      const curIdx = tabs.indexOf(state.activeTab || 'timeline');
      if (dx < -65 && curIdx < tabs.length - 1) {
        switchTab(tabs[curIdx + 1]);
        playSoundEffect('paper');
        triggerHaptic('light');
        return;
      } else if (dx > 65 && curIdx > 0) {
        switchTab(tabs[curIdx - 1]);
        playSoundEffect('paper');
        triggerHaptic('light');
        return;
      }
    }

    // 模态优先触控命中 (优先级最高者优先触发，零数组排序开销)
    let bestHitBox = null;
    for (let box of hitboxes) {
      if (x >= box.x && x <= box.x + box.width && y >= box.y && y <= box.y + box.height) {
        if (!bestHitBox || (box.priority || 0) > (bestHitBox.priority || 0)) {
          bestHitBox = box;
        }
      }
    }
    if (bestHitBox) {
      if (!isDrag || (bestHitBox.priority || 0) >= 90) {
        bestHitBox.handler();
        return;
      }
    }

    // 滚动区触控命中 (仅在非弹窗且非拖拽滑动时，彻底杜绝滑动松手误触)
    if (!state.activeModal && !isDrag) {
      let bestScrollHitBox = null;
      for (let box of scrollHitboxes) {
        // V36 视口外无效包围盒裁剪优化 (Offscreen Hitbox Pruning)
        if (box.y + box.height < -40 || box.y > screenHeight + 40) continue;
        if (x >= box.x && x <= box.x + box.width && y >= box.y && y <= box.y + box.height) {
          if (!bestScrollHitBox || (box.priority || 0) > (bestScrollHitBox.priority || 0)) {
            bestScrollHitBox = box;
          }
        }
      }
      if (bestScrollHitBox) {
        bestScrollHitBox.handler();
        return;
      }
    }
  });
}

if (typeof wx !== 'undefined' && typeof wx.onTouchCancel === 'function') {
  wx.onTouchCancel(() => {
    isTouching = false;
    pressedHitboxId = null;
    if (longPressTimer) {
      clearTimeout(longPressTimer);
      longPressTimer = null;
    }
  });
}

// ==========================================
// 十二、 启动运行与 60FPS 请求循环
// ==========================================
const _raf = (typeof requestAnimationFrame === 'function' ? requestAnimationFrame : null) ||
             (typeof wx !== 'undefined' && typeof wx.requestAnimationFrame === 'function' ? wx.requestAnimationFrame.bind(wx) : null) ||
             (typeof GameGlobal !== 'undefined' && typeof GameGlobal.requestAnimationFrame === 'function' ? GameGlobal.requestAnimationFrame.bind(GameGlobal) : null) ||
             (typeof window !== 'undefined' && typeof window.requestAnimationFrame === 'function' ? window.requestAnimationFrame.bind(window) : null) ||
             function(fn) { return setTimeout(fn, 16); };

function requestRender() {
  clampCoreStats(state);
  _raf(() => {
    animationTick();
    drawFrame();
  });
}

// 持续 60FPS 呼吸循环 (带后台挂起与智能空闲帧频微调防发热守护)
function startRenderLoop() {
  let lastFrameTime = 0;
  function loop(currentTime) {
    if (!state.isAppInBackground) {
      // 检查当前是否有高动态动效（触控操作、按下态、惯性滑动、回弹复位、滚动条渐隐、Tab浮入、骰子旋转、粒子飞舞、Toast浮现等）
      const hasFastAnimation = isTouching ||
        pressedHitboxId !== null ||
        Math.abs(scrollVelocity) > 0.05 ||
        (typeof scrollbarAlpha !== 'undefined' && scrollbarAlpha > 0.01) ||
        Math.abs(targetScrollY - scrollY) > 0.2 ||
        (typeof tabTransition !== 'undefined' && tabTransition.progress < 1.0) ||
        state.isRollingDice ||
        (typeof inkParticles !== 'undefined' && inkParticles.length > 0) ||
        (typeof floatingTexts !== 'undefined' && floatingTexts.length > 0) ||
        (typeof touchRipples !== 'undefined' && touchRipples.length > 0) ||
        (typeof goldConfettiList !== 'undefined' && goldConfettiList.length > 0) ||
        (typeof inspirationSparks !== 'undefined' && inspirationSparks.length > 0) ||
        (typeof inkWashBlooms !== 'undefined' && inkWashBlooms.length > 0) ||
        (typeof toastQueue !== 'undefined' && toastQueue.length > 0) ||
        (typeof calendarTearAnim !== 'undefined' && calendarTearAnim.active) ||
        (typeof stormRainAnim !== 'undefined' && stormRainAnim.active) ||
        (typeof dawnSunbeamAnim !== 'undefined' && dawnSunbeamAnim.active) ||
        (typeof inkWashAnim !== 'undefined' && inkWashAnim.active) ||
        (typeof modalAnimState !== 'undefined' && modalAnimState.progress < 1.0) ||
        (typeof screenShakeX !== 'undefined' && (screenShakeX !== 0 || screenShakeY !== 0));

      const now = currentTime || Date.now();
      // 在纯静止放置浏览时降至 ~15FPS (66ms 间隔)，纯阅读弹窗且静止时降至 ~10FPS (100ms 间隔)
      // 一旦有交互或特效立即满血 60FPS 丝滑渲染，彻底遏制移动端发热与整屏无效重绘功耗
      const isReadingModal = !!state.activeModal && (typeof modalAnimState !== 'undefined' && modalAnimState.progress >= 1.0);
      const targetInterval = hasFastAnimation ? 0 : (isReadingModal ? 100 : 66);

      if (!targetInterval || (now - lastFrameTime) >= targetInterval) {
        lastFrameTime = now;
        animationTick();
        drawFrame();
      }
    }
    _raf(loop);
  }

  // 首帧立即执行同步渲染，彻底消除启动黑屏等待
  try {
    animationTick();
    drawFrame();
    if (typeof console !== 'undefined' && typeof console.log === 'function') {
      console.log("【时代巨浪】首帧渲染完成，当前场景:", state.gameScene);
    }
  } catch (err) {
    console.error("【First Frame Error】", err);
  }
  _raf(loop);
}

// GameEngine and gameState will be exported at the end of the script



// ==========================================
// 高压底线严惩机制 (廉政审查、债务危机、过劳危象)
// ==========================================


function checkHighStakesConsequences() {
  const yr = state.year;
  if (yr < (state.anyCrisisCooldownUntil || 0)) return false;

  // 贤内助伴侣深情至真庇护 (夫妻同心化解二次危机，需已历练过至少一次危机且非长期怠政状态)
  if (state.family && state.family.spouseName && state.family.spouseType === 'soulmate' && (state.inactionStreak || 0) < 3) {
    if (state.clean < 45 && (state.auditCrisisCount || 0) >= 1 && (state.family.prestige || 0) >= 50 && !state.handledEvents[`spouse_clean_${yr}`]) {
      state.handledEvents[`spouse_clean_${yr}`] = true;
      state.clean = 58;
      state.auditCooldownUntil = yr + 4;
      showToast(`贤内助【${state.family.spouseName}】连夜整理合规台账并送来热汤，化解廉政审查危象！`, 'good');
      addChronicleItem(state.age, state.year, `【相濡以沫】在廉政核查风口浪尖，伴侣【${state.family.spouseName}】从容梳理后方台账，清风正气力挽狂澜！`, "齐家润心", "promo");
      playSoundEffect('tea');
      return false;
    }
    if (state.capital < 0 && (state.debtCrisisCount || 0) >= 1 && (state.family.endowmentFund || 0) > 0 && !state.handledEvents[`spouse_debt_${yr}`]) {
      state.handledEvents[`spouse_debt_${yr}`] = true;
      state.capital = 30000;
      state.debtCooldownUntil = yr + 4;
      state.family.endowmentFund = Math.max(0, state.family.endowmentFund - 30000);
      showToast(`贤内助【${state.family.spouseName}】拿出私房体己钱注资，保全居所安宁！`, 'gold');
      addChronicleItem(state.age, state.year, `【同甘共苦】在资金链断裂紧要关头，伴侣【${state.family.spouseName}】倾囊相助拿出体己储蓄，保全家庭底盘。`, "齐家润心", "promo");
      playSoundEffect('coin');
      return false;
    }
  }

  // 1. 廉政风暴与纪检立案专案审查 (清廉 < 54 必触，清廉 < 62 概率抽查，带 12 年冷却期防止连年死循环弹窗)
  const auditProb = state.clean < 54 ? 1.0 : (state.clean < 62 ? Math.min(0.65, 0.16 + (62 - state.clean) * 0.04) : 0);
  if (auditProb > 0 && yr >= (state.auditCooldownUntil || 0) && !state.handledEvents[`audit_${yr}`] && (auditProb >= 1.0 || seededRandom() < auditProb)) {
    state.handledEvents[`audit_${yr}`] = true;
    state.auditCooldownUntil = yr + 12;
    state.anyCrisisCooldownUntil = yr + 4;
    state.unresolvedCrisis = 'audit_crisis';
    state.activeModal = 'integrity_audit';
    reportGameMilestone('crisis_triggered', { type: 'integrity_audit', age: state.age || 18, year: yr });
    playSoundEffect('war');
    triggerHaptic('heavy');
    requestRender();
    return true;
  }

  // 2. 负债危机与破产查封 (资本 < 0 必触，或 32岁后资金链濒临断裂/连续决策失利导致资不抵债，带 12 年冷却期)
  const debtProb = state.capital < 0 ? 1.0 : (((state.age || 18) >= 32 && state.capital < 25000) ? 0.35 : (((state.age || 18) >= 34 && (state.decisionFailCount || 0) >= 11 && (state.debtCrisisCount || 0) === 0 && state.capital < 105000) ? 0.22 : 0));
  if (debtProb > 0 && yr >= (state.debtCooldownUntil || 0) && !state.handledEvents[`debt_${yr}`] && (debtProb >= 1.0 || seededRandom() < debtProb)) {
    state.handledEvents[`debt_${yr}`] = true;
    state.debtCooldownUntil = yr + 12;
    state.anyCrisisCooldownUntil = yr + 4;
    state.unresolvedCrisis = 'debt_crisis';
    state.activeModal = 'debt_crisis';
    reportGameMilestone('crisis_triggered', { type: 'debt_crisis', age: state.age || 18, year: yr });
    playSoundEffect('alert');
    triggerHaptic('heavy');
    requestRender();
    return true;
  }

  // 3. 过劳危象与重疾急救送医 (健康 < 25 必触，健康 < 33 概率触发，带 12 年冷却期)
  const healthProb = state.health < 25 ? 1.0 : (state.health < 33 ? Math.min(0.65, 0.16 + (33 - state.health) * 0.03) : 0);
  if (healthProb > 0 && yr >= (state.healthCooldownUntil || 0) && !state.handledEvents[`health_${yr}`] && (healthProb >= 1.0 || seededRandom() < healthProb)) {
    // V36 三宝护体庇佑 (Sanbao Shield) —— 在已发生过至少一次健康危象后触发免死护盾
    if (state.sanbaoShield && (state.healthCrisisCount || 0) >= 1) {
      state.sanbaoShield = false;
      state.health = 55;
      state.healthCooldownUntil = yr + 6;
      addStat('resilience', 10);
      showToast("☯️【三宝调摄 · 妙手回春】往日精气神充沛之蓄积顿发奇效，化解过劳危象！", "good");
      addChronicleItem(state.age, state.year, "【妙手回春】平日精气神调摄充盈，于重疾过劳边线自愈转安，转危为安！", "调摄安康", "good");
      playSoundEffect('temple_bell_deep');
      return false;
    }
    state.handledEvents[`health_${yr}`] = true;
    state.healthCooldownUntil = yr + 12;
    state.anyCrisisCooldownUntil = yr + 4;
    state.unresolvedCrisis = 'health_crisis';
    state.activeModal = 'health_crisis';
    reportGameMilestone('crisis_triggered', { type: 'health_crisis', age: state.age || 18, year: yr });
    playSoundEffect('alert');
    triggerHaptic('heavy');
    requestRender();
    return true;
  }

  // 4. 连续考评卓越 -> 破格超擢大赏（全生涯限触发一次，且严格同步 govLevel / rankIndex / lifetimeMaxRank）
  if (state.lastAppraisal && state.lastAppraisal.grade && state.lastAppraisal.grade.startsWith('S') && state.rep >= 90 && (state.decisionSuccessCount || 0) >= 18 && (state.govLevel || 1) < 5 && !state.handledEvents['breakthrough_career_once']) {
    state.handledEvents['breakthrough_career_once'] = true;
    state.handledEvents[`breakthrough_${yr}`] = true;
    triggerBreakthroughPromotion();
    return true;
  }

  return false;
}

function triggerBreakthroughPromotion() {
  addStat('rep', 6);
  state.capital += 22000;
  const nextLvl = syncRankProgression(Math.min(5, (state.govLevel || 1) + 1), state);
  clampCoreStats(state);
  const curTrack = TRACK_CONFIGS[state.track] || {};
  const ladder = curTrack.ladder || [];
  const curIdx = ladder.findIndex(l => (l.rank || l.targetRank) === state.rankName || (l.job || l.targetJob) === state.jobTitle);
  const nextTarget = (curIdx >= 0 && curIdx + 1 < ladder.length)
    ? ladder[curIdx + 1]
    : (ladder[Math.min(ladder.length - 1, Math.max(0, nextLvl - 1))] || { rank: "特等功勋专员", job: "大区战略巡视督办" });
  state.rankName = nextTarget.rank || nextTarget.targetRank || "特等功勋专员";
  state.jobTitle = nextTarget.job || nextTarget.targetJob || "大区战略巡视督办";
  playSoundEffect('fanfare');
  showToast(`🌟 经专家评审组破格拔擢晋升【${state.jobTitle}】！声望+6，嘉奖 ¥22,000！`, "gold");
  addChronicleItem(state.age, state.year, `【破格超擢】考核鉴定卓越，大节无亏，组织特批破格提拔，履新【${state.rankName} · ${state.jobTitle}】！`, "荣誉晋升", "promo");
  saveGameState();
}

function executeAuditChoice(choiceIdx) {
  state.unresolvedCrisis = null;
  state.annualActionsTaken = (state.annualActionsTaken || 0) + 1;
  state.auditCrisisCount = (state.auditCrisisCount || 0) + 1;
  state.lifespanCeiling = Math.max(60, (state.lifespanCeiling || 74) - 1);
  state.auditCooldownUntil = (state.year || 1992) + 6;
  state.anyCrisisCooldownUntil = (state.year || 1992) + 2;
  if (choiceIdx === 0) {
    // 方案一：如实陈述·严肃整改·补齐缺口
    state.resolvedCrisesCount = (state.resolvedCrisesCount || 0) + 1;
    state.capital = Math.round(state.capital * 0.78);
    state.clean = Math.max(state.clean, 74);
    state.rep = Math.max(15, getStat('rep', 50) - 8);
    state.rankName = "整改督导专员";
    playSoundEffect('gong');
    showToast("如实说明情况并补齐缺口，成功化解危机！", "alert");
    addChronicleItem(state.age, state.year, "【专项审计】面对合规审查，如实说明违规瑕疵并主动自筹资金补齐缺口，严肃接受通报批评，转任整改督导专员，成功化解审查风波。", "合规自律", "crisis");
  } else {
    // 方案二：依法依规移交责任·承担相应党纪政纪或行业合规处分
    state.capital = Math.round(state.capital * 0.55);
    state.rep = Math.max(10, getStat('rep', 50) - 18);
    state.clean = Math.max(state.clean, 62);
    state.govLevel = Math.max(1, (state.govLevel || 1) - 1);
    state.rankIndex = state.govLevel;
    state.rankName = "基层观察员";
    state.jobTitle = "一线生产协助员";
    playSoundEffect('war');
    showToast("依规查实管理过失，调整基层岗位重新磨砺！", "alert");
    addChronicleItem(state.age, state.year, "【问责处分】经合规部门深入核查，认定在相关项目中存在履职监管不力过失，依规调整至基层岗位反思磨砺。", "违规问责", "crisis");
  }
  clampCoreStats(state);
  state.activeModal = null;
  saveGameState();
  requestRender();
}

function executeDebtChoice(choiceIdx) {
  state.unresolvedCrisis = null;
  state.annualActionsTaken = (state.annualActionsTaken || 0) + 1;
  state.debtCrisisCount = (state.debtCrisisCount || 0) + 1;
  state.lifespanCeiling = Math.max(60, (state.lifespanCeiling || 74) - 1);
  state.debtCooldownUntil = (state.year || 1992) + 6;
  state.anyCrisisCooldownUntil = (state.year || 1992) + 2;
  if (choiceIdx === 0) {
    // 查封商品房降级，平账自救
    state.resolvedCrisesCount = (state.resolvedCrisesCount || 0) + 1;
    if (state.family) {
      state.family.livingLevel = 1;
      state.family.residenceName = '查封安置筒子楼';
    }
    state.capital = Math.max(32000, Math.round((state.capital || 0) * 0.72));
    state.rep = Math.max(15, getStat('rep', 50) - 8);
    playSoundEffect('gong');
    showToast("变卖抵押居所平息债务，平账自救成功化解清算！", "alert");
    addChronicleItem(state.age, state.year, "【债务查封】因资金链断裂遭遇债务危机，被迫变卖抵押居所与个人财产还清欠款，生活重归简朴，成功化解破产风波。", "债务重组", "crisis");
  } else {
    // 求助盟友注资
    const guardian = (state.contacts || []).find(c => c.isSwornGuardian);
    if (guardian) {
      state.resolvedCrisesCount = (state.resolvedCrisesCount || 0) + 1;
      state.capital = Math.max(55000, Math.round((state.capital || 0) * 0.85));
      guardian.affinity = Math.max(40, guardian.affinity - 30);
      playSoundEffect('coin');
      showToast(`莫逆挚友【${guardian.name}】紧急注资 ¥55,000 助你渡过难关！`, "gold");
      addChronicleItem(state.age, state.year, `【绝地注资】在资金链断裂边缘，莫逆挚友【${guardian.name}】筹措巨款注资相助，力挽狂澜化解债务危机。`, "商海破局", "promo");
    } else {
      state.capital = Math.max(24000, Math.round((state.capital || 0) * 0.55));
      state.rep = Math.max(10, getStat('rep', 50) - 16);
      playSoundEffect('alert');
      showToast("无挚友相助！法院强制拍卖部分个人动产，声名受损！", "alert");
      addChronicleItem(state.age, state.year, "【破产清算】缺乏外部资金援助，法院启动强制拍卖程序执行个人名下动产，信用严重受创。", "破产风波", "crisis");
    }
  }
  clampCoreStats(state);
  state.activeModal = null;
  saveGameState();
  requestRender();
}

function executeHealthChoice() {
  state.unresolvedCrisis = null;
  state.annualActionsTaken = (state.annualActionsTaken || 0) + 1;
  state.healthCrisisCount = (state.healthCrisisCount || 0) + 1;
  state.resolvedCrisesCount = (state.resolvedCrisesCount || 0) + 1;
  state.lifespanCeiling = Math.max(60, (state.lifespanCeiling || 74) - 2);
  state.healthCooldownUntil = (state.year || 1992) + 6;
  state.anyCrisisCooldownUntil = (state.year || 1992) + 2;
  state.capital = Math.max(0, state.capital - 15000);
  state.health = Math.max(state.health || 44, state.healthCrisisCount >= 2 ? 44 : 54);
  state.sp = 25;
  if (state.healthCrisisCount >= 3 && (state.age || 18) >= 54) {
    state.burnedOutRetire = true;
  }
  clampCoreStats(state);
  playSoundEffect('tea');
  showToast(`紧急送医救治！健康恢复至${state.health}，但久劳伤及元气。`, "info");
  addChronicleItem(state.age, state.year, "【过劳送医】在建设一线突发心脑血管险情紧急送医急救，虽脱离危险但落下了慢性病根，元气大伤。", "积劳成疾", "crisis");
  state.activeModal = null;
  saveGameState();
  requestRender();
}

// 统一策略弹窗抉择代理器（支持 'skip' | 'random' | 'first' | 'auto' | 'normal' | 'strategic'）
function resolveCurrentModalByPolicy(policy = 'strategic') {
  if (state.pendingPhoneCrisis) {
    if (policy === 'skip') {
      state.pendingPhoneCrisis = null;
      return 'skipped_phone';
    }
    answerRedPhone();
  }
  const m = state.activeModal;
  if (!m || m === 'endgame') return null;

  if (policy === 'skip') {
    state.activeModal = null;
    return 'skipped:' + m;
  }

  // 根据不同玩家画像动态调整年度工作方针（若玩家或测试显式锁定 _lockedStrategy 则保持锁定）
  const seedHash = Math.abs((state.age || 18) * 13 + (state.name ? state.name.charCodeAt(0) : 7));
  if ((policy === 'strategic' || policy === 'normal') && (state.age || 0) >= 18 && getStat('health', 80) < 58 && (state.ap || 0) > 0 && state._lockedStrategy !== 'aggressive' && typeof triggerWellnessAction === 'function') {
    triggerWellnessAction();
  }
  state._internalStrategySet = true;
  if (state._lockedStrategy) {
    state.strategy = state._lockedStrategy;
  } else if (policy === 'strategic') {
    if (getStat('health', 80) < 54) state.strategy = 'wellness';
    else if (getStat('clean', 80) < 65) state.strategy = 'clean';
    else if ((seedHash % 7 === 0) && (state.age || 18) < 46 && getStat('health', 80) >= 64) state.strategy = 'aggressive';
    else if ((seedHash % 11 === 0) && (state.age || 18) < 52) state.strategy = 'network';
    else state.strategy = 'balanced';
  } else if (policy === 'normal') {
    if (getStat('health', 80) < 54) state.strategy = 'wellness';
    else if (getStat('clean', 80) < 64) state.strategy = 'clean';
    else state.strategy = 'balanced';
  } else if (policy === 'auto') {
    // 自动巡航采取稳健或按需调养方针
    state.strategy = getStat('health', 80) < 54 ? 'wellness' : 'balanced';
  } else if (policy === 'random') {
    const stratKeys = ['aggressive', 'balanced', 'clean', 'network', 'wellness'];
    state.strategy = stratKeys[seedHash % stratKeys.length];
  }
  state._internalStrategySet = false;

  if (m === 'fate') {
    if (!state._disableAutoTalentPurchase && (policy === 'strategic' || policy === 'normal' || policy === 'auto')) {
      const talentPriority = policy === 'strategic'
        ? ['breakthrough', 'ironclad', 'network', 'decisive', 'wealth', 'vitality', 'clairvoyance', 'dynasty']
        : ['vitality', 'network', 'ironclad', 'wealth', 'breakthrough', 'clairvoyance', 'decisive', 'dynasty'];
      const rotOffset = Math.abs(_gameSeed || 0) % talentPriority.length;
      for (let ti = 0; ti < talentPriority.length && (state.talentPoints || 0) > 0; ti++) {
        const tid = policy === 'strategic'
          ? talentPriority[ti]
          : talentPriority[(ti + rotOffset) % talentPriority.length];
        if (!hasTalent(tid)) {
          unlockTalent(tid);
        }
      }
    }
    finishCharacterCreation();
    return 'fate_confirmed';
  }
  if (m === 'zhuazhou') {
    const items = Array.isArray(ZHUAZHOU_ITEMS) ? ZHUAZHOU_ITEMS : [];
    const pickIdx = (policy === 'random' || policy === 'auto')
      ? Math.floor(seededRandom() * items.length)
      : (policy === 'first' ? 0 : (state.age + getStat("iq", 0)) % Math.max(1, items.length));
    const item = items[pickIdx] || items[0];
    if (item) {
      state.zhuazhouItem = item;
      state.tags = state.tags || {};
      state.tags['seed_' + item.seed] = true;
    }
    state.activeModal = null;
    return 'zhuazhou_picked';
  }
  if (m === 'childhood_fast_forward_prompt') {
    state.activeModal = null;
    if (policy === 'strategic' || policy === 'first' || policy === 'auto') {
      if (typeof skipChildhoodToAdulthood === 'function') {
        skipChildhoodToAdulthood();
      }
      return 'childhood_fast_forward_skipped';
    } else {
      return 'childhood_fast_forward_continued';
    }
  }
  if (m === 'daily_challenge_hub' || m === 'life_trajectory_poster') {
    state.activeModal = null;
    return 'hub_modal_dismissed';
  }
  if (m === 'adult_ceremony_notice') {
    state.activeModal = null;
    flushNextQueuedModal();
    return 'adult_ceremony_confirmed';
  }
  if (m === 'decision') {
    const evt = state.activeDecisionEvent;
    const choices = (evt && Array.isArray(evt.choices)) ? evt.choices : [];
    if (choices.length === 0) {
      dismissDecisionModal();
      return 'decision_empty';
    }
    let bestIdx = 0;
    const effectivePolicy = (policy === 'normal' && seededRandom() < 0.24) ? 'random' : policy;
    if (effectivePolicy === 'random') {
      if (policy === 'normal' && getStat('health', 80) < 54 && choices.length > 1) {
        bestIdx = 1 + Math.floor(seededRandom() * (choices.length - 1));
      } else {
        bestIdx = Math.floor(seededRandom() * choices.length);
      }
    } else if (effectivePolicy === 'first') {
      bestIdx = 0;
    } else if (effectivePolicy === 'auto') {
      // 自动巡航（保守稳妥代理）：优先挑选门槛较低、守正无违纪风险的稳妥选项，绝不主动选违纪捷径
      let safestScore = -1e9;
      choices.forEach((ch, idx) => {
        const req = typeof ch.reqVal === 'number' ? ch.reqVal : 58;
        const c = ch.costs || {};
        const eff = ch.effects || {};
        const greyPen = (ch.isGreyOption || (eff.clean || 0) < -1) ? 45 : 0;
        const costPenalty = Math.abs(c.health || 0) * 3.5 + Math.abs(c.clean || 0) * 6 + Math.abs(c.capital || 0) / 1800 + greyPen;
        const safety = (100 - req) - costPenalty + (idx === 1 ? 6 : 0);
        if (safety > safestScore) {
          safestScore = safety;
          bestIdx = idx;
        }
      });
    } else {
      // 'strategic' / 'normal'(70%): 综合考量检定通过率 (calcChoiceSuccessRate)、赛道抱负契合度、成功净收益与代价反噬
      const tr = state.track || state.preferredTrack || 'gov';
      let bestScore = -1e9;
      choices.forEach((ch, idx) => {
        const p = calcChoiceSuccessRate(ch, state) / 100;
        const eff = ch.effects || {};
        const c = ch.costs || {};
        const fEff = ch.failEffects || { [ch.statReq || 'iq']: -4, rep: -4, health: -3 };
        const evalBundle = (b) => {
          let s = 0;
          const wClean = getStat('clean', 80) < 68 ? 3.8 : (['gov', 'agri', 'grassroots', 'law', 'med', 'education'].includes(tr) ? 2.4 : 1.5);
          const wHealth = getStat('health', 80) < 50 ? 4.2 : 1.6;
          const wRep = getStat('rep', 40) < 84 ? 2.8 : 1.7;
          const wIq = ['tech', 'industry', 'art', 'med', 'law', 'education'].includes(tr) ? 2.5 : (getStat('iq', 50) < 62 ? 2.0 : 1.3);
          const wEq = ['art', 'gov', 'biz', 'trade', 'education', 'grassroots'].includes(tr) ? 2.5 : (getStat('eq', 50) < 60 ? 2.2 : 1.4);
          const wCourage = ['industry', 'military', 'biz', 'trade'].includes(tr) ? 2.5 : (getStat('courage', 50) < 58 ? 2.0 : 1.3);
          const wRes = ['agri', 'grassroots', 'military'].includes(tr) ? 2.4 : 1.3;
          const wCap = ['biz', 'trade', 'agri', 'grassroots'].includes(tr) ? (1 / 1600) : (1 / 3200);
          s += (b.clean || 0) * wClean;
          s += (b.health || 0) * wHealth;
          s += (b.rep || 0) * wRep;
          s += (b.iq || 0) * wIq;
          s += (b.eq || 0) * wEq;
          s += (b.courage || 0) * wCourage;
          s += (b.resilience || 0) * wRes;
          s += (b.capital || 0) * wCap;
          return s;
        };
        const netSuccessScore = evalBundle(eff) + evalBundle(c) * 0.65;
        let score = p * netSuccessScore + (1 - p) * evalBundle(fEff) + (p - 0.5) * 20;
        if ((state.capital || 0) + (eff.capital || 0) + (c.capital || 0) < 0) score -= 55;
        if (getStat('clean', 80) + (eff.clean || 0) + (c.clean || 0) < 58) score -= 50;
        if (getStat('health', 80) + (eff.health || 0) + (c.health || 0) < 35) score -= 60;
        if (score > bestScore) {
          bestScore = score;
          bestIdx = idx;
        }
      });
    }
    if (typeof wx !== 'undefined' && !state._isHeadlessSimulation) {
      state.delegatedDecisionsCount = (state.delegatedDecisionsCount || 0) + 1;
    }
    state._isDelegatingDecision = true;
    executeDiceChoice(bestIdx);
    state._isDelegatingDecision = false;
    dismissDecisionModal();
    return 'decision_choice_' + bestIdx;
  }
  if (m === 'promotion') {
    finishPromotionProcess(evaluatePromotionStepVerdict(4));
    return 'promotion_resolved';
  }
  if (m === 'integrity_audit') {
    const idx = policy === 'random' ? (seededRandom() < 0.5 ? 0 : 1) : 0;
    executeAuditChoice(idx);
    return 'audit_choice_' + idx;
  }
  if (m === 'debt_crisis') {
    const hasGuardian = !!(state.contacts || []).find(c => c.isSwornGuardian);
    const idx = policy === 'random' ? (seededRandom() < 0.5 ? 0 : 1) : (hasGuardian ? 1 : 0);
    executeDebtChoice(idx);
    return 'debt_choice_' + idx;
  }
  if (m === 'health_crisis') {
    executeHealthChoice();
    return 'health_resolved';
  }
  if (m === 'high_stakes_conflict') {
    const conf = state.activeConflictEvent;
    if (conf) {
      const ch = (policy === 'random' && seededRandom() < 0.5) ? conf.choiceB : (getStat('health', 80) < 50 && conf.choiceB ? conf.choiceB : conf.choiceA);
      if (ch && ch.effects) {
        Object.keys(ch.effects).forEach(k => {
          const rawV = ch.effects[k];
          if (CORE_BOUNDED_STATS[k]) {
            const scaledV = rawV > 0 ? Math.min(4, Math.max(1, Math.round(rawV * 0.2))) : Math.max(-6, Math.round(rawV * 0.5));
            addStat(k, scaledV);
          } else if (k === 'capital') {
            state.capital += Math.max(-12000, Math.min(14000, Math.round(rawV * 0.25)));
          }
        });
      }
    }
    state.annualActionsTaken = (state.annualActionsTaken || 0) + 1;
    state.activeModal = null;
    flushNextQueuedModal();
    return 'conflict_resolved';
  }
  if (m === 'karma_nexus') {
    const ke = state.activeKarmaEvent;
    if (ke && ke.type === 'stage1' && ke.data) {
      const pickA = policy === 'random' ? (seededRandom() < 0.5) : true;
      const ch = pickA ? ke.data.choiceA : ke.data.choiceB;
      if (ch && ch.flag) state[ch.flag] = true;
      addStat('resilience', 3);
    } else {
      addStat('resilience', 4);
    }
    state.annualActionsTaken = (state.annualActionsTaken || 0) + 1;
    state.activeModal = null;
    flushNextQueuedModal();
    return 'karma_resolved';
  }
  if (m === 'frontline_event') {
    let pickIdx = 2;
    if (policy === 'random') {
      pickIdx = Math.floor(seededRandom() * 3);
    } else if (policy === 'strategic') {
      pickIdx = getStat('clean', 75) < 68 ? 2 : (getStat('health', 70) >= 56 && getStat('courage', 50) >= 62 ? 0 : ((state.capital || 0) >= 6000 ? 1 : 2));
    } else if (policy === 'normal') {
      const r = seededRandom();
      pickIdx = r < 0.42 ? 0 : (r < 0.72 && (state.capital || 0) >= 6000 ? 1 : 2);
    }
    executeFrontlineChoice(pickIdx);
    if (state.activeModal === 'frontline_event') {
      executeFrontlineChoice(2);
    }
    return 'frontline_resolved';
  }
  if (m === 'family_event') {
    let pickIdx = 2;
    if (policy === 'random') {
      pickIdx = Math.floor(seededRandom() * 3);
    } else if (policy === 'strategic') {
      pickIdx = (state.capital || 0) >= 48000 ? 0 : ((state.capital || 0) >= 22000 ? 1 : 2);
    } else if (policy === 'normal') {
      const r = seededRandom();
      pickIdx = r < 0.36 ? 0 : (r < 0.68 ? 1 : 2);
    }
    executeFamilyChoice(pickIdx);
    if (state.activeModal === 'family_event') {
      executeFamilyChoice(2);
    }
    return 'family_resolved';
  }
  state.annualActionsTaken = (state.annualActionsTaken || 0) + 1;
  state.activeModal = null;
  flushNextQueuedModal();
  return 'dismissed:' + m;
}



