// 1. 岁月相册展堂弹窗 (Memory Album Modal)
function drawMemoryAlbumModal() {
  const cardW = screenWidth - 28;
  const cardH = 460;
  const cardX = 14;
  const cardY = Math.max(16, Math.round((screenHeight - cardH) / 2));

  // 泛黄复古皮革相册封面背景
  ctx.fillStyle = '#1e1a24';
  roundRect(ctx, cardX, cardY, cardW, cardH, 10, true, true, '#eab308', 2);
  drawCornerOrnaments(ctx, cardX, cardY, cardW, cardH, 8, '#eab308');

  // 顶栏相册标题
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 15px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  const unlocked = state.memoryAlbum || [];
  ctx.fillText(`📷 流金岁月 · 生平纪实相册 (${unlocked.length}/12)`, screenWidth / 2, cardY + 14);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#94a3b8';
  ctx.fillText("每一张发黄的相片，都是大国崛起与个人奋斗的滚烫见证", screenWidth / 2, cardY + 34);

  // 2 列 3 行相册微缩卡展示
  const startCardY = cardY + 54;
  const gridW = cardW - 24;
  const colW = (gridW - 10) / 2;
  const photoH = 88;

  // 展示前 6 张或分页
  const photoCount = Math.min(6, MEMORY_ALBUM_DATABASE.length);
  for (let idx = 0; idx < photoCount; idx++) {
    const photo = MEMORY_ALBUM_DATABASE[idx];
    const col = idx % 2;
    const row = Math.floor(idx / 2);
    const px = cardX + 12 + col * (colW + 10);
    const py = startCardY + row * (photoH + 8);
    const isUnlocked = unlocked.includes(photo.id);

    // 宝丽来相框质感
    drawTactileButton(ctx, {
      id: `view_photo_${photo.id}`,
      x: px,
      y: py,
      w: colW,
      h: photoH,
      radius: 5,
      bg: isUnlocked ? '#fbf7ee' : '#27272a',
      border: isUnlocked ? '#d97706' : '#3f3f46',
      borderWidth: 1,
      priority: 100,
      renderContent: (c) => {
        if (isUnlocked) {
          // 影调区
          c.fillStyle = '#f4ede0';
          c.fillRect(px + 4, py + 4, colW - 8, photoH - 28);

          c.textAlign = 'left';
          c.textBaseline = 'top';
          c.font = 'bold 14px ' + FONT_CHRONICLE;
          c.fillStyle = '#78350f';
          c.fillText(photo.title, px + 8, py + 8);

          c.font = '13.5px ' + FONT_UI;
          c.fillStyle = '#b45309';
          c.fillText(`【${photo.tag}】`, px + 8, py + 24);

          // 缩略简语
          c.font = '13.5px ' + FONT_CHRONICLE;
          c.fillStyle = '#44403c';
          c.fillText(fitText(photo.desc, colW - 16, '13.5px ' + FONT_CHRONICLE), px + 8, py + 42);

          // 底部相纸铭刻
          c.font = 'bold 14px ' + FONT_MONO;
          c.fillStyle = '#b45309';
          c.textAlign = 'right';
          c.fillText(`★ ${photo.stamp}`, px + colW - 8, py + photoH - 18);
        } else {
          c.textAlign = 'center';
          c.textBaseline = 'middle';
          c.font = '18px sans-serif';
          c.fillText("🔒", px + colW / 2, py + photoH / 2 - 8);
          c.font = '13.5px ' + FONT_CHRONICLE;
          c.fillStyle = '#71717a';
          c.fillText(photo.title, px + colW / 2, py + photoH / 2 + 14);
        }
      },
      onClick: () => {
        if (isUnlocked) {
          showToast(`【${photo.title}】：${photo.desc}`, 'gold');
          playSoundEffect('paper');
        } else {
          showToast(`尚未拍下【${photo.title}】，待亲历时代重要时刻方可留影！`, 'info');
        }
      }
    });
  }

  // 关闭相册按钮
  const cBtnW = cardW - 64;
  const cBtnH = 34;
  const cBtnX = cardX + 32;
  const cBtnY = cardY + cardH - cBtnH - 12;

  drawTactileButton(ctx, {
    id: 'close_album_modal',
    x: cBtnX,
    y: cBtnY,
    w: cBtnW,
    h: cBtnH,
    radius: 6,
    bg: '#78350f',
    border: '#f59e0b',
    text: "合 上 生 平 相 册 ➔",
    font: 'bold 14px ' + FONT_CHRONICLE,
    textColor: '#fef08a',
    priority: 100,
    onClick: () => {
      state.activeModal = null;
      playSoundEffect('paper');
      requestRender();
    }
  });
}

// 3. 周易问卦与天机推演弹窗 (Divination Modal)
function drawDivinationModal() {
  const hex = state.activeDivinationResult || state.fortuneHexagram;
  if (!hex) return;

  const cardW = screenWidth - 28;
  const cardH = 410;
  const cardX = 14;
  const cardY = Math.max(16, Math.round((screenHeight - cardH) / 2));

  // 道骨仙风青墨底色
  ctx.fillStyle = '#0f172a';
  roundRect(ctx, cardX, cardY, cardW, cardH, 10, true, true, '#38bdf8', 2);
  drawCornerOrnaments(ctx, cardX, cardY, cardW, cardH, 8, '#38bdf8');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 16px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#7dd3fc';
  ctx.fillText("🌅 岁 时 策 照 · 岁 律 观 照", screenWidth / 2, cardY + 16);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#94a3b8';
  ctx.fillText("顺应传统岁时节令流转，洞察宏观大势与履职前瞻", screenWidth / 2, cardY + 38);

  // 四时时令与大字展示框
  const hexBoxY = cardY + 62;
  const hexBoxH = 110;
  ctx.fillStyle = '#1e293b';
  roundRect(ctx, cardX + 16, hexBoxY, cardW - 32, hexBoxH, 8, true, true, '#0284c7', 1.5);

  ctx.textAlign = 'center';
  ctx.font = 'bold 22px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText(`【 ${hex.name} 】`, screenWidth / 2, hexBoxY + 14);

  ctx.font = '16px monospace';
  ctx.fillStyle = '#38bdf8';
  ctx.fillText(hex.lines, screenWidth / 2, hexBoxY + 44);

  ctx.font = 'bold 14px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fed7aa';
  ctx.fillText(hex.title, screenWidth / 2, hexBoxY + 74);

  // 策辞与效验框
  const vBoxY = hexBoxY + hexBoxH + 12;
  ctx.fillStyle = '#090d16';
  roundRect(ctx, cardX + 16, vBoxY, cardW - 32, 120, 6, true, true, '#334155', 1);

  ctx.textAlign = 'left';
  ctx.font = 'bold 14px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#94a3b8';
  ctx.fillText("【岁华策辞】：", cardX + 26, vBoxY + 12);

  ctx.font = '13.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#e2e8f0';
  const vLines = wrapTextLines(hex.verdict, cardW - 52, '13.5px ' + FONT_CHRONICLE);
  const vLimit = Math.min(2, vLines.length);
  for (let vi = 0; vi < vLimit; vi++) {
    ctx.fillText(vLines[vi], cardX + 26, vBoxY + 30 + vi * 18);
  }

  ctx.font = 'bold 14px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#34d399';
  ctx.fillText("【岁华调摄】：", cardX + 26, vBoxY + 74);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#6ee7b7';
  ctx.fillText(fitText(hex.bonusText, cardW - 52, '13.5px ' + FONT_UI), cardX + 26, vBoxY + 92);

  // 确认收下岁策按钮
  const okBtnW = cardW - 64;
  const okBtnH = 36;
  const okBtnX = cardX + 32;
  const okBtnY = cardY + cardH - okBtnH - 14;

  drawTactileButton(ctx, {
    id: 'close_divination_modal',
    x: okBtnX,
    y: okBtnY,
    w: okBtnW,
    h: okBtnH,
    radius: 6,
    bg: '#0284c7',
    border: '#38bdf8',
    text: "顺应岁时 · 笃行致远 ➔",
    font: 'bold 14px ' + FONT_CHRONICLE,
    textColor: '#fff',
    priority: 100,
    onClick: () => {
      state.activeModal = null;
      state.activeDivinationResult = null;
      playSoundEffect('bell');
      requestRender();
    }
  });
}

